INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv1-m1', 'bv1', 'Modul 1', 'Modul 1 – Läkaryrket m.fl.', 'Läkarrollen och det professionella förhållningssättet, hälso- och sjukvårdens organisation och lagar, epidemiologiska mått, etiska principer och hur vuxen inlärning (TBL) fungerar.', 45, 1, '["CanMEDS sju roller utgår från medicinsk expert.","DALY kombinerar förtidig död och år med funktionsnedsättning.","TBL-cykeln bygger på förberedelse, individuellt test, grupptest och återkoppling."]'::jsonb, '[{"label":"Ninja Nerd: medicinsk professionalism och kommunikation","query":"ninja nerd professionalism medical communication"}]'::jsonb, '[{"code":"1.1","title":"Läkaryrket"},{"code":"1.2","title":"Hälso- och sjukvård i samhället"},{"code":"1.3","title":"Etik"},{"code":"1.4","title":"Lärande"}]'::jsonb, false)
