INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv1-m2', 'bv1', 'Modul 2', 'Modul 2 – Cellbiologi m.fl.', 'Cellens uppbyggnad och organeller, genetiska basbegrepp, embryologi och evolution, samt mikrobiologins grunder: prokaryoter, virus, parasiter, antibiotika, mikrobiota och smittvägar.', 45, 2, '["Mitokondrie-DNA ärvs maternellt.","LPS i Gramnegativa bakteriers yttre membran är ett endotoxin.","Protozoer, maskar och svampar är eukaryota – bakterier är prokaryota."]'::jsonb, '[{"label":"Ninja Nerd: cellstruktur och organeller","query":"ninja nerd cell structure organelles"},{"label":"Ninja Nerd: bakterier och gramfärgning","query":"ninja nerd bacteria structure gram positive negative"}]'::jsonb, '[{"code":"2.1","title":"Cellbiologi"},{"code":"2.2","title":"Mikrobiologi (Modul 2 och 5)"}]'::jsonb, false)
