INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv1-m3', 'bv1', 'Modul 3', 'Modul 3 – Biokemins grunder m.fl.', 'Biokemins grunder (makromolekyler och ämnesomsättning), histologins fyra vävnader, översiktlig anatomi och fysiologi.', 45, 3, '["De fyra grundvävnaderna: epitel, bindväv, muskel, nerv.","Parenkym = funktion, stroma = stöd.","ATP är cellens energivaluta."]'::jsonb, '[{"label":"Ninja Nerd: histologi – de fyra vävnaderna","query":"ninja nerd histology four tissue types"},{"label":"Ninja Nerd: biokemins grunder","query":"ninja nerd biochemistry macromolecules basics"}]'::jsonb, '[{"code":"3.1","title":"Biokemins grunder"},{"code":"3.2","title":"Histologi – kroppens vävnader"},{"code":"3.3","title":"Anatomi"},{"code":"3.4","title":"Fysiologi"}]'::jsonb, false)
