INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv1-m4', 'bv1', 'Modul 4', 'Modul 4 – Cellulär neurovetenskap m.fl.', 'Neuronet och synaptisk transmission, sensorik och motorik, högre hjärnfunktioner, neuroanatomi, endokrinologi samt en första introduktion till immunologi.', 45, 4, '["Talamus är omslagsstation för nästan all sensorik utom lukt.","Fettlösliga hormoner verkar via intracellulära receptorer.","Myelin bildas av oligodendrocyter i CNS och Schwannceller i PNS."]'::jsonb, '[{"label":"Ninja Nerd: nervsystemet översikt","query":"ninja nerd nervous system overview action potential"},{"label":"Ninja Nerd: endokrina systemet","query":"ninja nerd endocrine system hormones overview"}]'::jsonb, '[{"code":"4.1","title":"Cellulär neurovetenskap"},{"code":"4.2","title":"Sensorik"},{"code":"4.3","title":"Motorik"},{"code":"4.4","title":"Högre hjärnfunktioner"},{"code":"4.5","title":"Neuroanatomi–strukturer (flertalet berörs ovan)"},{"code":"4.6","title":"Endokrinologi"},{"code":"4.7","title":"Immunologi (Modul 5)"}]'::jsonb, false)
