INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv1-m5', 'bv1', 'Modul 5', 'Modul 5 – Immunologi m.fl.', 'Immunförsvarets uppbyggnad och funktion, patologins grundbegrepp samt farmakologins grunder (farmakokinetik, farmakodynamik och ADME).', 45, 5, '["Adaptiv immunitet är specifik och har minne – därför tar den dagar.","Anafylaxi är IgE-medierad typ I-reaktion.","ADME = absorption, distribution, metabolism, elimination."]'::jsonb, '[{"label":"Ninja Nerd: immunförsvaret översikt","query":"ninja nerd immune system innate adaptive overview"},{"label":"Ninja Nerd: farmakokinetik – ADME","query":"ninja nerd pharmacokinetics ADME"}]'::jsonb, '[{"code":"5.1","title":"Immunologi"},{"code":"5.2","title":"Patologi"},{"code":"5.3","title":"Farmakologi"}]'::jsonb, false)
