INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv2-m1', 'bv2', 'Modul 1', 'Modul 1 – Kromosomen m.fl.', 'Kromosomens uppbyggnad, cellcykeln och dess kontrollpunkter, DNA-replikation, reparation och apoptos, kromatin och epigenetik, samt transkription, RNA-processning, translation och genreglering.', 45, 1, '["p53 stoppar cellcykeln vid DNA-skada.","Telomeras förlänger telomererna – högt uttryck i stamceller och tumörceller.","Okazaki-fragment fogas ihop av DNA-ligas."]'::jsonb, '[{"label":"Ninja Nerd: DNA-replikation","query":"ninja nerd DNA replication"},{"label":"Ninja Nerd: translation och proteinsyntes","query":"ninja nerd translation protein synthesis"}]'::jsonb, '[{"code":"1.1","title":"Kromosomen"},{"code":"1.2","title":"Cellcykeln"},{"code":"1.3","title":"DNA-replikation"},{"code":"1.4","title":"DNA-reparation"},{"code":"1.5","title":"Apoptos"},{"code":"1.6","title":"Kromatinstruktur och epigenetik"},{"code":"1.7","title":"Transkription"},{"code":"1.8","title":"RNA-processning"},{"code":"1.9","title":"Translation"},{"code":"1.10","title":"Genreglering och signaltransduktion"}]'::jsonb, false)
