INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv2-m2', 'bv2', 'Modul 2', 'Modul 2 – Cellskelett och cellrörelse m.fl.', 'Cellskelettets tre komponenter och motorproteiner, extracellulär matrix, cell-cell-adhesion och celljunctions, biomembran och transport, organellerna ER, mitokondrier, peroxisomer, Golgi och lysosomer samt sårläkning.', 45, 2, '["Gap junctions = connexoner för direkt cellkommunikation.","Na+/K+-ATPas är elektrogen och skapar vilopotentialen.","Aktin, intermediärfilament och mikrotubuli är cellskelettets tre delar."]'::jsonb, '[{"label":"Ninja Nerd: cellmembran och transport","query":"ninja nerd cell membrane transport"},{"label":"Ninja Nerd: cytoskelett","query":"ninja nerd cytoskeleton microtubules actin"}]'::jsonb, '[{"code":"2.1","title":"Cellskelett och cellrörelse"},{"code":"2.2","title":"Extracellulär matrix"},{"code":"2.3","title":"Cell-cell interaktioner (celladhesion och cell junctions)"},{"code":"2.4","title":"Cellens interna struktur samt introduktion till biomembranstruktur"},{"code":"2.5","title":"Det endoplasmatiska retiklet"},{"code":"2.6","title":"Mitokondrier och peroxisomer"},{"code":"2.7","title":"Golgi, vesikulär transport samt lysosomen"},{"code":"2.8","title":"Sår och sårläkning"}]'::jsonb, false)
