INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv2-m3', 'bv2', 'Modul 3', 'Modul 3 – Gametogenes och fertilisering m.fl.', 'Gametogenes och befruktning, fosterveckorna 1–3, meios och könsbestämning, neurulation, gälbågar och ansiktsutveckling, organanläggning samt utvecklingsbiologins molekylära grunder och regenerativ medicin.', 45, 3, '["Implantation sker cirka dag 6–7.","Neuralröret sluts under vecka 3–4; folsyra förebygger slutenhetsdefekter.","Meios ger fyra haploida celler."]'::jsonb, '[{"label":"Ninja Nerd: tidig embryologi","query":"ninja nerd early embryology gastrulation implantation"},{"label":"Ninja Nerd: neurulation","query":"ninja nerd neurulation neural tube development"}]'::jsonb, '[{"code":"3.1","title":"Gametogenes och fertilisering"},{"code":"3.2","title":"Första fosterveckan"},{"code":"3.3","title":"Andra fosterveckan"},{"code":"3.4","title":"Tredje fosterveckan"},{"code":"3.5","title":"Meios och variation, könsbestämning"},{"code":"3.6","title":"Neurulation och veckning"},{"code":"3.7","title":"Bildandet av gälbågar, utveckling av olika strukturer i ansiktet (översiktligt)"},{"code":"3.8","title":"Anläggning av organ"},{"code":"3.9","title":"Utvecklingsbiologins molekylärbiologi"},{"code":"3.10","title":"Regenerativ medicin nu och i framtiden"}]'::jsonb, false)
