INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv2-m4', 'bv2', 'Modul 4', 'Modul 4 – Kolhydrater m.fl.', 'Kolhydraters, lipiders, proteiners och nukleotiders struktur och kemi, enzymer och kinetik, vitaminer och mineraler, mag-tarmkanalens fysiologi och motorik samt nutrition.', 45, 4, '["Lågt Km = hög affinitet.","Amylopektin har α-1,6-grenar och bryts snabbare ner än amylos.","A, D, E, K är fettlösliga vitaminer."]'::jsonb, '[{"label":"Ninja Nerd: enzymkinetik","query":"ninja nerd enzyme kinetics michaelis menten"},{"label":"Ninja Nerd: makromolekyler","query":"ninja nerd biochemistry carbohydrates lipids proteins"}]'::jsonb, '[{"code":"4.1","title":"Kolhydrater"},{"code":"4.2","title":"Lipider"},{"code":"4.3","title":"Proteiner och enzymer"},{"code":"4.4","title":"Nukleotider, mineraler och vitaminer"},{"code":"4.5","title":"Matsmältningssystemets fysiologi och biokemi"},{"code":"4.6","title":"Matsmältningskanalens motorik"},{"code":"4.7","title":"Farmakologi"},{"code":"4.8","title":"Nutrition"}]'::jsonb, false)
