INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv2-m5', 'bv2', 'Modul 5', 'Modul 5 – Kolhydratmetabolism m.fl.', 'Kolhydratmetabolismen: glykolys, glukoneogenes, citronsyracykeln och oxidativ fosforylering, glykogenomsättning, fruktos- och galaktosomsättning samt HMP-shunten.', 45, 5, '["PFK-1 är glykolysens hastighetsbestämmande enzym.","HMP-shunten ger NADPH till erytrocyternas antioxidationsförsvar.","Glukoneogenes sker främst i levern under fasta."]'::jsonb, '[{"label":"Ninja Nerd: glykolys","query":"ninja nerd glycolysis"},{"label":"Ninja Nerd: citronsyracykeln och elektrontransportkedjan","query":"ninja nerd krebs cycle electron transport chain"}]'::jsonb, '[{"code":"5.1","title":"Kolhydratmetabolism"},{"code":"5.2","title":"Glykogenomsättning, omsättning av fruktos och galaktos samt HMP-shunten"}]'::jsonb, false)
