INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv2-m6', 'bv2', 'Modul 6', 'Modul 6 – Lipidmetabolism m.fl.', 'Lipidmetabolism (fettsyrasyntes, TAG, fosfolipider, lipolys, ketonkroppar, kolesterol och lipoproteiner), aminosyrametabolism med ureacykeln samt nukleotid- och hem-metabolism.', 45, 6, '["Ketogenes sker i levermitokondrierna vid insulinbrist eller lång fasta.","Ureacykeln sker i levern; lever svikt ger hyperammonemi.","HMG-CoA-reduktas är mål för statiner."]'::jsonb, '[{"label":"Ninja Nerd: lipidmetabolism","query":"ninja nerd lipid metabolism beta oxidation"},{"label":"Ninja Nerd: ureacykeln","query":"ninja nerd urea cycle"}]'::jsonb, '[{"code":"6.1","title":"Lipidmetabolism"},{"code":"6.2","title":"Aminosyrametabolism"},{"code":"6.3","title":"Nukleotidmetabolism"}]'::jsonb, false)
