INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv2-m7', 'bv2', 'Modul 7', 'Modul 7 – Hunger och mättnad, samt feed-fast-cykeln m.fl.', 'Reglering av hunger och mättnad, feed-fast-cykeln, inkretiner (GLP-1/GLP-2), metabolism vid olika fysiologiska tillstånd, proteinnedbrytning, HbA1c, kolhydratbelastning, polyolvägen, tarmflorans betydelse och adiponektin.', 45, 7, '["HbA1c speglar medelglukos 2–3 månader.","GLP-1 förstärker insulinfrisättningen glukosberoende.","Adiponektin ökar insulinkänsligheten; låga nivåer vid fetma."]'::jsonb, '[{"label":"Ninja Nerd: inkretiner och GLP-1","query":"ninja nerd incretin GLP-1"},{"label":"Ninja Nerd: hunger och mättnad","query":"ninja nerd appetite regulation leptin ghrelin"}]'::jsonb, '[{"code":"7.1","title":"Hunger och mättnad, samt feed-fast-cykeln"},{"code":"7.2","title":"Förklara begreppet inkretin samt peptiderna GLP-1:s och GLP-2:s signaltransduktion, funktion och var de bildas i tarmen"}]'::jsonb, false)
