INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv2-m8', 'bv2', 'Modul 8', 'Modul 8 – Konsultation, basal hygien och kliniska färdigheter', 'Den patientcentrerade konsultationens tre delar, basal hygien och patientsäkerhet, egna värderingar och fördomar i mötet, öppet lyssnande samt praktisk undersökningsteknik och provtagning.', 45, 8, '["Konsultationen: initiering, mitten (anamnes/undersökning/förklaring), avslut.","Handdesinfektion före och efter varje patientkontakt.","Manschettbredd cirka 40 % av överarmens omkrets."]'::jsonb, '[{"label":"Ninja Nerd: klinisk undersökning – blodtryck","query":"ninja nerd blood pressure measurement technique"},{"label":"Ninja Nerd: hjärt- och lungauskultation","query":"ninja nerd cardiac auscultation lung sounds"}]'::jsonb, '[{"code":"8.1","title":"Redogöra för innehållet i de tre delarna i den patientcentrerade konsultationen"},{"code":"8.2","title":"Redogöra för sjukhushygienens betydelse och Socialstyrelsens föreskrifter om basal hygien 117 8.2.1 Kunna redogöra för varför basal hygien är viktigt"},{"code":"8.3","title":"Beskriva strategier för att identifiera och hantera egna värderingar och fördomar som kan påverka mötet med medmänniskor"},{"code":"8.4","title":"Tillämpa öppet lyssnande med hjälp av öppna invitationer, sammanfattningar och bekräftelse i intervju med patient"},{"code":"8.5","title":"Redogöra för korrekt utförande av och utföra blodtrycksmätning, klinisk undersökning av hjärta, lungor, buk och öron samt undersökning av reflexer"},{"code":"8.6","title":"Redogöra för korrekt utförande och på ett patientsäkert sätt genomföra ven-, kapillär- samt svalgprovtagning"}]'::jsonb, false)
