INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv3-m1', 'bv3', 'Modul 1', 'Modul 1 – Huvud och hals m.fl.', 'Rörelseapparatens och visceras anatomi: skelett, muskler, kärl och nerver i huvud-hals, thorax, buk och bäcken, rygg samt arm och ben – med kliniska korrelat.', 45, 1, '["N. phrenicus (C3–C5) innerverar diafragma.","Karpaltunnelsyndrom = n. medianus.","Vena cava inferior passerar diafragma i foramen venae cavae (Th8)."]'::jsonb, '[{"label":"Ninja Nerd: plexus brachialis","query":"ninja nerd brachial plexus"},{"label":"Ninja Nerd: thorax anatomi","query":"ninja nerd anatomy thorax mediastinum"}]'::jsonb, '[{"code":"1.1","title":"Modul 1 – Huvud och hals"},{"code":"1.2","title":"Modul 2 – thorax"},{"code":"1.3","title":"Modul 3 – buk och bäcken"},{"code":"1.4","title":"Modul 4 – rygg"},{"code":"1.5","title":"Modul 5 – armar"},{"code":"1.6","title":"Modul 6 – ben"}]'::jsonb, false)
