INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv3-m2', 'bv3', 'Modul 2', 'Modul 2 – Vävnader m.fl.', 'Histologins grunder: de fyra vävnadernas mikroskopiska uppbyggnad och hur de bygger organ och organsystem, inklusive matsmältningskanalens vägg.', 45, 2, '["Bindväv = få celler, rik extracellulär matrix.","Tarmens mukosa har enlagers cylinderepitel med mikrovilli.","Muskelvävnad: skelett-, hjärt- och glatt muskulatur."]'::jsonb, '[{"label":"Ninja Nerd: histologi – epitelvävnad","query":"ninja nerd histology epithelium"},{"label":"Ninja Nerd: histologi – bindväv","query":"ninja nerd histology connective tissue"}]'::jsonb, '[{"code":"2.1","title":"Vävnader"},{"code":"2.2","title":"Organ/organsystem"}]'::jsonb, false)
