INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv3-m3', 'bv3', 'Modul 3', 'Modul 3 – Klinisk konsultation, patientsäkerhet och etik', 'Klinisk konsultation och undersökning, patientsäkerhet och basal hygien, vetenskap och beprövad erfarenhet, genus och sociala faktorers betydelse för hälsa, samt medicinsk etik inklusive synen på död.', 45, 3, '["Lex Maria = anmälan av allvarlig vårdskada till IVO.","Nödvärn/vård utan samtycke gäller vid fara för liv eller allvarlig skada.","Basal handhygien före och efter patientkontakt."]'::jsonb, '[{"label":"Ninja Nerd: klinisk konsultation","query":"ninja nerd clinical consultation patient centered"},{"label":"Ninja Nerd: medicinsk etik","query":"ninja nerd medical ethics four principles"}]'::jsonb, '[{"code":"3.1","title":"Redogöra för konsultationens tre delar samt strukturen för läkarens del av konsultationen innefattande differentialdiagnostiskt tänkande, den riktade anamnesen, samt statusundersökningar (S3)"},{"code":"3.2","title":"Redogöra för grundläggande begrepp inom patientsäkerhet och de vanligaste typerna av vårdskador (S3)"},{"code":"3.3","title":"Redogöra för sambandet mellan vetenskap och beprövad erfarenhet inom hälso- och"},{"code":"3.4","title":"Redogöra översiktligt för hur genus, psykosociala, socioekonomiska, samhälls- och miljörelaterade faktorer påverkar hälsa, hälsolitteracitet och möjligheten att tillgodogöra sig hälso- och sjukvård (S3)"},{"code":"3.5","title":"Resonera kring hur likabehandling, bemötande och hälsolitteracitet kan påverka hälsa, och möjlighet att tillgodogöra sig hälso- och sjukvård och basera sitt resonemang på vetenskaplig grund (S4)"},{"code":"3.6","title":"Redogöra för centrala etiska begrepp, teorier, normer, värderingar och principer (S3) och beskriva hur de tillämpas inom hälso- och sjukvården (S4)"},{"code":"3.7","title":"Resonera kring etiska och moraliska dilemman av relevans för läkaren med utgångspunkt i medicinhistoriska exempel (S4)"},{"code":"3.8","title":"Analysera etiska problem som att precisera handlingsalternativ,"},{"code":"3.9","title":"Ge exempel på hur individers och gruppers behov kan stå i konflikt med varandra och påverka beslutsfattande i olika situationer (S4)"},{"code":"3.10","title":"Redogöra för hur synen på död och döende i relation till läkaryrket har förändrats ur ett transkulturellt ett medicinhistoriskt perspektiv (S3)"}]'::jsonb, false)
