INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv4-m1', 'bv4', 'Modul 1', 'Neuroanatomi, neurohistologi, samt grundläggande neurofysiologi och farmakologi', 'Nervsystemets uppbyggnad och neurofysiologi: neuronets membranpotential och aktionspotential, synaptisk transmission, neurotransmittorer och farmakologiska principer.', 45, 1, '["Depolarisering drivs av Na+ in, repolarisering av K+ ut.","Myelin ger saltatorisk ledning och högre hastighet.","GABA är det viktigaste inhibitoriska transmittorsystemet."]'::jsonb, '[{"label":"Ninja Nerd: aktionspotential","query":"ninja nerd action potential"},{"label":"Ninja Nerd: synaptisk transmission","query":"ninja nerd synaptic transmission neurotransmitters"}]'::jsonb, '[{"code":"1.1","title":"Studenten ska kunna redogöra i detalj för nervsystemets makroskopiska"},{"code":"1.2","title":"Studenten ska kunna identifiera och översiktligt redogöra för funktionerna för viktiga strukturer och bansystem i modeller, humanpreparat och MR bilder (S2) .. 9 1.3 Studenten ska kunna förklara"},{"code":"1.3","title":"Studenten ska kunna förklara"},{"code":"1.4","title":"Studenten ska i detalj kunna redogöra för"}]'::jsonb, false)
