INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv4-m2', 'bv4', 'Modul 2', 'Sensorik', 'Sinnesorganen och de sensoriska banorna: somatosensorik och smärta, syn, hörsel, vestibularis, lukt och smak samt farmakologisk behandling av smärta.', 45, 2, '["Spinothalamiska banan korsar i ryggmärgen.","Skada i chiasma opticum ger bitemporal hemianopsi.","Tappar = färg och skärpa, stavar = mörkerseende."]'::jsonb, '[{"label":"Ninja Nerd: sensoriska banor","query":"ninja nerd sensory pathways spinothalamic dorsal column"},{"label":"Ninja Nerd: synen och näthinnan","query":"ninja nerd visual pathway retina"}]'::jsonb, '[{"code":"2.1","title":"Studenten ska kunna redogöra för:"},{"code":"2.2","title":"Studenten ska kunna förklara:"},{"code":"2.3","title":"Studenten ska kunna:"}]'::jsonb, false)
