INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv4-m3', 'bv4', 'Modul 3', 'Motorik', 'Motorikens organisation: motoriska enheter, reflexer, hjärnstam, cerebellum, basala ganglier och motorisk cortex samt motoriskt neurologiskt status.', 45, 3, '["Parkinson = dopaminbrist i substantia nigra.","Cerebellär skada ger ipsilateral ataxi och intentionstremor.","Pyramidbanan korsar i medulla oblongata."]'::jsonb, '[{"label":"Ninja Nerd: motoriska systemet","query":"ninja nerd motor system corticospinal tract"},{"label":"Ninja Nerd: basala ganglier","query":"ninja nerd basal ganglia direct indirect pathway"}]'::jsonb, '[{"code":"3.1","title":"Studenten ska i detalj kunna redogöra för:"},{"code":"3.2","title":"Studenten skall översiktligt kunna redogöra för"},{"code":"3.3","title":"Studenten ska i detalj kunna redogöra för:"}]'::jsonb, false)
