INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv4-m4', 'bv4', 'Modul 4', 'Högre kognitiva funktioner', 'Högre kognitiva funktioner: kortikal organisation, uppmärksamhet, minne, emotioner, exekutiva funktioner, språk och neuropsykofarmakologi.', 45, 4, '["Broca = produktion, Wernicke = förståelse.","Hippocampus konsoliderar deklarativt minne.","Frontalloben styr exekutiva funktioner."]'::jsonb, '[{"label":"Ninja Nerd: minne och hippocampus","query":"ninja nerd memory hippocampus"},{"label":"Ninja Nerd: språkcentra","query":"ninja nerd broca wernicke aphasia"}]'::jsonb, '[{"code":"4.1","title":"Komplexa hjärnfunktioner och kortikal organisation"},{"code":"4.2","title":"Kortikala tillstånd"},{"code":"4.3","title":"Uppmärksamhet"},{"code":"4.4","title":"Minne"},{"code":"4.5","title":"Emotioner"},{"code":"4.6","title":"Att tänka, planera, och fatta beslut"},{"code":"4.7","title":"Tal och språk"},{"code":"4.8","title":"Nueropsychofarmakologi"}]'::jsonb, false)
