INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv4-m5', 'bv4', 'Modul 5', 'Modul 5 – Hypothalamus och hypofys m.fl.', 'Hypotalamus och hypofysens reglering, tyreoidea, binjurarnas hormoner med steroidhormonernas verkningsmekanism samt integrering av endokrina axlar.', 45, 5, '["Primär hypotyreos: lågt fT4 + högt TSH.","Kortisol bildas i zona fasciculata under ACTH-kontroll.","Neurohypofysen frisätter ADH och oxytocin."]'::jsonb, '[{"label":"Ninja Nerd: hypofysen","query":"ninja nerd pituitary gland hypothalamus axis"},{"label":"Ninja Nerd: tyreoidea","query":"ninja nerd thyroid gland hormones"}]'::jsonb, '[{"code":"5.1","title":"Hypothalamus och hypofys"},{"code":"5.2","title":"Thyroidea"},{"code":"5.3","title":"Steroidhormoner"},{"code":"5.4","title":"Binjurarna"},{"code":"5.5","title":"Integrering"}]'::jsonb, false)
