INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv4-m6', 'bv4', 'Modul 6', 'Modul 6 – Blodkärl m.fl.', 'Centrala nervsystemets anatomi och blodförsörjning: hjärnans kärl, ventriklar och hjärnhinnor, vit substans, ryggmärg, cerebellum, hjärnstam, basala ganglier, kranialnerver och sympatikus.', 45, 6, '["A. cerebri media är vanligaste stroke-kärlet.","N. facialis påverkar både mimik och smak (chorda tympani).","CSF bildas i plexus choroideus."]'::jsonb, '[{"label":"Ninja Nerd: hjärnans blodkärl","query":"ninja nerd cerebral blood supply circle of willis"},{"label":"Ninja Nerd: kranialnerver","query":"ninja nerd cranial nerves"}]'::jsonb, '[{"code":"6.1","title":"Blodkärl"},{"code":"6.2","title":"Ventriculi cerebri"},{"code":"6.3","title":"Hjärnhinnorna"},{"code":"6.4","title":"Vit substans i telencephalon"},{"code":"6.5","title":"Ryggmärgen"},{"code":"6.6","title":"Cerebellum"},{"code":"6.7","title":"Truncus encephali"},{"code":"6.8","title":"Basala ganglierna"},{"code":"6.9","title":"Diencephalon"},{"code":"6.10","title":"Gyri, sulci och cortex"},{"code":"6.11","title":"Kranialnerver"},{"code":"6.12","title":"Bansystem"},{"code":"6.13","title":"Sympatikus"}]'::jsonb, false)
