INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv5-m1', 'bv5', 'Modul 1', 'Farmakologi och immunologi', 'Allmän farmakologi (farmakokinetik, farmakodynamik, interaktioner), immunologins grunder, microbicida substanser och immunofarmakologi.', 40, 1, '["First-pass-metabolism sänker biotillgängligheten.","Betalaktamer hämmar cellväggssyntesen och är baktericida.","Steady state nås efter cirka 4–5 halveringstider."]'::jsonb, '[{"label":"Ninja Nerd: farmakokinetik","query":"ninja nerd pharmacokinetics"},{"label":"Ninja Nerd: antibiotika – verkningsmekanismer","query":"ninja nerd antibiotics mechanisms of action"}]'::jsonb, '[{"code":"1.1","title":"Allmän farmakologi"},{"code":"1.2","title":"Immunologi"},{"code":"1.3","title":"Microbicida substanser"},{"code":"1.4","title":"Immunofarmakologi"}]'::jsonb, false)
