INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv5-m2', 'bv5', 'Modul 2', 'Muskel och hjärta', 'Skelettmuskelns och hjärtmuskelns fysiologi och farmakologi, excitation–kontraktion, hjärtats arbete och vanliga hjärtsjukdomar med behandling.', 40, 2, '["Platåfasen skyddar hjärtat från tetani.","Hjärtsviktsbehandling: ACE-hämmare/ARNI + betablockad + MRA.","Frank–Starling: ökad preload ökar slagvolymen."]'::jsonb, '[{"label":"Ninja Nerd: muskelkontraktion","query":"ninja nerd muscle contraction sliding filament"},{"label":"Ninja Nerd: hjärtcykeln","query":"ninja nerd cardiac cycle"}]'::jsonb, '[{"code":"2.1","title":"Skelettmuskel och hjärtmuskel – Jämförelse"},{"code":"2.2","title":"Skelettmuskel"},{"code":"2.3","title":"Hjärta"},{"code":"2.4","title":"Hjärtsjukdomar"},{"code":"2.5","title":"Biokemi och nutrition"}]'::jsonb, false)
