INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv5-m3', 'bv5', 'Modul 3', 'Blod och cirkulation', 'Blodets sammansättning och hemostas, cirkulationsfysiologi och blodtrycksreglering samt blodets sjukdomar och cirkulationspatologi.', 40, 3, '["vWF medierar trombocytadhesion.","Baroreceptorreflexen höjer sympatikus vid tryckfall.","Aldosteron: Na+ reabsorption, K+ utsöndring."]'::jsonb, '[{"label":"Ninja Nerd: hemostas","query":"ninja nerd hemostasis coagulation cascade"},{"label":"Ninja Nerd: blodtrycksreglering","query":"ninja nerd blood pressure regulation baroreceptors RAAS"}]'::jsonb, '[{"code":"3.1","title":"Blodets kemi och nutrition"},{"code":"3.2","title":"Hemostas"},{"code":"3.3","title":"Benmärgspatologi"},{"code":"3.4","title":"Cirkulationsfysiologi"},{"code":"3.5","title":"Cirkulationspatologi"}]'::jsonb, false)
