INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv5-m4', 'bv5', 'Modul 4', 'Respiration', 'Andningens fysiologi: ventilation, pulmonellt blodflöde, gasutbyte och syretransport samt andningsreglering.', 40, 4, '["Bohr-effekten: högre CO2 → hemoglobin avger syre lättare.","Typ II-pneumocyter bildar surfaktant.","V/Q-kvoten är cirka 0,8 normalt."]'::jsonb, '[{"label":"Ninja Nerd: andningsmekanik","query":"ninja nerd respiratory mechanics ventilation"},{"label":"Ninja Nerd: syre-hemoglobinkurvan","query":"ninja nerd oxygen hemoglobin dissociation curve"}]'::jsonb, '[{"code":"4.1","title":"Ventilation"},{"code":"4.2","title":"Pulmonellt blodflöde"},{"code":"4.3","title":"Gasutbyte och transport"},{"code":"4.4","title":"Andningsreglering"},{"code":"4.5","title":"Respirationsorganens patologi"}]'::jsonb, false)
