INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv5-m5', 'bv5', 'Modul 5', 'Njuren', 'Njurens funktion: filtration, reabsorption och sekretion, GFR och autoregulation, koncentration av urin, syra-bas- och vätskebalans samt njurens hormonella funktioner.', 40, 5, '["Loop-diuretika verkar i uppåtstigande Henles slynga.","GFR autoregleras mellan cirka 80 och 180 mmHg.","ADH ger aquaporin-2-insättande och koncentrerad urin."]'::jsonb, '[{"label":"Ninja Nerd: njurens fysiologi","query":"ninja nerd renal physiology filtration reabsorption"},{"label":"Ninja Nerd: syra-bas och njuren","query":"ninja nerd acid base renal regulation"}]'::jsonb, '[{"code":"5.1","title":"Njurfunktion"},{"code":"5.2","title":"Renal Autoreglering"},{"code":"5.3","title":"Vatten & Saltbalans"},{"code":"5.4","title":"Hormonell Reglering"},{"code":"5.5","title":"Diuretika"},{"code":"5.6","title":"Syra-Bas Reglering"},{"code":"5.7","title":"Medicinska njursjukdomar"},{"code":"5.8","title":"Urologiska sjukdomstillstånd"}]'::jsonb, false)
