INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv6-m1', 'bv6', 'Modul 1', 'Allmän mikrobiologi', 'Mikrobiologins grunder: klassificering, hygien, immunologi, bakterier, virus, parasiter och svampar samt mikrobiotans betydelse.', 40, 1, '["Virus är obligat intracellulära – antibiotika hjälper inte.","Gramnegativa bakterier har LPS (endotoxin) i yttre membranet.","Betalaktamer hämmar cellväggssyntesen."]'::jsonb, '[{"label":"Ninja Nerd: bakteriologi – struktur","query":"ninja nerd bacteria structure and function"},{"label":"Ninja Nerd: virus replikation","query":"ninja nerd virus replication"}]'::jsonb, '[{"code":"1.1","title":"Klassificering"},{"code":"1.2","title":"Hygien"},{"code":"1.3","title":"Immunologi"},{"code":"1.4","title":"Bakterier"},{"code":"1.5","title":"Virus"},{"code":"1.6","title":"Parasiter och svampar"},{"code":"1.7","title":"Mikrobiota"}]'::jsonb, false)
