INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv6-m2', 'bv6', 'Modul 2', 'Tropiska sjukdomar och global hälsa', 'Global hälsa och epidemiologi, tropiska infektionssjukdomar som malaria, tuberkulos och dengue samt prevention ur ett globalt perspektiv.', 40, 2, '["P. falciparum ger svårast malaria; behandlas med IV artesunat.","Tuberkulos kräver kombinationsbehandling i månader.","Anopheles-myggor överför malaria."]'::jsonb, '[{"label":"Ninja Nerd: malaria","query":"ninja nerd malaria plasmodium"},{"label":"Ninja Nerd: tuberkulos","query":"ninja nerd tuberculosis"}]'::jsonb, '[{"code":"2.1","title":"Epidemiologi och global hälsa"},{"code":"2.2","title":"Zoonoser"},{"code":"2.3","title":"Tropiska sjukdomar"}]'::jsonb, false)
