INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv6-m3', 'bv6', 'Modul 3', 'Mag- och tarminfektioner, samt antimikrobiell behandling', 'Mag- och tarminfektioner, antibakteriell behandling och resistens, antiviral behandling, vacciner och mikrobiologisk laborationsdiagnostik.', 40, 3, '["C. difficile-kolit kommer efter antibiotika som rubbat tarmfloran.","Levande vaccin undviks vid immunosuppression.","Betalaktamaser bryter ner penicillin – hämmare kombineras."]'::jsonb, '[{"label":"Ninja Nerd: antibiotikaresistens","query":"ninja nerd antibiotic resistance mechanisms"},{"label":"Ninja Nerd: vaccin","query":"ninja nerd vaccines immunology types"}]'::jsonb, '[{"code":"3.1","title":"Mag- och tarminfektioner"},{"code":"3.2","title":"Antibakteriell behandling och antibiotikaresistens"},{"code":"3.3","title":"Antiviral behandling"},{"code":"3.4","title":"Vaccin"},{"code":"3.5","title":"Laboration"}]'::jsonb, false)
