INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv6-m4', 'bv6', 'Modul 4', 'Luftvägs-, hud- och barninfektioner', 'Luftvägs-, hud- och barninfektioner: bakteriella och virala luftvägsinfektioner, hudinfektioner, barnsjukdomar och parasitinfektioner.', 40, 4, '["Vattkoppor ger utslag i olika stadier samtidigt.","Erysipelas orsakas oftast av grupp A-streptokocker.","Rubella under graviditet ger kongenitalt rubellasyndrom."]'::jsonb, '[{"label":"Ninja Nerd: pneumoni","query":"ninja nerd pneumonia clinical medicine"},{"label":"Ninja Nerd: hudinfektioner","query":"ninja nerd cellulitis skin infections"}]'::jsonb, '[{"code":"4.1","title":"Mikrobiota och diagnostik"},{"code":"4.2","title":"Bakterieinfektioner"},{"code":"4.3","title":"Virusinfektioner"},{"code":"4.4","title":"Barnsjukdomar"},{"code":"4.5","title":"Parasitinfektioner"}]'::jsonb, false)
