INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('bv6-m5', 'bv6', 'Modul 5', 'CNs-infektioner och STI:s', 'CNS-infektioner och sexuellt överförbara infektioner: meningit och encefalit, HIV och HPV, urinvägsinfektioner samt mindre vanliga patogener som prioner och toxoplasma.', 40, 5, '["Petekier + feber = misstänk meningokocksepsis – behandla direkt.","HIV angriper CD4+ T-celler.","TBE-vaccin finns; borrelia förebyggs med fästingkontroll."]'::jsonb, '[{"label":"Ninja Nerd: bakteriell meningit","query":"ninja nerd bacterial meningitis"},{"label":"Ninja Nerd: HIV","query":"ninja nerd HIV AIDS pathophysiology"}]'::jsonb, '[{"code":"5.1","title":"Nisseria"},{"code":"5.2","title":"Andra bakterier"},{"code":"5.3","title":"Urinvägsinfektioner"},{"code":"5.4","title":"Sexuellt överförbara sjukdomar och spirocheter"},{"code":"5.5","title":"Meningoencefalit"},{"code":"5.6","title":"Prioner"},{"code":"5.7","title":"HIV och HPV"},{"code":"5.8","title":"Toxoplasma"}]'::jsonb, false)
