INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km1-1', 'km1', 'Modul 1', 'Akutmedicin', 'Strukturerat omhändertagande av den akut sjuka patienten: ABCDE, chockutredning, hjärt-lungräddning och de vanligaste akuta invärtesmedicinska tillstånden.', 33, 1, '["Blodtrycksfall är ett sent tecken på chock – takykardi och förlängd kapillär återfyllnad kommer först.","Spänningsthorax behandlas på klinisk misstanke; röntgen får inte fördröja dekompression.","Vid anafylaxi är intramuskulärt adrenalin förstahandsbehandling – antihistamin och glukokortikoid är tillägg.","Laktat och urinproduktion används för att värdera effekten av återupplivning."]'::jsonb, '[{"label":"Ninja Nerd: strukturerat akutomhändertagande enligt ABCDE","query":"ninja nerd ABCDE primary survey assessment"},{"label":"Ninja Nerd: chock – patofysiologi och chocktyper","query":"ninja nerd types of shock pathophysiology"}]'::jsonb, '[]'::jsonb, false)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, code = EXCLUDED.code, title = EXCLUDED.title,
  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km1-2', 'km1', 'Modul 2', 'Kardiologi', 'Hjärtsvikt, akut koronart syndrom, förmaksflimmer och klaffel – patofysiologi, diagnostik och prognosförbättrande behandling.', 34, 2, '["ST-höjning i V1–V4 talar för framväggsinfarkt vid LAD-ocklusion.","Primär PCI är förstahandsreperfusion vid STEMI när den kan göras i tid.","Vid inferior STEMI ska nitrater undvikas vid misstänkt högerkammarinfarkt.","Betablockad vid hjärtsvikt titreras långsamt och startas inte vid akut dekompensation."]'::jsonb, '[{"label":"Ninja Nerd: hjärtsvikt och dess patofysiologi","query":"ninja nerd heart failure pathophysiology"},{"label":"Ninja Nerd: akut koronart syndrom och EKG-lokalisering","query":"ninja nerd acute coronary syndrome ECG"},{"label":"Ninja Nerd: förmaksflimmer på EKG","query":"ninja nerd atrial fibrillation ECG"}]'::jsonb, '[]'::jsonb, false)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, code = EXCLUDED.code, title = EXCLUDED.title,
  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km1-3', 'km1', 'Modul 3', 'Endokrinologi', 'Diabetes mellitus, tyreoidearubbningar och binjurebarkssjukdomar – patofysiologi, diagnostik och principer för behandling.', 32, 3, '["Primär hypotyreos: högt TSH och lågt fritt T4; sekundär: lågt TSH.","TRAK vid Graves sjukdom stimulerar TSH-receptorn.","Tionamider kan ge agranulocytos – feber och halsont kräver provtagning.","Vid typ 2-diabetes med hjärt-kärlsjukdom eller njursjukdom tillkommer SGLT2- eller GLP-1-behandling utöver metformin."]'::jsonb, '[{"label":"Ninja Nerd: tyreoideasjukdomar och tyreostatika","query":"ninja nerd thyroid disorders hyperthyroidism"},{"label":"Ninja Nerd: diabetes mellitus typ 1 och typ 2","query":"ninja nerd diabetes mellitus type 1 type 2"}]'::jsonb, '[]'::jsonb, false)
