INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km1-4', 'km1', 'Modul 4', 'Lungmedicin och allergologi', 'Astma, KOL, pneumoni, lungemboli och allergiska sjukdomar – diagnostik, differentialdiagnostik och behandlingsprinciper.', 31, 4, '["Vid astma är inflammationsbehandling med inhalationssteroider grunden i all underhållsbehandling.","Rökstopp är den enda intervention som bromsar lungfunktionsförlusten vid KOL.","Intramuskulärt adrenalin är förstahandsbehandling vid anafylaxi.","Ett negativt D-dimer utesluter lungemboli endast vid låg eller måttlig klinisk sannolikhet."]'::jsonb, '[{"label":"Ninja Nerd: astma och obstruktiv lungsjukdom","query":"ninja nerd asthma obstructive lung disease"},{"label":"Ninja Nerd: lungemboli","query":"ninja nerd pulmonary embolism"}]'::jsonb, '[]'::jsonb, false)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, code = EXCLUDED.code, title = EXCLUDED.title,
  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
