  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km1-5', 'km1', 'Modul 5', 'Njurmedicin', 'Akut njurskada, kronisk njursjukdom, nefrotiskt och nefritiskt syndrom samt handläggning av elektrolytrubbningar.', 30, 5, '["Kalcium vid hyperkalemi skyddar hjärtat men sänker inte kalium – det är inte elimination.","Nefrotiskt syndrom ger ökad tromboembolisk risk på grund av förluster av antikoagulerande proteiner i urinen.","Postrenal obstruktion ska uteslutas tidigt vid akut njurskada – bladderscan och ultraljud.","ACE-hämmare kan ge ett måttligt kreatininstegring i början; kraftig stegring talar för renal artärstenos."]'::jsonb, '[{"label":"Ninja Nerd: akut njurskada och dess orsaker","query":"ninja nerd acute kidney injury"},{"label":"Ninja Nerd: nefrotiskt syndrom","query":"ninja nerd nephrotic syndrome"}]'::jsonb, '[]'::jsonb, false)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, code = EXCLUDED.code, title = EXCLUDED.title,
  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km1-6', 'km1', 'Modul 6', 'Gastroenterologi och hepatologi', 'Levercirros och dess komplikationer, akut pankreatit, inflammatorisk tarmsjukdom och gallvägssjukdom – utredning och handläggning.', 33, 6, '["Spontan bakteriell peritonit diagnostiseras med ascitespunktion – cellräkning är avgörande.","Vid cirros med ascites ska ASCITES-vård (saltrestriktion, diuretika, terlipressin/albumin vid behov) individualiseras.","Gallsten och alkohol dominerar som orsaker till akut pankreatit.","Vid ulcerös kolit är 5-ASA första linjens underhållsbehandling; steroider används för induktion."]'::jsonb, '[{"label":"Ninja Nerd: levercirros och portahypertension","query":"ninja nerd liver cirrhosis portal hypertension"},{"label":"Ninja Nerd: inflammatorisk tarmsjukdom","query":"ninja nerd inflammatory bowel disease Crohn ulcerative colitis"}]'::jsonb, '[]'::jsonb, false)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, code = EXCLUDED.code, title = EXCLUDED.title,
  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km1-7', 'km1', 'Modul 7', 'Hematologi', 'Anemier, maligna blodsjukdomar och koagulationsrubbningar – utredningsgång och behandlingsprinciper.', 32, 7, '["Lågt ferritin är det mest specifika enskilda provet för järnbrist.","B12-brist ger både makrocytär anemi och neurologiska symtom – folsyra monoterapi döljer skadan.","CRAB: hyperkalcemi, njursvikt, anemi och benskador vid myelom.","Lågt haptoglobin och högt LDH är typiska hemolysmarkörer."]'::jsonb, '[{"label":"Ninja Nerd: anemier och blodutstryk","query":"ninja nerd anemia types classification"},{"label":"Ninja Nerd: leukemi och lymfom","query":"ninja nerd leukemia lymphoma"}]'::jsonb, '[]'::jsonb, false)
