  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km1-8', 'km1', 'Modul 8', 'Reumatologi', 'Reumatoid artrit, kristallsjukdomar, vaskuliter och systemsjukdomar – klinisk igenkänning och tidig behandling.', 32, 8, '["Anti-CCP är mer specifikt än reumatoid faktor vid reumatoid artrit.","Akut gikt ska behandlas antiinflammatoriskt – uratsänkning startas i lugnt skede.","Jättecellsarterit med synpåverkan är en akut behandlingsindikation på grund av blindhetsrisk.","Tidig insättning av DMARD vid reumatoid artrit bromsar leddestruktion."]'::jsonb, '[{"label":"Ninja Nerd: reumatoid artrit","query":"ninja nerd rheumatoid arthritis"},{"label":"Ninja Nerd: gikt och kristallartrit","query":"ninja nerd gout crystal arthritis"}]'::jsonb, '[]'::jsonb, false)
