  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km2-1', 'km2', 'Modul 1', 'Geriatrik', 'Skörhet, delirium, demenssjukdomar, fall och polyfarmaci – den geriatriska helhetsbedömningen och det förebyggande arbetet hos den äldre patienten.', 30, 1, '["Delirium är ett akut tillstånd och en medicinsk akut situation – sök orsaken.","Sederande läkemedel förvärrar delirium och ökar fallrisken.","Skörhet är en bättre prediktor för utfall än kronologisk ålder.","Multifaktoriell fallprevention med balansträning har starkast evidens för att förebygga fall."]'::jsonb, '[{"label":"Ninja Nerd: delirium och förvirringstillstånd","query":"ninja nerd delirium altered mental status"},{"label":"Ninja Nerd: demenssjukdomar","query":"ninja nerd dementia Alzheimer disease"}]'::jsonb, '[]'::jsonb, false)
