  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km2-2', 'km2', 'Modul 2', 'Infektionssjukdomar', 'Sepsis, endokardit, bakteriell meningit, tuberkulos och HIV – tidig igenkänning, diagnostik och behandlingsprinciper.', 33, 2, '["Vid sepsis gäller odling före antibiotika – men aldrig väntan på odlingssvar.","Modifierade Duke-kriterier kombinerar blododlingar och ekokardiografi.","Bakteriell meningit behandlas med antibiotika och dexametason utan dröjsmål.","Tuberkulos är luftsmittsam och kräver isolering med andningsskydd av FFP3-typ."]'::jsonb, '[{"label":"Ninja Nerd: sepsis och septisk chock","query":"ninja nerd sepsis septic shock"},{"label":"Ninja Nerd: infektiös endokardit","query":"ninja nerd infective endocarditis"},{"label":"Ninja Nerd: tuberkulos","query":"ninja nerd tuberculosis"}]'::jsonb, '[]'::jsonb, false)
