INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km2-3', 'km2', 'Modul 3', 'Hudsjukdomar', 'Eksem, psoriasis, akne, hudtumörer och infektiösa hudtillstånd – klinisk igenkänning och principer för topikal och systemisk behandling.', 28, 3, '["Basaliom metastaserar i princip aldrig men växer destruktivt lokalt.","Breslow-tjocklek är den starkaste prognosfaktorn vid malignt melanom.","Psoriasis kan ge artrit (psoriasisartrit) och är associerad med metabolt syndrom.","Koebners fenomen innebär att psoriasis uppstår i hudskada."]'::jsonb, '[{"label":"Ninja Nerd: hudens anatomi och primärefflorescenser","query":"ninja nerd skin lesions dermatology terminology"},{"label":"Ninja Nerd: malignt melanom","query":"ninja nerd melanoma skin cancer"}]'::jsonb, '[]'::jsonb, false)
