INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km2-4', 'km2', 'Modul 4', 'Antibiotika och resistens', 'Verkningsmekanismer, resistensmekanismer och principer för rationell antibiotikaanvändning – smalt spektrum, rätt duration och resistensförebyggande arbete.', 29, 4, '["ESBL och MRSA är resistensmekanismer – enzymatisk nedbrytning respektive förändrat målprotein.","Vid odlingssvar ska behandlingen smalnas av (deeskaleras).","Kinoloner ska sparas för att begränsa resistens och biverkningar.","Behandlingstid ska vara så kort som möjligt och evidensbaserad för respektive infektion."]'::jsonb, '[{"label":"Ninja Nerd: antibiotikas verkningsmekanismer","query":"ninja nerd antibiotics mechanism of action"},{"label":"Ninja Nerd: antibiotikaresistens","query":"ninja nerd antibiotic resistance mechanisms"}]'::jsonb, '[]'::jsonb, false)
