INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km3-1', 'km3', 'Modul 1', 'Allmänkirurgi och akut buk', 'Akut buksmärta är en av de vanligaste kirurgiska kontaktorsakerna. Här tränas strukturerad handläggning från anamnes och bukstatus till bilddiagnostik och beslut om operation.', 32, 1, '["Fri luft under diafragma på upprätt röntgen är ett starkt tecken på perforation av ihålig struktur.","Adherenser är den vanligaste orsaken till mekanisk tunntarmsileus i Sverige.","Smärtans migrering vid appendicit speglar övergången från visceral till somatisk smärta.","Laktatstegring och metabol acidos vid akut buk ska väcka misstanke om tarmischemi."]'::jsonb, '[{"label":"Ninja Nerd: akut buk och appendicit","query":"ninja nerd acute abdomen appendicitis"},{"label":"Ninja Nerd: ileus och tarmobstruktion","query":"ninja nerd bowel obstruction ileus"}]'::jsonb, '[]'::jsonb, false)
