  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km3-2', 'km3', 'Modul 2', 'Trauma och ortopedi', 'Prioritering vid trauma enligt ABCDE och de vanligaste ortopediska skadorna hos äldre och yngre. Tyngdpunkten ligger på att känna igen livshotande tillstånd och på frakturläkningens villkor.', 33, 2, '["Blödningskontroll (C) prioriteras samtidigt med A vid massiv yttre blödning.","Förkortat, utåtrotterat ben efter fall hos äldre = misstänkt höftfraktur.","Oproportionerlig smärta och spänd muskelkammare = kompartmentsyndrom, fasciotomi utan dröjsmål.","Spänningsthorax är en klinisk diagnos som dekomprimeras direkt."]'::jsonb, '[{"label":"Ninja Nerd: traumapatienten och ABCDE","query":"ninja nerd trauma primary survey ABCDE"},{"label":"Ninja Nerd: frakturläkning och benläkning","query":"ninja nerd bone fracture healing"}]'::jsonb, '[]'::jsonb, false)
