INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km3-3', 'km3', 'Modul 3', 'Anestesi och perioperativ vård', 'Perioperativ riskbedömning, generell och regional anestesi samt de vanligaste anestesiologiska komplikationerna. Fokus ligger på mekanismer och på vad som gör en operation farlig för just den här patienten.', 28, 3, '["Malignt hypertermi behandlas med dantrolen och utlöses av inhalationsanestetika och succinylkolin.","Lokalbedövningsmedel blockerar spänningsstyrda natriumkanaler.","Postpunktionell huvudvärk är ortostatisk och lindras i liggande.","ASA-klass och ingreppets omfattning bedöms separat."]'::jsonb, '[{"label":"Ninja Nerd: generell anestesi och sövningsmedel","query":"ninja nerd general anesthesia pharmacology"},{"label":"Ninja Nerd: malignt hypertermi","query":"ninja nerd malignant hyperthermia"}]'::jsonb, '[]'::jsonb, false)
