  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km3-4', 'km3', 'Modul 4', 'Urologi', 'Vanliga urologiska tillstånd från godartad prostatahyperplasi och njursten till testistorsion och urinvägsinfektion. Fokus ligger på att skilja benigna symtom från tillstånd som kräver akut ingripande.', 30, 4, '["E. coli dominerar som orsak till okomplicerad urinvägsinfektion.","Obstruktion plus infektion = akut avlastning, inte enbart antibiotika.","Testistorsion är en tidskritisk kirurgisk diagnos – exploration före ultraljud.","PSA stiger även av benign prostatahyperplasi, prostatit och mekanisk irritation."]'::jsonb, '[{"label":"Ninja Nerd: njurens fysiologi och njursten","query":"ninja nerd kidney stones nephrolithiasis"},{"label":"Ninja Nerd: prostatahyperplasi och urinvägar","query":"ninja nerd benign prostatic hyperplasia"}]'::jsonb, '[]'::jsonb, false)
