  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km3-5', 'km3', 'Modul 5', 'Kärlkirurgi', 'Arteriell och venös insufficiens, akut extremitetsischemi och bukaortaaneurysm. Fokus ligger på att skilja claudicatio från andra gångsmärtor och på att känna igen den kärlkirurgiska akutsituationen.', 27, 5, '["Akut extremitetsischemi behandlas genom revaskularisering – inte genom att avvakta.","Rökning är den starkaste modifierbara riskfaktorn vid perifer artärsjukdom.","Rupturerat aortaaneurysm ger hypotoni med pulsatile resistens och ryggsmärta.","Djupt ventrombos hotar framför allt genom lungemboli."]'::jsonb, '[{"label":"Ninja Nerd: perifer artärsjukdom och claudicatio","query":"ninja nerd peripheral arterial disease claudication"},{"label":"Ninja Nerd: aortaaneurysm","query":"ninja nerd abdominal aortic aneurysm"}]'::jsonb, '[]'::jsonb, false)
