  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km4-1', 'km4', 'Modul 1', 'Neurologi', 'Nervsystemets sjukdomar från akut stroke och epilepsi till Parkinsons sjukdom och MS. Här tränas den strukturerade neurologiska undersökningen och igenkänning av tidskritiska tillstånd.', 34, 1, '["DT utan kontrast utesluter blödning inför trombolys vid stroke.","Parkinsons sjukdom är en degenerationssjukdom i substantia nigra, inte en ren vilotremor-diagnos.","Aura vid migrän utvecklas gradvis och varar upp till en timme.","Pyramidbanan korsar i medulla oblongata."]'::jsonb, '[{"label":"Ninja Nerd: stroke och cerebral ischemi","query":"ninja nerd ischemic stroke pathophysiology"},{"label":"Ninja Nerd: basal ganglia och Parkinsons sjukdom","query":"ninja nerd basal ganglia parkinson disease"}]'::jsonb, '[]'::jsonb, false)
