  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km4-2', 'km4', 'Modul 2', 'Psykiatri', 'Affektiva sjukdomar, psykossjukdomar, ångest och beroende. Fokus ligger på att ställa rätt diagnos utifrån symtomens duration och funktionspåverkan samt på suicidriskbedömning.', 32, 2, '["Mani kräver minst en veckas duration (eller inläggning) med ökad aktivitet och minskat sömnbehov.","Antidepressiv monoterapi vid bipolär sjukdom kan utlösa mani.","OCD kännetecknas av bevarad insikt – till skillnad från psykos.","Delirium tremens är en livshotande abstinenskomplikation med förvirring och autonoma symtom."]'::jsonb, '[{"label":"Ninja Nerd: depression och monoaminhypotesen","query":"ninja nerd depression pathophysiology monoamine"},{"label":"Ninja Nerd: schizofreni och dopaminhypotesen","query":"ninja nerd schizophrenia dopamine hypothesis"}]'::jsonb, '[]'::jsonb, false)
