  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km4-3', 'km4', 'Modul 3', 'Ögonsjukdomar', 'Röda ögon, glaukom, katarakt, makuladegeneration och näthinneavlossning. Fokus ligger på att skilja benigna besvär från synhotande tillstånd som kräver omedelbar handläggning.', 28, 3, '["Metamorfopsi pekar på makulapåverkan.","Akut vinkelblockglaukom är en ögonakut med trycksänkning och ögonläkarkontakt direkt.","Ljusblixtar med växande skuggfält = näthinneavlossning tills motsatsen bevisats.","Katarakt opereras – den botas inte med droppar."]'::jsonb, '[{"label":"Ninja Nerd: ögats anatomi och främre kammare","query":"ninja nerd eye anatomy aqueous humor"},{"label":"Ninja Nerd: glaukom","query":"ninja nerd glaucoma pathophysiology"}]'::jsonb, '[]'::jsonb, false)
