  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km4-4', 'km4', 'Modul 4', 'Öron-, näs- och halssjukdomar', 'Öroninflammationer, hörselnedsättning, yrsel, näsblödning och misstänkta tumörer i huvud-halsregionen. Fokus ligger på att känna igen benigna besvär men också varningssignaler som kräver utredning.', 27, 4, '["Heshet över tre veckor ska utredas med laryngoskopi.","De flesta näsblödningar kommer från plexus Kiesselbachi på septum.","Weber lateralisering till sjuka örat = ledningshinder.","Akut otitis media är oftast virusorsakad eller självläkande."]'::jsonb, '[{"label":"Ninja Nerd: örats anatomi och hörselorganet","query":"ninja nerd ear anatomy hearing physiology"},{"label":"Ninja Nerd: vestibularissystemet och yrsel","query":"ninja nerd vestibular system vertigo"}]'::jsonb, '[]'::jsonb, false)
