INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km4-5', 'km4', 'Modul 5', 'Neurokirurgi', 'Intrakraniella blödningar, höjt intrakraniellt tryck och hydrocefalus. Fokus ligger på att tidigt känna igen den neurokirurgiska akutsituationen och förstå varför tiden är så avgörande.', 26, 5, '["Epiduralt hematom ger linsformad samling och ett kort vaket intervall.","Subduralt hematom korsar suturerna, epiduralt gör det inte.","Thunderclap-huvudvärk ska utredas med DT och vid behov lumbalpunktion.","GCS under 8 motiverar luftvägssäkring."]'::jsonb, '[{"label":"Ninja Nerd: intrakraniellt tryck och hjärnherniering","query":"ninja nerd intracranial pressure herniation"},{"label":"Ninja Nerd: epiduralt och subduralt hematom","query":"ninja nerd epidural subdural hematoma"}]'::jsonb, '[]'::jsonb, false)
