INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km5-1', 'km5', 'Modul 1', 'Barnets normala utveckling', 'Tillväxt, motorik, språk och social utveckling under de första åren, med normalvärden och röda flaggor. Fokus ligger på att kunna avgöra när en avvikelse kräver utredning.', 28, 1, '["Utebliven sittning vid 9 månader ska alltid utredas.","Hörseln kontrolleras först vid försenad språkutveckling.","Telarke inleder puberteten hos flickor, testikelvolym hos pojkar.","Avplanande tillväxtkurva är allvarligare än en låg men parallell kurva."]'::jsonb, '[{"label":"Ninja Nerd: barnets utvecklingsmilstolpar","query":"ninja nerd pediatric developmental milestones"},{"label":"Ninja Nerd: tillväxt och tillväxthormon","query":"ninja nerd growth hormone pediatric growth"}]'::jsonb, '[]'::jsonb, false)
