  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km5-2', 'km5', 'Modul 2', 'Neonatologi', 'Nyföddhetsperiodens anpassning och sjukdomar: andningsstörning hos prematurer, neonatal sepsis, ikterus och hypoglykemi. Fokus ligger på tidiga tecken och på varför nyfödda försämras snabbt.', 30, 2, '["Ikterus inom första dygnet är alltid patologisk.","RDS beror på surfaktantbrist hos prematurer och behandlas med CPAP och surfaktant.","Grupp B-streptokocker och E. coli är vanliga orsaker till neonatal sepsis.","Högt obundet bilirubin kan ge kernikterus."]'::jsonb, '[{"label":"Ninja Nerd: andningssvårigheter hos nyfödda och surfaktant","query":"ninja nerd respiratory distress syndrome newborn surfactant"},{"label":"Ninja Nerd: neonatal ikterus och bilirubin","query":"ninja nerd neonatal jaundice bilirubin"}]'::jsonb, '[]'::jsonb, false)
