  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km5-3', 'km5', 'Modul 3', 'Barninfektioner och vaccinprogrammet', 'Vanliga barninfektioner, deras komplikationer och det svenska vaccinationsprogrammets uppbyggnad. Fokus ligger på att känna igen sjukdomsbilder som vaccinen förebygger och på att inte missa invasiv sjukdom.', 29, 3, '["Kopliks fläckar är patognomona för mässling.","Epiglottit är en luftvägsakut – tvinga aldrig fram en halsundersökning.","Apnéer kan vara det ledande symtomet på kikhosta hos spädbarn.","MPR är ett levande vaccin som ges i två doser."]'::jsonb, '[{"label":"Ninja Nerd: mässling och barnsjukdomar","query":"ninja nerd measles rubella mumps"},{"label":"Ninja Nerd: vacciner och immunisering","query":"ninja nerd vaccines immunology types"}]'::jsonb, '[]'::jsonb, false)
