  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km5-4', 'km5', 'Modul 4', 'Barnmedicinska akutfall', 'Akut andnöd, luftvägsobstruktion, dehydrering och kramper hos barn. Fokus ligger på snabb bedömning av andning och cirkulation samt på åldersspecifika skillnader mot vuxna.', 31, 4, '["RS-virus är den vanligaste orsaken till bronkiolit; behandlingen är stödjande.","Vid total luftvägsobstruktion: ryggslag och buktryck, inte blint fingersök.","Bradykardi hos ett sjukt barn är ett pre-arrest-tecken.","Enkel feberkramp kräver ingen rutinmässig LP."]'::jsonb, '[{"label":"Ninja Nerd: pediatrisk andnöd och bedside-bedömning","query":"ninja nerd pediatric respiratory distress assessment"},{"label":"Ninja Nerd: barnets vätskebalans och dehydrering","query":"ninja nerd pediatric dehydration fluid management"}]'::jsonb, '[]'::jsonb, false)
