  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km6-1', 'km6', 'Modul 1', 'Graviditet och förlossning', 'Den normala graviditetens fysiologi, fostrets övervakning och förlossningens skeden. Fokus ligger på att känna igen avvikande blödning och på akuta förlossningssituationer.', 32, 1, '["Smärtfri blödning sent i graviditeten = placenta previa tills ultraljud visat annat; ingen vaginal undersökning.","Sena decelerationer på CTG talar för placentär insufficiens.","Axelinkärkning löses med McRoberts position och suprapubiskt tryck.","Livmoderatoni är den vanligaste orsaken till postpartumblödning."]'::jsonb, '[{"label":"Ninja Nerd: graviditetens fysiologi och placentan","query":"ninja nerd pregnancy physiology placenta"},{"label":"Ninja Nerd: förlossningens mekanism","query":"ninja nerd labor mechanism stages of delivery"}]'::jsonb, '[]'::jsonb, false)
