  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km6-2', 'km6', 'Modul 2', 'Graviditetskomplikationer', 'Preeklampsi, ektopisk graviditet, graviditetsdiabetes och fosterdöd. Fokus ligger på tidiga varningssymtom och på hur komplikationer påverkar både mor och foster.', 33, 2, '["Magnesiumsulfat ges som krampförebyggande vid svår preeklampsi.","Positivt hCG med tom uterus = misstänkt extrauterin graviditet.","Graviditetsdiabetes screenas med glukosbelastning hos riskpatienter.","Preeklampsi uppstår efter 20 graviditetsveckor."]'::jsonb, '[{"label":"Ninja Nerd: preeklampsi och eklampsi","query":"ninja nerd preeclampsia eclampsia pathophysiology"},{"label":"Ninja Nerd: ektopisk graviditet","query":"ninja nerd ectopic pregnancy"}]'::jsonb, '[]'::jsonb, false)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, code = EXCLUDED.code, title = EXCLUDED.title,
