  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km6-3', 'km6', 'Modul 3', 'Gynekologi', 'Blödningsrubbningar, myom, endometrios och gynekologisk malignitet. Fokus ligger på att utreda avvikande blödning korrekt och på att inte fördröja cancerdiagnostik.', 30, 3, '["Postmenopausal blödning utreds alltid med ultraljud och endometriebiopsi.","Endometrios ger tilltagande dysmenorré, dyspareuni och infertilitet.","Cervixcancer är HPV-driven och screening upptäcker förstadier.","Myom är benigna men kan ge rikliga blödningar och trycksymtom."]'::jsonb, '[{"label":"Ninja Nerd: menstruationscykeln och dess hormoner","query":"ninja nerd menstrual cycle hormones"},{"label":"Ninja Nerd: endometrios","query":"ninja nerd endometriosis pathophysiology"}]'::jsonb, '[]'::jsonb, false)
