INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km6-4', 'km6', 'Modul 4', 'Reproduktionsmedicin och preventivmedel', 'Infertilitetsutredning, PCOS, assisterad befruktning och antikonception med kontraindikationer. Fokus ligger på att välja säkert preventivmedel utifrån patientens riskprofil.', 27, 4, '["Migrän med aura är en kontraindikation för kombinerade preventivmedel.","Klamydia kan ge tubarskada med infertilitet och extrauterin graviditet.","Spermaanalys ingår alltid i infertilitetsutredningen.","PCOS diagnostiseras på två av tre Rotterdam-kriterier."]'::jsonb, '[{"label":"Ninja Nerd: kvinnlig reproduktionscykel och ovulation","query":"ninja nerd female reproductive cycle ovulation"},{"label":"Ninja Nerd: polycystiskt ovariesyndrom","query":"ninja nerd polycystic ovary syndrome"}]'::jsonb, '[]'::jsonb, false)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, code = EXCLUDED.code, title = EXCLUDED.title,
  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km7-1', 'km7', 'Modul 1', 'Cancerbiologi och tumörsjukdomar', 'Från cellcykelns kontrollpunkter till invasion och metastasering. Här tränas begreppen onkogen, tumörsuppressorgen, grad och stadium samt hur cancersymtom presenteras kliniskt.', 32, 1, '["p53 kallas ''genomets väktare'' och är den vanligaste muterade tumörsuppressorgonen.","Knudsons två-hit-hypotes förklarar ärftliga cancerformer.","TNM beskriver utbredning, grad beskriver differentiering.","Angiogenes är en förutsättning för tumörtillväxt över några millimeter."]'::jsonb, '[{"label":"Ninja Nerd: cancerbiologi och onkogener","query":"ninja nerd cancer biology oncogenes tumor suppressor"},{"label":"Ninja Nerd: metastasering och angiogenes","query":"ninja nerd metastasis angiogenesis"}]'::jsonb, '[]'::jsonb, false)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, code = EXCLUDED.code, title = EXCLUDED.title,
  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km7-2', 'km7', 'Modul 2', 'Cancerbehandling: kirurgi, cytostatika och strålning', 'De fyra behandlingsmodaliteterna och deras principer: kirurgi, cytostatika, strålning och målsökande behandling. Fokus ligger på varför behandlingarna ger biverkningar och på begreppen adjuvant, neoadjuvant och palliativ behandling.', 30, 2, '["Cytostatika drabbar alla snabbt delande celler – därav benmärgs- och slemhinnebiverkningar.","Fraktionerad strålning ökar den terapeutiska kvoten.","Adjuvant = efter kirurgi, neoadjuvant = före kirurgi.","R0 innebär radikal resektion utan kvarvarande tumörväxt."]'::jsonb, '[{"label":"Ninja Nerd: cytostatika och cellcykeln","query":"ninja nerd chemotherapy cell cycle"},{"label":"Ninja Nerd: strålbehandling och strålningsbiologi","query":"ninja nerd radiation therapy radiobiology"}]'::jsonb, '[]'::jsonb, false)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, code = EXCLUDED.code, title = EXCLUDED.title,
  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km7-3', 'km7', 'Modul 3', 'Palliativ vård och symtomlindring', 'Palliativ vård av patienter med obotlig sjukdom: smärtlindring, opioidbehandling, andnöd, brytpunktssamtal och stöd till närstående. Fokus ligger på helhetssyn och på att behandla symtom utan att förkorta livet.', 28, 3, '["Total smärta = fysisk, psykisk, social och existentiell komponent.","Tolerans utvecklas inte mot opioidinducerad obstipation – laxantia ges profylaktiskt.","Brytpunktssamtalet klargör vårdens inriktning och patientens önskemål.","Opioider används vid svår smärta oavsett förväntad överlevnad."]'::jsonb, '[{"label":"Ninja Nerd: opioidanalgetika och opioida receptorer","query":"ninja nerd opioid analgesics pharmacology"},{"label":"Ninja Nerd: palliativ vård och smärtbehandling","query":"ninja nerd palliative care pain management"}]'::jsonb, '[]'::jsonb, false)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, code = EXCLUDED.code, title = EXCLUDED.title,
  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('km7-4', 'km7', 'Modul 4', 'Onkologiska akutfall', 'Febril neutropeni, tumörlyssyndrom, spinal kompression och ökat intrakraniellt tryck. Alla är tidskritiska och kan vara första tecknet på en tidigare okänd cancer.', 29, 4, '["Febril neutropeni behandlas med antibiotika utan att invänta odlingssvar.","Tumörlyssyndrom ger hyperkalemi, hyperfosfatemi och hypokalcemi.","Ryggmärgskompression kräver omedelbar MR och kortison.","Kortison minskar peritumört hjärnödem."]'::jsonb, '[{"label":"Ninja Nerd: febril neutropeni och sepsis","query":"ninja nerd febrile neutropenia oncology emergency"},{"label":"Ninja Nerd: tumörlyssyndrom","query":"ninja nerd tumor lysis syndrome"}]'::jsonb, '[]'::jsonb, false)
