  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('mdbi-m1', 'mdbi', 'Modul 1', 'Modul 1 – Analyser och statistisk tolkning m.fl.', 'Laboratoriediagnostik och statistisk tolkning: blodstatus och cellräkning, anemi och leukemi, venprovtagning, hemostas, lever/pancreas/GI-markörer, inflammation samt njure och urindiagnostik.', 40, 1, '["Lågt MCV + lågt ferritin = järnbrist.","Förhöjt anjon-gap = ackumulerad syra (laktat, ketoner, toxiner).","Citratrör används för koagulationsprover."]'::jsonb, '[{"label":"Ninja Nerd: blodstatus och anemi","query":"ninja nerd complete blood count anemia"},{"label":"Ninja Nerd: leverprover","query":"ninja nerd liver function tests"}]'::jsonb, '[{"code":"1.1","title":"Analyser och statistisk tolkning"},{"code":"1.2","title":"Blodstatus och B-celler"},{"code":"1.3","title":"Anemi och leukemi"},{"code":"1.4","title":"Venprovtagning"},{"code":"1.5","title":"Endokrinologi"},{"code":"1.6","title":"Hemostas"},{"code":"1.7","title":"Lever, pancreas och GI-sjukdomar"},{"code":"1.8","title":"Inflammation och proteiner"},{"code":"1.9","title":"Njure och urindiagnostik"}]'::jsonb, false)
