INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('mdbi-m2', 'mdbi', 'Modul 2', 'Modul 2 – EKG m.fl.', 'Hjärtdiagnostik: EKG, ekokardiografi, myokardscintigrafi, DT- och MR-hjärta samt lungfunktionsdiagnostik och val av metod.', 40, 2, '["STEMI = ST-höjning i två angränsande avledningar.","hs-troponin är förstahandsmarkör vid misstänkt infarkt.","Ekoko visar EF, klaffar och perikardvätska."]'::jsonb, '[{"label":"Ninja Nerd: EKG-grunder","query":"ninja nerd ECG interpretation basics"},{"label":"Ninja Nerd: ekokardiografi","query":"ninja nerd echocardiography"}]'::jsonb, '[{"code":"2.1","title":"EKG"},{"code":"2.2","title":"Ekokardiografi"},{"code":"2.3","title":"Myokardscintigrafi"},{"code":"2.4","title":"DT-hjärta"},{"code":"2.5","title":"MR hjärta"},{"code":"2.6","title":"Val av metod vid hjärtdiagnostik"},{"code":"2.7","title":"Kärldiagnostik"},{"code":"2.8","title":"Lungfunktionsdiagnostik"}]'::jsonb, false)
