  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('mdbi-m3', 'mdbi', 'Modul 3', 'Modul 3 – Modaliteter m.fl.', 'Radiologiska modaliteter, strålfysik, remissen och kontrastmedel samt de vanligaste röntgenundersökningarna av neuro, thorax, buk och skelett.', 40, 3, '["DT ger hög stråldos men är snabb och avgörande akut.","Ultraljud är förstahandsval vid gallsten och graviditet.","Absorberad dos mäts i gray, effektiv dos i sievert."]'::jsonb, '[{"label":"Ninja Nerd: röntgen av thorax","query":"ninja nerd chest x ray interpretation"},{"label":"Ninja Nerd: DT och strålsäkerhet","query":"ninja nerd CT scan radiation basics"}]'::jsonb, '[{"code":"3.1","title":"Modaliteter"},{"code":"3.2","title":"Strålfysik"},{"code":"3.3","title":"Remissen"},{"code":"3.4","title":"Kontrast"},{"code":"3.5","title":"De vanligaste röntgenundersökningarna"},{"code":"3.6","title":"Neuro"},{"code":"3.7","title":"Thorax"},{"code":"3.8","title":"Buk"},{"code":"3.9","title":"Skelett"}]'::jsonb, false)
