  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('mdbi-m4', 'mdbi', 'Modul 4', 'Modul 4 – Klinisk mikrobiologi m.fl.', 'Klinisk mikrobiologi, klinisk immunologi och transfusionsmedicin: odling och resistensbestämning, immunologiska analyser samt blodgruppering och transfusion.', 40, 4, '["A har anti-B, B har anti-A, O har båda.","ABO + antikroppsscreening + identitetskontroll före transfusion.","EDTA-rör används för blodstatus."]'::jsonb, '[{"label":"Ninja Nerd: blodgrupper och transfusion","query":"ninja nerd blood groups transfusion reactions"},{"label":"Ninja Nerd: immunologiska tester","query":"ninja nerd immunoassays ELISA"}]'::jsonb, '[{"code":"4.1","title":"Klinisk mikrobiologi"},{"code":"4.2","title":"Klinisk immunologi"},{"code":"4.3","title":"Transfusionsmedicin"}]'::jsonb, false)
