INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('mdbi-m5', 'mdbi', 'Modul 5', 'Modul 5 – Tyreoidea m.fl.', 'Patologi, endokrinologi och hematopatologisk diagnostik: tyreoidea, paratyreoidea, binjure, lunga, skelett, benmärg, akuta buktillstånd och klinisk obduktion.', 40, 5, '["Primär hyperparatyreoidism: högt Ca, lågt fosfat, högt PTH.","Benmärgsbiopsi + flödescytometri krävs vid misstänkt leukemi/lymfom.","FNA är förstahandsmetod vid tyreoideaknöl."]'::jsonb, '[{"label":"Ninja Nerd: tyreoidea – diagnostik","query":"ninja nerd thyroid disorders diagnosis"},{"label":"Ninja Nerd: benmärg och cytopenier","query":"ninja nerd bone marrow biopsy cytopenia"}]'::jsonb, '[{"code":"5.1","title":"Tyreoidea"},{"code":"5.2","title":"Paratyreoidea"},{"code":"5.3","title":"Binjure"},{"code":"5.4","title":"Lunga och Thorax"},{"code":"5.5","title":"Skelett och leder"},{"code":"5.6","title":"Hematopatologisk diagnostik"},{"code":"5.7","title":"Akuta tillstånd i mag-tarmkanalen"},{"code":"5.8","title":"Klinisk obduktion"}]'::jsonb, false)
