INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('mvtm-1', 'mvtm', 'Modul 1', 'Vetenskaplig metod och studiedesign', 'Hur medicinsk kunskap byggs: från frågeställning och studiedesign till systematiska översikter, med fokus på vad varje design kan och inte kan besvara.', 30, 1, '["Randomisering hanterar confounding – även okända confounders.","Fall-kontroll lämpar sig för ovanliga sjukdomar och långa latenstider.","Kohortstudier kan ge incidens och relativ risk; fall-kontroll ger oddskvot.","PRISMA är rapporteringsriktlinjen för systematiska översikter."]'::jsonb, '[{"label":"Ninja Nerd: studiedesigner i medicinsk forskning","query":"ninja nerd study design clinical research"},{"label":"Ninja Nerd: systematiska översikter och metaanalys","query":"ninja nerd systematic review meta analysis"}]'::jsonb, '[]'::jsonb, false)
