  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('mvtm-2', 'mvtm', 'Modul 2', 'Statistik för medicinare', 'Deskriptiv och analytisk statistik, p-värden och konfidensintervall, diagnostisk testteori samt de vanligaste statistiska fällorna i medicinsk litteratur.', 32, 2, '["p-värdet är inte sannolikheten att nollhypotesen är sann.","Ett 95 % konfidensintervall som omfattar noll innebär ingen signifikant skillnad på 5 %-nivån.","PPV beror av prevalensen – sensitivitet och specificitet gör det inte.","Statistisk signifikans är inte samma sak som klinisk relevans."]'::jsonb, '[{"label":"Ninja Nerd: p-värde, konfidensintervall och hypotesprövning","query":"ninja nerd p value confidence interval hypothesis testing"},{"label":"Ninja Nerd: sensitivitet och specificitet","query":"ninja nerd sensitivity specificity predictive value"}]'::jsonb, '[]'::jsonb, false)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, code = EXCLUDED.code, title = EXCLUDED.title,
  summary = EXCLUDED.summary, est_minutes = EXCLUDED.est_minutes, sort_order = EXCLUDED.sort_order,
  facts = EXCLUDED.facts, ninja_topics = EXCLUDED.ninja_topics, sections = EXCLUDED.sections,
  archived = EXCLUDED.archived;
INSERT INTO chapters (id, course_id, code, title, summary, est_minutes, sort_order, facts, ninja_topics, sections, archived)
VALUES ('mvtm-3', 'mvtm', 'Modul 3', 'Evidens, bias och kritiskt läsande', 'Att granska en vetenskaplig artikel systematiskt: bias, evidensgradering enligt GRADE, kausalitetskriterier, publikationsbias och intressekonflikter.', 31, 3, '["Intention-to-treat skyddar randomiseringen; per-protokoll kan överskatta effekten.","GRADE sänker tilliten vid bias, inkonsistens, indirekthet, imprecision och publikationsbias.","Funnel plot används för att misstänka publikationsbias.","Screening kan ge överdiagnostik och lead-time bias – mät mortalitet, inte överlevnadstid."]'::jsonb, '[{"label":"Ninja Nerd: bias i kliniska studier","query":"ninja nerd bias in clinical research"},{"label":"Ninja Nerd: evidensgradering och kritiskt läsande","query":"ninja nerd levels of evidence critical appraisal"}]'::jsonb, '[]'::jsonb, false)
