INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv1-m1-q1', 'bv1-m1', NULL, 'mcq', 'CanMEDS beskriver läkarens sju kompetensroller. Vilket alternativ räknar upp dem korrekt?', '["Medicinsk expert, kommunikatör, samarbetspartner, ledare, hälsoadvokat, forskare och professionell","Medicinsk expert, kirurg, diagnostiker, ledare, lärare, forskare och administratör","Kommunikatör, empatiker, ledare, ekonom, jurist, forskare och kliniker","Medicinsk expert, patientsäkerhet, kvalitet, etik, juridik, ekonomi och ledarskap"]'::jsonb, 'Medicinsk expert, kommunikatör, samarbetspartner, ledare, hälsoadvokat, forskare och professionell', 'CanMEDS sju roller används internationellt för att beskriva läkarkompetens. Medicinsk expert är kärnrollen som de övriga rollerna kretsar kring – de andra alternativen blandar ihop roller med yrkesområden.', 1, 1, 'kapitel', false)
