  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv1-m1-q2', 'bv1-m1', NULL, 'mcq', 'Vilken beskrivning av skillnaden mellan patientlagen och hälso- och sjukvårdslagen (HSL) är korrekt?', '["Patientlagen reglerar patientens rättigheter (information, samtycke, delaktighet); HSL reglerar vårdgivarens ansvar och organisation","Patientlagen reglerar personalens arbetsmiljö; HSL reglerar patientens rättigheter","Patientlagen gäller bara i primärvården; HSL gäller bara på sjukhus","De är två namn på samma lag"]'::jsonb, 'Patientlagen reglerar patientens rättigheter (information, samtycke, delaktighet); HSL reglerar vårdgivarens ansvar och organisation', 'Patientlagen är patientens rättighetslag – information, samtycke, delaktighet och val av utförare. HSL är den struktur- och ansvarslag som ålägger vårdgivaren att ge en god vård på lika villkor.', 1, 2, 'kapitel', false)
