  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv1-m1-q3', 'bv1-m1', NULL, 'cloze', 'Måttet som anger förlorade levnadsår till följd av sjukdom och funktionsnedsättning kallas ______.', NULL, 'DALY', 'DALY (disability-adjusted life years) = förlorade levnadsår på grund av förtidig död plus år levda med funktionsnedsättning. Används för att jämföra sjukdomsbörda mellan länder och diagnoser.', 1, 3, 'kapitel', false)
