  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv1-m2-q1', 'bv1-m2', NULL, 'mcq', 'Vilken organell är platsen för oxidativ fosforylering och har eget maternellt nedärvt DNA?', '["Mitokondrien","Golgiapparaten","Lysosomen","Släta endoplasmatiska retiklet"]'::jsonb, 'Mitokondrien', 'Mitokondrien har eget cirkulärt DNA, ribosomer och inre membran med elektrontransportkedjan. Den ärvs från mor – därför drabbar mitokondriella sjukdomar ofta vävnader med hög energiförbrukning.', 1, 1, 'kapitel', false)
