  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv1-m2-q2', 'bv1-m2', NULL, 'mcq', 'En patient får septisk chock vid en Gramnegativ infektion. Vilken komponent driver det kraftiga immunsvaret?', '["Lipopolysackarid (LPS) i yttre membranet","Tejkolsyra i cellväggen","Peptidoglykan i cytoplasmamembranet","Kapselpolysackarider"]'::jsonb, 'Lipopolysackarid (LPS) i yttre membranet', 'LPS är ett endotoxin som binder TLR4 och utlöser en massiv cytokinfrisättning. Tejkolsyra finns i Grampositiva bakterier, och peptidoglykan ligger utanför membranet – inte i det.', 1, 2, 'kapitel', false)
