  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv1-m2-q3', 'bv1-m2', NULL, 'cloze', 'Organismer vars celler saknar kärnmembran och membranbundna organeller kallas ______.', NULL, 'prokaryoter', 'Prokaryoter (bakterier och arkéer) har ingen cellkärna; DNA ligger fritt i nukleoiden. Eukaryoter har kärna och organeller – svampar, protozoer och maskar är alla eukaryota.', 1, 3, 'kapitel', false)
