  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv1-m3-q1', 'bv1-m3', NULL, 'mcq', 'Vilka är kroppens fyra grundvävnader?', '["Epitel, bindväv, muskel och nervvävnad","Epitel, ben, brosk och blod","Muskel, fett, hud och slemhinna","Nerv, glia, neuron och axon"]'::jsonb, 'Epitel, bindväv, muskel och nervvävnad', 'Alla organ byggs av de fyra grundvävnaderna i olika proportioner. Ben, brosk och blod är specialiserade bindväver – inte egna grundvävnader.', 1, 1, 'kapitel', false)
