INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv1-m3-q2', 'bv1-m3', NULL, 'mcq', 'Vad är skillnaden mellan stroma och parenkym i ett organ?', '["Parenkym är den funktionella cellpopulationen; stroma är stödjevävnaden med kärl och bindväv","Stroma är den funktionella vävnaden; parenkym är bindväv","Parenkym finns bara i epitelorgan","Stroma och parenkym är samma sak"]'::jsonb, 'Parenkym är den funktionella cellpopulationen; stroma är stödjevävnaden med kärl och bindväv', 'I t.ex. levern är hepatocyterna parenkym och bindväv/kärl/sinusoider stroma. Tumörer beskrivs ofta utifrån om de utgår från parenkym eller stroma.', 1, 2, 'kapitel', false)
