INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv1-m3-q3', 'bv1-m3', NULL, 'cloze', 'Den funktionella cellpopulationen i ett organ kallas ______.', NULL, 'parenkym', 'Parenkymet utför organets huvudfunktion, medan stromat ger struktur, blodförsörjning och stöd.', 1, 3, 'kapitel', false)
