INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv1-m4-q1', 'bv1-m4', NULL, 'mcq', 'I vilken ordning passerar en sensorisk impuls från huden till medveten perception?', '["Perifer receptor → ryggmärgen → talamus → somatosensoriska cortex","Perifer receptor → cerebellum → hypotalamus → cortex","Perifer receptor → basala ganglier → ryggmärgen → talamus","Perifer receptor → cortex → talamus → ryggmärgen"]'::jsonb, 'Perifer receptor → ryggmärgen → talamus → somatosensoriska cortex', 'De sensoriska banorna går via ryggmärgen (eller hjärnnerverna) till talamus, som är obligatorisk omslagsstation, och vidare till somatosensoriska cortex. Cerebellum och basala ganglier hör till motoriken.', 1, 1, 'kapitel', false)
