INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv1-m4-q2', 'bv1-m4', NULL, 'mcq', 'Vilken typ av receptor binder fettlösliga hormoner som kortisol och tyreoideahormoner?', '["Intracellulära receptorer som påverkar genuttryck","G-proteinkopplade receptorer i membranet","Jonkanaler i membranet","Enzymkopplade tyrosinkinasreceptorer"]'::jsonb, 'Intracellulära receptorer som påverkar genuttryck', 'Fettlösliga hormoner passerar membranet och binder nukleära receptorer som reglerar transkription – effekten kommer därför långsamt men blir långvarig. Vattenlösliga hormoner binder ytreceptorer.', 1, 2, 'kapitel', false)
