INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv1-m5-q1', 'bv1-m5', NULL, 'mcq', 'Vad kännetecknar det adaptiva immunförsvaret jämfört med det medfödda?', '["Det är specifikt mot en strukturell detalj, har immunologiskt minne och tar dagar att aktivera","Det är snabbt, ospecifikt och saknar minne","Det består enbart av neutrofiler","Det verkar bara mot virus"]'::jsonb, 'Det är specifikt mot en strukturell detalj, har immunologiskt minne och tar dagar att aktivera', 'Adaptiv immunitet bygger på klonal selektion av T- och B-celler med receptorer för en specifik epitop, ger minne och tar därför längre tid – det medfödda svaret är snabbt men ospecifikt.', 1, 1, 'kapitel', false)
