INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv1-m5-q2', 'bv1-m5', NULL, 'mcq', 'En patient utvecklar anafylaxi efter penicillin. Vilket påstående om mekanismen är korrekt?', '["IgE-förmedlad typ I-reaktion med mastcellsdegranulering","Immunkomplexutfällning i kärlväggarna","T-cellsmedierad fördröjd reaktion","Komplementmedierad hemolys"]'::jsonb, 'IgE-förmedlad typ I-reaktion med mastcellsdegranulering', 'Anafylaxi är en typ I-reaktion: allergen korsbinder IgE på mastceller → histaminfrisättning → bronkospasm, hypotoni och urtikaria. Typ II/III/IV är andra mekanismer.', 1, 2, 'kapitel', false)
