INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m1-q1', 'bv2-m1', NULL, 'mcq', 'Vad händer vid G1/S-kontrollpunkten i cellcykeln om DNA:t är skadat?', '["p53 stoppar cykeln så att DNA kan repareras eller cellen går i apoptos","Cellen går direkt in i mitos","Cellen ökar sin proteinsyntes och fortsätter som vanligt","Cellen fusioneras med en grancell"]'::jsonb, 'p53 stoppar cykeln så att DNA kan repareras eller cellen går i apoptos', 'G1/S-kontrollen avgör om cellen ska replikera sitt DNA. p53 aktiverar p21 som hämmar cyklin–CDK-komplexen; kvarstår skadan går cellen i apoptos – en viktig skyddsmekanism mot tumörer.', 1, 1, 'kapitel', false)
