INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m1-q2', 'bv2-m1', NULL, 'mcq', 'Varför behövs telomeras i stamceller och i många tumörceller?', '["Utan telomeras kortas kromosomernas ändar vid varje delning tills cellen slutar dela sig","Telomeras reparerar dubbelsträngsbrott i hela genomet","Telomeras transkriberar rRNA i nukleolen","Telomeras avlägsnar introner från mRNA"]'::jsonb, 'Utan telomeras kortas kromosomernas ändar vid varje delning tills cellen slutar dela sig', 'DNA-polymeras kan inte kopiera allra yttersta änden, så telomererna kortas vid varje delning (Hayflick-gränsen). Telomeras förlänger telomererna och ger obegränsad delningsförmåga – därför är det attraktivt för tumörceller.', 1, 2, 'kapitel', false)
