INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m1-27af8f8a', 'bv2-m1', NULL, 'mcq', 'En patient med ärftlig bröstcancer har en mutation i BRCA1-genen. BRCA1 är involverad i homolog rekombination (HR). Vilken typ av DNA-skada är denna reparationsväg primärt ansvarig för att reparera?', '["Dubbelsträngsbrott","Enkelsträngsbrott","Basmodifieringar","Felaktiga baspar"]'::jsonb, 'Dubbelsträngsbrott', 'Homolog rekombination reparerar dubbelsträngsbrott noggrant med hjälp av systerkromatiden som mall. Enkelsträngsbrott hanteras av BER eller NER, basmodifieringar av BER, och felaktiga baspar av MMR.', 2, 4, 'ai', true)
