INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m1-cc87f92b', 'bv2-m1', NULL, 'mcq', 'En patient med ärftlig icke-polypös kolorektal cancer (Lynch syndrom) har en mutation i en gen som är viktig för DNA-mismatchreparation. Vilken typ av DNA-skada är denna reparationsmekanism primärt ansvarig för att åtgärda?', '["Felaktigt infogade baser under replikationen, så kallade mismatch","Skador orsakade av UV-ljus, såsom tymindimerer","Dubbelsträngsbrott som uppstår vid replikationsstopp","Basförändringar orsakade av alkylerande medel"]'::jsonb, 'Felaktigt infogade baser under replikationen, så kallade mismatch', 'Mismatch repair (MMR) systemet identifierar och reparerar felaktigt parade baser som uppstått under DNA-replikationen. Det vanligaste distraktionsalternativet är UV-ljusinducerade tymindimerer, vilka istället repareras av nukleotid excision repair (NER).', 2, 5, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
