INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m1-fd73bdb2', 'bv2-m1', NULL, 'mcq', 'Under cellcykeln finns kontrollpunkter som säkerställer att DNA är intakt och korrekt replikerat innan cellen går vidare. Vid en skada på DNA:t i G1-fasen stannar cellcykeln upp. Vilket protein är centralt för att blockera cellcykelns fortsättning vid denna skada?', '["p53","Cyclin D","CDK4","Retinoblastomaprotein (Rb)"]'::jsonb, 'p53', 'p53 aktiveras vid DNA-skada och inducerar celcykelstopp genom att bland annat öka uttrycket av CDK-hämmaren p21. Det vanligaste distraktionsalternativet är Cyclin D, som istället driver cellcykeln framåt genom att aktivera CDK4/6.', 2, 6, 'ai', true)
