INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m1-0d72874e', 'bv2-m1', NULL, 'mcq', 'Ett läkemedel som hämmar prokaryota ribosomer används för att behandla en bakterieinfektion. Vilken av följande mekanismer förklarar varför läkemedlet kan hämma bakteriens proteinsyntes utan att påverka patientens egna celler i lika hög grad?', '["Prokaryota ribosomer har en annan struktur än eukaryota, vilket gör att läkemedlet specifikt kan binda till den prokaryota ribosomen.","Prokaryota celler saknar cellkärna, så läkemedlet kan inte tränga in i eukaryota celler.","Eukaryota ribosomer använder en annan genetisk kod, så läkemedlet påverkar inte deras proteinsyntes.","Prokaryota ribosomer är belägna i cellkärnan, dit läkemedlet inte kommer åt i eukaryota celler."]'::jsonb, 'Prokaryota ribosomer har en annan struktur än eukaryota, vilket gör att läkemedlet specifikt kan binda till den prokaryota ribosomen.', 'Prokaryota ribosomer skiljer sig strukturellt från eukaryota, vilket möjliggör selektiv hämning. Det vanligaste distraktionsalternativet är att prokaryota celler saknar cellkärna, vilket inte förklarar den selektiva toxiciteten eftersom läkemedlet verkar på ribosomerna och inte på cellkärnan.', 2, 7, 'ai', true)
