INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m2-q1', 'bv2-m2', NULL, 'mcq', 'Vilken typ av celljunctions möjliggör direkt kommunikation mellan cellers cytoplasma via connexoner?', '["Gap junctions","Tight junctions","Desmosomer","Hemidesmosomer"]'::jsonb, 'Gap junctions', 'Gap junctions bildar kanaler av connexoner som låter joner och små molekyler passera mellan celler – viktigt i hjärtmuskel och glatt muskulatur. Tight junctions förseglar, desmosomer förankrar.', 1, 1, 'kapitel', false)
