INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m2-q2', 'bv2-m2', NULL, 'mcq', 'Natrium-kaliumpumpen flyttar 3 Na+ ut och 2 K+ in per ATP. Vad blir den direkta konsekvensen?', '["Cellens insida blir negativt laddad och vilopotentialen upprätthålls","Cellens insida blir positivt laddad","Kalcium strömmar in i cellen","Vatten lämnar cellen genom aktiv transport"]'::jsonb, 'Cellens insida blir negativt laddad och vilopotentialen upprätthålls', 'Pumpen är elektrogen – fler positiva laddningar förs ut än in – och skapar tillsammans med läckagekanaler vilopotentialen (cirka −70 mV). Den är primär aktiv transport.', 1, 2, 'kapitel', false)
