INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m2-q3', 'bv2-m2', NULL, 'cloze', 'Det kolhydratrika skikt på cellens utsida som bland annat medierar cell-cell-igenkänning kallas ______.', NULL, 'glykocalyx', 'Glykocalyx består av glykoproteiner och glykolipider och skyddar membranet, påverkar adhesion och igenkänning samt fungerar som barriär.', 1, 3, 'kapitel', false)
