INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m2-ed901e5e', 'bv2-m2', NULL, 'mcq', 'Vid sårläkning bildas granulationsvävnad. Vilken extracellulär matrixkomponent är central för att ge denna vävnad dess karaktäristiska struktur och funktion?', '["Kollagen typ I","Fibronektin","Hyaluronan","Laminin"]'::jsonb, 'Hyaluronan', 'Fibronektin är en viktig komponent i granulationsvävnad; det bildar ett tillfälligt matrixnätverk som underlättar cellmigration och proliferation under sårläkningen. Kollagen typ I är den vanligaste kollagenet i hud men är mer karakteristiskt för den senare ärrvävnaden. Hyaluronan är en glykosaminoglykan som finns i matrix men är inte den strukturella komponent som definierar granulationsvävnad. Laminin finns främst i basalmembran och är inte den viktigaste komponenten i granulationsvävnad.', 2, 4, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m2-dbbf8e81', 'bv2-m2', NULL, 'mcq', 'Ett läkemedel som höjer pH i lysosomerna förväntas påverka nedbrytningen av fagocyterat material. Vilken mekanism förklarar detta?', '["Höjningen av pH ökar aktiviteten hos lysosomala hydrolaser.","Höjningen av pH minskar aktiviteten hos lysosomala hydrolaser.","Höjningen av pH ökar fusionen mellan fagosom och lysosom.","Höjningen av pH minskar mängden mannos-6-fosfat på lysosomala enzym."]'::jsonb, 'Höjningen av pH minskar aktiviteten hos lysosomala hydrolaser.', 'Lysosomala hydrolaser är optimerade för sur miljö (lågt pH). Om pH höjs minskar deras aktivitet och nedbrytningen av fagocyterat material försämras. Alternativet att höjt pH skulle öka aktiviteten är fel eftersom hydrolaserna är anpassade till sur miljö. Fusion mellan fagosom och lysosom påverkas inte direkt av pH. Mannos-6-fosfat är en sorteringssignal som redan finns på enzymen och påverkas inte akut av pH-förändringar.', 2, 5, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
