INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m2-a96e6a78', 'bv2-m2', NULL, 'mcq', 'En patient har en medfödd defekt i dyneinarmarna i cilierna. Vilken av följande funktioner förväntas vara mest direkt påverkad?', '["Rörelse av cilier i luftvägarna, eftersom dynein driver cilierörelsen längs mikrotubuli","Kontraktion av skelettmuskulatur, eftersom dynein driver aktin-myosin-interaktionen","Uppbyggnad av mikrovilli i tarmepitel, eftersom dynein tvärbinder aktinfilament","Transport av vesiklar längs mikrotubuli mot cellperiferin, eftersom dynein är det motorprotein som går i plus-riktning"]'::jsonb, 'Rörelse av cilier i luftvägarna, eftersom dynein driver cilierörelsen längs mikrotubuli', 'Dynein är ett motorprotein som rör sig längs mikrotubuli och driver ciliernas slag, så en defekt i dyneinarmarna slår direkt mot cilierörelsen. Det vanligaste distraktionsalternativet är vesikeltransporten mot periferin: den transporten sköts av kinesin (som går mot plus-änden), medan dynein primärt rör sig mot minus-änden.', 2, 6, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
