INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m2-42bc8131', 'bv2-m2', NULL, 'mcq', 'En cell ska transportera ett nybildat lysosomalt enzym från Golgikomplexet till lysosomen. Vilken mekanism är avgörande för att enzymet ska hamna rätt?', '["Mannos-6-fosfat-märkning som känns igen av receptorer i trans-Golgi och sorterar proteinet till lysosomen","Klatrinmärkning direkt på enzymet i det granulära ER, vilket styr det förbi Golgi","Ett signalpeptid som leder till co-translationell transport in i mitokondrien","Glykosylering i det släta ER med efterföljande konstitutiv sekretion via default-vägen"]'::jsonb, 'Mannos-6-fosfat-märkning som känns igen av receptorer i trans-Golgi och sorterar proteinet till lysosomen', 'Lysosomala enzymer märks med mannos-6-fosfat i Golgi och sorteras via receptorer till lysosomen. Det vanligaste distraktionsalternativet är konstitutiv sekretion via default-vägen: den vägen leder proteiner ut ur cellen utan särskild sorteringssignal, och lysosomala enzym behöver just M6P-märkning för att undgå den.', 2, 7, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m2-f45d3b9b', 'bv2-m2', NULL, 'mcq', 'Vid sårläkning bildas ett granulationsvävnad. Vilken roll spelar extracellulär matrix i denna process?', '["ECM ger ett tillfälligt stöd som fibroblaster och kapillärer kan vandra in i, och binder via integriner ihop matrixen med cellernas cytoskelett","ECM fungerar främst som en passiv barriär som hindrar cellmigration tills epitelet är återställt","ECM bryts ned fullständigt i såret och ersätts först sent av kollagen utan cellmedverkan","ECM:s huvudsakliga uppgift i sårläkning är att transportera syre till sårområdet via glykocalyx"]'::jsonb, 'ECM ger ett tillfälligt stöd som fibroblaster och kapillärer kan vandra in i, och binder via integriner ihop matrixen med cellernas cytoskelett', 'ECM bildar en tillfällig matris som celler kan fästa vid och migrera genom, och integriner kopplar matrixen till cytoskelettet så att cellen kan dra sig fram. Det vanligaste distraktionsalternativet är att ECM skulle vara en passiv barriär: tvärtom underlättar den migration, och nedbrytning av matrix (t.ex. av matrixmetalloproteaser) är en del av den dynamiska ombyggnaden, inte ett hinder.', 2, 8, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m2-dc57be35', 'bv2-m2', NULL, 'mcq', 'En patient med en ärftlig sjukdom som påverkar mikrotubuli får symtom från flera organsystem. Vilken av följande cellulära processer är mest direkt beroende av mikrotubuli och deras motorproteiner?', '["Transport av vesiklar från Golgi till plasmamembranen","Kontraktion av muskelceller","Uppbyggnad av cellens kärnlamina","Bildning av cellcellkontakter av typen desmosomer"]'::jsonb, 'Transport av vesiklar från Golgi till plasmamembranen', 'Mikrotubuli fungerar som räls för motorproteinerna kinesin och dynein, vilka transporterar vesiklar mellan organeller och till plasmamembranen. Det vanligaste distraktionsalternativet, kontraktion av muskelceller, är istället beroende av aktin och myosin, inte av mikrotubuli.', 2, 9, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m2-cdfd2335', 'bv2-m2', NULL, 'mcq', 'En cell tar upp extracellulära partiklar genom receptorförmedlad endocytos. Vilken av följande händelser är nödvändig för att vesikeln ska kunna bildas från plasmamembranen?', '["Bindning av COPII-proteiner till membranet","Associering av klatrin och dynamin till membranet","Fusion med lysosomen via SNARE-proteiner","Aktivering av mannos-6-fosfatreceptorer"]'::jsonb, 'Associering av klatrin och dynamin till membranet', 'Vid receptorförmedlad endocytos bildas klatrintäckta vesiklar; dynamin hjälper till att snöra av vesikeln från membranet. COPII är involverad i transport från ER till Golgi, inte i endocytos. Fusion med lysosomen sker efter vesikelbildning och är inte nödvändig för själva bildandet.', 2, 10, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m2-e3e8652b', 'bv2-m2', NULL, 'mcq', 'Vid sårläkning genomgår vävnaden flera faser. Vilken av följande cellulära processer är viktigast för att fibroblaster ska kunna migrera in i sårområdet under den proliferativa fasen?', '["Ökad produktion av kollagen typ IV i basalmembranet","Differentiering av fibroblaster till myofibroblaster","Omdaning av extracellulär matrix av matrixmetalloproteinaser","Uppsättning av täta cellkontakter mellan fibroblaster"]'::jsonb, 'Omdaning av extracellulär matrix av matrixmetalloproteinaser', 'För att fibroblaster ska kunna migrera genom den tillfälliga matrixen krävs nedbrytning av matrixkomponenter av matrixmetalloproteinaser (MMP). Differentiering till myofibroblaster sker senare och bidrar till sårkontraktion, inte till migration. Kollagen typ IV finns i basalmembran och är inte direkt avgörande för fibroblastmigration.', 2, 11, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m2-dcfb1909', 'bv2-m2', NULL, 'mcq', 'En patient med en ärftlig defekt i dynein får problem med clearance av sekret i luftvägarna. Vilken mekanism förklarar detta bäst?', '["Dynein driver retrograd transport längs mikrotubuli och är nödvändigt för ciliens slagriktning och därmed för transporten av sekret","Dynein är ett aktinbundet motorprotein som driver mikrovilliets rörelse och därmed sekretclearance","Dynein är ansvarigt för att fästa celler vid extracellulär matrix via integriner","Dynein driver anterograd transport av vesiklar från ER till Golgi"]'::jsonb, 'Dynein driver retrograd transport längs mikrotubuli och är nödvändigt för ciliens slagriktning och därmed för transporten av sekret', 'Cilier rör sig genom att dynein (ett mikrotubulibundet motorprotein) genererar glidning mellan tubulidubletter, vilket ger slagrörelsen som flyttar sekret. Det vanligaste distraktionsalternativet är att förväxla dynein med ett aktinbundet motorprotein; mikrovilli innehåller aktin men drivs inte av dynein och rör sig inte aktivt på detta sätt.', 2, 12, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m2-8ec39513', 'bv2-m2', NULL, 'mcq', 'En cell ska transportera ett nysyntetiserat protein från Golgi till lysosomen. Proteinet har försetts med mannos-6-fosfat. Vad händer om märkningen uteblir?', '["Proteinet kan inte binda M6P-receptorn i trans-Golgi och sorteras därför inte till lysosomen utan hamnar i konstitutiv sekretion","Proteinet kan inte glykosyleras i Golgi och stannar kvar i det granulära ER","Proteinet kan inte passera kärnporen och stannar i cytoplasman","Proteinet kan inte modifieras i peroxisomen och ansamlas där"]'::jsonb, 'Proteinet kan inte binda M6P-receptorn i trans-Golgi och sorteras därför inte till lysosomen utan hamnar i konstitutiv sekretion', 'Mannos-6-fosfat är den sorteringssignal som M6P-receptorn i trans-Golgi känner igen för transport till lysosomen. Utan märkning sker ingen receptorstyrd sortering och proteinet följer den konstitutiva sekretionsvägen. Det vanligaste distraktionsalternativet är att tro att märkningen behövs för glykosylering i ER; glykosyleringen sker i ER/Golgi oberoende av M6P, som är en sorteringssignal, inte en förutsättning för själva glykosyleringen.', 2, 13, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m2-824013fe', 'bv2-m2', NULL, 'mcq', 'I ett sår sker en tillfällig matrisbildning innan den slutliga ärrvävnaden formas. Vilken sekvens beskriver bäst ECM:s roll i sårläkningen?', '["Fibrin bildar en tillfällig matris som ger celler fäste och vandringsbanor; fibroblaster lägger sedan ned kollagen som mognar till en starkare matrix","Kollagen bryts ned först så att ett tomrum bildas, varefter celler fyller det med fibrin utan inblandning av andra ECM-komponenter","ECM fungerar enbart som passiv fyllnad och påverkar inte cellernas migration eller proliferation","Proteoglykaner hindrar cellmigration och måste avlägsnas helt innan fibroblaster kan vandra in i såret"]'::jsonb, 'Fibrin bildar en tillfällig matris som ger celler fäste och vandringsbanor; fibroblaster lägger sedan ned kollagen som mognar till en starkare matrix', 'Vid sårläkning bildas först en tillfällig fibrinrik matris som ger celler fäste och möjlighet att migrera; därefter producerar fibroblaster kollagen som successivt ersätter och mognar matrisen. Det vanligaste distraktionsalternativet är att se ECM som enbart passiv fyllnad; ECM interagerar via integriner med cytoskelettet och påverkar cellmigration, proliferation och differentiering, vilket är centralt i läkningen.', 2, 14, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
