INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m3-q1', 'bv2-m3', NULL, 'mcq', 'Vid vilken mekanism kan en ektopisk graviditet uppstå?', '["Det befruktade ägget fastnar i äggledaren innan det nått livmodern","Blastocysten implanterar i livmoderbotten istället för bakväggen","Två ägg befruktas samtidigt","Gulkroppen fortsätter producera progesteron för länge"]'::jsonb, 'Det befruktade ägget fastnar i äggledaren innan det nått livmodern', 'Ektopisk graviditet uppstår när implantationen sker utanför livmoderhålan, vanligtvis i tuban. Risker är tubarskada, endometrios och tidigare ektopisk graviditet – tillståndet kan ge tubarruptur med blödning.', 1, 1, 'kapitel', false)
