  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m3-q2', 'bv2-m3', NULL, 'mcq', 'Vad är den viktigaste skillnaden mellan mitos och meios?', '["Meios ger fyra haploida celler med överkorsningar och variation; mitos ger två diploida identiska celler","Mitos ger fyra haploida celler; meios ger två diploida","Båda ger identiska dotterceller men meios går snabbare","Meios sker bara i somatiska celler"]'::jsonb, 'Meios ger fyra haploida celler med överkorsningar och variation; mitos ger två diploida identiska celler', 'Meios har två delningar (reduktionsdelning) och överkorsningar i profas I, vilket ger genetisk variation. Mitos bevarar kromosomtalet och används för tillväxt och reparation.', 1, 2, 'kapitel', false)
