INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m3-q3', 'bv2-m3', NULL, 'cloze', 'Under andra fosterveckan bildas två groddblad som kallas epiblast och ______.', NULL, 'hypoblast', 'Den bilaminära skivan består av epiblast (ovan) och hypoblast (under). Vid gastrulationen bildas sedan de tre groddbladen ektoderm, mesoderm och endoderm.', 1, 3, 'kapitel', false)
