INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m3-036f2c4d', 'bv2-m3', NULL, 'mcq', 'Ett foster aborteras i vecka 12 och karyotypning visar 47,XX,+21. Vilken cellulär mekanism förklarar bäst uppkomsten av denna aneuploidi?', '["En mitotisk nondisjunction i embryots somatiska celler efter befruktningen","En felaktig separation av homologa kromosomer eller systerkromatider under meios, vilket ger en gameter med extra kromosom 21","En överkorsning mellan kromosom 21 och en annan kromosom som skapar en translocation","En mutation i Hox-gener som ändrar segmenteringen längs kroppsaxeln"]'::jsonb, 'En felaktig separation av homologa kromosomer eller systerkromatider under meios, vilket ger en gameter med extra kromosom 21', 'Trisomi 21 uppstår vanligen genom nondisjunction i meios I eller II, så att en äggcell eller spermie bär två kopior av kromosom 21 och zygoten får tre. Det vanligaste distraktionsalternativet – mitotisk nondisjunction efter befruktningen – är fel eftersom det ger mosaik, inte en konstitutionell trisomi som ses i alla celler.', 2, 5, 'ai', true)
