INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv2-m3-b74017cd', 'bv2-m3', NULL, 'mcq', 'Ett nyfött barn har en lumbal missbildning där ryggmärgen och dess hinnor är blottade utanför kroppen, och man konstaterar att neuralröret inte slutits komplett. Vilken av följande strukturer bildas normalt från neurallistceller och kan därför också vara påverkad vid omfattande neurulationsstörningar?', '["Melanocyter i hud och brosk i ansiktsskelettet","Neuralrörets ependymceller","Notokorden","Den sekundära gulesäcken"]'::jsonb, 'Melanocyter i hud och brosk i ansiktsskelettet', 'Neurallistceller vandrar ut från neuralrörets kanter och differentierar bland annat till melanocyter samt brosk och ben i huvud och ansikte, så dessa kan påverkas vid neurulationsstörningar. Det vanligaste distraktionsalternativet – ependymceller i neuralröret – är fel eftersom de härstammar från neuroepiteliet i neuralröret, inte från neurallistcellerna.', 2, 6, 'ai', true)
