INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m4-q1', 'bv2-m4', NULL, 'mcq', 'Vad innebär det att ett enzym har lågt Km för sitt substrat?', '["Hög affinitet – enzymet når halva maxhastigheten vid låg substratkoncentration","Låg affinitet – det krävs hög substratkoncentration","Enzymet är mättat och kan inte öka sin hastighet","Enzymet är kompetitivt hämmat"]'::jsonb, 'Hög affinitet – enzymet når halva maxhastigheten vid låg substratkoncentration', 'Km är substratkoncentrationen vid Vmax/2 och är ett mått på affinitet: lågt Km = hög affinitet. Kompetitiv hämning höjer Km men lämnar Vmax oförändrat.', 1, 1, 'kapitel', false)
