INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m4-q2', 'bv2-m4', NULL, 'mcq', 'Varför är essentiella aminosyror och essentiella fettsyror viktiga att få i sig via kosten?', '["Kroppen kan inte syntetisera dem själv i tillräcklig mängd","De bryts inte ner i tarmen","De behövs bara vid graviditet","De lagras inte i kroppen och utsöndras direkt"]'::jsonb, 'Kroppen kan inte syntetisera dem själv i tillräcklig mängd', 'Essentiella aminosyror (t.ex. lysin, leucin) och essentiella fettsyror (linolsyra, alfa-linolensyra) måste tillföras via kosten eftersom människan saknar enzym för att bilda dem.', 1, 2, 'kapitel', false)
