INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m5-q1', 'bv2-m5', NULL, 'mcq', 'Vilket enzym katalyserar det hastighetsbestämmande steget i glykolysen och hämmas av ATP och citrat?', '["Fosfofruktokinas-1 (PFK-1)","Hexokinas","Pyruvatkinas","Glukos-6-fosfatas"]'::jsonb, 'Fosfofruktokinas-1 (PFK-1)', 'PFK-1 omvandlar fruktos-6-fosfat till fruktos-1,6-bisfosfat och är glykolysens viktigaste reglerande steg – hämmas av ATP/citrat och stimuleras av AMP och fruktos-2,6-bisfosfat.', 1, 1, 'kapitel', false)
