INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m5-q2', 'bv2-m5', NULL, 'mcq', 'En patient fastar i 24 timmar. Vilka substrat använder hjärnan och musklerna främst?', '["Hjärnan är beroende av glukos (och ketonkroppar vid längre fasta); muskler använder fettsyror och ketonkroppar","Hjärnan använder fettsyror direkt, musklerna glukos","Båda använder enbart aminosyror","Båda använder enbart laktat"]'::jsonb, 'Hjärnan är beroende av glukos (och ketonkroppar vid längre fasta); muskler använder fettsyror och ketonkroppar', 'Fettsyror kan inte passera blod-hjärnbarriären i nämnvärd grad. Vid längre fasta bildar levern ketonkroppar som hjärnan kan utnyttja och sparat glukos används till erytrocyter och hjärna.', 1, 2, 'kapitel', false)
