INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m6-q1', 'bv2-m6', NULL, 'mcq', 'En patient med långvarig fasta och diabetes typ 1 har högt p-glukos och hyperventilerar. Varför bildas ketonkroppar?', '["Insulinbrist driver lipolys och levern omvandlar överskott av acetyl-CoA till ketonkroppar","Njurarna bildar ketonkroppar av urea","Ketonkroppar bildas i musklerna vid ansträngning","Ketonkroppar bildas när glukos lagras som glykogen"]'::jsonb, 'Insulinbrist driver lipolys och levern omvandlar överskott av acetyl-CoA till ketonkroppar', 'Utan insulin frisätts fettsyror från fettväven i stor mängd; levern oxiderar dem till acetyl-CoA som överstiger citronsyracykelns kapacitet och omvandlas till acetoacetat och beta-hydroximärat – ketoner som ger metabol acidos.', 1, 1, 'kapitel', false)
