INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m6-q2', 'bv2-m6', NULL, 'mcq', 'Var sker ureacykeln och vilket organ är avgörande för att den fungerar?', '["I leverns mitokondrier och cytoplasma – levern är det centrala organet","I njurarna – njurarna bildar urea av ammoniak","I musklerna – musklerna omvandlar ammoniak till urea","I tarmen – bakterierna bildar urea"]'::jsonb, 'I leverns mitokondrier och cytoplasma – levern är det centrala organet', 'Ureacykeln sker i levern (första steget i mitokondrien, resten i cytoplasman) och omvandlar toxiskt ammoniak till urea som utsöndras via njurarna. Leversvikt ger hyperammonemi.', 1, 2, 'kapitel', false)
