INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m6-q3', 'bv2-m6', NULL, 'cloze', 'Fettsyrornas nedbrytning till acetyl-CoA kallas ______ och sker i mitokondrierna.', NULL, 'beta-oxidation', 'Vid beta-oxidation klyvs två kol i taget från fettsyrans karboxylände, vilket ger acetyl-CoA, NADH och FADH2. Ketonemi uppstår när produktionen överstiger citronsyracykelns kapacitet.', 1, 3, 'kapitel', false)
