INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m7-q1', 'bv2-m7', NULL, 'mcq', 'Varför mäter man HbA1c och vad speglar det?', '["Det speglar medelglukos de senaste 2–3 månaderna eftersom glukos binder till hemoglobin irreversibelt","Det visar blodsockret precis vid provtagningen","Det mäter insulinproduktionen i bukspottkörteln","Det visar hur mycket glykogen levern lagrar"]'::jsonb, 'Det speglar medelglukos de senaste 2–3 månaderna eftersom glukos binder till hemoglobin irreversibelt', 'HbA1c bildas genom icke-enzymatisk glykering av hemoglobin under erytrocytens livslängd (cirka 120 dagar) och används därför för att följa långtidsglukos och diagnostisera diabetes.', 1, 1, 'kapitel', false)
