INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m7-q2', 'bv2-m7', NULL, 'mcq', 'Vilken effekt har GLP-1 som frisätts från tarmen vid måltid?', '["Ökar insulinfrisättningen glukosberoende, hämmar glukagon och saktar magsäckstömningen","Höjer blodglukoset genom att stimulera glukagon","Ökar aptiten och magsäckstömningen","Bryter ner insulin i levern"]'::jsonb, 'Ökar insulinfrisättningen glukosberoende, hämmar glukagon och saktar magsäckstömningen', 'GLP-1 är ett inkretinhormon från L-celler i ileum/kolon som förstärker insulinfrisättningen (inkretineffekten), hämmar glukagon, fördröjer magsäckstömningen och ökar mättnad – grunden för GLP-1-analoger.', 1, 2, 'kapitel', false)
