INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m8-q1', 'bv2-m8', NULL, 'mcq', 'Vilka tre delar ingår i den patientcentrerade konsultationen enligt modellen i kursen?', '["Initiering, den mellersta delen (anamnes, undersökning, förklaring) och avslutning","Anamnes, diagnos och behandling","Insamling, dokumentation och remiss","Hälsning, provtagning och utskrivning"]'::jsonb, 'Initiering, den mellersta delen (anamnes, undersökning, förklaring) och avslutning', 'Modellen delar konsultationen i initiering (skapa kontakt, lyssna på patientens agenda), en mellersta del (anamnes, undersökning, förklaring och planering) samt avslutning (sammanfatta, säkerställa förståelse, nästa steg).', 1, 1, 'kapitel', false)
