INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv2-m8-q2', 'bv2-m8', NULL, 'mcq', 'Varför är basal handhygien den viktigaste åtgärden mot vårdrelaterade infektioner?', '["Händerna är den vanligaste överföringsvägen för mikroorganismer mellan patienter","Handdesinfektion dödar alla bakterier i kroppen","Handskar ersätter behovet av handhygien","Det minskar användningen av antibiotika i hela sjukvården"]'::jsonb, 'Händerna är den vanligaste överföringsvägen för mikroorganismer mellan patienter', 'Kontaktsmitta via händer är den dominerande överföringsvägen. Korrekt handdesinfektion före och efter patientkontakt bryter kedjan – handskar ersätter aldrig handhygien.', 1, 2, 'kapitel', false)
