INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv3-m1-q1', 'bv3-m1', NULL, 'mcq', 'Vilken nerv innerverar diafragman och varifrån utgår den?', '["Nervus phrenicus från C3–C5","Nervus vagus från hjärnstammen","Nervus intercostalis från Th1–Th4","Nervus laryngeus recurrens"]'::jsonb, 'Nervus phrenicus från C3–C5', 'N. phrenicus kommer från plexus cervicalis (C3–C5, ''C3-4-5 keeps the diaphragm alive'') och ger motorisk innervation till diafragma. Skada ger andningspåverkan.', 1, 1, 'kapitel', false)
