INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv3-m1-q2', 'bv3-m1', NULL, 'mcq', 'En patient har domningar i tumme, pek- och långfinger samt svaghet i tummens abduktion. Vilken nerv är sannolikt påverkad?', '["Nervus medianus i karpaltunneln","Nervus ulnaris i sulcus cubitalis","Nervus radialis i axillen","Nervus musculocutaneus"]'::jsonb, 'Nervus medianus i karpaltunneln', 'N. medianus försörjer thenarmusklerna (abductor pollicis brevis) och känseln i tumme/pek/långfinger. Ulnaris påverkar lillfinger och hypothenar, radialis handledsextension.', 1, 2, 'kapitel', false)
