INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv3-m3-q1', 'bv3-m3', NULL, 'mcq', 'En patient som saknar beslutsförmåga behöver akut vård. Vad gäller enligt patientlagen?', '["Vård får ges utan samtycke om det är nödvändigt för att avvärja fara för liv eller allvarlig skada","Ingen vård får ges förrän en anhörig godkänt","Endast polisen kan fatta beslut","Patienten måste alltid skriva på ett samtycke först"]'::jsonb, 'Vård får ges utan samtycke om det är nödvändigt för att avvärja fara för liv eller allvarlig skada', 'När patienten inte kan lämna samtycke och det finns fara för liv eller allvarlig skada får nödvändig vård ges. I övriga fall ska patienten få information och möjlighet att delta så långt det går.', 1, 1, 'kapitel', false)
