INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv3-m3-q2', 'bv3-m3', NULL, 'mcq', 'Vad är en vårdskada enligt patientsäkerhetslagen?', '["Lidande, kroppslig eller psykisk skada eller sjukdom som hade kunnat undvikas om adekvata åtgärder vidtagits","Varje komplikation som uppstår i vården, oavsett orsak","Endast skador som uppstår vid operation","Skada som patienten själv orsakat i hemmet"]'::jsonb, 'Lidande, kroppslig eller psykisk skada eller sjukdom som hade kunnat undvikas om adekvata åtgärder vidtagits', 'Nyckelordet är undvikbarhet – en vårdskada är en skada som hade kunnat förhindras med adekvata åtgärder. Allvarliga vårdskador anmäls enligt lex Maria.', 1, 2, 'kapitel', false)
