INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv3-m3-7bd712e4', 'bv3-m3', NULL, 'mcq', 'En patient med långvarig ryggsmärta har haft flera vårdkontakter utan förbättring. Läkaren överväger att remittera till arbetsplatsinriktad rehabilitering. Vilken mekanism förklarar bäst hur sådana insatser kan främja patientens hälsa och minska behovet av sjukskrivning?', '["De ökar patientens möjlighet att återgå i arbete genom att anpassa arbetsuppgifter och stärka socialt stöd, vilket minskar risken för långtidssjukskrivning.","De fokuserar på att ge patienten ekonomisk kompensation så att denne kan vara sjukskriven längre.","De syftar till att diagnostisera underliggande psykiatriska orsaker till smärtan.","De innebär att patienten får starkare smärtstillande medicin för att kunna arbeta trots smärta."]'::jsonb, 'De ökar patientens möjlighet att återgå i arbete genom att anpassa arbetsuppgifter och stärka socialt stöd, vilket minskar risken för långtidssjukskrivning.', 'Arbetsplatsinriktade insatser syftar till att anpassa arbetsuppgifter och arbetsmiljö samt stärka socialt stöd, vilket underlättar återgång i arbete och minskar behovet av sjukskrivning. Alternativ A är rätt. Det vanligaste distraktionsalternativet är alternativ C, som felaktigt antar att insatserna främst handlar om att diagnostisera psykiatriska orsaker; även om sådana faktorer kan vara relevanta är insatserna primärt inriktade på arbetsanpassning och rehabilitering, inte diagnostik.', 2, 5, 'ai', true)
