INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv4-m1-q1', 'bv4-m1', NULL, 'mcq', 'Vad sker vid aktionspotentialens depolarisering?', '["Spänningsstyrda Na+-kanaler öppnas och Na+ strömmar in i cellen","K+-kanaler öppnas och K+ strömmar in i cellen","Na+-kanaler stängs helt och membranet hyperpolariseras","Kalcium strömmar ut ur cellen"]'::jsonb, 'Spänningsstyrda Na+-kanaler öppnas och Na+ strömmar in i cellen', 'Vid tröskelvärdet öppnas spänningsstyrda Na+-kanaler, Na+ strömmar in och membranet depolariseras snabbt. Repolariseringen sker sedan via K+ utflöde och Na+/K+-pumpen återställer gradienten.', 1, 1, 'kapitel', false)
