INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv4-m1-q2', 'bv4-m1', NULL, 'mcq', 'Hur påverkar myelin och saltatorisk ledning impulshastigheten?', '["Myelin isolerar axonet så att potentialen hoppar mellan noder – ledningshastigheten ökar","Myelin bromsar ledningen så att impulsen går långsammare","Myelin ökar mängden neurotransmittor i terminalen","Myelin bildas av astrocyter i CNS"]'::jsonb, 'Myelin isolerar axonet så att potentialen hoppar mellan noder – ledningshastigheten ökar', 'Myelin sänker den membranens kapacitans och möjliggör saltatorisk ledning mellan Ranviers noder, vilket ger betydligt snabbare överföring. Myelin bildas av oligodendrocyter i CNS och Schwannceller i PNS.', 1, 2, 'kapitel', false)
