INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv4-m2-q1', 'bv4-m2', NULL, 'mcq', 'Var korsar den spinothalamiska banan (smärta/temperatur) till motsatt sida och vilken funktion får det?', '["I ryggmärgens bakre horn på samma nivå som inkomsten – smärta/temperatur uppfattas kontralateralt","I medulla oblongata på samma sida","I talamus på samma sida","Den korsar aldrig"]'::jsonb, 'I ryggmärgens bakre horn på samma nivå som inkomsten – smärta/temperatur uppfattas kontralateralt', 'Spinothalamiska banan korsar omedelbart i ryggmärgen och går via talamus till somatosensoriska cortex – därför ger en halv ryggmärgsskada (Brown-Séquard) kontralateral smärtförlust men ipsilateral beröringsförlust.', 1, 1, 'kapitel', false)
