INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv4-m2-q2', 'bv4-m2', NULL, 'mcq', 'En patient har bitemporal hemianopsi. Var sitter den mest sannolika skadan?', '["I chiasma opticum där de nasala fibrerna korsar","I n. opticus på ena sidan","I synkortex på ena sidan","I corpus geniculatum laterale på ena sidan"]'::jsonb, 'I chiasma opticum där de nasala fibrerna korsar', 'I chiasma korsar de nasala retinala fibrerna, som representerar det temporala synfältet. Skada centralt i chiasma ger bitemporal hemianopsi – typiskt vid hypofystumör.', 1, 2, 'kapitel', false)
