INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv4-m3-q1', 'bv4-m3', NULL, 'mcq', 'En patient har vilotremor, rigidity och bradykinesi. Vilken struktur är primärt drabbad?', '["Substantia nigra pars compacta med dopaminerg degeneration","Cerebellum med Purkinjecellsdegeneration","Motoriska cortex pyramidceller","Ryggmärgens bakre horn"]'::jsonb, 'Substantia nigra pars compacta med dopaminerg degeneration', 'Parkinsons sjukdom beror på förlust av dopaminerga neuron i substantia nigra pars compacta, vilket ger minskad aktivering av direkta vägen och ökad indirekta vägen i basala ganglier – hypoaktiva rörelser med tremor.', 1, 1, 'kapitel', false)
