INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv4-m3-q2', 'bv4-m3', NULL, 'mcq', 'Vilka fynd är typiska vid cerebellär skada?', '["Ataxi, dysmetri och intentionstremor, värre vid rörelse","Vilotremor och rigidity","Spastisk hemipares med Babinski","Snabba ofrivilliga koreatiska rörelser"]'::jsonb, 'Ataxi, dysmetri och intentionstremor, värre vid rörelse', 'Cerebellum koordinerar rörelser och finjusterar timing. Skada ger ipsilateral ataxi, dysdiadokokinesi och intentionstremor – i motsats till basala gangliernas vilotremor.', 1, 2, 'kapitel', false)
