INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv4-m3-q3', 'bv4-m3', NULL, 'cloze', 'En motorisk enhet består av ett α-motorneuron och de ______ det innerverar.', NULL, 'muskelfibrer', 'Motoriska enheten är nervsystemets minsta funktionella rörelseenhet. Ju fler muskelfibrer per motorneuron, desto grövre rörelse (t.ex. gastrocnemius) – få fibrer ger finmotorik (ögat).', 1, 3, 'kapitel', false)
