INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv4-m4-q1', 'bv4-m4', NULL, 'mcq', 'En patient talar hackigt och ansträngt men förstår vad du säger. Vilken skada är mest sannolik?', '["Brocaområdet i vänstra frontalloben","Wernickeområdet i vänstra temporalloben","Höger hörselcortex","Cerebellum"]'::jsonb, 'Brocaområdet i vänstra frontalloben', 'Brocaafasi (motorisk afasi) ger nedsatt talproduktion med bevarad förståelse. Wernickeafasi ger flytande men innehållslöst tal och nedsatt förståelse.', 1, 1, 'kapitel', false)
