INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv4-m4-q2', 'bv4-m4', NULL, 'mcq', 'Vilken struktur är avgörande för att nya deklarativa minnen ska lagras?', '["Hippocampus och omgivande mediala temporallob","Amygdala","Cerebellum","Hypothalamus"]'::jsonb, 'Hippocampus och omgivande mediala temporallob', 'Hippocampus konsoliderar deklarativt (explicit) minne. Skada ger anterograd amnesi (som hos patient HM). Amygdala är central för emotionskoppling, cerebellum för motoriskt minne.', 1, 2, 'kapitel', false)
