VALUES ('bv4-m4-q3', 'bv4-m4', NULL, 'cloze', 'Området i vänstra temporalloben som är centralt för språkförståelse kallas ______ område.', NULL, 'Wernicke', 'Wernickes område (area 22) bearbetar språkförståelse; skada ger flytande afasi med bristande förståelse och neologismer.', 1, 3, 'kapitel', false)
