INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv4-m5-q1', 'bv4-m5', NULL, 'mcq', 'En patient har trötthet, viktuppgång och förstoppning. Prov visar lågt fritt T4 och högt TSH. Vilken är den mest sannolika orsaken?', '["Primär hypotyreos i tyreoidea med kompensatoriskt högt TSH","Sekundär hypotyreos med hypofyssvikt","Tyreotoxikos","Jodförgiftning"]'::jsonb, 'Primär hypotyreos i tyreoidea med kompensatoriskt högt TSH', 'Vid primär hypotyreos sjunker T4 fritt och hypofysen höjer TSH som kompensation. Vid central (sekundär) hypotyreos är både fritt T4 och TSH låga eller inadekvat normala.', 1, 1, 'kapitel', false)
