INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv4-m6-q2', 'bv4-m6', NULL, 'mcq', 'Vilken kranialnerv innerverar mimisk muskulatur och smak från de två bakre tungotredjedelarna?', '["Nervus facialis (VII)","Nervus trigeminus (V)","Nervus glossopharyngeus (IX)","Nervus hypoglossus (XII)"]'::jsonb, 'Nervus facialis (VII)', 'N. facialis ger mimisk muskulatur, smak från de två främre tungotredjedelarna via chorda tympani samt parasympatikus till spottkörtlar. Perifer facialispares ger även påverkan på pannan.', 1, 2, 'kapitel', false)
