INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv5-m1-q1', 'bv5-m1', NULL, 'mcq', 'Varför får ett läkemedel med hög first-pass-metabolism låg biotillgänglighet vid peroral administrering?', '["En stor del bryts ner i lever och tarmvägg innan det når systemcirkulationen","Det binds irreversibelt till albumin och utsöndras via njurarna","Det kan inte passera magsäckens pH","Det utsöndras direkt via gallan utan att verka"]'::jsonb, 'En stor del bryts ner i lever och tarmvägg innan det når systemcirkulationen', 'Efter absorption passerar läkemedlet portavenen till levern där en del metaboliseras (first-pass) innan det når systemcirkulationen – biotillgängligheten blir lägre än 100 procent.', 1, 1, 'kapitel', false)
