INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv5-m1-q2', 'bv5-m1', NULL, 'mcq', 'Hur verkar betalaktamantibiotika (t.ex. penicillin) på bakterier?', '["De hämmar transpeptidaser och därmed cellväggssyntesen","De hämmar bakteriens ribosomer (50S)","De hämmar DNA-gyras","De bildar fria radikaler i bakteriens cytoplasma"]'::jsonb, 'De hämmar transpeptidaser och därmed cellväggssyntesen', 'Betalaktamer binder penicillinbindande protein (PBP/transpeptidas) och blockerar peptidoglykansyntesen – baktericid effekt, särskilt i växande bakterier. Resistens sker ofta via betalaktamas.', 1, 2, 'kapitel', false)
