INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv5-m2-q1', 'bv5-m2', NULL, 'mcq', 'Vad skiljer hjärtmuskelns aktionspotential från skelettmuskelns?', '["Hjärtmuskeln har en platåfas med långsam Ca2+-inflöde via L-typkanaler som förlänger refraktärperioden","Hjärtmuskeln depolariseras av acetylkolin","Skelettmuskeln har längre refraktärperiod","Hjärtmuskeln saknar kalciumkanaler"]'::jsonb, 'Hjärtmuskeln har en platåfas med långsam Ca2+-inflöde via L-typkanaler som förlänger refraktärperioden', 'Platåfasen förhindrar tetani i hjärtat – en livsviktig skillnad mot skelettmuskeln. Kontraktionen utlöses av kalciuminducerad kalciumfrisättning (CICR) från sarkoplasmatiska retiklet.', 1, 1, 'kapitel', false)
