INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv5-m2-q2', 'bv5-m2', NULL, 'mcq', 'Vilken kombination av läkemedel förbättrar överlevnaden vid hjärtsvikt med nedsatt EF?', '["ACE-hämmare/ARB (eller ARNI), betablockerare och MRA","Nitroglycerin och acetylsalicylsyra","Digoxin som enda behandling","Loop-diuretika som enda behandling"]'::jsonb, 'ACE-hämmare/ARB (eller ARNI), betablockerare och MRA', 'Neurohormonell blockad är grunden: ACE-hämmare/ARNI, betablockerare och mineralokortikoidreceptorantagonist minskar mortalitet. Diuretika lindrar symtom men förbättrar inte överlevnaden.', 1, 2, 'kapitel', false)
