INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv5-m3-q1', 'bv5-m3', NULL, 'mcq', 'Vilket steg inleder primär hemostas vid ett kärlskadat område?', '["von Willebrand-faktor medierar trombocytadhesion till subendotelet","Fibrin bildas av trombin","Plasmin bryter ner fibrin","ADP frisätts från endotelceller och stoppar trombocyterna"]'::jsonb, 'von Willebrand-faktor medierar trombocytadhesion till subendotelet', 'Primär hemostas: kärlkontraktion, vWF-medierad adhesion, trombocytaktivering och aggregation (GPIIb/IIIa). Sekundär hemostas är koagulationskaskaden med fibrinbildning.', 1, 1, 'kapitel', false)
