INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv5-m3-q2', 'bv5-m3', NULL, 'mcq', 'Hur kompenserar kroppen ett akut blodtrycksfall?', '["Baroreceptorerna minskar sin hämning av sympatikus → ökad hjärtfrekvens, vasokonstriktion och RAAS-aktivering","Parasympatikus ökar och hjärtfrekvensen stiger","Njurarna utsöndrar mer natrium","Vagustonus ökar och kärlen dilateras"]'::jsonb, 'Baroreceptorerna minskar sin hämning av sympatikus → ökad hjärtfrekvens, vasokonstriktion och RAAS-aktivering', 'Vid tryckfall avlastas baroreceptorerna i carotissinus och arcus aortae, sympatikus ökar (tachycardi, vasokonstriktion) och RAAS aktiveras via renin – allt för att återställa trycket.', 1, 2, 'kapitel', false)
