INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv5-m3-q3', 'bv5-m3', NULL, 'cloze', 'Hormonet som frisätts från binjurebarkens zona glomerulosa och ökar natriumreabsorptionen i njuren kallas ______.', NULL, 'aldosteron', 'Aldosteron styrs av angiotensin II och kalium. Det ökar Na+-reabsorption och K+-utsöndring i distala tubuli och samlingsrör – därför kan loop-diuretika ge sekundär hyperaldosteronism med hypokalemi.', 1, 3, 'kapitel', false)
