INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv5-m3-4eb50e7d', 'bv5-m3', NULL, 'mcq', 'En 45-årig man med levercirros utvecklar ascites. Vilken förändring i Starlingkrafterna över kapillärmembranen är den främsta orsaken till hans ascites?', '["Ökat hydrostatiskt tryck i leverkapillärerna","Minskat kolloidosmotiskt tryck i plasma","Ökad kapillärpermeabilitet för proteiner","Ökat vävnadstryck i bukhålan"]'::jsonb, 'Minskat kolloidosmotiskt tryck i plasma', 'Vid levercirros är albuminsyntesen nedsatt, vilket leder till hypoalbuminemi och minskat kolloidosmotiskt tryck i plasma. Detta minskar vätskeåterresorptionen och leder till ödem/ascites. Det vanligaste distraktionsalternativet är ökat hydrostatiskt tryck i leverkapillärerna, vilket kan bidra vid portal hypertension, men den dominerande mekanismen vid cirros är det minskade onkotiska trycket.', 2, 4, 'ai', true)
