  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv5-m3-72bd5554', 'bv5-m3', NULL, 'mcq', 'En 30-årig kvinna med hereditär sfärocytos genomgår splenektomi. Vilken fördel förväntas avseende hemolys?', '["Minskad hemolys eftersom mjälten är den huvudsakliga platsen för extravaskulär hemolys","Ökad hemolys på grund av förlust av mjältens filtreringsfunktion","Oförändrad hemolys eftersom hemolysen är intravaskulär","Minskad hemolys på grund av ökad produktion av erytropoetin"]'::jsonb, 'Minskad hemolys eftersom mjälten är den huvudsakliga platsen för extravaskulär hemolys', 'Vid hereditär sfärocytos är erytrocyterna sfäriska och mindre deformerbara, vilket leder till att de fastnar i mjältens röda pulpa och genomgår extravaskulär hemolys. Splenektomi minskar hemolysen genom att avlägsna denna plats. Distraktionsalternativet ''ökad hemolys'' är fel eftersom mjälten är den plats där sfärocyter destrueras; att ta bort den minskar hemolysen.', 2, 5, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv5-m3-4d16e877', 'bv5-m3', NULL, 'mcq', 'En 70-årig man med förmaksflimmer insätter warfarinbehandling. Vilken av följande mekanismer förklarar warfarins antikoagulerande effekt?', '["Hämning av vitamin K-epoxidreduktas, vilket minskar regeneration av reducerat vitamin K","Direkt hämning av trombin","Hämning av cyklooxygenas och därmed tromboxansyntes","Aktivering av antitrombin III"]'::jsonb, 'Hämning av vitamin K-epoxidreduktas, vilket minskar regeneration av reducerat vitamin K', 'Warfarin hämmar vitamin K-epoxidreduktas (VKOR), vilket förhindrar regeneration av reducerat vitamin K. Detta leder till minskad gammakarboxylering av vitamin K-beroende koagulationsfaktorer (II, VII, IX, X) och därmed nedsatt koagulation. Distraktionsalternativet ''direkt hämning av trombin'' är fel eftersom det är verkningsmekanismen för direkta orala antikoagulantia som dabigatran, inte warfarin.', 2, 6, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv5-m3-ea376db9', 'bv5-m3', NULL, 'mcq', 'En 72-årig kvinna med känd hjärtsvikt och förmaksflimmer inkommer med akut förvärrad dyspné. Hon har nu högre NT-proBNP än tidigare. Vid lungauskultation hörs bilaterala basala rassel. Vilken mekanism förklarar bäst uppkomsten av lungödem vid hennes tillstånd?', '["Ökat kapillärt hydrostatiskt tryck till följd av vänsterkammarsvikt","Minskat kolloidosmotiskt tryck på grund av hyponatremi","Ökad kapillärpermeabilitet orsakad av inflammation","Lymfatisk obstruktion till följd av förmaksflimmer"]'::jsonb, 'Ökat kapillärt hydrostatiskt tryck till följd av vänsterkammarsvikt', 'Vid vänsterkammarsvikt ökar det hydrostatiska trycket i lungkapillärerna, vilket enligt Starling''s lag leder till ökad filtration och lungödem. Det vanligaste distraktionsalternativet är minskat kolloidosmotiskt tryck, men detta uppstår typiskt vid hypoalbuminemi (t.ex. nefrotiskt syndrom eller leversvikt), inte vid hjärtsvikt, och hyponatremi påverkar inte kolloidosmotiskt tryck nämnvärt.', 2, 7, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv5-m3-e90fc6af', 'bv5-m3', NULL, 'mcq', 'En 28-årig man med hereditär sfärocytos genomgår splenektomi. Före operationen hade han lindrig anemi och retikulocytos. Vilken biokemisk konsekvens av hemolys förklarar hans förhöjda retikulocytantal?', '["Ökad produktion av erytropoetin till följd av minskat syreleverans","Ökad nedbrytning av hem till bilirubin i mjälten","Minskad halt av haptoglobin i plasma","Ökad frisättning av järn från transferrin"]'::jsonb, 'Ökad produktion av erytropoetin till följd av minskat syreleverans', 'Hemolys leder till minskat antal erytrocyter och därmed minskad syretransport, vilket stimulerar njurarna att öka produktionen av erytropoetin som i sin tur ökar erytropoesen och retikulocytantalet. Det vanligaste distraktionsalternativet är ökad nedbrytning av hem till bilirubin, vilket visserligen sker vid hemolys men inte förklarar den ökade retikulocytosen; bilirubinökningen är en konsekvens men inte mekanismen bakom retikulocytos.', 2, 8, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
