INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv5-m3-6bda43e4', 'bv5-m3', NULL, 'mcq', 'En 65-årig kvinna med tidigare djup ventrombos i vänster ben insätts på warfarin. Hon har nu ett INR på 4,5 och små blödningar i hud och slemhinnor. Vilken är den viktigaste mekanismen bakom warfarins antikoagulerande effekt?', '["Hämning av vitamin K-epoxidreduktas, vilket minskar regenerationen av reducerat vitamin K","Direkt hämning av trombin (faktor IIa)","Hämning av cyklooxygenas-1 i trombocyter","Aktivering av antitrombin III"]'::jsonb, 'Hämning av vitamin K-epoxidreduktas, vilket minskar regenerationen av reducerat vitamin K', 'Warfarin hämmar vitamin K-epoxidreduktas (VKOR), vilket förhindrar återbildning av reducerat vitamin K och därmed minskar gammakarboxyleringen av vitamin K-beroende koagulationsfaktorer (II, VII, IX, X). Det vanligaste distraktionsalternativet är direkt hämning av trombin, men det är verkningsmekanismen för dabigatran, en direkt trombinhämmare, inte warfarin.', 2, 9, 'ai', true)
