INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv5-m4-q1', 'bv5-m4', NULL, 'mcq', 'Vad händer med syre-hemoglobinkurvan vid ökad pCO2 och acidos (Bohr-effekten)?', '["Kurvan förskjuts åt höger – hemoglobin släpper syre lättare i vävnaderna","Kurvan förskjuts åt vänster – hemoglobin binder syre hårdare","Kurvan blir helt rak","Hemoglobin börjar transportera koldioxid istället"]'::jsonb, 'Kurvan förskjuts åt höger – hemoglobin släpper syre lättare i vävnaderna', 'Ökad CO2, acidos, temperatur och 2,3-BPG sänker hemoglobins affinitet för syre (högerförskjutning), vilket underlättar avlämning i aktiva vävnader. I lungorna sker motsatsen.', 1, 1, 'kapitel', false)
