  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv5-m4-q2', 'bv5-m4', NULL, 'mcq', 'Vilka celler bildar surfaktant och vad händer om den saknas?', '["Typ II-pneumocyter; utan surfaktant kollapsar alveolerna (atelektas)","Typ I-pneumocyter; utan surfaktant ökar gasutbytet","Alveolmakrofager; utan surfaktant uppstår lungfibros","Slemhinnans bägarceller; utan surfaktant blir slemmet trögflytande"]'::jsonb, 'Typ II-pneumocyter; utan surfaktant kollapsar alveolerna (atelektas)', 'Surfaktant sänker ytspänningen och förhindrar alveolär kollaps. Prematura barn saknar ofta surfaktant (RDS) och behandlas med CPAP och surfaktant.', 1, 2, 'kapitel', false)
