INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv5-m4-q3', 'bv5-m4', NULL, 'cloze', 'Förhållandet mellan ventilation och perfusion i lungan förkortas ______.', NULL, 'V/Q-kvoten', 'V/Q-kvoten är cirka 0,8 i en frisk lunga. Låg V/Q (shunt) ger hypoxemi som inte svarar bra på syrgas; hög V/Q (dead space) ger ventilerade men operfunderade områden.', 1, 3, 'kapitel', false)
