  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv5-m5-q1', 'bv5-m5', NULL, 'mcq', 'Var verkar loop-diuretika och vilken effekt får de?', '["I tjocka uppåtstigande Henles slynga där de hämmar Na+/K+/2Cl− – kraftig diures med hypokalemi","I proximala tubuli där de hämmar glukosreabsorption","I samlingsröret där de blockerar aldosteron","I glomerulus där de ökar filtrationen"]'::jsonb, 'I tjocka uppåtstigande Henles slynga där de hämmar Na+/K+/2Cl− – kraftig diures med hypokalemi', 'Loopen ansvarar för cirka 25 procent av Na+-reabsorptionen, därför blir diuresen kraftig. Kaliumförlust, hypomagnesemi och ototoxicitet är typiska biverkningar. Tiazider verkar i distala tubuli, spironolakton i samlingsröret.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv5-m5-q2', 'bv5-m5', NULL, 'mcq', 'Vad innebär autoregulation av GFR?', '["Njuren håller GFR relativt konstant trots varierande blodtryck via myogen tonus och tubuloglomerulär återkoppling","GFR ökar linjärt med blodtrycket","GFR regleras enbart av ADH","GFR styrs av andningsfrekvensen"]'::jsonb, 'Njuren håller GFR relativt konstant trots varierande blodtryck via myogen tonus och tubuloglomerulär återkoppling', 'Autoregulationen verkar mellan cirka 80 och 180 mmHg: afferent arteriol kontraherar/dilaterar (myogen respons) och macula densa signalerar via tubuloglomerulär återkoppling för att stabilisera filtrationen.', 1, 2, 'kapitel', false)
