INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv5-m5-q3', 'bv5-m5', NULL, 'cloze', 'Andelen plasma som filtreras genom glomeruli per tidsenhet kallas ______.', NULL, 'GFR', 'GFR (glomerulär filtrationshastighet) beror på nettofiltrationstrycket och filtrationsytan. Normalvärdet är cirka 90–120 ml/min hos vuxna och skattas kliniskt med kreatinin/eGFR.', 1, 3, 'kapitel', false)
