  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m1-q1', 'bv6-m1', NULL, 'mcq', 'Vilken egenskap gör ett virus omöjligt att behandla med vanliga antibiotika?', '["Virus är obligat intracellulära och saknar egen cellvägg och metabolism","Virus har en tjock peptidoglykanvägg","Virus är större än bakterier","Virus förökar sig själva i blodet"]'::jsonb, 'Virus är obligat intracellulära och saknar egen cellvägg och metabolism', 'Antibiotika riktar sig mot bakteriella strukturer (cellvägg, ribosomer, DNA-gyras). Virus använder värdcellens maskineri, så antiviral behandling måste rikta sig mot virala enzymer – och vaccination är den viktigaste förebyggande åtgärden.', 1, 1, 'kapitel', false)
