INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m1-q2', 'bv6-m1', NULL, 'mcq', 'Vad kännetecknar en Gramnegativ bakterie i cellväggen?', '["Tunt peptidoglykanlager med yttre membran innehållande lipopolysackarid","Tjockt peptidoglykanlager med tejkolsyra","Ingen cellvägg alls","En cellvägg av cellulosa"]'::jsonb, 'Tunt peptidoglykanlager med yttre membran innehållande lipopolysackarid', 'Gramnegativa bakterier har ett tunt peptidoglykanlager och ett yttre membran med LPS (endotoxin). Grampositiva har tjockt peptidoglykan och tejkolsyra. Mykoplasma saknar cellvägg helt.', 1, 2, 'kapitel', false)
