INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m1-q3', 'bv6-m1', NULL, 'cloze', 'De antibiotika som hämmar bakteriens cellväggssyntes kallas samlingsnamn ______.', NULL, 'betalaktamer', 'Betalaktamer (penicilliner, cefalosporiner, karbapenemer) binder transpeptidaser och hämmar peptidoglykansyntesen – därför verkar de bara på bakterier som växer och bygger cellvägg.', 1, 3, 'kapitel', false)
