INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv6-m1-1a425f52', 'bv6-m1', NULL, 'mcq', 'En patient med en allvarlig gramnegativ bakterieinfektion får ett betalaktamantibiotikum. Behandlingen sviktar och man misstänker att bakterien förvärvat resistensgenen via en bakteriofag. Vilken mekanism beskriver detta bäst?', '["Konjugation, där plasmid-DNA överförs via en sexpili","Transformation, där fritt DNA från en död bakterie tas upp","Transduktion, där fagen bär med sig bakterie-DNA mellan bakterier","Mutation, där en punktmutation i genomet ger resistens"]'::jsonb, 'Transduktion, där fagen bär med sig bakterie-DNA mellan bakterier', 'Transduktion innebär att en bakteriofag felaktigt paketerar bakterie-DNA (inklusive resistensgener) och överför det till en ny bakterie vid nästa infektion – det stämmer med scenariot där fagen är inblandad. Det vanligaste distraktionsalternativet, konjugation, är fel eftersom det sker via direkt cellkontakt och plasmidöverföring, inte via en fag.', 2, 4, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m2-q1', 'bv6-m2', NULL, 'mcq', 'En patient återvänder från Västafrika med feber, frossa och ikterus. Blodutstryk visar ringformade trofozoiter. Vilken behandling är indicerad vid svår malaria?', '["Intravenöst artesunat (artemisinin-baserad behandling)","Oseltamivir","Bensylpenicillin","Aciklovir"]'::jsonb, 'Intravenöst artesunat (artemisinin-baserad behandling)', 'Svår malaria (ofta Plasmodium falciparum) behandlas med intravenöst artesunat. Vid okomplicerad malaria används peroral ACT (artemisinin-baserad kombinationsterapi). Oseltamivir är antiviral mot influensa.', 1, 1, 'kapitel', false)
