INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m2-q2', 'bv6-m2', NULL, 'mcq', 'Varför behandlas tuberkulos med flera läkemedel samtidigt?', '["För att förebygga resistensutveckling och döda olika subpopulationer av bakterier","För att minska biverkningarna av enskilda läkemedel","För att förkorta behandlingen till några dagar","För att vaccinet ska fungera bättre"]'::jsonb, 'För att förebygga resistensutveckling och döda olika subpopulationer av bakterier', 'Kombinationsbehandling (typiskt rifampicin, isoniazid, pyrazinamid och etambutol) krävs eftersom mutationer för resistens förekommer spontant och bakterierna har olika tillväxtfaser. Behandlingen är lång, ofta 6 månader.', 1, 2, 'kapitel', false)
