INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m2-q3', 'bv6-m2', NULL, 'cloze', 'Malaria överförs av myggor av släktet ______.', NULL, 'Anopheles', 'Anopheleshonan överför Plasmodium vid blodmål. Förebyggande: myggnät med insekticid, repellent och i vissa fall kemoprofylax.', 1, 3, 'kapitel', false)
