INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv6-m2-586fc38d', 'bv6-m2', NULL, 'mcq', 'En 34-årig man som nyligen anlänt från ett land i subsahariska Afrika söker på vårdcentral med återkommande feberperioder, förstorad mjälte och progressiv trötthet. Blodprov visar långsamt stigande parasitemi med extracellulära flagellater i blodet. Vilken patogenetisk mekanism förklarar bäst att sjukdomen kan pågå i månader till år utan att patienten avlider, till skillnad från vid malaria?', '["Parasiten genomgår kontinuerligt antigen variation av sitt ytglykoprotein, vilket möjliggör återkommande vågor av parasitemi och undandragande av immunförsvaret","Parasiten bildar dormanta hypnozoiter i levern som reaktiveras periodiskt och orsakar feberattacker","Parasiten invaderar och förstör röda blodkroppar synkront, vilket ger cykliska febertoppar varannan eller var tredje dag","Parasiten bildar cystor i hjärnan som gradvis expanderar och ger långsam symptomdebut"]'::jsonb, 'Parasiten genomgår kontinuerligt antigen variation av sitt ytglykoprotein, vilket möjliggör återkommande vågor av parasitemi och undandragande av immunförsvaret', 'Afrikansk sömnsjuka (Trypanosoma brucei) kännetecknas av successiv antigen variation av variant surface glycoprotein (VSG), vilket låter parasiten undkomma immunförsvaret och ge återkommande febervågor under lång tid. Det vanligaste distraktionsalternativet är hypnozoiter, men dessa är specifika för Plasmodium vivax/ovale och hör inte till trypanosomerna.', 2, 4, 'ai', true)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
