  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m3-q1', 'bv6-m3', NULL, 'mcq', 'En patient får blodig diarré och buksmärta efter en antibiotikakur. Vilken diagnos och orsak är mest sannolik?', '["Clostridioides difficile-kolit efter rubbad tarmflora","Campylobacter-enterit av antibiotikan","Laktosintolerans","Akut appendicit"]'::jsonb, 'Clostridioides difficile-kolit efter rubbad tarmflora', 'Bredspektrumantibiotika slår ut normalfloran så att C. difficile kan kolonisera och bilda toxiner (A och B) – ger pseudomembranös kolit. Behandling: stoppa onödig antibiotika och ge oralt vankomycin eller fidaxomicin.', 1, 1, 'kapitel', false)
