  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m3-q2', 'bv6-m3', NULL, 'mcq', 'Varför ska levande vaccin oftast inte ges till immunsupprimerade patienter?', '["Det försvagade vaccinviruset kan orsaka allvarlig infektion när immunförsvaret är nedsatt","Vaccinet ger ingen effekt alls","Det orsakar alltid allergiska reaktioner","Det kan inte förvaras i kylskåp"]'::jsonb, 'Det försvagade vaccinviruset kan orsaka allvarlig infektion när immunförsvaret är nedsatt', 'Levande vaccin (mässling, påssjuka, röda hund, gula febern, BCG) kräver ett fungerande immunförsvar för att kontrolleras. Vid immunosuppression används i stället inaktiverade vaccin när sådana finns.', 1, 2, 'kapitel', false)
