INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m3-q3', 'bv6-m3', NULL, 'cloze', 'Enzymet som vissa resistenta bakterier producerar för att bryta ner penicillin kallas ______.', NULL, 'betalaktamas', 'Betalaktamas hydrolyserar betalaktamringen. Kombinationer med betalaktamashämmare (klavulansyra, tazobaktam) eller karbapenemer används vid betalaktamasproducerande bakterier (t.ex. ESBL).', 1, 3, 'kapitel', false)
