INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m4-q1', 'bv6-m4', NULL, 'mcq', 'Ett barn har feber, koppliknande utslag i olika stadier och kliande hud. Vad är diagnosen?', '["Vattkoppor (varicella-zoster)","Mässling","Röda hund","Scharlakansfeber"]'::jsonb, 'Vattkoppor (varicella-zoster)', 'Vattkoppor ger utslag i olika utvecklingsstadier (makula, vesikel, krusta) samtidigt. Mässling ger katarrala symtom och Kopliks fläckar; röda hund ger tätt utslag och lymfadenopati.', 1, 1, 'kapitel', false)
