INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m4-q2', 'bv6-m4', NULL, 'mcq', 'Vilken bakterie är vanligaste orsak till erysipelas (rosfeber) i huden?', '["Streptococcus pyogenes (grupp A-streptokocker)","Staphylococcus aureus","Pseudomonas aeruginosa","Clostridium perfringens"]'::jsonb, 'Streptococcus pyogenes (grupp A-streptokocker)', 'Erysipelas orsakas oftast av grupp A-streptokocker och ger ett skarpt avgränsat, varmt och rött område, ofta med feber. Behandlas med penicillin. Stafylokocker dominerar vid abscesser och impetigo.', 1, 2, 'kapitel', false)
