INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m4-q3', 'bv6-m4', NULL, 'cloze', 'Röda hund (rubella) är särskilt farlig om en icke-immunicerad kvinna smittas under ______.', NULL, 'graviditeten', 'Rubella under tidig graviditet ger kongenitalt rubellasyndrom med hörselnedsättning, katarakt och hjärtmissbildningar – därför kontrolleras immunitet och MMR-vaccination rekommenderas före graviditet.', 1, 3, 'kapitel', false)
