INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-bv6-m4-65a7098c', 'bv6-m4', NULL, 'mcq', 'En 4-årig pojke kommer till vårdcentralen med feber, halsont och ett utslag som börjar i ansiktet och sprider sig nedåt kroppen. Utredningen visar senare att orsaken är ett virus som tillhör familjen Paramyxoviridae. Vilken patogen är den mest sannolika orsaken till pojkens symtom?', '["Parainfluensavirus","Mässlingsvirus","Epstein-Barr-virus","Humant metapneumovirus"]'::jsonb, 'Mässlingsvirus', 'Mässlingsvirus tillhör Paramyxoviridae och ger feber, luftvägssymtom och ett exantem som typiskt börjar i ansiktet och sprider sig nedåt – det passar väl med barn- och exantemsjukdomarna i lärandemålen. Parainfluensavirus är det vanligaste distraktionsalternativet eftersom det också är ett Paramyxoviridae-virus som ger luftvägsinfektion, men det ger inte det klassiska mässlingsutslaget; dess sjukdomsbild är snarare krupp eller övre luftvägsinfektion.', 2, 4, 'ai', true)
