INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m5-q1', 'bv6-m5', NULL, 'mcq', 'En ung patient har feber, nackstyvhet och petekier. Vilken åtgärd är mest angelägen?', '["Omedelbar behandling med cefalosporin (och vid misstanke meningokock: även droppsmittsisolering) innan diagnos är klar","Vänta på spinalvätskesvaret innan behandling","Ge antiviralt medel mot herpes simplex","Ge smärtstillande och skicka hem patienten"]'::jsonb, 'Omedelbar behandling med cefalosporin (och vid misstanke meningokock: även droppsmittsisolering) innan diagnos är klar', 'Bakteriell meningit är akut livshotande; behandling får inte fördröjas av diagnostik. Petekier talar för Neisseria meningitidis – droppsmittsisolering i 24 timmar och profylax till nära kontakter.', 1, 1, 'kapitel', false)
