INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m5-q2', 'bv6-m5', NULL, 'mcq', 'Vilken celltyp angrips primärt av HIV och vad är den viktigaste konsekvensen?', '["CD4+ T-hjälparceller – förlust leder till opportunistiska infektioner","Erytrocyter – ger anemi","Neutrofiler – ger neutropeni","B-celler – ger agammaglobulinemi"]'::jsonb, 'CD4+ T-hjälparceller – förlust leder till opportunistiska infektioner', 'HIV binder CD4 och CCR5/CXCR4 på hjälpar-T-celler och makrofager. När CD4-talet sjunker under cirka 200 celler/µl ökar risken för opportunistiska infektioner (PCP, toxoplasmos, candidiasis).', 1, 2, 'kapitel', false)
