INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('bv6-m5-q3', 'bv6-m5', NULL, 'cloze', 'Bakterien som ger purulent meningit med petekier och kan ge Waterhouse-Friderichsens syndrom är ______.', NULL, 'Neisseria meningitidis', 'Meningokocker kan ge snabb sepsis med binjureblödning (Waterhouse-Friderichsen). Vaccin mot vanliga serogrupper ingår i barnvaccinationsprogrammet.', 1, 3, 'kapitel', false)
