INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-1-q1', 'km1-1', NULL, 'mcq', 'En 72-årig man inkommer med feber 39,2 °C, blodtryck 82/48 mmHg, puls 118/min, varma perifera extremiteter och laktat 4 mmol/L vid misstänkt urinvägsinfektion. Vilken chocktyp föreligger?', '["Distributiv chock (septisk)","Kardiogen chock","Hypovolem chock","Obstruktiv chock"]'::jsonb, 'Distributiv chock (septisk)', 'Septisk chock är distributiv: uttalad vasodilatation ger lågt systemiskt kärlmotstånd med kompensatorisk takykardi och initialt varma extremiteter. Kardiogen chock har i stället högt fyllnadstryck med lungödem, och hypovolem chock svarar snabbt på volymtillförsel.', 1, 1, 'kapitel', false)
