INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-1-q2', 'km1-1', NULL, 'mcq', 'En traumapatient försämras akut med ensidig avsaknad av andningsljud, distenderade halsvener, hypotension och trakealförskjutning. Vilken åtgärd ska vidtas omedelbart?', '["Dekompression av pleurahålan med nål","Akut datortomografi av thorax före behandling","Inhalation av kortverkande beta2-agonist","Intravenös volymbelastning som enda åtgärd"]'::jsonb, 'Dekompression av pleurahålan med nål', 'Spänningsthorax är en klinisk diagnos där det övertryckta pleurarummet hindrar venöst återflöde och ger obstruktiv chock. Nål­dekompression får inte fördröjas av bilddiagnostik; därefter anläggs thoraxdrän.', 1, 2, 'kapitel', false)
