INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-1-q3', 'km1-1', NULL, 'mcq', 'En 60-årig man drabbas av hjärtstopp på en restaurang. Vilken åtgärd har störst betydelse för överlevnaden?', '["Tidiga bröstkompressioner och tidig defibrillering","Intubering innan kompressioner påbörjas","Adrenalin som första åtgärd","Snabb transport till sjukhus utan kompressioner"]'::jsonb, 'Tidiga bröstkompressioner och tidig defibrillering', 'Cirkulationen måste upprätthållas direkt; kompressioner ger kvarstående perfusion av hjärna och hjärta. Vid shockbar rytm (VF/pulslös VT) är defibrillering den avgörande åtgärden, medan läkemedel och avancerad luftväg kommer efter basal HLR.', 1, 3, 'kapitel', false)
