INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-1-q4', 'km1-1', NULL, 'cloze', 'En patient med anafylaxi, stridor och blodtryck 70/40 mmHg får som första läkemedelsbehandling intramuskulärt ______.', NULL, 'adrenalin', 'Adrenalin motverkar både bronkospasm och vasodilatation och ges intramuskulärt i låret. Antihistamin och glukokortikoid är tilläggsbehandling som inte häver den akuta luftvägsobstruktionen.', 1, 4, 'kapitel', false)
