INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-2-q1', 'km1-2', NULL, 'mcq', 'En 66-årig man med 40 minuters bröstsmärta har ST-höjning i avledningarna II, III och aVF. Vilket kärl är oftast ockluderat?', '["Höger kranskärl (RCA)","Vänster kranskärls framväggsgren (LAD)","Vänster cirkumflexa (LCx)","Vänster huvudstam"]'::jsonb, 'Höger kranskärl (RCA)', 'Avledningarna II, III och aVF speglar inferiorväggen, som vanligen försörjs av höger kranskärl. Vid inferior infarkt ska nitrater ges med stor försiktighet eftersom samtidig högerkammarinfarkt gör patienten volymberoende; ST-höjning i V1–V4 talar i stället för LAD-ocklusion.', 1, 1, 'kapitel', false)
