INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-2-q2', 'km1-2', NULL, 'mcq', 'En 78-årig kvinna har dyspné, ortopné, basala rassel och halsvenstas. Ekokardiografi visar ejektionsfraktion 30 %. Vilken behandling förbättrar prognosen vid hjärtsvikt med nedsatt ejektionsfraktion?', '["ACE-hämmare eller ARB i kombination med betablockerare, MRA och SGLT2-hämmare","Enbart loopdiuretika i fast dos","Digoxin som monoterapi","Kalciumflödeshämmare av dihydropyridintyp"]'::jsonb, 'ACE-hämmare eller ARB i kombination med betablockerare, MRA och SGLT2-hämmare', 'De fyra behandlingspelarna hämmar RAAS, sympatikus och natriumglukostransport och reducerar mortaliteten. Loopdiuretika lindrar kongestion men förbättrar inte överlevnaden, och dihydropyridiner kan försämra hjärtsvikt.', 1, 2, 'kapitel', false)
