INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-2-q3', 'km1-2', NULL, 'mcq', 'En 74-årig man har oregelbunden puls, EKG utan P-vågor och oregelbundet RR-intervall. Vilken behandling är viktigast för att förebygga stroke?', '["Antikoagulation med DOAK eller warfarin efter riskbedömning","Betablockerare för frekvenskontroll","Digitalis","Acetylsalicylsyra som monoterapi"]'::jsonb, 'Antikoagulation med DOAK eller warfarin efter riskbedömning', 'Förmaksflimmer ger stas i förmaket med trombbildning som kan embolisera till hjärnan; antikoagulation förebygger detta och risken skattas med CHA2DS2-VASc. Frekvenskontroll lindrar symtom men påverkar inte strokerisken, och acetylsalicylsyra har otillräcklig skyddseffekt.', 1, 3, 'kapitel', false)
