INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-2-q4', 'km1-2', NULL, 'cloze', 'Troponin T och troponin I är specifika markörer för ______ och stiger vid akut koronart syndrom.', NULL, 'myokardskada', 'Troponinerna frigörs från skadade kardiomyocyter och är mer specifika än CK-MB. Förhöjning utan ischemiska symtom eller EKG-förändringar talar för annan orsak till myokardskada, till exempel takykardi eller njursvikt.', 1, 4, 'kapitel', false)
