INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-3-q1', 'km1-3', NULL, 'mcq', 'En 24-årig kvinna har gått ner i vikt, har tremor, takykardi, struma och värmeintolerans. TSH är lågt och fritt T4 högt. Vad är den bakomliggande mekanismen?', '["TSH-receptorstimulerande antikroppar (TRAK)","Antikroppar som förstör tyreoideacellerna","Ökad TSH-sekretion från hypofysen","Jodbrist"]'::jsonb, 'TSH-receptorstimulerande antikroppar (TRAK)', 'Vid Graves sjukdom stimulerar TRAK TSH-receptorn, vilket ger både ökad hormonproduktion och struma. Ett högt TSH skulle i stället tala för sekundär hypertyreos, och jodbrist ger vanligen struma med normal eller sänkt funktion.', 1, 1, 'kapitel', false)
