INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-3-q2', 'km1-3', NULL, 'mcq', 'En 58-årig överviktig man får diagnosen typ 2-diabetes. HbA1c ligger över målet trots livsstilsåtgärder. Han har normal njurfunktion och ingen känd hjärt-kärlsjukdom. Vilket läkemedel är förstahandsval?', '["Metformin","Sulfonureid","Insulin","DPP-4-hämmare"]'::jsonb, 'Metformin', 'Metformin minskar hepatisk glukosproduktion och har god effekt utan hypoglykemirisk eller viktuppgång. Sulfonureider ger hypoglykemi och viktökning; vid etablerad hjärt-kärlsjukdom kompletteras i stället med SGLT2- eller GLP-1-behandling.', 1, 2, 'kapitel', false)
