INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-3-q3', 'km1-3', NULL, 'mcq', 'En 45-årig kvinna söker för trötthet, viktuppgång, köldkänsla, förstoppning och bradykardi. TSH är högt och fritt T4 lågt. Vilken behandling är förstahandsval?', '["Levotyroxin (T4) med dosjustering utifrån TSH","Liothyronin (T3) som monoterapi","Radiojodbehandling","Tyreostatika"]'::jsonb, 'Levotyroxin (T4) med dosjustering utifrån TSH', 'Primär hypotyreos substitueras med levotyroxin och dosen titreras mot TSH. T3-monoterapi ger fluktuerande hormonnivåer, medan radiojod och tyreostatika används vid hypertyreos.', 1, 3, 'kapitel', false)
