INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-3-q4', 'km1-3', NULL, 'cloze', 'En patient med hyperpigmentering, ortostatisk hypotension, hyponatremi och hyperkalemi misstänks ha primär binjurebarksinsufficiens. Det prov som då är förhöjt är ______.', NULL, 'ACTH', 'Lågt kortisol ger via negativ återkoppling högt ACTH, som driver melanokortinreceptorer och orsakar hyperpigmentering – typiskt för Addisons sjukdom. Vid sekundär insufficiens är ACTH lågt eller normalt och hyperpigmentering saknas.', 1, 4, 'kapitel', false)
