INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-4-q1', 'km1-4', NULL, 'mcq', 'En 28-årig kvinna har återkommande pipande andning, nattlig hosta och variabla symtom. Spirometri visar reversibel luftvägsobstruktion. Vilken underhållsbehandling är förstahandsval?', '["Inhalationssteroider, vid behov i kombination med långverkande beta2-agonist","Enbart kortverkande beta2-agonist vid behov","Perorala glukokortikoider i underhållsbehandling","Långverkande beta2-agonist som monoterapi"]'::jsonb, 'Inhalationssteroider, vid behov i kombination med långverkande beta2-agonist', 'Astma är en eosinofil luftvägsinflammation och grundbehandlingen är inhalationssteroider. Enbart beta2-agonist lindrar symtomen men lämnar inflammationen obehandlad, och LABA som monoterapi vid astma är kontraindicerat på grund av ökad risk för svåra exacerbationer.', 1, 1, 'kapitel', false)
