  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-4-q2', 'km1-4', NULL, 'mcq', 'En 62-årig rökare har kronisk hosta med upphostningar och progredierande dyspné. Spirometri visar FEV1/FVC under 0,7 efter bronkdilatation. Vilken åtgärd har störst effekt på sjukdomsförloppet?', '["Rökstopp","Kontinuerlig peroral glukokortikoid","Rutinmässig antibiotikabehandling","Betablockerare i låg dos"]'::jsonb, 'Rökstopp', 'Rökstopp är den enda åtgärd som bromsar den accelererade förlusten av lungfunktion vid KOL. Perorala steroider ges vid exacerbation, inte som underhåll, och antibiotika är indicerat vid infektiös exacerbation med ökad sputumproduktion eller purulens.', 1, 2, 'kapitel', false)
