INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-4-q3', 'km1-4', NULL, 'mcq', 'En 34-årig kvinna får tio minuter efter ett jordnötsintag generaliserad urtikaria, stridor och blodtryck 75/40 mmHg. Vilken behandling ska ges först?', '["Intramuskulärt adrenalin","Intravenöst antihistamin som enda behandling","Perorala glukokortikoider","Nebuliserad beta2-agonist som enda åtgärd"]'::jsonb, 'Intramuskulärt adrenalin', 'Adrenalin häver både bronkospasm, slemhinneödem och vasodilatation och ges intramuskulärt i låret. Antihistamin och glukokortikoid verkar långsamt och påverkar inte luftvägsobstruktionen akut; beta2-agonist är bara ett komplement vid kvarstående bronkospasm.', 1, 3, 'kapitel', false)
