INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-4-q4', 'km1-4', NULL, 'cloze', 'Vid misstänkt lungemboli och låg klinisk sannolikhet kan diagnosen uteslutas med ett normalt ______.', NULL, 'D-dimer', 'D-dimer har hög sensitivitet men låg specificitet och kan bara användas för att utesluta lungemboli vid låg eller måttlig klinisk sannolikhet. Vid hög sannolikhet eller positivt D-dimer görs datortomografi med lungemboliprotokoll.', 1, 4, 'kapitel', false)
