INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-5-q1', 'km1-5', NULL, 'mcq', 'En 72-årig man med kräkningar och diarré har kreatinin 210 µmol/L, kalium 6,6 mmol/L och breddat QRS på EKG. Vilken åtgärd ska ges först?', '["Kalciumglukonat intravenöst","Insulin-glukos intravenöst","Loopdiuretika intravenöst","Peroral kalciumbindare"]'::jsonb, 'Kalciumglukonat intravenöst', 'Kalcium stabiliserar myokardmembranen och motverkar arytmi inom minuter men sänker inte kaliumvärdet. Därefter ges insulin-glukos och inhalationssalbutamol för att flytta kalium intracellulärt, kalciumbindare för elimination och dialys vid refraktär hyperkalemi.', 1, 1, 'kapitel', false)
