INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-5-q2', 'km1-5', NULL, 'mcq', 'En 55-årig kvinna har uttalade perifera ödem, proteinuri 5 g/dygn och lågt serumalbumin. Vilket syndrom föreligger?', '["Nefrotiskt syndrom","Nefritiskt syndrom","Akut tubulär nekros","Prerenal azotemi"]'::jsonb, 'Nefrotiskt syndrom', 'Proteinuri över 3,5 g/dygn med hypoalbuminemi och ödem definierar nefrotiskt syndrom, där glomerulär filtration blir genomsläpplig för protein. Nefritiskt syndrom kännetecknas i stället av hematuri, hypertoni och salt- och vattenretention.', 1, 2, 'kapitel', false)
