INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-5-q3', 'km1-5', NULL, 'mcq', 'En 68-årig man med typ 2-diabetes har eGFR 32 ml/min/1,73 m² och albuminuri. Vilken behandling bromsar njurfunktionsförlusten bäst?', '["ACE-hämmare eller ARB och SGLT2-hämmare med god blodtryckskontroll","Rutinmässig användning av NSAID vid ledsmärta","Kalciumtillägg som enda åtgärd","Upprepade kontrastundersökningar för kontroll"]'::jsonb, 'ACE-hämmare eller ARB och SGLT2-hämmare med god blodtryckskontroll', 'RAAS-hämning sänker intraglomerulärt tryck och minskar albuminuri, och SGLT2-hämmare har dokumenterad njurskyddande effekt. NSAID och jodkontrast kan utlösa akut njurskada och ska undvikas eller användas med försiktighet.', 1, 3, 'kapitel', false)
