INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-5-q4', 'km1-5', NULL, 'cloze', 'En snabb, inom timmar till dagar uppkommen försämring av njurfunktionen kallas ______.', NULL, 'akut njurskada', 'Akut njurskada (AKI) definieras av stigande kreatinin eller fallande urinproduktion enligt KDIGO och delas in i prerenala, renala och postrenala orsaker. Tillståndet är ofta reversibelt om orsaken åtgärdas i tid.', 1, 4, 'kapitel', false)
