INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-6-q1', 'km1-6', NULL, 'mcq', 'En 58-årig man med känd levercirros och ascites insjuknar med feber, buksmärta och försämrat allmäntillstånd. Vilken undersökning är avgörande för diagnosen spontan bakteriell peritonit?', '["Ascitespunktion med neutrofilräkning och odling","Datortomografi av buken","Enbart blododling","Leverbiopsi"]'::jsonb, 'Ascitespunktion med neutrofilräkning och odling', 'Diagnosen ställs vid förhöjt antal neutrofila granulocyter i ascitesvätskan, och odling identifierar agens. Datortomografi kan vara normal och blododling är otillräcklig som enda underlag; leverbiopsi är irrelevant i det akuta skedet.', 1, 1, 'kapitel', false)
