INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-6-q2', 'km1-6', NULL, 'mcq', 'En 45-årig man med hög alkoholkonsumtion har svår epigastriesmärta som utstrålar mot ryggen och kraftigt förhöjt pankreaslipas. Vilka är de två vanligaste orsakerna till akut pankreatit?', '["Gallsten och alkohol","Hyperkalcemi och hypertriglyceridemi","Läkemedel och trauma","Infektion och autoimmunitet"]'::jsonb, 'Gallsten och alkohol', 'Gallstenspassage över papilla Vateri och alkohol står för majoriteten av fallen. Hyperkalcemi, hypertriglyceridemi och läkemedel är ovanligare orsaker men ska övervägas vid recidiv utan gallsten eller alkohol.', 1, 2, 'kapitel', false)
