INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-6-q3', 'km1-6', NULL, 'mcq', 'En 27-årig man har i två månader haft blodiga diarréer, trängningar och buksmärta. Koloskopi visar kontinuerlig inflammation från rektum och proximalt. Vilken behandling är förstahandsval vid lindrig till måttlig sjukdom?', '["Mesalazin (5-ASA)","Systemisk glukokortikoid som underhållsbehandling","Metronidazol","Loperamid"]'::jsonb, 'Mesalazin (5-ASA)', '5-ASA används både för att inducera och bibehålla remission vid lindrig till måttlig ulcerös kolit. Systemiska steroider inducerar remission men är olämpliga för långtidsbruk, och loperamid kan bidra till toxiskt megakolon.', 1, 3, 'kapitel', false)
