INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-6-q4', 'km1-6', NULL, 'cloze', 'Vid levercirros sjunker syntesen av albumin och koagulationsfaktorer, vilket ses som förhöjt ______ i blodprov.', NULL, 'INR', 'Levern bildar koagulationsfaktorerna II, VII, IX och X samt albumin; vid nedsatt synteskapacitet förlängs protrombintiden och INR stiger. Tillsammans med bilirubin och encefalopati ingår detta i Child-Pugh-klassificeringen.', 1, 4, 'kapitel', false)
