INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-7-q1', 'km1-7', NULL, 'mcq', 'En 34-årig kvinna söker för trötthet. Hb är lågt, MCV lågt och ferritin lågt. Vilket påstående är korrekt?', '["Järnbrist föreligger och orsaken till blodförlusten måste utredas","Ferritin är förhöjt och talar för järnbrist","MCV är typiskt förhöjt vid järnbrist","Järntabletter kan ges utan att orsaken utreds"]'::jsonb, 'Järnbrist föreligger och orsaken till blodförlusten måste utredas', 'Lågt ferritin är det mest specifika provet för järnbrist och mikrocytos talar för bristen, men även talassemi ger små erytrocyter. Eftersom järnbrist hos vuxna oftast beror på blödning ska källan utredas, särskilt i mag-tarmkanalen.', 1, 1, 'kapitel', false)
