INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-7-q2', 'km1-7', NULL, 'mcq', 'En 72-årig man har trötthet, glossit och domningar i fötterna. Hb är lågt med högt MCV och vitamin B12 är lågt. Vilken behandling ska ges?', '["Substitution med kobalamin (B12)","Järntabletter","Folsyra som monoterapi","Erytropoetin"]'::jsonb, 'Substitution med kobalamin (B12)', 'B12-brist ger makrocytär anemi och neurologiska symtom, ofta på grund av perniciös anemi med antikroppar mot intrinsic factor. Folsyra som monoterapi kan häva anemin men dölja och förvärra den neurologiska skadan.', 1, 2, 'kapitel', false)
