INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-7-q3', 'km1-7', NULL, 'mcq', 'En 68-årig man har trötthet, ryggvärk, hyperkalcemi, nedsatt njurfunktion och anemi. Serum elektrofores visar en M-komponent. Vilken diagnos är mest sannolik?', '["Multiplalt myelom","Kronisk lymfatisk leukemi","Essentiell trombocytemi","Järnbristanemi"]'::jsonb, 'Multiplalt myelom', 'CRAB-kriterierna – hyperkalcemi, njursvikt, anemi och bentäthetsförändringar – tillsammans med M-komponent talar för myelom. CLL ger i stället lymfocytos och lymfkörtelförstoring, och trombocytemi påverkar varken kalcium eller skelett.', 1, 3, 'kapitel', false)
