INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-7-q4', 'km1-7', NULL, 'cloze', 'Vid intravasal hemolys ses lågt haptoglobin, förhöjt LDH och förhöjt ______.', NULL, 'okonjugerat bilirubin', 'Haptoglobin binder fritt hemoglobin och förbrukas vid hemolys, medan LDH frigörs från sönderfallande erytrocyter och hemoglobin bryts ner till okonjugerat bilirubin. Konjugerat bilirubin stiger i stället vid kolestas eller hepatocellulär skada.', 1, 4, 'kapitel', false)
