INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-8-q1', 'km1-8', NULL, 'mcq', 'En 52-årig kvinna har symmetrisk morgonstelhet i över en timme, synovit i MCP- och PIP-leder samt positiv anti-CCP. Vilken diagnos är mest sannolik?', '["Reumatoid artrit","Artros","Akut gikt","Polymyalgia rheumatica"]'::jsonb, 'Reumatoid artrit', 'Symmetriskt småledsengagemang med långvarig morgonstelhet och anti-CCP talar för reumatoid artrit. Artros engagerar typiskt DIP-leder med kort morgonstelhet, gikt sitter oftast i MTP I, och polymyalgia rheumatica ger proximal muskelvärk utan synovit.', 1, 1, 'kapitel', false)
