INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-8-q2', 'km1-8', NULL, 'mcq', 'En 68-årig man med hypertoni och diuretikabehandling får akut rodnad, svullnad och intensiv smärta i första MTP-leden. Vilken behandling är lämplig i akutskedet?', '["NSAID, kolchicin eller glukokortikoid","Allopurinol som enda behandling","Antibiotika","Metotrexat"]'::jsonb, 'NSAID, kolchicin eller glukokortikoid', 'Akut gikt kräver snabb antiinflammatorisk behandling. Allopurinol sänker uratet men ska inte startas eller dosändras under en pågående attack eftersom det kan förlänga den; antibiotika är bara aktuellt vid misstänkt septisk artrit.', 1, 2, 'kapitel', false)
