INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-8-q3', 'km1-8', NULL, 'mcq', 'En 74-årig kvinna får plötslig bitemporal huvudvärk, käksmärta vid tuggning och dimsyn. SR och CRP är kraftigt förhöjda. Vilken åtgärd ska vidtas?', '["Omedelbar behandling med högdos glukokortikoid","Avvakta temporalisbiopsisvar innan behandling","Behandling med NSAID som monoterapi","Behandling med metotrexat som monoterapi"]'::jsonb, 'Omedelbar behandling med högdos glukokortikoid', 'Jättecellsarterit kan ge irreversibel blindhet genom ischemisk optikusneuropati, så glukokortikoid ges direkt vid misstanke. Temporalisbiopsi kan göras efter påbörjad behandling utan att diagnostiken går förlorad, men får aldrig fördröja terapin.', 1, 3, 'kapitel', false)
