INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km1-8-q4', 'km1-8', NULL, 'cloze', 'Den sjukdomsmodifierande basbehandlingen vid reumatoid artrit är i första hand ______.', NULL, 'metotrexat', 'Metotrexat är förstahandsval som DMARD och sätts in tidigt för att bromsa leddestruktion. Glukokortikoid används som brygga vid insättningen, och biologiska läkemedel tillkommer vid otillräcklig effekt.', 1, 4, 'kapitel', false)
