INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-1-q1', 'km2-1', NULL, 'mcq', 'En 84-årig kvinna inlagd för pneumoni blir akut förvirrad, ser synhallucinationer och växlar i vakenhet. Hon var tidigare kognitivt klar. Vilken åtgärd är viktigast?', '["Utreda och behandla bakomliggande orsak samt icke-farmakologiska åtgärder","Rutinmässig behandling med bensodiazepin","Sederande antipsykotika som första åtgärd","Fastspänning i sängen för att skydda patienten"]'::jsonb, 'Utreda och behandla bakomliggande orsak samt icke-farmakologiska åtgärder', 'Delirium är ett akut, fluktuerande tillstånd med nedsatt uppmärksamhet som kräver orsaksutredning: infektion, läkemedel, elektrolytrubbning, urinretention och smärta. Bensodiazepiner och andra sederande läkemedel förvärrar och förlänger delirium; farmakologisk behandling är undantag, inte regel.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-1-q2', 'km2-1', NULL, 'mcq', 'En 78-årig man har under två år fått tilltagande nedsättning av närminnet, ordletning och svårigheter med vardagliga aktiviteter. Han är orienterad och undersökningen visar inga fokalneurologiska bortfall. Vilken diagnos är mest sannolik?', '["Alzheimers sjukdom","Delirium","Vaskulär demens","Normalt åldrande"]'::jsonb, 'Alzheimers sjukdom', 'Smygande debut med episodisk minnesnedsättning och progredierande ADL-påverkan är typiskt för Alzheimers sjukdom. Vaskulär demens debuterar ofta stegvis med fokal neurologi, delirium är akut och fluktuerande, och normalt åldrande ger inte förlorad ADL-förmåga.', 1, 2, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-1-q3', 'km2-1', NULL, 'mcq', 'En 82-årig skör kvinna har fallit två gånger det senaste halvåret. Vilken åtgärd har bäst evidens för att förebygga nya fall?', '["Strukturerad multiprofessionell fallprevention med styrke- och balansträning","Rutinmässig sederande behandling nattetid","Sängförbud med larm","Enbart högdos D-vitamin utan känd brist"]'::jsonb, 'Strukturerad multiprofessionell fallprevention med styrke- och balansträning', 'Fall är multifaktoriella och multifaktoriell intervention med träning, läkemedelsgenomgång, syn- och hjälpmedelsöversyn samt bostadsanpassning har bäst stöd. Sederande läkemedel ökar fallrisken, och högdos D-vitamin utan brist rekommenderas inte.', 1, 3, 'kapitel', false)
