INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-1-q4', 'km2-1', NULL, 'cloze', 'Ökad sårbarhet med nedsatt reservkapacitet och ökad risk för funktionsfall vid sjukdom eller stress kallas ______.', NULL, 'skörhet', 'Skörhet (frailty) innebär att små påfrestningar kan utlösa stora funktionsförluster. Den bedöms kliniskt, till exempel med gångtid, greppstyrka, viktnedgång och trötthet, och är en viktig prognosmarkör.', 1, 4, 'kapitel', false)
