INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-2-q1', 'km2-2', NULL, 'mcq', 'En 65-årig man med misstänkt urinvägsinfektion har blodtryck 85/50 mmHg, andningsfrekvens 26/min, laktat 4 mmol/L och är förvirrad. Blododlingar har tagits. Vilken åtgärd får inte fördröjas?', '["Bredspektrumantibiotika intravenöst tillsammans med vätskebehandling","Svar på blododling innan antibiotika ges","Enbart antipyretika och observation","Datortomografi innan vätska och antibiotika"]'::jsonb, 'Bredspektrumantibiotika intravenöst tillsammans med vätskebehandling', 'Septisk chock kräver omedelbar antibiotika och vätskeresuscitering; fördröjd behandling ökar mortaliteten. Odlingar tas före antibiotika men får aldrig skjuta upp densamma, och bilddiagnostik sker först när patienten är hemodynamiskt stabil.', 1, 1, 'kapitel', false)
