INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-2-q2', 'km2-2', NULL, 'mcq', 'En 58-årig man har feber, nytt systoliskt blåsljud, petekier och en nyligen genomgången tandinfektion. Vilken undersökningskombination är central för diagnosen?', '["Upprepade blododlingar och ekokardiografi","Enbart CRP och SR","Röntgen av thorax","Lumbalpunktion"]'::jsonb, 'Upprepade blododlingar och ekokardiografi', 'Modifierade Duke-kriterier bygger på positiva blododlingar tillsammans med ekokardiografiska fynd som vegetation på klaffar. CRP är ospecifikt, röntgen thorax ger ingen klaffdiagnostik och lumbalpunktion är irrelevant här.', 1, 2, 'kapitel', false)
