INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-2-q3', 'km2-2', NULL, 'mcq', 'En 24-årig kvinna har sedan ett dygn feber, nackstelhet, fotofobi och sänkt medvetande. Vilken åtgärd ska prioriteras?', '["Intravenös bredspektrumantibiotika utan onödigt dröjsmål","Röntgen av skallen före all behandling","Vänta på svar från likvorodling","Enbart antiviral behandling"]'::jsonb, 'Intravenös bredspektrumantibiotika utan onödigt dröjsmål', 'Bakteriell meningit är livshotande och antibiotika ges omedelbart efter lumbalpunktion – eller direkt om punktionen fördröjs. Dexametason ges före eller i samband med första antibiotikadosen för att minska hörselnedsättning och neurologiska skador.', 1, 3, 'kapitel', false)
