INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-2-q4', 'km2-2', NULL, 'cloze', 'Sepsis definieras som livshotande organdysfunktion orsakad av en bristande reglering av kroppens svar på ______.', NULL, 'infektion', 'Sepsis-3-definitionen betonar organdysfunktion – mätt till exempel med SOFA – snarare än enbart infektion och inflammation. Septisk chock är sepsis med kvarstående hypotoni och behov av vasopressor trots adekvat vätskebehandling.', 1, 4, 'kapitel', false)
