INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-3-q1', 'km2-3', NULL, 'mcq', 'En 8-årig pojke har kliande, torr hud i armveck och knäveck samt tidigare astma och allergisk rinit. Vilken behandling är grunden?', '["Fuktighetsbevarande kräm och topikala glukokortikoider","Systemisk antibiotika som basbehandling","Enbart topikala kalcineurinhämmare utan mjukgörande","Långvarig peroral glukokortikoidbehandling"]'::jsonb, 'Fuktighetsbevarande kräm och topikala glukokortikoider', 'Atopiskt eksem beror på en defekt hudbarriär med inflammation; daglig mjukgörande behandling återställer barriären och topikala steroider dämpar skoven. Systemiska steroider är förbehållna svåra skov och ska inte ges långvarigt.', 1, 1, 'kapitel', false)
