INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-3-q2', 'km2-3', NULL, 'mcq', 'En 30-årig man har skarpt avgränsade erytematösa plack med silverfärgade fjäll på armbågarnas sträcksidor och i hårbotten samt nagelgrop. Vilken diagnos är mest sannolik?', '["Psoriasis","Atopiskt dermatit","Rosacea","Tinea corporis"]'::jsonb, 'Psoriasis', 'Plack med silverfjäll på extensorsidor, hårbottenengagemang och nagelgrop är typiskt för psoriasis, liksom Koebners fenomen. Atopiskt eksem sitter i böjveck, rosacea engagerar ansiktet och tinea har en aktiv rand med central uppklarning.', 1, 2, 'kapitel', false)
