INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-3-q3', 'km2-3', NULL, 'mcq', 'En 62-årig man har en ny pigmenterad lesion på huden som är asymmetrisk, har oregelbunden kant och varierande färg. Vilken faktor är viktigast för prognosen?', '["Breslow-tjockleken (invasionsdjupet)","Lesionens färg","Patientens ålder","Antalet nevus på kroppen"]'::jsonb, 'Breslow-tjockleken (invasionsdjupet)', 'Breslow-tjockleken mäts i millimeter i den exciderade lesionen och är den starkaste prognosfaktorn; den styr marginal och utredning av vakningskörtel. Antal nevus och solexponering är riskfaktorer för uppkomst, inte för prognos.', 1, 3, 'kapitel', false)
