INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-3-q4', 'km2-3', NULL, 'cloze', 'En äldre patient får grupperade, smärtande vesikler i ett dermatom. Orsaken är reaktivering av ______.', NULL, 'varicella-zostervirus', 'Herpes zoster uppstår när latent varicella-zostervirus i dorsalrotsganglier reaktiveras. Tidig antiviral behandling förkortar förloppet och minskar risken för postherpetisk neuralgi.', 1, 4, 'kapitel', false)
