INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-4-q1', 'km2-4', NULL, 'mcq', 'En 70-årig man har en urinvägsinfektion orsakad av en ESBL-producerande E. coli. Vad kännetecknar ESBL?', '["Enzymer som hydrolyserar cefalosporiner och ger resistens mot dessa","En mutation i ribosomen som ger makrolidresistens","Ett effluxpump som pumpar ut tetracyklin","En förändrad DNA-gyras som ger kinolonresistens"]'::jsonb, 'Enzymer som hydrolyserar cefalosporiner och ger resistens mot dessa', 'ESBL är betalaktamaser med utökat spektrum som bryter penicilliner och cefalosporiner men hämmas av karbapenemer. Resistensen uppstår genom enzymatisk nedbrytning av antibiotikumet, inte genom förändrad målstruktur.', 1, 1, 'kapitel', false)
