INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-4-q2', 'km2-4', NULL, 'mcq', 'Vilken mekanism ligger bakom meticillinresistens hos Staphylococcus aureus (MRSA)?', '["Förändrat penicillinbindande protein (PBP2a) kodat av mecA-genen","Höga halter av betalaktamas i cellväggen","En förtjockad cellvägg av keratin","Enbart nedsatt membranpermeabilitet"]'::jsonb, 'Förändrat penicillinbindande protein (PBP2a) kodat av mecA-genen', 'mecA ger ett alternativt penicillinbindande protein med låg affinitet för betalaktamer, vilket ger resistens mot i stort sett alla betalaktamer utom ceftarolin. MRSA kräver därför alternativa läkemedel och kontaktisolering inom vården.', 1, 2, 'kapitel', false)
