INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-4-q3', 'km2-4', NULL, 'mcq', 'En 40-årig kvinna med dysuri och pollakisuri utan feber eller flankömhet har en okomplicerad cystit. Vilket behandlingsval är lämpligt?', '["Pivmecillinam eller nitrofurantoin","Ciprofloxacin","Cefotaxim intravenöst","Klaritromycin"]'::jsonb, 'Pivmecillinam eller nitrofurantoin', 'Okomplicerad cystit behandlas med smalspektrumpreparat som pivmecillinam eller nitrofurantoin. Kinoloner ska sparas på grund av resistensutveckling och biverkningar som tendinopati och sensorisk påverkan, och intravenös behandling är omotiverad vid okomplicerad cystit.', 1, 3, 'kapitel', false)
