INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km2-4-q4', 'km2-4', NULL, 'cloze', 'Enzymer som bryter betalaktamringen och därmed inaktiverar penicilliner kallas ______.', NULL, 'betalaktamaser', 'Betalaktamaser hydrolyserar den fyraledade betalaktamringen som är nödvändig för bindning till penicillinbindande proteiner. Kombinationer med betalaktamashämmare, som klavulansyra, återställer känsligheten för vissa stammar.', 1, 4, 'kapitel', false)
