INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-1-q1', 'km3-1', NULL, 'mcq', 'En 24-årig man söker med buksmärta som började kring naveln och som under ett dygn flyttat ned till höger fossa. Temp 38,3 grader, puls 96. Vid bukstatus är han öm med försvar över höger fossa och positivt släppömhetstecken (Blumberg). Vilken diagnos är mest sannolik?', '["Akut appendicit","Akut pankreatit","Uretärsten","Akut gastroenterit"]'::jsonb, 'Akut appendicit', 'Klassisk migrering av smärtan beror på att den viscerala, oskarpa smärtan från appendix följer nerven till naveln medan den somatiska irritationen av parietalperitoneum ger lokal ömhet i höger fossa. Gastroenterit ger diffus smärta med diarré utan försvar, och en uretärsten ger typiskt kolikartad flank-dysuri och inget peritonealt försvar.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-1-q2', 'km3-1', NULL, 'mcq', 'En 52-årig överviktig kvinna har haft molande smärta i höger arcus i två dygn med utstrålning mot höger skulderblad. Temp 38,9 grader. Vid bukstatus utlöser djup palpation i höger arcus en smärta som får henne att stanna andningen. Vilken diagnos är mest sannolik?', '["Akut kolecystit","Akut pankreatit","Perforerat ventrikelulcus","Högersidig pyelonefrit"]'::jsonb, 'Akut kolecystit', 'Positivt Murphys tecken uppstår när den inflammerade gallblåsan trycks mot den palperande handen och patienten reflexmässigt håller andan. Smärtan utstrålar via n. phrenicus till skulderbladet. Pankreatit ger oftast utstrålning till ryggen och kraftigt förhöjt pankreasenzymer, medan pyelonefrit ger flankömhet och dysuri.', 1, 2, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-1-q3', 'km3-1', NULL, 'mcq', 'En 67-årig man med långvarig NSAID-behandling får plötslig svår epigastriesmärta. Han är tachycard och har bräddad buk med allmän palpationsömhet. Lungröntgen i upprätt ställning visar fri luft under båda diafragmabågarna. Vilket fynd är här det avgörande för handläggningen?', '["Fri luft under diafragma talar för perforation och patienten behöver akut kirurgi","Frånvaron av feber utesluter perforation","Han ska i första hand få syrahämmande behandling och skickas hem","Fyndet talar för ileus och patienten ska få lavemang"]'::jsonb, 'Fri luft under diafragma talar för perforation och patienten behöver akut kirurgi', 'Fri intraperitoneal luft på upprätt lungröntgen eller DT är starkt tecken på hål i en ihålig struktur, oftast perforerat ulcus, och kräver akut kirurgisk bedömning. Tidig peritonit kan ge förhållandevis diskret bukstatus, så frånvaro av uttalade fynd eller feber utesluter inte diagnosen.', 1, 3, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
