INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-1-q4', 'km3-1', NULL, 'cloze', 'En 74-årig kvinna opererades för appendicit för tio år sedan och söker nu med buksmärta, kräkningar, uppspänd buk och frånvaro av gaser sedan två dygn. Röntgen visar vidgade tunntarmsslyngor med luftvätskenivåer. Den vanligaste orsaken till hennes tillstånd är ______.', NULL, 'adherenser', 'Bindvävssträngar (adherenser) efter tidigare bukoperation är den vanligaste orsaken till mekanisk tunntarmsileus. De kan ge strangulation med ischemi, vilket gör att tillståndet kan kräva akut operation.', 1, 4, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
