INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-2-q1', 'km3-2', NULL, 'mcq', 'En 21-årig man kommer in efter en motorcykelolycka. Han är kraftigt påverkad, tachycard och hypotensiv. Andningsljudet saknas över vänster hemithorax, perkussionstonen är hyperresonant och trakea är förskjuten mot höger. Vilken är den omedelbara åtgärden?', '["Omedelbar dekompression av pleurarummer – till exempel nålpunktion följd av thoraxdrän","Akut DT av thorax innan behandling","Syrgastillförsel och avvakta blodgas","Bronkospasmolytika och kortison"]'::jsonb, 'Omedelbar dekompression av pleurarummer – till exempel nålpunktion följd av thoraxdrän', 'Spänningsthorax ger obstruktiv chock med mediastinalförskjutning och är en klinisk diagnos som ska behandlas direkt utan att vänta på bilddiagnostik. Ett vanligt misstag är att tolka det som blödning och bara ge vätska, vilket inte löser den mekaniska chocken.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-2-q2', 'km3-2', NULL, 'mcq', 'En 82-årig kvinna faller i hemmet och kan inte stödja på höger ben. Benet är förkortat och utåtrotterat. Röntgen visar en medial collumfraktur (femurhalsfraktur). Vilken är den mest fruktade komplikationen till just denna frakturtyp?', '["Avaskulär nekros (caputnekros) på grund av skadad kärlförsörjning","Fettemboli från rörbenmärgen","Kompartmentsyndrom i vaden","Perifer nervskada i n. peroneus"]'::jsonb, 'Avaskulär nekros (caputnekros) på grund av skadad kärlförsörjning', 'Caput femoris försörjs till stor del av a. circumflexa femoris medialis, som löper intrakapsulärt längs collum. Vid mediala, dislocerade frakturer brister kärlförsörjningen, vilket ger pseudartros och caputnekros – därför väljs ofta protes i stället för osteosyntes hos äldre.', 1, 2, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-2-q3', 'km3-2', NULL, 'mcq', 'En 68-årig man har fallit på utsträckt hand. Röntgen visar en distal radiusfraktur med volarförskjutning av distala fragmentet. Vilken nerv löper störst risk att påverkas?', '["N. medianus","N. radialis","N. ulnaris","N. axillaris"]'::jsonb, 'N. medianus', 'N. medianus passerar genom karpaltunneln strax volart om distala radius, och volarförskjutet fragment kan ge tryck med karpaltunnelsyndrom eller sensibilitetsnedsättning i tumme-indexfinger. N. ulnaris påverkas typiskt vid fraktur i distala humerus eller vid skada i ulnar diket.', 1, 3, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-2-q4', 'km3-2', NULL, 'cloze', 'En 19-årig fotbollsspelare har fått ett slag mot underbenet. Skenbenet är svullet, spänt och hårt som ett vedträ, smärtan ökar kraftigt vid passiv uttänjning av tåextensorerna och han har domningar i foten. Detta talar för ______.', NULL, 'kompartmentsyndrom', 'Ökat tryck i en sluten muskelkammare ger ischemi. Smärta vid passiv uttänjning, spänd kammare och sensibilitetsnedsättning är tidiga tecken, medan bortfall av puls är ett sent och opålitligt fynd. Tillståndet kräver omedelbar fasciotomi.', 1, 4, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-3-q1', 'km3-3', NULL, 'mcq', 'Under en operation i generell anestesi med inhalationsanestetika och depolariserande muskelrelaxans utvecklar en ung man plötsligt massiv muskelrigiditet, stigande kroppstemperatur, hyperkapni och metabol acidos. Vilken diagnos misstänker du?', '["Malignt hypertermi","Malign neuroleptikasyndrom","Serotonergt syndrom","Undertryckande tyreotoxikos"]'::jsonb, 'Malignt hypertermi', 'Malignt hypertermi beror på en mutation i ryanodinreceptorn (RYR1) som ger okontrollerad kalciumfrisättning från sarcoplasmatiskt retikulum. Behandlingen är dantrolen, som blockerar ryanodinreceptorn. Neuroleptikasyndrom utlöses av antipsykotika och ger rigiditet med autonom instabilitet men förklaras inte av anestesimedel.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-3-q2', 'km3-3', NULL, 'mcq', 'Varför ska en patient vara fastande inför generell anestesi?', '["Anestesimedel slår ut skyddsreflexerna så att maginnehåll kan aspireras","Fasta förbättrar upptaget av anestesimedel","Magen måste vara tom för att kunna intubera lättare","Fasta minskar blödningen under operation"]'::jsonb, 'Anestesimedel slår ut skyddsreflexerna så att maginnehåll kan aspireras', 'Nedsatta host- och sväljreflexer tillsammans med relaxation av övre esofagussfinktern gör aspiration möjlig, med risk för aspirationspneumoni och obstruktion. Fasta minskar magsäckens innehåll men påverkar inte anestesimedels upptag eller blödning.', 1, 2, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-3-q3', 'km3-3', NULL, 'mcq', 'En 30-årig kvinna har genomgått kejsarsnitt i spinalanestesi. Dagen efter får hon svår huvudvärk som är klart värre upprätt och lindras när hon ligger ner. Vilken är den mest sannolika orsaken?', '["Postpunktionell huvudvärk på grund av läckage av cerebrospinalvätska","Akut subduralhematom","Migrän med aura","Meningit"]'::jsonb, 'Postpunktionell huvudvärk på grund av läckage av cerebrospinalvätska', 'Vid duralpunktion kan cerebrospinalvätska läcka ut, vilket ger intrakraniell hypovolemi och traktion på meningerna. Klassiskt är ortostatisk huvudvärk som lindras i liggande. Meningit ger feber, nackstelhet och tilltagande allmänpåverkan.', 1, 3, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-3-q4', 'km3-3', NULL, 'cloze', 'Lokalbedövningsmedel ger sin analgetiska effekt genom att blockera spänningsstyrda ______ i nervmembranet, så att aktionspotentialen inte kan genereras.', NULL, 'natriumkanaler', 'Blockad av Na+-kanaler hindrar depolarisering och fortledning i tunna, myeliniserade nervfibrer först (smärta och temperatur före beröring och motorik). Om medlet kommer i blodet kan systemisk toxicitet med centralnervösa symtom och arytmier uppstå.', 1, 4, 'kapitel', false)
