INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-4-q1', 'km3-4', NULL, 'mcq', 'En 68-årig man söker med svag urinstråle, startbesvär, nokturi två gånger per natt och känsla av ofullständig blåstömning. Prostata är jämnt förstorad och mjuk vid rektalexploration, PSA är normalt och urinsticka visar inga tecken på infektion. Vilken behandling är förstahandsval vid besvärande symtom?', '["Alfablockerare","Antibiotika","Radikal prostatektomi","Långtidsbehandling med kortison"]'::jsonb, 'Alfablockerare', 'Symtomgivande godartad prostatahyperplasi behandlas i första hand med alfablockerare som relaxerar glatt muskulatur i prostata och blåshals, med snabb symtomlindring. Antibiotika är relevant vid samtidig prostatit och kirurgi övervägs vid recidiverande retention, blåssten eller njurpåverkan.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-4-q2', 'km3-4', NULL, 'mcq', 'En 44-årig man har sedan två timmar svår kolikartad smärta från vänster flank ut mot ljumsken, han är illamående och har mikroskopisk hematuri. DT visar en sten i vänster uretär som ger lätt hydronefros. Han är afebril och njurfunktionen är normal. Vilken behandling är förstahandsval mot smärtan?', '["NSAID-preparat","Antibiotika","Alfablockerare som enda behandling","Akut dialys"]'::jsonb, 'NSAID-preparat', 'NSAID lindrar både smärtan och den prostaglandindrivna diuresen som ökar trycket ovanför stenen. Antibiotika ges endast vid samtidig infektion, och vid feber med obstruktion krävs akut avlastning med dränage eftersom det är ett urosepstillstånd.', 1, 2, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-4-q3', 'km3-4', NULL, 'mcq', 'En 15-årig pojke får plötslig svår smärta i vänster skrotum under en fotbollsmatch, han kräks och skrotum är svullet. Testikeln står högt och cremasterreflexen är borta på den drabbade sidan. Vad gör du?', '["Akut kirurgisk exploration – tiden till detorsion är avgörande","Skickar hem honom med analgetika och kontroll om en vecka","Beställer ultraljud och avvaktar svar","Behandlar med antibiotika mot epididymit"]'::jsonb, 'Akut kirurgisk exploration – tiden till detorsion är avgörande', 'Testistorsion stryper blodförsörjningen via funiculus spermaticus och kan ge testikelnekros inom några timmar. Kliniska tecken som högställd testikel, saknad cremasterreflex och akut debut motiverar omedelbar exploration; ultraljud får inte fördröja kirurgin. Epididymit debuterar mer successivt och har bevarad cremasterreflex.', 1, 3, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-4-q4', 'km3-4', NULL, 'cloze', 'En 22-årig kvinna har dysuri, ökad miktionsfrekvens och suprapubisk ömhet utan feber eller flankömhet. Den vanligaste orsaken till okomplicerad nedre urinvägsinfektion är ______.', NULL, 'E. coli', 'Escherichia coli orsakar majoriteten av okomplicerade urinvägsinfektioner tack vare adhesiner som fäster vid uroepitelet. Feber och flankömhet talar i stället för pyelonefrit, som kräver annan behandlingsstrategi.', 1, 4, 'kapitel', false)
