INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-5-q1', 'km3-5', NULL, 'mcq', 'En 71-årig man som röker söker för krampande smärta i vänster vad efter ungefär 200 meters gång. Smärtan försvinner inom ett par minuters vila och kommer tillbaka vid exakt samma gångsträcka. Pulsen på vänster a. dorsalis pedis saknas. Vilken diagnos är mest sannolik?', '["Claudicatio intermittens vid perifer artärsjukdom","Spinal stenos","Venös insufficiens","Kroniskt kompartmentsyndrom"]'::jsonb, 'Claudicatio intermittens vid perifer artärsjukdom', 'Reproducerbar gångsmärta som lindras inom minuter i vila, avsaknad av fotpuls och rökning passar perifer artärsjukdom. Spinal stenos ger i stället symtom som ofta lindras av att sätta sig eller böja sig framåt och påverkas mindre av gångsträckan, och venös insufficiens ger ödem, tunga ben och hyperpigmentering.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-5-q2', 'km3-5', NULL, 'mcq', 'En 78-årig kvinna med förmaksflimmer insjuknar plötsligt med svår smärta i höger underben. Benet är blekt, kallt från mitten av vaden, pulslöst och hon har domningar i foten. Vad är nästa steg?', '["Omedelbar bedömning för revaskularisering – kirurgisk eller endovaskulär","Smärtlindring och observation över natten","Kompressionsbehandling och mobilisering","Antibiotika mot misstänkt cellulit"]'::jsonb, 'Omedelbar bedömning för revaskularisering – kirurgisk eller endovaskulär', 'Akut extremitetsischemi är en tidskritisk kärlkirurgisk akut situation där muskulaturen skadas inom timmar. Förmaksflimmer gör arteriell emboli sannolik. Att avvakta ger irreversibel ischemi med risk för amputation och rabdomyolys.', 1, 2, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-5-q3', 'km3-5', NULL, 'mcq', 'En 76-årig man med känd hypertoni och rökning kommer in med akut svår buk- och ryggsmärta. Han är blek och svettig, blodtrycket är 85/50 och vid bukpalpation känns en pulserande resistens mitt i buken. Vilken diagnos måste antas till motsats bevisats?', '["Rupturerat bukaortaaneurysm","Akut pankreatit","Njurkolik","Ileus"]'::jsonb, 'Rupturerat bukaortaaneurysm', 'Pulserande resistens, hypotoni och akut buk-/ryggsmärta hos äldre rökande man är klassisk presentation av rupturerat aortaaneurysm, där dödligheten är hög. Tillståndet kräver omedelbar kirurgisk/kärlkirurgisk handläggning, och tiden till åtgärd är avgörande.', 1, 3, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
