INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km3-5-q4', 'km3-5', NULL, 'cloze', 'En 60-årig kvinna har svullet vänster ben, ökad vadmuskelömhet och rodnad efter en lång flygresa. Den mest fruktade akuta komplikationen till djupt ventrombos är ______.', NULL, 'lungemboli', 'En trombbildning i de djupa benvenerna kan lossna och föras med venflödet till lungkretsloppet, där den ger obstruktion och högersidig hjärtsvikt eller cirkulatorisk kollaps. Utredning sker med D-dimer och ultraljud/DT-angiografi beroende på sannolikhet.', 1, 4, 'kapitel', false)
