INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-1-q1', 'km4-1', NULL, 'mcq', 'En 72-årig man med förmaksflimmer insjuknar plötsligt med högersidig arm- och benpares samt expressiv afasi. Symtomen började för 40 minuter sedan. Vilken är den första undersökningen som ska göras?', '["Akut DT av hjärnan utan kontrast för att utesluta blödning","Lumbalpunktion","MR av halsryggen","EEG"]'::jsonb, 'Akut DT av hjärnan utan kontrast för att utesluta blödning', 'Vid misstänkt stroke är första steget att utesluta intracerebral blödning, eftersom trombolys annars är direkt farligt. DT är snabbt tillgängligt och blod framstår hyperdensivt. Lumbalpunktion är kontraindicerad vid misstänkt ökad intrakraniell tryck och EEG används inte i akut skede.', 1, 1, 'kapitel', false)
