INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-1-q2', 'km4-1', NULL, 'mcq', 'En 28-årig kvinna har i flera år haft attacker av pulserande halvsidig huvudvärk med illamående och ljus- och ljudkänslighet. Under en timme före varje attack ser hon ett zigzagmönster som växer ut i synfältet. Vilken diagnos är mest sannolik?', '["Migrän med aura","Klusterhuvudvärk","Subaraknoidalblödning","Spänningshuvudvärk"]'::jsonb, 'Migrän med aura', 'Aura är ett fokalt neurologiskt symtom som utvecklas gradvis och varar i upp till en timme innan huvudvärken, ofta med visuella fenomen som förklaras av kortikal spreading depression. Klusterhuvudvärk ger korta, mycket intensiva attacker kring ögat med autonomt symtom, och subaraknoidalblödning ger plötslig ''åskknallshuvudvärk''.', 1, 2, 'kapitel', false)
