  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-1-q3', 'km4-1', NULL, 'mcq', 'En 68-årig man har sedan ett år fått allt svårare att komma igång med rörelser, han skriver allt mindre och går med korta steg. Vid undersökning ses vilotremor i höger hand, stelhet vid passiv rörelse och ett utslätat ansiktsuttryck. Vilken förändring ligger bakom symtomen?', '["Förlust av dopaminerga neuron i substantia nigra","Demyliniserande lesioner i corpus callosum","Amyloidplack i hippocampus","Motorisk neuronförlust i cornu anterius"]'::jsonb, 'Förlust av dopaminerga neuron i substantia nigra', 'Hypokinesi, rigiditet och vilotremor vid Parkinsons sjukdom beror på degeneration av dopaminerga neuron i substantia nigra pars compacta, vilket ger minskad dopaminerg stimulering av striatum. Multipel skleros ger demyliniserande lesioner med skov och amyloidplack hör till Alzheimers sjukdom.', 1, 3, 'kapitel', false)
