  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-1-q4', 'km4-1', NULL, 'cloze', 'En patient visar sig ha nedsatt kraft i höger arm och ben men ingen påverkan i ansiktet. Symtomen är kontralaterala eftersom de nedåtgående motorbanorna (pyramidbanan) korsar i ______.', NULL, 'medulla oblongata', 'Pyramidbanan korsar i decussatio pyramidum i övergången mellan medulla oblongata och ryggmärgen, vilket förklarar att lesioner ovanför korsningen ger kontralaterala motorsymtom.', 1, 4, 'kapitel', false)
