INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-2-q1', 'km4-2', NULL, 'mcq', 'En 30-årig kvinna söker efter sex veckor med nedstämdhet, minskat intresse för allt hon tidigare tyckt om, sömninsvårigheter, aptitförlust med viktnedgång, orkeslöshet och skuldkänslor. Hon har inga tankar på att skada sig. Vilken diagnos är mest sannolik?', '["Egentlig depression","Anpassningsstörning","Bipolär sjukdom typ I","Generaliserat ångestsyndrom"]'::jsonb, 'Egentlig depression', 'Egentlig depression kräver nedstämdhet eller anhedoni under minst två veckor samt minst fem symtom med funktionspåverkan; här finns både nedstämdhet och anhedoni med sömn-, aptit- och energipåverkan. Anpassningsstörning kräver en identifierbar stressor och uppfyller inte det fulla symtomkriteriet.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-2-q2', 'km4-2', NULL, 'mcq', 'En 22-årig man inkommer efter att i en vecka ha sovit två timmar per natt utan att känna trötthet. Han pratar oavbrutet, beskriver hur han ska köpa ett flygbolag och har spenderat stora summor pengar på ogenomtänkta affärer. Vilken behandling bör undvikas som monoterapi?', '["Antidepressivt läkemedel i monoterapi","Stämningsstabiliserande behandling","Sömnfrämjande åtgärder","Strukturerad dygnsrytm och minskad stimuli"]'::jsonb, 'Antidepressivt läkemedel i monoterapi', 'Bilden är en manisk episod vid bipolär sjukdom typ I. Antidepressiva medel i monoterapi kan framkalla eller förvärra mani och ge snabbare cykling, därför används stämningsstabiliserare som grund. Sömn och struktur är viktiga komplement men inte tillräckliga vid uttalad mani.', 1, 2, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-2-q3', 'km4-2', NULL, 'mcq', 'En 26-årig man söker för återkommande, påträngande tankar om att han ska smitta sin familj med smuts. Han tvättar händerna 40 gånger per dag, vilket tar flera timmar. Han beskriver tankarna som orimliga och egna, och han är mycket besvärad av dem. Vilken diagnos är mest sannolik?', '["Tvångssyndrom (OCD)","Schizofreni","Generaliserat ångestsyndrom","Tourettes syndrom"]'::jsonb, 'Tvångssyndrom (OCD)', 'Vid OCD upplevs tvångstankarna som egna och påträngande och insikten om att de är orimliga är oftast bevarad, medan tvångshandlingarna utförs för att dämpa ångesten. Vid schizofreni är vanföreställningarna ego-syntona och insikten nedsatt, och det finns ofta hallucinationer.', 1, 3, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-2-q4', 'km4-2', NULL, 'cloze', 'En 48-årig man som dricker stora mängder alkohol dagligen läggs in på grund av en infektion och blir 24 timmar senare förvirrad, kraftigt tremorös, svettig med takykardi och synhallucinationer. Detta är den mest fruktade komplikationen till alkoholabstinens, nämligen ______.', NULL, 'delirium tremens', 'Delirium tremens är en abstinenspsykos med förvirring, autonoma symtom, hallucinationer och risk för kramper, och den kan vara livshotande. Behandlingen är bland annat bensodiazepiner, tiamin och vätske-/elektrolytkorrigering.', 1, 4, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-3-q1', 'km4-3', NULL, 'mcq', 'En 74-årig man söker akut med svår smärta i höger öga, huvudvärk, illamående och kraftigt dimmig syn. Ögat är rött, kornea grumlig, pupillen mellanvid och reagerar dåligt på ljus, och ögontrycket är högt. Vad är den omedelbara åtgärden?', '["Akut trycksänkande behandling och omedelbar ögonläkarkontakt","Antibiotikadroppar mot misstänkt konjunktivit","Tryckförband och kontroll om en vecka","Kortisondroppar i väntan på kontroll"]'::jsonb, 'Akut trycksänkande behandling och omedelbar ögonläkarkontakt', 'Bilden är akut vinkelblockglaukom där kammarvinkeln är stängd så att kammarvattnet inte kan dräneras. Ökat tryck skadar synnerven snabbt. Symtom som illamående, halosyn och medelvid pupill skiljer tillståndet från konjunktivit, som ger rött öga men normal syn och skarp pupillreflex.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-3-q2', 'km4-3', NULL, 'mcq', 'En 79-årig kvinna söker för långsamt tilltagande svårighet att läsa och se ansikten. Hon beskriver att raka linjer, till exempel i dörrkarmen, ser böjda och vinda ut. Främre segment och tryck är normala. Vilken diagnos är mest sannolik?', '["Åldersrelaterad makuladegeneration","Katarakt","Öppenvinkelglaukom","Optikusneurit"]'::jsonb, 'Åldersrelaterad makuladegeneration', 'Metamorfopsi (vinda linjer) och central synnedsättning talar för påverkan i makula, där fotoreceptorerna sitter. Katarakt ger diffus dimma och bländning utan metamorfopsi, glaukom ger perifera synfältsbortfall och optikusneurit ger snabb synnedsättning med smärta vid ögonrörelse.', 1, 2, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-3-q3', 'km4-3', NULL, 'mcq', 'En 55-årig närsynt man får plötsliga ljusblixtar och ''flugor'' i vänster synfält, och några timmar senare ett mörkt skymningsfält som växer från periferin. Vad ska han göra?', '["Omedelbart söka ögonakut – misstanke om näthinneavlossning","Avvakta eftersom flugor och blixtar alltid är godartade","Boka tid hos optiker om en månad","Behandla med smörjande ögondroppar"]'::jsonb, 'Omedelbart söka ögonakut – misstanke om näthinneavlossning', 'Ljusblixtar (fotopsier) och en växande skugga i synfältet är klassiska symtom på näthinneavlossning, särskilt hos närsynta och efter trauma. Avlossad näthinne får irreversibla skador utan kirurgisk åtgärd; godartade culprits är i stället enskilda symptom utan skuggfält.', 1, 3, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-3-q4', 'km4-3', NULL, 'cloze', 'Vid akut vinkelblockglaukom stiger ögontrycket därför att ______ är blockerad, så att kammarvattnet inte kan lämna ögat.', NULL, 'kammarvinkeln', 'När linsen pressar iris framåt stängs kammarvinkeln där trabekelverket dränerar kammarvattnet. Tryckstegringen ger smärta, korneaödem och synnedsättning, och behandlingen syftar till att öppna vinkeln och sänka produktionen av kammarvatten.', 1, 4, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-4-q1', 'km4-4', NULL, 'mcq', 'En 5-årig pojke har haft förkylning i tre dagar och får nu feber och svår öronvärk på höger sida. Otoskopi visar en utbuktande, rodnad och ogenomskinlig trumhinna. Vilken diagnos är mest sannolik?', '["Akut otitis media","Otitis externa","Sekretorisk otit","Vestibularisneurit"]'::jsonb, 'Akut otitis media', 'Akut otitis media uppstår när en övre luftvägsinfektion leder till dysfunktion av tuba auditiva så att sekret ansamlas i mellanörat. Utbuktande, rodnad trumhinna med feber och öronvärk är typiskt, medan otitis externa ger smärta vid dragning i öronmusslan och sekretorisk otit ger vätska utan akut inflammation.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-4-q2', 'km4-4', NULL, 'mcq', 'En 42-årig man har kraftig näsblödning från vänster näsborre sedan 25 minuter. Han är hyperton och tar blodtryckssänkande medicin. Blödningen kommer från septum i den främre delen av näsan. Vilket område blöder och vad gör du först?', '["Plexus Kiesselbachi – komprimera näsvingen och sätt patienten upprätt framåtlutad","Sinus sphenoidalis – lägg patienten på rygg utan kompression","Tonsillerna – svalgtamponad direkt","Mellanörat – trumhinneincision"]'::jsonb, 'Plexus Kiesselbachi – komprimera näsvingen och sätt patienten upprätt framåtlutad', 'De flesta främre näsblödningar kommer från plexus Kiesselbachi på septum, ett kärlrikt område där flera artärer möts. Korrekt första åtgärd är tryck mot näsvingen i cirka 10–15 minuter med patienten upprätt och framåtlutad så att blod inte sväljs. Bakre blödningar ger blod i svalget och kräver oftast tamponad av bakre näshålan.', 1, 2, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-4-q3', 'km4-4', NULL, 'mcq', 'En 62-årig man som röker söker för heshet som varat i sex veckor och som tilltagit. Han har gått ner i vikt och har en palpabel körtel på halsens vänstra sida. Han har fått antibiotika utan effekt. Vad ska göras?', '["Remiss för utredning med laryngoskopi och biopsi vid misstänkt larynx- eller hypofarynxcancer","Förnyad antibiotikakur","Behandling med protonpumpshämmare och kontroll om sex månader","Röstvila i tre månader"]'::jsonb, 'Remiss för utredning med laryngoskopi och biopsi vid misstänkt larynx- eller hypofarynxcancer', 'Heshet som varar över tre veckor, särskilt med rökning, viktnedgång och palpabel halskörtel, är en varningssignal för malignitet i larynx eller hypofarynx och ska utredas med laryngoskopi. Upprepad antibiotika eller lång observation fördröjer diagnosen.', 1, 3, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-4-q4', 'km4-4', NULL, 'cloze', 'En 38-årig kvinna får plötslig kraftig yrsel, illamående och kräkningar och kan inte stå stadigt. Hon har spontannystagmus men normal hörsel och inga centrala neurologiska bortfall. Detta talar för ______.', NULL, 'vestibularisneurit', 'Vestibularisneurit är en inflammation i vestibularisnerven, ofta efter en virusinfektion, som ger akut perifer yrsel utan hörselpåverkan. Centrala symtom som dubbelseende, talstörning eller bortfall av kraft ska i stället väcka misstanke om stroke i hjärnstammen eller lillhjärnan.', 1, 4, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-5-q1', 'km4-5', NULL, 'mcq', 'En 24-årig man slår huvudet i en trappa, är vaken och klar i huvudet i några minuter men blir sedan allt slöare. Vid ankomst är höger pupill vidgad och reagerar inte på ljus, och han har högersidig svaghet i armen. Vilken struktur är skadad och vilket tillstånd föreligger?', '["Epiduralt hematom efter skada på a. meningea media","Subduralt hematom efter skada på bryggvener","Kroniskt subduralhematom med långsam utveckling","Subaraknoidalblödning från rupturerat aneurysm"]'::jsonb, 'Epiduralt hematom efter skada på a. meningea media', 'Epiduralt hematom är arteriellt och ger ett snabbt förlopp, ofta med ett kort vaket intervall innan försämring. DT visar en linsformad (bikonvex) samling. Den vidgade ipsilaterala pupillen beror på transtentoriell herniering som trycker på n. oculomotorius, ett akut neurokirurgiskt tillstånd.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-5-q2', 'km4-5', NULL, 'mcq', 'En 68-årig kvinna som behandlas med blodförtunnande har haft lätt huvudvärk och tilltagande förvirring under tre veckor. Hon slog huvudet lätt i badrummet för en månad sedan. DT visar en halvmåneformad samling längs hemisfärens yta. Vilken diagnos föreligger?', '["Kroniskt subduralhematom","Epiduralt hematom","Subaraknoidalblödning","Hjärnabscess"]'::jsonb, 'Kroniskt subduralhematom', 'Kroniskt subduralhematom uppstår efter lindrigt trauma med skada på bryggvener, blöder långsamt och ger progredierande neurologiska symtom över veckor. På DT ses en halvmåneformad samling som kan korsa suturerna, till skillnad från det linsformade epidurala hematomet som inte passerar suturer.', 1, 2, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-5-q3', 'km4-5', NULL, 'mcq', 'En 45-årig kvinna får plötslig, extremt svår huvudvärk som hon beskriver som ''ett slag mot bakhuvudet'', och hon kräks. Hon är lätt nackstyv. DT utan kontrast är utan säkra tecken på blödning. Vad gör du?', '["Lumbalpunktion för att leta efter xanthokromi/blod i cerebrospinalvätskan","Skickar hem henne med analgetika","Beställer MR av halsryggen","Ger antibiotika mot meningit och avvaktar"]'::jsonb, 'Lumbalpunktion för att leta efter xanthokromi/blod i cerebrospinalvätskan', 'Thunderclap-huvudvärk ger stark misstanke om subaraknoidalblödning, oftast från ett rupturerat aneurysm. En tidig DT kan vara falskt negativ, varför lumbalpunktion med analys av xanthokromi är nästa steg. Att skicka hem patienten riskerar blödningsrecidiv med hög mortalitet.', 1, 3, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km4-5-q4', 'km4-5', NULL, 'cloze', 'En patient med uttalat höjt intrakraniellt tryck har bradycardi, hypertoni och oregelbunden andning. Detta symtomtrias kallas ______.', NULL, 'Cushings trias', 'Cushings trias uppstår när herniering komprimerar hjärnstammen och ger ökad sympatikusaktivitet med hypertoni och reflexbradycardi samt andningsstörning. Det är ett sent och allvarligt tecken på hotande herniering.', 1, 4, 'kapitel', false)
