INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-1-q1', 'km5-1', NULL, 'mcq', 'En 10-månaders flicka kommer på kontroll. Hon kan inte sitta utan stöd och har inte börjat gripa efter leksaker med vilja. Föräldrarna har inte märkt något avvikande. Hur bör du agera?', '["Avvikande utveckling för åldern – utredning med neurologisk bedömning, syn- och hörselkontroll","Normal variation – ingen åtgärd, kontroll vid 18 månader","Enbart råd om mer magläge och återbesök om ett år","Remiss direkt till ortoped för misstänkt höftledsluxation"]'::jsonb, 'Avvikande utveckling för åldern – utredning med neurologisk bedömning, syn- och hörselkontroll', 'De flesta barn sitter utan stöd vid 6–8 månader och griper aktivt efter föremål betydligt tidigare, så att inte kunna sitta vid 10 månader är en tydlig avvikelse som kräver utredning. Att avvakta riskerar att fördröja diagnostik av cerebral pares, neuromuskulär sjukdom eller syn-/hörselnedsättning.', 1, 1, 'kapitel', false)
