  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-1-q2', 'km5-1', NULL, 'mcq', 'En 3-årig pojke talar bara enstaka ord som bara föräldrarna förstår, han har alltid varit svår att väcka och reagerar inte på ljud bakom sig. Vad är den viktigaste första åtgärden?', '["Hörselutredning","Remiss till logoped utan hörselkontroll","Diagnostik för autism utan vidare utredning","Avvakta till skolstart"]'::jsonb, 'Hörselutredning', 'Hörseln är grunden för språkutveckling, och nedsatt hörsel är en vanlig och behandlingsbar orsak till försenad språkutveckling. Därför ska hörseln alltid kontrolleras först, medan logoped och autismutredning kan bli aktuella därefter.', 1, 2, 'kapitel', false)
