INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-1-q3', 'km5-1', NULL, 'mcq', 'En 11-årig flicka remitteras för misstänkt tidig pubertet. Vilket är det första pubertetstecknet hos flickor respektive pojkar?', '["Flickor: bröstutveckling (telarke). Pojkar: ökad testikelvolym","Flickor: menarche. Pojkar: skäggväxt","Flickor: pubeshår. Pojkar: röstmörkning","Flickor: tillväxtspurt. Pojkar: axelbreddning"]'::jsonb, 'Flickor: bröstutveckling (telarke). Pojkar: ökad testikelvolym', 'Puberteten indelas i Tanner-stadier, där telarke (bröststadium 2) inleder hos flickor och en testikelvolym över 4 ml inleder hos pojkar. Menarche kommer sent i puberteten och är därför inget tidigt tecken.', 1, 3, 'kapitel', false)
