INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-1-q4', 'km5-1', NULL, 'cloze', 'Ett barns längd följer en kurva som planar ut och korsar percentillinjer nedåt mellan kontrollerna. Detta talar för sänkt ______, vilket är ett viktigare fynd än den aktuella längden.', NULL, 'tillväxthastighet', 'Vid bedömning av tillväxt är tillväxthastigheten mer känslig än den absoluta längden; en utplanande kurva kan vara första tecknet på systemsjukdom, malnutrition, celiaki eller tillväxthormonbrist.', 1, 4, 'kapitel', false)
