INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-2-q1', 'km5-2', NULL, 'mcq', 'Ett barn fött i graviditetsvecka 28 utvecklar inom några timmar takypné, indragningar och grymtande andning. Lungröntgen visar diffusa, retikulogranulära infiltrat och luftbronkogram, och barnet behöver CPAP. Vad är den bakomliggande mekanismen?', '["Surfaktantbrist leder till ökad ytspänning och alveolar kollaps","Överflöd av surfaktant ger hyperinflation","Mekoniumaspiration med luftvägsobstruktion","Medfödd hjärtmissbildning med vänster-höger-shunt"]'::jsonb, 'Surfaktantbrist leder till ökad ytspänning och alveolar kollaps', 'Surfaktant produceras av typ II-pneumocyter och sänker ytspänningen så att alveolerna hålls öppna vid låg volym. Vid prematuritet är produktionen otillräcklig, vilket ger atelektaser, minskad lungcomplians och hypoxi – respiratory distress syndrome.', 1, 1, 'kapitel', false)
