  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-2-q2', 'km5-2', NULL, 'mcq', 'En 10 dagar gammal nyfödd som ammar allt sämre blir slö och blek, har temp 38,4 grader och andas fort. Vilken är den mest sannolika orsaken och hur handläggs det?', '["Neonatal sepsis – omedelbar inläggning, blododling och intravenös antibiotikabehandling","Förkylning – råd om nässpray och kontroll om några dagar","Övermatning – minska måltiderna","Normal nyföddhetsanpassning – avvakta"]'::jsonb, 'Neonatal sepsis – omedelbar inläggning, blododling och intravenös antibiotikabehandling', 'Nyfödda har omoget immunförsvar och ger ofta ospecifika symtom som dålig amning, slöhet, temperaturinstabilitet och takypné. Sepsis kan utvecklas på timmar, så låg tröskel för odling och intravenös antibiotika gäller. Grupp B-streptokocker och E. coli är vanliga agens.', 1, 2, 'kapitel', false)
