  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-2-q3', 'km5-2', NULL, 'mcq', 'Ett barn som är 20 timmar gammalt är kraftigt gulfärgat ända ut i handflator och fotsulor. Barnet är fött i vecka 39 och är i övrigt opåverkat. Hur ska fyndet tolkas?', '["Patologisk ikterus – utredning för hemolys, immunisering eller infektion påbörjas","Fysiologisk ikterus som inte behöver åtgärd","Tecken på bröstmjölksikterus som kommer sent","Normalt fynd första dygnet som bara behöver följas med ögat"]'::jsonb, 'Patologisk ikterus – utredning för hemolys, immunisering eller infektion påbörjas', 'Ikterus som debuterar inom första dygnet är alltid patologisk och ska utredas, eftersom den kan bero på hemolytisk sjukdom (Rh-/ABO-immunisering), infektion eller enzymbrist. Fysiologisk ikterus kommer typiskt efter 24–48 timmar och når sin topp dag 3–5.', 1, 3, 'kapitel', false)
