INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-2-q4', 'km5-2', NULL, 'cloze', 'Om obundet bilirubin hos en nyfödd blir mycket högt och passerar blod-hjärnbarriären kan det ge bestående neurologisk skada, vilket kallas ______.', NULL, 'kernikterus', 'Bilirubin är lipofilt och kan vid hög koncentration avlagras i basilarganglierna hos den nyfödde, vilket ger kernikterus med bland annat rörelsestörningar och hörselpåverkan. Behandlingstrappan är ljusbehandling och i svåra fall utbyte av blod.', 1, 4, 'kapitel', false)
