INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-3-q1', 'km5-3', NULL, 'mcq', 'En 4-årig ovaccinerad pojke får hög feber, hosta, rinnande ögon och förkylningssymtom. Efter tre dagar upptäcks vita beläggningar på insidan av kinderna, och därefter ett utslag som börjar bakom öronen och i ansiktet för att sprida sig nedåt. Vilken diagnos är mest sannolik?', '["Mässling","Röda hund","Vattkoppor","Scharlakansfeber"]'::jsonb, 'Mässling', 'Kopliks fläckar på kindens slemhinna följt av ett kraniokaudalt spridande makulopapulöst utslag är klassiskt för mässling. Röda hund ger ett ljusare utslag som börjar i ansiktet men med lindrigare allmänpåverkan och retroaurikulära körtlar, och vattkoppor ger kliande vesiklar i olika stadier.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-3-q2', 'km5-3', NULL, 'mcq', 'En 3-årig ovaccinerad flicka är kraftigt påverkad med hög feber, dreglande, inspiratorisk stridor och sitter framåtlutat med hakan framåt. Hon vill inte svälja. Vad gör du?', '["Larma omedelbart och säkra luftvägen – misstänkt epiglottit, undvik att titta i halsen","Undersök halsen noggrant med spatel och tryck ned tungan","Ge hostmedicin och skicka hem","Lägg henne ned på rygg och palpera halsen"]'::jsonb, 'Larma omedelbart och säkra luftvägen – misstänkt epiglottit, undvik att titta i halsen', 'Epiglottit ger snabbt tilltagande luftvägsobstruktion; symtom som dreglande, trippodställning och hög feber är varningssignaler. Undersökning av svalget kan utlösa total obstruktion och ska undvikas utan beredskap att säkra luftvägen. Haemophilus influenzae typ b-vaccin har gjort tillståndet ovanligt.', 1, 2, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-3-q3', 'km5-3', NULL, 'mcq', 'Ett 3 månader gammalt barn har haft hostattacker i två veckor. Under attackerna hostar han kraftigt flera gånger i följd och slutar sedan andas, varpå han kiknar och kräks. Mellan attackerna är han relativt opåverkad. Vilken diagnos är mest sannolik?', '["Kikhosta","Bronkiolit orsakad av RS-virus","Krupp","Frånvaro av sjukdom – normal hosta"]'::jsonb, 'Kikhosta', 'Kikhosta (Bordetella pertussis) ger paroxysmal hosta med kikningar och posttussiv kräkning; hos spädbarn kan apnéer vara det dominerande symtomet. Bronkiolit ger i stället takypné, indragningar och pipande andning, och krupp ger skällande hosta med inspiratorisk stridor.', 1, 3, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-3-q4', 'km5-3', NULL, 'cloze', 'I det svenska barnvaccinationsprogrammet ges ett kombinationsvaccin mot mässling, påssjuka och röda hund, vilket förkortas ______.', NULL, 'MPR', 'MPR-vaccinet är ett levande försvagat vaccin som ges i två doser och har gjort de tre sjukdomarna ovanliga i Sverige. Hög täckning behövs för att behålla flockimmuniteten.', 1, 4, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-4-q1', 'km5-4', NULL, 'mcq', 'En 5-månaders pojke har sedan två dagar snuva och nu tilltagande hosta. Han andas 65 gånger per minut, har indragningar mellan revbenen, grymtar och syremättnaden är sänkt. Auskultation visar pipande andning och fina rassel. Vilken behandling är den viktigaste?', '["Stödjande behandling med syrgas och vätska, vid behov andningsstöd","Rutinmässig antibiotikabehandling","Inhalationer med kortison som enda åtgärd","Omedelbar intubation av alla barn med bronkiolit"]'::jsonb, 'Stödjande behandling med syrgas och vätska, vid behov andningsstöd', 'Bronkiolit är oftast virusorsakad (RS-virus) och behandlas stödjande; antibiotika har ingen effekt på virus och ges bara vid misstänkt bakteriell komplikation. Kortison och bronkodilatatorer har ingen säker rutineffekt hos spädbarn, medan syrgas och vätska är avgörande.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-4-q2', 'km5-4', NULL, 'mcq', 'En 2-årig flicka får på natten skällande hosta, hes röst och inspiratorisk stridor efter några dagars förkylning. Hon är vaken men besvärad. Vilken behandling är förstahandsval?', '["Kortison, och vid svårare stridor även inhalationsbehandling med adrenalin","Antibiotika mot Haemophilus influenzae","Slemhinneavsvällande näsdroppar som enda åtgärd","Omedelbar tracheostomi"]'::jsonb, 'Kortison, och vid svårare stridor även inhalationsbehandling med adrenalin', 'Krupp (akut laryngit) orsakas av virus och ger ödem i subglottis. Kortison minskar ödemet och ges till alla med måttliga besvär; inhalationsadrenalin ges vid svårare stridor i väntan på effekt. Antibiotika har ingen plats eftersom orsaken är viral.', 1, 2, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-4-q3', 'km5-4', NULL, 'mcq', 'En 2-årig pojke leker med jordnötter när han plötsligt slutar andas, hostar till och blir blå om läpparna. Han kan inte gråta eller hosta. Vad gör du?', '["Ryggslag och därefter buktryck, och larma omedelbart","Ge honom vatten att dricka","Lägg honom på sidan och vänta på ambulans","Sätt fingret i halsen och försök fiska upp nöten"]'::jsonb, 'Ryggslag och därefter buktryck, och larma omedelbart', 'Oförmåga att hosta, gråta eller andas vid misstänkt aspiration innebär total luftvägsobstruktion och kräver omedelbara ryggslag och buktryck. Blint fingersök i svalget kan trycka ned föremålet djupare och ska undvikas. Vid kvarstående obstruktion krävs laryngoskopi och avlägsnande.', 1, 3, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km5-4-q4', 'km5-4', NULL, 'cloze', 'En 14-månaders flicka med feber får generaliserade kramper som varar i två minuter och därefter sover hon djupt en stund. Hon är sedan vaken och reagerar normalt. Detta är en ______.', NULL, 'feberkramp', 'Enkla feberkramper är vanliga mellan 6 månader och 5 år, varar under 15 minuter och ger inga postiktala fokala bortfall. Utredning med LP eller EEG krävs inte vid typisk enkel feberkramp, men vid långvariga, fokala eller upprepade anfall utreds bakomliggande orsak.', 1, 4, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km6-1-q1', 'km6-1', NULL, 'mcq', 'En 34-årig kvinna i graviditetsvecka 34 söker för riklig, smärtfri vaginal blödning som börjat plötsligt. Livmodern är mjuk och oöm, barnet rör sig normalt på CTG. Vad gör du?', '["Lägger in henne och gör ultraljud – undvik vaginal undersökning","Gör vaginal undersökning för att bedöma blödningskällan","Skickar hem henne med råd om vila","Startar värkstimulerande behandling för att påskynda förlossning"]'::jsonb, 'Lägger in henne och gör ultraljud – undvik vaginal undersökning', 'Smärtfri vaginal blödning sent i graviditeten är typisk för placenta previa, där placentan ligger över inre modermunnen. En vaginal undersökning kan då riva sönder placenta och utlösa livshotande blödning, så placentans läge måste först bedömas med ultraljud.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km6-1-q2', 'km6-1', NULL, 'mcq', 'Under en förlossning visar CTG upprepade decelerationer som börjar efter att värken kulminerat och som återhämtar sig långsamt. Vilken mekanism ligger bakom detta mönster?', '["Utebliven syretillförsel via placentan vid värken (uteroplacentär insufficiens)","Navelsträngskompression, som ger variabla decelerationer","Fostrets normala reaktion vid huvudets nedträngande","Mammans andning ger artefakt i registreringen"]'::jsonb, 'Utebliven syretillförsel via placentan vid värken (uteroplacentär insufficiens)', 'Sena decelerationer speglar en redan nedsatt reservkapacitet i placentan: under värken minskar blodflödet så mycket att fostersyresättningen sviktar. Variabla decelerationer beror i stället på navelsträngskompression och har ett annat utseende.', 1, 2, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
