INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km6-1-q3', 'km6-1', NULL, 'mcq', 'Efter att huvudet fötts fastnar axlarna och trots kraftig värk kommer ingen vidare utdrivning. Vilken är den första åtgärden?', '["McRoberts position – kraftig höjning av benen och tryck ovan blygdbenet","Öka värkstyrkan med infusion av oxytocin","Dra kraftigt i barnets huvud","Avvakta nästa värk och sedan göra kristellers uttagning direkt"]'::jsonb, 'McRoberts position – kraftig höjning av benen och tryck ovan blygdbenet', 'Vid axelinkärkning ska höftlederna kraftigt flekteras (McRoberts) och suprapubiskt tryck ges, vilket ändrar bäckenets vinkel och frigör den fastnade axeln. Att dra i huvudet ökar risken för plexus brachialis-skada, och oxytocin förvärrar inklämningen.', 1, 3, 'kapitel', false)
