INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km6-1-q4', 'km6-1', NULL, 'cloze', 'Tio minuter efter en vaginal förlossning blöder patienten rikligt, livmodern är slapp och når ovan naveln. Diagnosen är ______, den vanligaste orsaken till postpartumblödning.', NULL, 'livmoderatoni', 'Efter förlossningen måste myometriet dra ihop sig för att stänga av blodkärlen vid placentarfästet. Vid atoni uteblir detta, vilket ger riklig blödning. Behandlingen är uteruskontraherande läkemedel, livmodermassage och vid behov kirurgisk åtgärd.', 1, 4, 'kapitel', false)
