INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km6-2-q1', 'km6-2', NULL, 'mcq', 'En 29-årig förstföderska i graviditetsvecka 35 har blodtryck 168/112, proteinuri, huvudvärk och synstörningar i form av flimmer för ögonen. Vilken behandling är central för att förebygga kramper?', '["Magnesiumsulfat som krampförebyggande behandling","Antibiotika mot misstänkt infektion","Enbart vätsketillförsel och vila","Sänkt saltintag och sederande läkemedel"]'::jsonb, 'Magnesiumsulfat som krampförebyggande behandling', 'Vid preeklampsi med svåra symtom (högt blodtryck, neurologiska symtom, synstörningar) ges magnesiumsulfat för att förebygga eklampsi, det vill säga kramper. Definitiv behandling är förlossning, medan blodtryckssänkning och övervakning är stödjande.', 1, 1, 'kapitel', false)
