INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km6-2-q2', 'km6-2', NULL, 'mcq', 'En 27-årig kvinna i graviditetsvecka 7 söker med ensidig buksmärta och lätt vaginal blödning. Hon har tidigare haft en klamydiainfektion. S-hCG är positivt men ultraljud visar tom livmoder. Vilken diagnos är mest sannolik?', '["Extrauterin graviditet","Missed abortion","Normal tidig graviditet","Äggstockscancer"]'::jsonb, 'Extrauterin graviditet', 'Positivt hCG utan intrauterin graviditet vid ultraljud, ensidig smärta och tidigare klamydia (som ger tubarskada) talar för extrauterin graviditet. Risken är tubarruptur med massiv blödning, varför uppföljning av hCG och ultraljud är avgörande.', 1, 2, 'kapitel', false)
