INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km6-2-q3', 'km6-2', NULL, 'mcq', 'En 31-årig kvinna i graviditetsvecka 28 har högt BMI och ett tidigare barn som vägde mycket vid födseln. Vilken är den lämpligaste åtgärden för att upptäcka graviditetsdiabetes?', '["Peroral glukosbelastning med kontroll av blodsocker","Upprepade fasteblodsocker varje vecka utan belastning","Ingen screening eftersom hon saknar symtom","Ultraljud av buken i stället för blodprov"]'::jsonb, 'Peroral glukosbelastning med kontroll av blodsocker', 'Graviditetsdiabetes screenas med peroral glukosbelastning hos kvinnor med riskfaktorer som hög ålder, övervikt och tidigare makrosomt barn. Behandling är i första hand kostråd och egenkontroll av blodsocker, med insulin om målen inte nås; sjukdomen påverkar både mor och barn.', 1, 3, 'kapitel', false)
