INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km6-2-q4', 'km6-2', NULL, 'cloze', 'En kvinna i graviditetsvecka 30 upptäcker att fosterrörelserna upphört, och ultraljud visar inga hjärtljud. Tillståndet kallas ______.', NULL, 'intrauterin fosterdöd', 'Intrauterin fosterdöd innebär att fostret dör efter att ha uppnått en viss graviditetslängd. Utredningen omfattar bland annat infektioner, placentarpatologi, diabetes och kromosomavvikelser, och förlossning sätts igång.', 1, 4, 'kapitel', false)
