INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('ai-km6-2-f4241966', 'km6-2', NULL, 'mcq', 'En 32-årig förstföderska i graviditetsvecka 34 kommer till akutmottagningen med huvudvärk och synrubbningar. Blodtrycket är 165/110 mmHg och urinprov visar kraftig proteinuri. Vilket av följande fynd skulle starkast tala för att hon har utvecklat allvarlig preeklampsi med behov av omedelbar åtgärd?', '["Blodtryck 165/110 mmHg tillsammans med synrubbningar och påverkat allmäntillstånd","Lindrig perifer ödem i fotlederna","Ett enstaka blodtryck på 145/95 mmHg utan symtom","Proteinuri utan samtidig hypertoni"]'::jsonb, 'Blodtryck 165/110 mmHg tillsammans med synrubbningar och påverkat allmäntillstånd', 'Allvarlig preeklampsi kännetecknas av svår hypertoni (diastoliskt tryck kring 110 mmHg eller högre) i kombination med organsymtom som huvudvärk, synrubbningar eller påverkat allmäntillstånd – detta kräver omedelbar åtgärd och övervakning. Det vanligaste distraktionsalternativet, lindrig perifer ödem, är mycket vanligt hos gravida utan att vara tecken på allvarlig sjukdom och saknar den akuta handläggningsbetydelsen.', 2, 5, 'ai', true)
