INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km6-3-q1', 'km6-3', NULL, 'mcq', 'En 44-årig kvinna söker för rikliga menstruationer med koagel, tryckkänsla i buken och täta trängningar till urinering. Ultraljud visar flera väl avgränsade, solida förändringar i livmoderväggen. Vilken diagnos är mest sannolik?', '["Uterusmyom","Endometriecancer","Ovarialcysta","Cervixcancer"]'::jsonb, 'Uterusmyom', 'Myom (leiomyom) är benigna muskelknutor i myometriet som ger rikliga menstruationer och trycksymtom beroende på läge, och de framstår som väl avgränsade solida förändringar på ultraljud. Endometriecancer ger i stället postmenopausal blödning, och en ovarialcysta ger oftast inga blödningssymtom.', 1, 1, 'kapitel', false)
