INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km6-3-q3', 'km6-3', NULL, 'mcq', 'En 23-årig kvinna har sedan tonåren svår dysmenorré som inte lindras av vanliga smärtstillande medel, djup dyspareuni och tilltagande bäckensmärta. Hon vill bli gravid. Vilken diagnos är mest sannolik?', '["Endometrios","Akut salpingit","Uterusmyom","Premenstruellt syndrom"]'::jsonb, 'Endometrios', 'Endometrios innebär endometrieliknande vävnad utanför livmodern som blöder vid menstruation och ger inflammation, ärrbildning och adherenser. Klassisk bild är tilltagande dysmenorré, dyspareuni och infertilitet. Salpingit är akut med feber, och myom debuterar oftast senare i livet.', 1, 3, 'kapitel', false)
