INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km6-3-q4', 'km6-3', NULL, 'cloze', 'Cytologisk provtagning från livmoderhalsen i kombination med HPV-test används för att upptäcka förstadier till ______.', NULL, 'cervixcancer', 'Cervixcancer uppstår nästan alltid via persisterande infektion med högrisk-HPV, och förstadier kan upptäckas och behandlas genom screening. Vaccination mot HPV förebygger de vanligaste onkogena typerna.', 1, 4, 'kapitel', false)
