  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km6-4-q2', 'km6-4', NULL, 'mcq', 'En 36-årig kvinna som röker vill börja med p-piller. Hon har migrän med aura sedan tonåren och blodtrycket är 138/88. Vad rekommenderar du?', '["Gestagenbaserat preventivmedel – kombinerade metoder är olämpliga vid migrän med aura och rökning","Kombinerat p-piller med låg östrogendos","Kombinerat p-piller men bara under sex månader","Ingen preventivmedelsrådgivning behövs"]'::jsonb, 'Gestagenbaserat preventivmedel – kombinerade metoder är olämpliga vid migrän med aura och rökning', 'Östrogeninnehållande preventivmedel ökar tromboembolismrisken, och migrän med aura plus rökning hos kvinna över 35 år är en uttalad riskkombination för stroke. Gestagena metoder, till exempel p-stav eller hormonspiral, är därför ett säkrare val.', 1, 2, 'kapitel', false)
