  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km6-4-q3', 'km6-4', NULL, 'mcq', 'Ett par söker eftersom de försökt bli gravida i ett och ett halvt år. Kvinnan är 31 år och har regelbunden menstruation. Vilken undersökning är central i den basala utredningen?', '["Spermaanalys från mannen","Endast hormonprov på kvinnan","Laparoskopi som första åtgärd","Ingen utredning före två års försök"]'::jsonb, 'Spermaanalys från mannen', 'Infertilitet utreds alltid hos båda parter, och spermaanalys är en enkel och central del eftersom manlig faktor är vanlig. Kvinnan utreds med ovulation, äggledarpassage och livmoderbedömning. Laparoskopi är inte förstahandsval.', 1, 3, 'kapitel', false)
