INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km6-4-q4', 'km6-4', NULL, 'cloze', 'En obehandlad klamydiainfektion kan ge ärrbildning i äggledarna och därmed ökad risk för ______, eftersom det befruktade ägget fastnar på vägen ned till livmodern.', NULL, 'extrauterin graviditet', 'Klamydia ger ofta få symtom men kan orsaka tubarskada med nedsatt äggledartransport. Detta är en viktig orsak till både infertilitet och extrauterin graviditet, vilket är skälet till att tidig testning och behandling är viktig.', 1, 4, 'kapitel', false)
