INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-1-q1', 'km7-1', NULL, 'mcq', 'En 38-årig kvinna har flera släktingar med bröst- och äggstockscancer i unga år. Hon bär på en sjukdomsgivande variant i BRCA1. Vilken typ av gen rör det sig om?', '["Tumörsuppressorgen – båda alleler måste vara inaktiverade","Onkogen – en aktiverad allel räcker","Fusionsgen som bildas vid translokation","Gen för ett reparationsprotein som aldrig kan skadas"]'::jsonb, 'Tumörsuppressorgen – båda alleler måste vara inaktiverade', 'BRCA1/2 är tumörsuppressorgener som deltar i reparation av dubbelsträngsbrott i DNA. Enligt Knudsons två-hit-hypotes krävs inaktivering av båda allelerna, vilket förklarar den höga livstidsrisken men också varför ärftligheten är dominant på familjenivå men recessiv på cellnivå. Onkogener kräver tvärtom bara en aktiverad allel (gain of function).', 1, 1, 'kapitel', false)
