  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-1-q2', 'km7-1', NULL, 'mcq', 'En 64-årig man söker för trötthet och viktnedgång. Blodprov visar järnbristanemi utan känd blödningskälla, och han är avföringsprovspositiv. Vilken utredning är den centrala?', '["Kolonoskopi","Övre gastroskopi som enda undersökning","Ultraljud av njurarna","Bentäthetsmätning"]'::jsonb, 'Kolonoskopi', 'Järnbristanemi hos en äldre man utan uppenbar blödningskälla är ett klassiskt tecken på högersidig koloncancer, som blöder långsamt och därför inte ger synligt blod i avföringen. Koloskopi ger både diagnos och möjlighet till biopsi och eventuell polypbehandling.', 1, 2, 'kapitel', false)
