INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-1-q3', 'km7-1', NULL, 'mcq', 'En tumör i colon sigmoideum har vuxit genom tarmväggen och spridit sig till regionala lymfkörtlar men inte till lever eller lungor. Vad beskriver denna beskrivning?', '["Stadium med lokal tumörutbredning och regionala lymfkörtelmetastaser (T och N)","Tumörens histologiska grad","Tumörens molekylära profil","Tumörens tillväxthastighet"]'::jsonb, 'Stadium med lokal tumörutbredning och regionala lymfkörtelmetastaser (T och N)', 'TNM beskriver utbredning: T för tumörens djup, N för regionala lymfkörtlar och M för fjärrmetastaser. Grad beskriver i stället hur differentierade cellerna är och är en separat bedömning som påverkar prognos men inte stadium.', 1, 3, 'kapitel', false)
