INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-1-q4', 'km7-1', NULL, 'cloze', 'En tumör som växer över några millimeter behöver egen blodförsörjning. Förmågan att stimulera nybildning av kärl kallas ______.', NULL, 'angiogenes', 'Tumörceller frisätter bland annat VEGF som stimulerar tillväxt av nya blodkärl, vilket möjliggör fortsatt tillväxt och ger väg ut i blodbanan. Angiogeneshämmare används därför som cancerbehandling.', 1, 4, 'kapitel', false)
