INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-2-q1', 'km7-2', NULL, 'mcq', 'En patient som får cytostatika utvecklar håravfall, sår i munslemhinnan och sjunkande neutrofila granulocyter. Varför uppstår just dessa biverkningar?', '["Cytostatika skadar alla snabbt delande celler, inte bara tumörceller","Cytostatika binder specifikt till tumörcellernas DNA-reparationsenzymer","Biverkningarna beror på allergisk reaktion mot läkemedlet","Biverkningarna orsakas av vätskeansamling i vävnaderna"]'::jsonb, 'Cytostatika skadar alla snabbt delande celler, inte bara tumörceller', 'Cytostatika verkar på mekanismer som DNA-skada, mikrotubuli och nukleotidsyntes, vilka alla är centrala i delande celler. Därför drabbas benmärg, slemhinnor och hårsäckar, som delar sig snabbt men friskt. Det är också skälet till att behandlingen ges i kurer med återhämtningsperioder.', 1, 1, 'kapitel', false)
