INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-2-q2', 'km7-2', NULL, 'mcq', 'Varför delas strålbehandling upp i många små fraktioner i stället för att ges som en enda stor dos?', '["Normalvävnad hinner reparera skador mellan fraktionerna samtidigt som tumörceller ansamlas i känsliga cellfaser","Fraktionering gör strålningen starkare per tillfälle","Fraktionering behövs bara för att patienten ska slippa biverkningar helt","Fraktionering ökar tumörens syretillförsel så att den blir mer motståndskraftig"]'::jsonb, 'Normalvävnad hinner reparera skador mellan fraktionerna samtidigt som tumörceller ansamlas i känsliga cellfaser', 'Strålning skadar DNA direkt och via fria radikaler. Fraktionering utnyttjar att normalvävnad reparerar subletala skador bättre än tumörvävnad och att celler omfördelas till känsliga cellcykelfaser, vilket ökar den terapeutiska kvoten. En enda stor dos skulle ge mer skada på frisk vävnad.', 1, 2, 'kapitel', false)
