INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-2-q3', 'km7-2', NULL, 'mcq', 'En patient opereras med radikal resektion av en koloncancer, och det finns inga synliga metastaser. Efter operationen erbjuds cytostatikabehandling i sex månader. Vad kallas denna behandling?', '["Adjuvant behandling","Neoadjuvant behandling","Palliativ behandling","Induktionsbehandling"]'::jsonb, 'Adjuvant behandling', 'Adjuvant behandling ges efter att all synlig tumör avlägsnats, i syfte att slå ut mikrometastaser och minska recidivrisken. Neoadjuvant behandling ges i stället före operation för att krympa tumören och öka chansen till radikal resektion.', 1, 3, 'kapitel', false)
