INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-2-q4', 'km7-2', NULL, 'cloze', 'Behandling som ges före operation för att minska tumörens storlek och göra den lättare att avlägsna radikalt kallas ______ behandling.', NULL, 'neoadjuvant', 'Neoadjuvant behandling ges före kirurgi, vanligt vid exempelvis rektalcancer och bröstcancer. Den kan göra en primärt inoperabel tumör operabel och ger samtidigt information om tumörens känslighet.', 1, 4, 'kapitel', false)
