INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-3-q1', 'km7-3', NULL, 'mcq', 'En 71-årig man med spridd prostatacancer har svår smärta trots adekvat opioidbehandling. Han är samtidigt djupt nedstämd, orolig för ekonomin och känner att livet saknar mening. Vad menas med ''total smärta'' i denna situation?', '["Smärtan har fysiska, psykiska, sociala och existentiella komponenter som alla måste hanteras","Att smärtan är så svår att den kräver högsta möjliga opioid dos","Att smärtan kommer från flera olika metastaser samtidigt","Att patienten överdriver sina besvär"]'::jsonb, 'Smärtan har fysiska, psykiska, sociala och existentiella komponenter som alla måste hanteras', 'Begreppet total smärta beskriver att lidande vid livshotande sjukdom är sammansatt. Enbart ökad opioid dos löser inte oro, ekonomi eller existentiell kris; därför krävs ett tvärprofessionellt team med läkare, sjuksköterska, kurator, psykolog och vid behov präst.', 1, 1, 'kapitel', false)
