INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-3-q3', 'km7-3', NULL, 'mcq', 'En 68-årig kvinna med obotlig lungsjukdom blir allt svagare. Vad innebär ett brytpunktssamtal?', '["Ett strukturerat samtal där man samtalar om sjukdomens förlopp, patientens önskemål och att vården övergår till att vara lindrande","Ett samtal där läkaren meddelar att behandlingen avslutas mot patientens vilja","Ett samtal som bara förs med närstående","Ett samtal som bara handlar om ställningstagande till HLR"]'::jsonb, 'Ett strukturerat samtal där man samtalar om sjukdomens förlopp, patientens önskemål och att vården övergår till att vara lindrande', 'Brytpunktssamtalet är ett planerat samtal med patienten och närstående där man klargör sjukdomens förlopp, förväntade symtom, vårdens inriktning och patientens önskemål, inte minst om plats för vård i livets slut. HLR-frågan ingår som en del men samtalet är bredare.', 1, 3, 'kapitel', false)
