INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-3-q4', 'km7-3', NULL, 'cloze', 'Vid medelsvår till svår cancersmärta är den grundläggande farmakologiska behandlingen ______, som trappas upp stegvis och ges med dosering anpassad efter symtom.', NULL, 'opioider', 'Enligt WHO:s smärtstege används vid medelsvår till svår smärta starka opioider som morfin, oberoende av förväntad överlevnad. Behandlingen titreras efter effekt och biverkningar, och vid neuropatisk smärta kompletteras den med antidepressiva eller antiepileptika.', 1, 4, 'kapitel', false)
