INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-4-q1', 'km7-4', NULL, 'mcq', 'En 54-årig kvinna som fick cytostatika för åtta dagar sedan kommer med feber 38,6 grader och ett neutrofilt granulocytvärde på 0,3. Hon ser i övrigt ganska opåverkad ut. Vad gör du?', '["Tar blododlingar och startar bredspektrumantibiotika intravenöst utan dröjsmål","Avvaktar odlingssvar innan antibiotika ges","Skickar hem henne med kontroll om några dagar eftersom hon inte ser sjuk ut","Ger febernedsättande och nytt blodprov dagen efter"]'::jsonb, 'Tar blododlingar och startar bredspektrumantibiotika intravenöst utan dröjsmål', 'Febril neutropeni är ett livshotande tillstånd: neutropena patienter kan inte uppvisa klassiska infektionstecken och kan försämras på timmar. Odlingar tas om möjligt, men antibiotika ska inte fördröjas i väntan på svar – målet är mycket snabb behandlingsstart.', 1, 1, 'kapitel', false)
