INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-4-q2', 'km7-4', NULL, 'mcq', 'En 24-årig man med nydiagnostiserad högmalign lymfom börjar cytostatikabehandling. Två dygn senare ses stigande kalium, fosfat och urat, sjunkande kalcium och stigande kreatinin. Vilken komplikation föreligger och vad gör du?', '["Tumörlyssyndrom – intensiv hydrering och behandling som sänker uratnivån","Hyponatremi med cerebralt ödem – vätskerestriktion","Njursten med obstruktion – smärtlindring och avvakta","Rhabdomyolys – enbart alkalisk diures utan kontroll"]'::jsonb, 'Tumörlyssyndrom – intensiv hydrering och behandling som sänker uratnivån', 'När många tumörceller dör snabbt frigörs intracellulärt kalium, fosfat och nukleinsyror, vilket ger hyperkalemi, hyperfosfatemi och hyperurikemi med utfällning av uratkristaller i njurarna och akut njursvikt. Kalcium sjunker eftersom det binds till fosfat. Behandlingen är hydrering, allopurinol eller rasburikas och elektrolytkorrigering.', 1, 2, 'kapitel', false)
