INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-4-q3', 'km7-4', NULL, 'mcq', 'En 68-årig man med känd prostatacancer söker för tilltagande ryggvärk som blir värre i liggande, och han har de senaste dagarna fått svaghet i båda benen och svårt att tömma blåsan. Vad gör du?', '["Misstänker ryggmärgskompression och ordnar omedelbar MR och kortisonbehandling","Behandlar med analgetika och återbesök om två veckor","Beställer röntgen av ländryggen med låg prioritet","Remitterar till sjukgymnastik för ryggsmärta"]'::jsonb, 'Misstänker ryggmärgskompression och ordnar omedelbar MR och kortisonbehandling', 'Ryggvärk som förvärras i liggande, tilltagande kraftnedsättning och blåsstörning hos en cancerpatient är klassiska tecken på metastatisk ryggmärgskompression. Neurologisk funktion som gått förlorad kommer sällan tillbaka, därför ska MR och kortison ges omedelbart.', 1, 3, 'kapitel', false)
