  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('km7-4-q4', 'km7-4', NULL, 'cloze', 'En patient med hjärnmetastaser blir allt slöare och får huvudvärk och kräkningar. För att minska det peritumöra ödemet ges ______.', NULL, 'kortison', 'Kortikosteroider minskar ödemet kring tumörväxt i hjärnan och lindrar symtom snabbt. Behandlingen är symtomlindrande och ges tillsammans med andra åtgärder som strålning eller kirurgi beroende på situation.', 1, 4, 'kapitel', false)
