INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mdbi-m1-q1', 'mdbi-m1', NULL, 'mcq', 'En patient har Hb 95 g/L, MCV 72 fL och lågt ferritin. Vilken typ av anemi är det?', '["Mikrocytär järnbristanemi","Makrocytär B12-bristanemi","Normocytär anemi vid kronisk sjukdom","Hemolytisk anemi"]'::jsonb, 'Mikrocytär järnbristanemi', 'Lågt MCV och lågt ferritin talar för järnbrist – vanligast orsak till mikrocytär anemi (utöver talassemi). B12/folatbrist ger makrocytär (högt MCV) anemi; kronisk sjukdom ger oftast normocytär.', 1, 1, 'kapitel', false)
