INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mdbi-m1-q2', 'mdbi-m1', NULL, 'mcq', 'Vad innebär ett förhöjt anjon-gap vid metabol acidos?', '["Ackumulering av icke-mätta syror som laktat eller ketoner","Förlust av bikarbonat via GI-kanalen eller njurarna","Hyperkloridemi utan syraöverskott","Respiratorisk alkalos med kompensation"]'::jsonb, 'Ackumulering av icke-mätta syror som laktat eller ketoner', 'Anjon-gap = Na+ − (Cl− + HCO3−). Förhöjt gap (MUDPILES: metanol, uremi, DKA, propylenglykol, isoniazid, laktat, etylenglykol, salicylater) betyder att en omätt anjon ansamlats; normalt gap vid diarré/renal tubulär acidos.', 1, 2, 'kapitel', false)
