INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mdbi-m2-q1', 'mdbi-m2', NULL, 'mcq', 'Vilket fynd på EKG talar för akut ST-höjningsinfarkt (STEMI)?', '["ST-höjning i två angränsande avledningar","Generellt låg amplitud","Förkortad QT-tid","Sinustakycardi utan ST-förändringar"]'::jsonb, 'ST-höjning i två angränsande avledningar', 'STEMI definieras av ST-höjning i två angränsande avledningar (eller ny vänstergrenblock) och kräver omedelbar reperfusion (PCI). NSTEMI ger ST-sänkning/T-vändning eller normaliserat EKG med förhöjt troponin.', 1, 1, 'kapitel', false)
