INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mdbi-m2-q2', 'mdbi-m2', NULL, 'mcq', 'Vad mäter ekokardiografi och vad är dess viktigaste användning akut?', '["Hjärtats struktur och funktion (EF, klaffar, väggrörlighet) – används vid hjärtsvikt, klaffel och misstänkt tamponad","Hjärtats elektriska aktivitet i vila","Kranskärlens anatomi med kontrast","Lungornas gasutbyte"]'::jsonb, 'Hjärtats struktur och funktion (EF, klaffar, väggrörlighet) – används vid hjärtsvikt, klaffel och misstänkt tamponad', 'Ekokardiografi är snabbt, strålningsfritt och visar strukturell och funktionell information inklusive ejektionsfraktion. Akut kan det snabbt avslöja perikardvätska/tamponad och nedsatt pumpförmåga.', 1, 2, 'kapitel', false)
