INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mdbi-m2-q3', 'mdbi-m2', NULL, 'cloze', 'Hjärtmarkören som stiger 3–6 timmar efter infarkt och är mest specifik kallas ______.', NULL, 'troponin', 'Högsensitivt troponin (hs-cTn) är förstahandsmarkör: stiger snabbt, förblir förhöjt i dagar och kombineras med klinik och EKG i 0/1- eller 0/3-timmarsalgoritmer.', 1, 3, 'kapitel', false)
