INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mdbi-m3-q1', 'mdbi-m3', NULL, 'mcq', 'Vilken modalitet har högst stråldos och när är den motiverad?', '["DT (datortomografi) – vid akuta tillstånd som misstänkt blödning, lungemboli eller trauma","Ultraljud – vid alla frågeställningar","MR – eftersom den saknar magnetfält","Slätröntgen – vid mjukdelsbedömning"]'::jsonb, 'DT (datortomografi) – vid akuta tillstånd som misstänkt blödning, lungemboli eller trauma', 'DT ger hög stråldos men är snabb och avgörande akut. Principen är ALARA (as low as reasonably achievable): välj modalitet efter frågeställning, undvik onödig strålning särskilt hos barn och gravida.', 1, 1, 'kapitel', false)
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, objective_id = EXCLUDED.objective_id,
  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mdbi-m3-q2', 'mdbi-m3', NULL, 'mcq', 'Vilken modalitet är förstahandsval för att bedöma gallstenar och gravid livmoder utan strålning?', '["Ultraljud","Slätröntgen buk","DT buk med kontrast","PET-CT"]'::jsonb, 'Ultraljud', 'Ultraljud är snabbt, tillgängligt och strålningsfritt – bäst för gallblåsa, njurar, uterus och foster. DT används vid oklara akuta bukar och vid komplikationer.', 1, 2, 'kapitel', false)
