INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mdbi-m4-q1', 'mdbi-m4', NULL, 'mcq', 'En patient med blodgrupp A får en transfusion med blodgrupp B. Vad händer och varför?', '["Akut hemolytisk reaktion – anti-B-antikroppar förstör de transfunderade erytrocyterna","Ingen reaktion eftersom A och B är kompatibla","Enbart feber utan hemolys","Agglutinering sker först efter flera dagar"]'::jsonb, 'Akut hemolytisk reaktion – anti-B-antikroppar förstör de transfunderade erytrocyterna', 'Personer med blodgrupp A har anti-B-antikroppar (IgM). Feltransfusion ger komplementaktivering, hemolys, feber, ryggsmärta och DIC – livshotande. Blodgrupp O-negativ är universaldonator för erytrocyter.', 1, 1, 'kapitel', false)
