INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mdbi-m4-q2', 'mdbi-m4', NULL, 'mcq', 'Vad är viktigt innan en blodtransfusion för att förebygga transfusionsreaktioner?', '["Korrekt blodgruppering och antikroppsscreening samt identitetskontroll vid sängkanten","Att patienten fastar i 6 timmar","Att ge antihistamin rutinmässigt","Att ge transfusionen snabbt under 10 minuter"]'::jsonb, 'Korrekt blodgruppering och antikroppsscreening samt identitetskontroll vid sängkanten', 'Blodgruppering (ABO/Rh), antikroppsscreening och förväxlingskontroll vid patienten är de avgörande säkerhetsstegen. Transfusion ges långsamt de första 15 minuterna och patienten observeras.', 1, 2, 'kapitel', false)
