INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mdbi-m5-q1', 'mdbi-m5', NULL, 'mcq', 'En patient har hyperkalcemi, lågt fosfat och förhöjt PTH. Vilken är den mest sannolika orsaken?', '["Primär hyperparatyreoidism (adenom i paratyroidea)","Sekundär hyperparatyreoidism vid njursvikt","Hypoparatyreoidism","D-vitaminbrist"]'::jsonb, 'Primär hyperparatyreoidism (adenom i paratyroidea)', 'Vid primär hyperparatyreoidism produceras PTH självständigt: kalcium stiger, fosfat sjunker. Vid sekundär (njursvikt) är kalcium lågt/normalt och fosfat högt – PTH stiger som kompensation.', 1, 1, 'kapitel', false)
