INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mvtm-1-q1', 'mvtm-1', NULL, 'mcq', 'En forskargrupp vill undersöka sambandet mellan tidigare exponering för ett läkemedel och en ovanlig sjukdom som bara drabbar ett fåtal personer per år. Vilken studiedesign är mest lämplig?', '["Fall-kontrollstudie","Randomiserad kontrollerad prövning","Prospektiv kohortstudie","Tvärsnittsstudie"]'::jsonb, 'Fall-kontrollstudie', 'Vid ovanliga utfall är fall-kontroll effektiv eftersom man utgår från de sjuka och väljer kontroller, och den ger oddskvot men inte incidens. En kohort kräver mycket stora populationer och lång uppföljning, och tvärsnitt kan inte fastställa tidsordningen mellan exponering och sjukdom.', 1, 1, 'kapitel', false)
