  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mvtm-1-q2', 'mvtm-1', NULL, 'mcq', 'Vilken studiedesign ger i allmänhet starkast stöd för att en behandling har en kausal effekt?', '["Randomiserad kontrollerad prövning","Prospektiv kohortstudie","Fall-kontrollstudie","Djurstudie"]'::jsonb, 'Randomiserad kontrollerad prövning', 'Randomiseringen fördelar både kända och okända confounders mellan grupperna och ger därför starkast kausalt stöd. I kohort- och fall-kontrollstudier kan confounding kvarstå även efter justering.', 1, 2, 'kapitel', false)
