  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mvtm-1-q3', 'mvtm-1', NULL, 'mcq', 'I en kohortstudie ses ett tydligt samband mellan kaffedrickande och lungcancer. Efter justering för rökning minskar sambandet kraftigt. Vad illustrerar detta?', '["Confounding","Selektionsbias","Informationsbias","Regression mot medelvärdet"]'::jsonb, 'Confounding', 'Rökning påverkar både kaffedrickandet och risken för lungcancer och uppfyller därmed definitionen på en confounder. Selektionsbias uppstår i urvalet av studiedeltagare och informationsbias i mätningen – ingen av dem är en tredje bakomliggande faktor.', 1, 3, 'kapitel', false)
