  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mvtm-1-q4', 'mvtm-1', NULL, 'cloze', 'Den rapporteringsriktlinje för randomiserade kontrollerade prövningar som många tidskrifter kräver att författarna följer förkortas ______.', NULL, 'CONSORT', 'CONSORT beskriver hur en randomiserad prövning ska redovisas – från rekrytering och randomisering till bortfall och utfall – så att studien kan granskas och replikeras. Motsvarande riktlinjer finns för andra designer, till exempel STROBE för observationella studier.', 1, 4, 'kapitel', false)
