  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mvtm-2-q1', 'mvtm-2', NULL, 'mcq', 'En studie rapporterar p = 0,03 för skillnaden mellan två behandlingar. Vad betyder p-värdet?', '["Sannolikheten för det observerade resultatet eller mer extremt om nollhypotesen vore sann","Sannolikheten att nollhypotesen är sann","Sannolikheten att resultatet är kliniskt relevant","Andelen falskt positiva fynd i studien"]'::jsonb, 'Sannolikheten för det observerade resultatet eller mer extremt om nollhypotesen vore sann', 'p-värdet beräknas under antagandet att nollhypotesen gäller och uttalar sig inte om sannolikheten för hypotesen själv. Ett litet p-värde säger heller inget om effektens storlek eller kliniska betydelse.', 1, 1, 'kapitel', false)
