  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mvtm-2-q2', 'mvtm-2', NULL, 'mcq', 'En studie visar en medelvärdesskillnad i blodtryck på 2,1 mmHg med 95 % konfidensintervall −1,3 till 5,5. Hur tolkas resultatet?', '["Resultatet är inte statistiskt signifikant eftersom intervallet omfattar noll","Resultatet är signifikant eftersom medelvärdesskillnaden inte är noll","Intervallet anger att 95 % av patienterna fick effekt","Resultatet visar att behandlingen är skadlig"]'::jsonb, 'Resultatet är inte statistiskt signifikant eftersom intervallet omfattar noll', 'Om 95 % konfidensintervallet för en skillnad innehåller noll kan nolleffekten inte uteslutas på 5 % signifikansnivå. Intervallet beskriver osäkerheten i skattningen, inte hur stor andel av patienterna som svarade på behandlingen.', 1, 2, 'kapitel', false)
