INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mvtm-2-q3', 'mvtm-2', NULL, 'mcq', 'Samma screeningtest med oförändrad sensitivitet och specificitet används i en population med mycket låg prevalens i stället för en med hög prevalens. Vad händer?', '["Positivt prediktivt värde sjunker medan sensitivitet och specificitet är oförändrade","Sensitiviteten sjunker","Specificiteten sjunker","Prediktiva värden påverkas inte av prevalensen"]'::jsonb, 'Positivt prediktivt värde sjunker medan sensitivitet och specificitet är oförändrade', 'Sensitivitet och specificitet är testegenskaper som inte beror på prevalensen, medan PPV sjunker och NPV stiger när prevalensen sjunker. Det är därför screening i lågriskgrupper ger många falskt positiva prov.', 1, 3, 'kapitel', false)
