INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mvtm-2-q4', 'mvtm-2', NULL, 'cloze', 'Sannolikheten att felaktigt förkasta en sann nollhypotes kallas typ I-fel och betecknas ______.', NULL, 'alfa', 'Typ I-fel (alfa) är risken att få ett falskt positivt resultat och hålls konventionellt vid 5 %. Typ II-fel (beta) är risken att inte upptäcka en verklig effekt; statistisk styrka är 1 − beta.', 1, 4, 'kapitel', false)
