INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mvtm-3-q1', 'mvtm-3', NULL, 'mcq', 'I en randomiserad studie är varken patienterna eller de läkare som skattar symtomen blindade. Vilken typ av bias är mest sannolik?', '["Performans- och detektionsbias","Selektionsbias","Attritionsbias","Publikationsbias"]'::jsonb, 'Performans- och detektionsbias', 'Utan blindning kan förväntningar påverka både hur behandlingen ges och hur utfallet mäts, vilket motsvarar performans- respektive detektionsbias. Selektionsbias handlar om hur deltagarna valdes ut och attrition om bortfall under studiens gång.', 1, 1, 'kapitel', false)
