  kind = EXCLUDED.kind, prompt = EXCLUDED.prompt, options = EXCLUDED.options, answer = EXCLUDED.answer,
  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mvtm-3-q2', 'mvtm-3', NULL, 'mcq', 'Varför analyseras randomiserade prövningar i första hand enligt intention-to-treat?', '["Det bevarar randomiseringens effekt och undviker bias från selektivt bortfall","Det ger alltid en större behandlingseffekt","Det kräver färre deltagare","Det ersätter behovet av blindning"]'::jsonb, 'Det bevarar randomiseringens effekt och undviker bias från selektivt bortfall', 'ITT analyserar alla deltagare i den grupp de randomiserades till och skyddar mot att bortfall kopplat till effekt snedvrider resultatet. Per-protokoll-analys kan överskatta effekten eftersom de som fullföljer behandlingen ofta är friskare.', 1, 2, 'kapitel', false)
