  explanation = EXCLUDED.explanation, difficulty = EXCLUDED.difficulty, sort_order = EXCLUDED.sort_order,
  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mvtm-3-q3', 'mvtm-3', NULL, 'mcq', 'Vilka faktorer sänker tilliten till en effektskattning enligt GRADE?', '["Risk för bias, inkonsistens, indirekthet och imprecision","Att studien har många deltagare","Att effekten är stor","Att det finns en dos-respons-relation"]'::jsonb, 'Risk för bias, inkonsistens, indirekthet och imprecision', 'GRADE utgår från studiedesign och sänker tilliten vid risk för bias, inkonsistens mellan studier, indirekthet i population eller utfall, imprecision och publikationsbias. Stor effekt och dos-respons-relation höjer i stället tilliten.', 1, 3, 'kapitel', false)
