  origin = EXCLUDED.origin, fact_checked = EXCLUDED.fact_checked;
INSERT INTO recall_items (id, chapter_id, objective_id, kind, prompt, options, answer, explanation, difficulty, sort_order, origin, fact_checked)
VALUES ('mvtm-3-q4', 'mvtm-3', NULL, 'cloze', 'Att en screening upptäcker förändringar som aldrig skulle ha gett symtom eller skadat patienten kallas ______.', NULL, 'överdiagnostik', 'Överdiagnostik leder till onödig behandling och ångest utan att förbättra utfall, och är en av de viktigaste invändningarna mot bred screening. Den skiljs från överbehandling, som är behandling utan nytta av en korrekt ställd diagnos.', 1, 4, 'kapitel', false)
