  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726649976333-ntfm', 'bv1-m1', 'Vad betyder dexter respektive sinister?', 'Dexter betyder höger och sinister betyder vänster. Riktningen anges utifrån personen själv, inte betraktaren.', 5, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726650017145-8172', 'bv1-m1', 'Vad betyder superior respektive inferior?', 'Superior betyder övre (mer kranialt) och inferior betyder nedre (mer kaudalt).', 6, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726650206215-34eg', 'bv1-m1', 'Vad betyder medial?', 'Medial betyder belägen närmare kroppens mittlinje.', 7, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726650253195-dwke', 'bv1-m1', 'Vad betyder lateral?', 'Lateral betyder belägen längre ut åt sidan, bort från kroppens mittlinje.', 8, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726650318218-v3sn', 'bv1-m1', 'Vad betyder proximal respektive distal?', 'Proximal betyder närmare kroppens centrum (eller en extremitets rot), distal betyder längre ut mot periferin.', 9, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726650349593-7c0m', 'bv1-m1', 'Vad betyder anterior respektive posterior?', 'Anterior betyder framåt (mot buken) och posterior betyder bakåt (mot ryggen).', 10, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726650403555-pvhr', 'bv1-m1', 'Vad betyder ipsilateral respektive kontralateral?', 'Ipsilateral betyder på samma sida som en given referenspunkt, kontralateral betyder på motsatt sida.', 11, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726650538252-wmxw', 'bv1-m1', 'Vad betyder visceral respektive parietal?', 'Visceral avser den del som vetter mot ett organ, parietal den del som vetter mot omgivningen. Exempel: lungsäcken har ett visceralt och ett parietalt blad.', 12, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726650617357-7i82', 'bv1-m1', 'Vad betyder profund respektive superficiell?', 'Profund betyder djupt liggande och superficiell betyder ytligt liggande, nära kroppsytan.', 13, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726650647386-hxdy', 'bv1-m1', 'Vad betyder dorsal respektive ventral?', 'Dorsal betyder mot ryggen och ventral betyder mot buken (magen).', 14, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726650692588-boaa', 'bv1-m1', 'Vad betyder kraniell respektive caudal riktning?', 'Kraniell betyder mot kraniet (huvudet) och caudal mot svanskotan/svansen. Inom centrala nervsystemet används i stället rostral (mot näbben) och caudal.', 15, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726651461089-1u0t', 'bv1-m1', 'Vilken funktion har arterioler?', 'Arterioler är små grenar från artärerna och reglerar blodflödet till kapillärbäddarna. De är viktiga för att styra det perifera motståndet.', 16, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726651536619-re9a', 'bv1-m1', 'Vilka egenskaper har artärer?', 'Artärer är de första kärlen efter hjärtat, har högt tryck och för blod ut till kroppens olika delar.', 17, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726651660220-nerc', 'bv1-m1', 'Vad är kapillärernas huvudsakliga funktion?', 'Kapillärer är tunna kärl där utbyte av syre, näring och slaggprodukter sker mellan blod och vävnad.', 18, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726760821115-5q54', 'bv1-m1', 'Var i cirkulationen kommer venolerna?', 'Venoler är de kärl som kommer direkt efter kapillärerna och leder blodet vidare mot venerna.', 19, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726760965294-jy0h', 'bv1-m1', 'Vad är venernas funktion?', 'Vener för tillbaka blodet till hjärtat.', 20, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726766180112-3xjl', 'bv1-m1', 'Vilka egenskaper har det fibrösa pericardiet?', 'Det fibrösa pericardiet är slitstarkt, omger hjärtat på utsidan och hindrar överfyllning av hjärtat.', 21, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726766212640-yybh', 'bv1-m1', 'Vilka egenskaper har det serösa pericardiet?', 'Det serösa pericardiet består av två blad och minskar friktionen mellan hjärta och omgivning. Det ligger innanför det fibrösa pericardiet.', 22, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1726766244263-n07x', 'bv1-m1', 'Vad är pericardium?', 'Pericardium är den säck som omger hjärtat och består av ett fibröst och ett seröst lager.', 23, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631097796097-fa6n', 'bv1-m1', 'Vad är ett embryo och hur länge varar embryonalperioden?', 'Ett embryo är de tidiga anlagen till en individ under utveckling från den befruktade äggcellen. Embryonalperioden varar till slutet av vecka 9, då armar och ben kan urskiljas.', 24, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631097897384-twae', 'bv1-m1', 'Vad är ett foster och när börjar fosterperioden?', 'Ett foster är den ofödda avkomman hos människa från vecka 9 till perinatalperioden. Fosterperioden är cirka 7 månader lång.', 25, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631097942162-obb3', 'bv1-m1', 'Vad menas med perinatalperioden?', 'Perinatalperioden är tidsperioden kring födseln, det vill säga kort före och efter förlossningen.', 26, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631101778413-5glh', 'bv1-m1', 'Nämn tre infektionssjukdomar som historiskt påverkat människans genetik och historia.', 'Pest, smittkoppor och fläcktyfus har alla haft stor påverkan på människans historia och genetiska utveckling.', 27, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631861646871-3tu4', 'bv1-m1', 'Vilka huvudfunktioner har blodet?', 'Transport av syre, näringsämnen, koldioxid, vatten och slaggprodukter; värmetransport; hormonell kommunikation; immunförsvar via leukocyter; reglering av syra-bas-balansen.', 28, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631861723499-2wst', 'bv1-m1', 'Vilka komponenter ingår i blodets sammansättning?', 'Vatten, salter, proteiner, fetter, hormoner och blodkroppar.', 29, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631861794250-jc9x', 'bv1-m1', 'Vilka tre huvudtyper av blodkroppar finns?', 'Erytrocyter (röda blodkroppar), leukocyter (vita blodkroppar) och trombocyter (blodplättar).', 30, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631861846011-msn2', 'bv1-m1', 'Vad är hjärtats huvudsakliga funktion?', 'Att pumpa blod genom lilla (pulmonella) och stora (systemiska) kretsloppet.', 31, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631861930571-1j9u', 'bv1-m1', 'Vad innebär det att stora kretsloppet är parallellkopplat?', 'Att artärerna förgrenar sig så att blodet samtidigt kan förse olika organ och vävnader, inte i serie efter varandra.', 32, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631862109444-3vkf', 'bv1-m1', 'Hur fungerar AV-klaffarna (klaffarna mellan förmak och kammare)?', 'De öppnas när trycket i förmaket överstiger trycket i kammaren, så att blodet strömmar från förmak till kammare, och hindrar backflöde.', 33, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631862149838-vpdj', 'bv1-m1', 'Hur uppstår hjärtljuden?', 'När blodet studsar tillbaka mot stängda klaffar uppstår vibrationer som hörs som hjärtljud.', 34, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631862237300-xmll', 'bv1-m1', 'Vart leder lilla respektive stora kretsloppet?', 'Höger hjärthalva pumpar blod till lilla kretsloppet (lungorna); vänster hjärthalva pumpar blod till stora kretsloppet (kroppens vävnader).', 35, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631862683883-49uv', 'bv1-m1', 'Vilka celltyper bygger upp hjärtats system?', 'Pacemakerceller, retledningssystemets celler och hjärtmuskelceller (myokard).', 36, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631862741292-tbzn', 'bv1-m1', 'Var sitter pacemakercellerna och vad gör de?', 'De sitter i sinusknutan (nodus sinuatrialis) och styr hjärtfrekvensen genom att generera elektriska impulser.', 37, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631862877646-cxps', 'bv1-m1', 'Vad är hjärtats retledningssystem?', 'System som leder impulser genom hjärtat med start i sinusknuten och sprider dem snabbt till myokardiet.', 38, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631862942184-broi', 'bv1-m1', 'Vad är myokardium?', 'De tvärstrimmiga kontraktila hjärtmuskelcellerna som kontraherar hjärtat och driver pumpningen av blodet.', 39, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631863096898-v92s', 'bv1-m1', 'Vad kännetecknar systole?', 'Hjärtmuskeln kontraherar och blod pumpas ut genom valva aortae och valva trunci pulmonalis, medan AV-klaffarna är stängda. Det första hjärtljudet uppstår här.', 40, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631863160251-9vls', 'bv1-m1', 'Vad orsakar det första hjärtljudet?', 'Det uppstår i systole när blodet slår mot de stängda AV-klaffarna (valva mitralis och valva tricuspidalis).', 41, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631863249128-94dr', 'bv1-m1', 'Vad kännetecknar diastole?', 'Hjärtmuskeln slappnar av, AV-klaffarna är öppna och blodet forsar in i kammrarna, medan valva aortae och valva trunci pulmonalis är stängda. Det andra hjärtljudet uppstår här.', 42, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631863299638-nt5i', 'bv1-m1', 'Vad orsakar det andra hjärtljudet?', 'Det uppstår i diastole när blodet slår mot de stängda valva aortae och valva trunci pulmonalis.', 43, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631863352348-gdqv', 'bv1-m1', 'Vad är slagvolym (SV)?', 'Den mängd blod hjärtat pumpar ut vid varje slag.', 44, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631863376504-805l', 'bv1-m1', 'Vad är hjärtfrekvens (HF)?', 'Antalet hjärtslag per minut.', 45, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631863419485-cl3m', 'bv1-m1', 'Vad är hjärtminutvolymen (HMV)?', 'Den mängd blod hjärtat pumpar ut per minut, beräknad som HF × SV.', 46, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631863478692-u9un', 'bv1-m1', 'Vad är hjärtminutvolymen i vila respektive vid maximalt fysiskt arbete?', 'I vila cirka 5 l/min och vid maximalt arbete cirka 25 l/min.', 47, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631863593123-5wu8', 'bv1-m1', 'Vilka två faktorer bestämmer hjärtminutvolymen (HMV)?', 'HMV = hjärtfrekvens (HF) × slagvolym (SV). Genom att påverka någon av dessa ändras HMV.', 48, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631863633954-rfae', 'bv1-m1', 'Vad styr hjärtfrekvensen (HF) och vad påverkar den?', 'HF bestäms av sinusknutans aktionspotentialer, som i sin tur regleras av autonoma nerver.', 49, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631863731911-lfxl', 'bv1-m1', 'Vilka tre faktorer påverkar slagvolymen (SV)?', 'Förbelastning (mängd blod som fyller hjärtat), efterbelastning (motståndet vid utpumpning) och kontraktilitet (hur starkt hjärtat kontraherar).', 50, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631863871230-2db3', 'bv1-m1', 'Vad är aortans och de medelstora artärernas funktion?', 'De är elastiska: volymen ökar vid hjärtats kontraktion och de elastiska fibrerna drar sedan ihop sig och driver blodet framåt, vilket ger upphov till den kännbara pulsen.', 51, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631863936971-bn1t', 'bv1-m1', 'Vad är funktionen hos de elastiska fibrerna i stora artärer?', 'De hjälper hjärtat att driva blodet framåt genom att växelvis dilatera och kontrahera. Utan elasticiteten hade hjärtat behövt pumpa mycket hårdare.', 52, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631863985462-q39k', 'bv1-m1', 'Vad är arterioler?', 'Små blodkärl som kan ändra sin diameter genom vasodilation och vasokonstriktion.', 53, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631864047101-el4j', 'bv1-m1', 'Vad innebär vasodilation?', 'Att arteriolerna vidgar sig, vilket ökar blodflödet genom dem.', 54, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631864159718-7nnw', 'bv1-m1', 'Vad innebär vasokonstriktion?', 'Att arteriolerna drar ihop sig, vilket minskar blodflödet genom dem.', 55, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631864285926-ispu', 'bv1-m1', 'Vad är kapillärer och vad är deras funktion?', 'De minsta blodkärlen (ca 5–10 µm), uppbyggda av endotelceller. Deras funktion är utbyte av gaser, näringsämnen och avfall.', 56, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631864346882-29qv', 'bv1-m1', 'Vad är vensidans funktion?', 'Vensidan transporterar blod tillbaka till hjärtat och fungerar även som reservpool för blod, eftersom en stor del av blodvolymen finns där.', 57, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631865391859-gh9t', 'bv1-m1', 'Vilka två faktorer reglerar hjärnstammen för att styra blodtrycket?', 'Hjärtminutvolymen och det perifera motståndet.', 58, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631865411151-c4pg', 'bv1-m1', 'Var sker den långsiktiga regleringen av blodtrycket?', 'I njurarna.', 59, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631865493863-hkxk', 'bv1-m1', 'Hur reglerar njurarna blodtrycket på lång sikt?', 'Genom att justera blodvolymen via återresorption eller utsöndring av vatten. Njurarna kan även stimulera produktion av fler röda blodkroppar.', 60, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632222311788-inm5', 'bv1-m1', 'Vad kännetecknar artärer?', 'De är de första kärlen efter hjärtat och transporterar syrerikt blod ut till kroppen.', 61, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632222335825-fckb', 'bv1-m1', 'I vilka kärl är blodtrycket högst?', 'I artärerna.', 62, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632222395658-0g2a', 'bv1-m1', 'Vilka tre lager bygger upp en artär?', 'Tunica intima (endotel), tunica media (muskellager) och tunica adventitia (kollagenfibrer).', 63, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632223344650-5ofo', 'bv1-m1', 'Vilken funktion har atrium dextrum?', 'Atrium dextrum tar emot venöst blod från vena cava superior och inferior. Vid kontraktion toppfyller det ventriculus dextrum.', 64, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632223480894-f1xj', 'bv1-m1', 'Vart pumpar ventriculus dextra blodet och genom vilken klaff?', 'Genom valva trunci pulmonalis ut i truncus pulmonalis (lungartären).', 65, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632223554489-7wy1', 'bv1-m1', 'I vilka kärl delar truncus pulmonalis upp sig?', 'I a. pulmonalis dextra (höger lunga) och a. pulmonalis sinistra (vänster lunga).', 66, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632223593552-5lsb', 'bv1-m1', 'Vad betyder truncus och communis i kärlnamn?', 'Att kärlet snabbt delar upp sig i två eller fler andra kärl.', 67, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632223923328-lhrj', 'bv1-m1', 'Genom vilka kärl återvänder syresatt blod från lungorna till hjärtat?', 'Via vv. pulmonales dextra och sinistra.', 68, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632224055117-obna', 'bv1-m1', 'Beskriv blodets väg från lungorna genom vänster hjärthalva till aorta.', 'Från vv. pulmonales in i atrium sinistra, genom valva mitralis till ventriculus sinistra, och via valva aortae ut i aorta.', 69, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632224142625-xm5t', 'bv1-m1', 'Vilka ben skyddar hjärtat dorsalt och anteriort?', 'Dorsalt skyddas hjärtat av ryggraden och anteriort av corpus sterni.', 70, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632224335562-y0rx', 'bv1-m1', 'Vilka segelklaffar finns mellan förmak och kammare?', 'Valva tricuspidalis (tre segel) på höger sida och valva mitralis (två segel) på vänster sida.', 71, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632224382557-qm5h', 'bv1-m1', 'Vilka fickklaffar finns i hjärtat?', 'Valva trunci pulmonalis mellan höger kammare och truncus pulmonalis, samt valva aortae mellan vänster kammare och aorta.', 72, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632224508647-8fj9', 'bv1-m1', 'Varför finns klaffar i hjärtat?', 'För att förhindra bakåtflöde så att blodet pumpas ordentligt framåt.', 73, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632224677832-opct', 'bv1-m1', 'Hur förhindrar valva tricuspidalis backflöde till atrium dextrum under ventrikelsystole?', 'När ventrikeln kontraherar ökar trycket och blodet pressar mot seglen. M. papillaris spänns och hindrar seglen från att tryckas in i atrium. Blodet kan då bara passera genom valva trunci pulmonalis.', 74, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632224853053-bxaa', 'bv1-m1', 'Hur fungerar valva trunci pulmonalis under ventrikelsystole och diastole?', 'Under systole ökar trycket i ventrikeln, blodet tvingar fickklaffarna att öppna och blodet forsar ut i truncus pulmonalis. Under diastole slappnar ventrikeln av, fickklaffarna återgår till ursprunglig form och förhindrar backflöde.', 75, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632225135210-qk9p', 'bv1-m1', 'Var finns hjärtats pacemakerceller?', 'I nodus sinuatrialis (SA-noden) och i nodus atrioventricularis (AV-noden).', 76, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632225245677-l4y5', 'bv1-m1', 'Var ligger nodus sinuatrialis och varför är den primär pacemaker?', 'Den ligger i atrium dextrum nära superior vena cavas inflöde. Cellerna har snabbast spontan aktivitet och aktiveras först, varvid signalen sprids till nodus atrioventricularis.', 77, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632225316391-5gqt', 'bv1-m1', 'Vad händer när pacemakercellerna i SA-noden aktiveras?', 'De skapar en elektrisk impuls som sprider sig över atrierna och får dem att kontrahera.', 78, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632225415960-o605', 'bv1-m1', 'Var ligger nodus atrioventricularis och vad är dess funktion?', 'Den ligger mellan atrium och ventrikel. Den för impulsen vidare via fibrer till hjärtats spets, så att ventrikeln kontraherar nedifrån och uppåt och trycker blodet mot fickklaffarna.', 79, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632225448128-391i', 'bv1-m1', 'Vilka kransartärer avgår från aorta och försörjer hjärtat?', 'A. coronaria dextra och a. coronaria sinistra.', 80, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632225585695-1ato', 'bv1-m1', 'Varför kan hjärtat inte syresättas av blodet i sina egna hålrum?', 'Hjärtmuskulaturen försörjs av kranskärlen som avgår från aorta. Blodet i hålrummen kan inte användas direkt för syresättning av myokardiet.', 81, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632225702089-yhq1', 'bv1-m1', 'Vart tar det venösa blodet från hjärtmuskulaturen vägen?', 'Det samlas i större vener på hjärtats yta som mynnar i sinus coronarius, vilken leder till atrium dextrum.', 82, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632225807222-39sb', 'bv1-m1', 'Hur skiljer sig artärers och veners läge i kroppen?', 'Artärer går oftast djupt i kroppen, med få undantag. Vener går mer ytligt men kan även gå djupt, ofta utmed stora artärer.', 83, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632226300087-gx3h', 'bv1-m1', 'Vilka tre kärl utgår från arcus aortae?', 'Truncus brachiocephalicus, a. subclavia sinistra och a. carotis communis sinistra.', 84, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632226367753-mf5d', 'bv1-m1', 'Vilka två artärer utgår från truncus brachiocephalicus?', 'A. subclavia dextra och a. carotis communis dextra.', 85, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632226424961-3xpr', 'bv1-m1', 'Vad är a. carotis communis?', 'Den stora halsartären som löper upp i halsen och delar sig för att försörja ansikte och hjärna.', 86, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632226467060-d5p5', 'bv1-m1', 'Vad är a. subclavia?', 'En artär som löper under clavicula och försörjer armen med blod.', 87, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632226529280-ggka', 'bv1-m1', 'Vilka två kärl delar a. carotis communis upp sig i?', 'A. carotis interna (till hjärnan) och a. carotis externa (till ansiktet).', 88, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632226650091-8k5j', 'bv1-m1', 'Vilka artärer följer a. subclavia i armen i ordning?', 'A. axillaris, därefter a. brachialis, som delar sig i a. radialis och a. ulnaris.', 89, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632226650091-mz7y', 'bv1-m1', 'Vilken avgrening från a. subclavia försörjer hjärnan?', 'A. vertebralis, som främst försörjer hjärnstammen och delar av ryggmärgen.', 90, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632226719958-aghr', 'bv1-m1', 'Vad delas aortan upp i och vad skiljer dem åt?', 'Aorta thoracica och aorta abdominalis; diafragman skiljer dem åt.', 91, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632226758432-6m89', 'bv1-m1', 'Hur går a. radialis och a. ulnaris i underarmen?', 'A. radialis går lateralt och a. ulnaris går medialt.', 92, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632226780713-tvay', 'bv1-m1', 'I vilken artär känner man pulsen vid handleden?', 'A. radialis.', 93, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632226854695-r69o', 'bv1-m1', 'Vilket kärl försörjer största delen av hjärnvävnaden med blod?', 'A. carotis interna, som försörjer cirka 80 % av hjärnvävnaden.', 94, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632226969791-l71t', 'bv1-m1', 'På vilka två sätt passerar stora kärl diafragman?', 'Antingen genom diafragman (t.ex. v. cava inferior genom foramen venae cavae) eller bakom den (aorta genom hiatus aorticus).', 95, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632227178044-tfk7', 'bv1-m1', 'Vilka fem stora grenar avgår från aorta abdominalis i kranial till kaudal ordning?', '1. Truncus coeliacus, 2. a. mesenterica superior, 3. aa. renales, 4. a. testicularis/ovarica, 5. a. mesenterica inferior.', 96, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632227321945-qj64', 'bv1-m1', 'Vilka tre huvudgrenar delar truncus coeliacus upp sig i?', 'A. hepatica communis, a. gastrica sinistra och a. splenica.', 97, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
