INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632230306280-emxp', 'bv1-m1', 'Vilka tre huvudfunktioner har näsan?', 'Uppvärmning, fuktning och filtrering av inandningsluften, lukt samt resonanslåda för rösten.', 119, 'anki-ai')
