INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632230421278-1l43', 'bv1-m1', 'Hur värms, fuktas och filtreras inandningsluften i näsan?', 'Näsans varma och fuktiga miljö värmer och fuktar luften, och små hår filtrerar bort smuts som annars skulle nå lungorna.', 120, 'anki-ai')
