  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632333135426-idw4', 'bv1-m1', 'Vad påverkar storleken på cartilago thyroidea?', 'Hormoner påverkar storleken; män har typiskt större och mer spetsigt brosk, vilket påverkar rösten.', 130, 'anki-ai')
