INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632333275464-129h', 'bv1-m1', 'Vilken funktion har plicae vestibularis vid sväljning?', 'De drar ihop sig och stänger luftvägarna så att mat inte hamnar i lungorna.', 134, 'anki-ai')
