  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632333331904-xah4', 'bv1-m1', 'Vilken funktion har plicae vocalis?', 'De skapar ljud och står för rösten.', 136, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632333376916-pctx', 'bv1-m1', 'Hur styrs plicae vocalis?', 'Av muskler de är fästa i, vilka spänner och slappnar av stämbanden.', 137, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632333427227-k8rq', 'bv1-m1', 'Vilken röstkaraktär ger spända respektive avslappnade stämband?', 'Spända stämband ger en ljus röst. Avslappnade stämband ger en mörk röst.', 138, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632333439823-4je2', 'bv1-m1', 'Vilken typ av vävnad bygger upp tracheas vägg?', 'Trachea består av brosk.', 139, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632333494430-atde', 'bv1-m1', 'Hur är brosket i trachea format och hur är det positionerat?', 'Brosket är hästskoformat och sitter anteriort och lateralt men inte posteriort.', 140, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632333569780-szz0', 'bv1-m1', 'Varför är tracheas brosk hästskoformat?', 'Den öppna baksidan gör att esophagus kan trycka in i tracheas utrymme vid sväljning, då luftvägarna ändå är stängda.', 141, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632333589521-4mtp', 'bv1-m1', 'Vad kallas lungsäcken?', 'Pleuran.', 142, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632333653724-xukz', 'bv1-m1', 'Vad fäster inandningsmusklerna i och varför?', 'De fäster i pleuran, inte direkt i lungorna. När pleuran dras skapas ett undertryck som gör att lungorna följer med och luft sugs in.', 143, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632333696090-huq0', 'bv1-m1', 'Vilka delar kan pleuran delas upp i?', 'Den parietala pleuran, den viscerala pleuran och vätskan mellan dem.', 144, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632334524303-vjnv', 'bv1-m1', 'Var sitter de två pleurabladen ihop?', 'Vid bronkerna i lunghilus.', 145, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632334648299-5lx6', 'bv1-m1', 'Hur samverkar pleuran med diafragman vid andning?', 'När diafragman kontraherar dras pleuran med och luft sugs in. När diafragman slappnar av trycker pleuravätskan tillbaka lungan uppåt.', 146, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632334740504-mxpt', 'bv1-m1', 'Vilka två sätt kan man andas in på?', 'Autonomt via diafragmans kontraktioner och relaxationer, samt forcerat via intercostalmusklerna runt revbenen.', 147, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632334782902-fq1y', 'bv1-m1', 'Var sitter mm. intercostales och vad gör de?', 'De sitter mellan revbenen och hjälper till vid forcerad andning.', 148, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632334839477-osto', 'bv1-m1', 'Vad gör mm. intercostales externi vid andning?', 'Deras muskelfibrer drar revbenen uppåt och utåt, vilket ger inspiration.', 149, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632334897717-omxl', 'bv1-m1', 'Vad gör mm. intercostales interni vid andning?', 'Deras muskelfibrer drar revbenen nedåt och inåt, vilket ger expiration.', 150, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632334947129-dg26', 'bv1-m1', 'Vad fäster revbenen som utgår från ryggraden i ventralt?', 'Sternum, bröstbenet.', 151, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632334986794-o35v', 'bv1-m1', 'Vilka två delar kan sternum delas in i?', 'Manubrium sterni (övre delen) och corpus sterni (nedre delen).', 152, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632335022694-9bdg', 'bv1-m1', 'Fäster revbenen direkt i sternum?', 'Nej, de fäster i brosk som utgör ett mellanrum mellan revben och sternum.', 153, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632335066025-27oo', 'bv1-m1', 'Vilken funktion har brosket i bröstkorgen?', 'Brosket gör bröstkorgen mer rörlig och tillåter extra rörelse vid in- och utandning.', 154, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632335121382-fhed', 'bv1-m1', 'Vilka muskler står för inspiration?', 'M. diafragma, mm. intercostales externi och mm. scaleni (halsmuskler).', 155, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632335172792-mfla', 'bv1-m1', 'Vilka muskler står för expiration?', 'Mm. intercostales interni och de abdominala musklerna; diafragma relaxerar passivt.', 156, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632335249108-btov', 'bv1-m1', 'Hur rör sig lungan vid andning?', 'Vid inandning expanderar lungan och vid utandning blir den mindre.', 157, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632335305882-g8sq', 'bv1-m1', 'Vad krävs anatomiskt för att lungan ska kunna expandera?', 'Alla strukturer inne i lungan – bronker, artärer och vener – måste kunna expandera tillsammans med lungvävnaden.', 158, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632335334636-cmw2', 'bv1-m1', 'Varför kan utandning ske passivt?', 'På grund av diafragmans och lungans elastiska återfjädring, som driver ut luften när musklerna slappnar av.', 159, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632335389994-axcm', 'bv1-m1', 'Vad menas med att lungan är en elastisk struktur?', 'Att lungvävnaden återgår till sin ursprungliga form när de spända musklerna slappnar av.', 160, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv1-m2-c1', 'bv1-m2', 'Vilka organeller finns i en eukaryot cell och vad gör de?', 'Mitokondrie (ATP), grovt ER (proteinsyntes), slätt ER (lipider och avgiftning), Golgi (modifiering och sortering), lysosom (nedbrytning), peroxisom (oxidation).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv1-m2-c2', 'bv1-m2', 'Vad skiljer Grampositiva från Gramnegativa bakterier?', 'Grampositiva: tjockt peptidoglykanlager och tejkolsyra, färgas blå. Gramnegativa: tunt peptidoglykan, yttre membran med LPS (endotoxin), färgas rosa.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv1-m2-c3', 'bv1-m2', 'Vilka byggstenar har ett virus?', 'Nukleinsyra (DNA eller RNA) omgiven av kapsid; vissa har dessutom ett hölje (envelope) från värdcellens membran. Virus kan inte föröka sig utan värdcell.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv1-m2-c4', 'bv1-m2', 'Vad är skillnaden mellan adhesiner och toxiner?', 'Adhesiner låter mikroorganismen fästa vid värdcellens yta (första steget i kolonisation). Toxiner skadar värdcellen direkt eller via immunsvar (t.ex. endotoxin, exotoxin).', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631092653401-pebd', 'bv1-m2', 'Vilken funktion har cellkärnan?', 'Cellkärnan lagrar DNA (arvsmassan) och styr cellens funktioner genom att reglera proteinproduktionen. Den finns endast i eukaryota organismer och omges av ett eget membran.', 5, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631092653401-dnxa', 'bv1-m2', 'Vad är nukleolen och vilken funktion har den?', 'Nukleolen är en struktur inuti cellkärnan som har en viktig funktion vid RNA-syntesen.', 6, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631093175298-rgl0', 'bv1-m2', 'Vilken funktion har lysosomen?', 'Lysosomen står för den intracellulära nedbrytningen av makromolekyler, t.ex. gamla organeller, bakterier och annat avfall. Hydrolytiska enzym bryter ned materialet sedan vesiklar smält samman med lysosomen.', 7, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631093175298-5v77', 'bv1-m2', 'Hur möjliggör lysosomen återvinning av nedbrutet material?', 'Nedbrutna material transporteras ut i cytosolen för återvinning, medan oönskade ämnen transporteras ut ur cellen.', 8, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631093414439-pyav', 'bv1-m2', 'Vilken funktion har Golgiapparaten?', 'I Golgiapparaten bearbetas, sorteras och paketeras proteiner som bildats i ER. Enzymer modifierar makromolekylerna genom att tillföra kolhydrat- och fosfatgrupper, vilket anger vart proteinerna ska transporteras.', 9, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631093414439-gu4n', 'bv1-m2', 'Hur är Golgiapparaten uppbyggd?', 'Golgiapparaten består av membransäckar och fraktar makromolekyler i vesiklar.', 10, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631093638172-dj8x', 'bv1-m2', 'Vilka två typer av endoplasmatiskt retikel finns?', 'Det finns glatt och kornigt (granulärt) endoplasmatiskt retikel.', 11, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631093638172-mo16', 'bv1-m2', 'Vad kännetecknar kornigt ER?', 'Kornigt ER ligger närmast cellkärnan och är fyllt med ribosomer. De flesta ribosomer som bildas här transporteras ut ur cellen.', 12, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631093638172-y7j2', 'bv1-m2', 'Vad sker i glatt ER?', 'I glatt ER syntetiseras lipider och fosfolipider.', 13, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631093638172-pl4i', 'bv1-m2', 'Vilken ytterligare funktion har ER?', 'ER fungerar även som transportscentral och är fyllt med hålrum och porer.', 14, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631093931423-qnjw', 'bv1-m2', 'Vilken funktion har mitokondrien?', 'Mitokondrien är cellens energifabrik och har en viktig roll i cellandningen genom att tillverka ATP (adenosintrifosfat).', 15, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631093931423-s6xn', 'bv1-m2', 'Vilket genetiskt material innehåller mitokondrien?', 'Mitokondrien innehåller en kort DNA-sekvens.', 16, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631093931423-9t0w', 'bv1-m2', 'Hur är mitokondrien uppbyggd?', 'Mitokondrien är oval och omges av två lipidmembran, varav det inre har veck och därför större yta.', 17, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631094100663-evc3', 'bv1-m2', 'Vilken funktion har ribosomen?', 'Ribosomen är cellens proteinfabrik där proteinsyntesen äger rum; RNA translateras och aminosyror binds till proteiner.', 18, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631094100663-8k4t', 'bv1-m2', 'Var finns ribosomer i cellen?', 'Ribosomer finns både fria i cytoplasman och bundna till ER.', 19, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631094100663-9hcd', 'bv1-m2', 'Hur är ribosomen uppbyggd?', 'Ribosomen består av två subenheter.', 20, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631092653401-l1u2', 'bv1-m2', 'Vilka huvudfunktioner har cellkärnan?', 'Cellkärnan lagrar DNA (arvsmassan) och styr cellens funktioner genom att reglera proteinproduktionen. Den finns endast hos eukaryota organismer och har ett eget membran.', 21, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631093175298-y8tz', 'bv1-m2', 'Vad är lysosomens huvudfunktion i cellen?', 'Lysosomen ansvarar för intracellulär nedbrytning av makromolekyler, gamla organeller och bakterier. Hydrolytiska enzym bryter ned materialet så att det kan återvinnas till cytosolen.', 22, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631093638172-nk7v', 'bv1-m2', 'Vad skiljer kornigt ER från glatt ER?', 'Kornigt ER ligger nära cellkärnan och är täckt av ribosomer som syntetiserar proteiner. Glatt ER saknar ribosomer och syntetiserar lipider och fosfolipider. ER fungerar även som transportsystem med hålrum och porer.', 23, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631093931423-ls8y', 'bv1-m2', 'Vilken roll har mitokondrien i cellen?', 'Mitokondrien producerar ATP genom cellandning och ämnesomsättning. Den har eget DNA och ett inre veckat lipidmembran som ger stor yta.', 24, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631094100663-g10o', 'bv1-m2', 'Vad är ribosomens funktion och uppbyggnad?', 'Ribosomen är platsen för proteinsyntes där mRNA translateras och aminosyror binds till proteiner. Den består av två subenheter och förekommer både fritt i cytoplasman och bundna till ER.', 25, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631094367908-d8fr', 'bv1-m2', 'Vilka funktioner och vilken uppbyggnad har cellmembranet?', 'Cellmembranet reglerar vilka ämnen som passerar in och ut ur cellen och avgränsar organeller och DNA. Det består av ett fosfolipiddubbellager med proteiner och kolesterol enligt fluid mosaic-modellen.', 26, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631094506546-hpz9', 'bv1-m2', 'Vad innefattar cytoplasman?', 'Cytoplasman är allt innanför cellmembranet utom cellkärnan, det vill säga cytosolen och organellerna. Här sker bland annat proteinsyntes i ribosomer och glykolys.', 27, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631094586776-q0nv', 'bv1-m2', 'Vad är cytosol?', 'Cytosol är vätskan innanför cellmembranet som till största delen består av vatten och lösta ämnen. Den geléaktiga konsistensen gör att molekyler kan röra sig i den.', 28, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631095760311-bhjg', 'bv1-m2', 'Vilka funktioner har cytoskelettet och vilka delar ingår?', 'Cytoskelettet ger cellen struktur och form samt möjliggör transporter och celldelning. Det består av mikrotubuli, intermediära filament och aktinfilament.', 29, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631096202058-vrgb', 'bv1-m2', 'Vilken funktion har peroxisomen?', 'Peroxisomen är en membranbunden organell med enzymer för fettsyrornas beta-oxidation och bildning av gallsyror. Vid oxidationen bildas väteperoxid som kan användas för att oxidera giftiga molekyler.', 30, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631097106317-mutl', 'bv1-m2', 'Vilka egenskaper har mikrotubuli i cytoskelettet?', 'Mikrotubuli är tunna rör som utgör en del av cellskelettet och fungerar som transportvägar inuti cellen. Motorproteiner binder till det som ska transporteras och rör sig längs mikrotubuli. Centrioler är uppbyggda av mikrotubuli.', 31, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631097149034-4y40', 'bv1-m2', 'Vad är extracellulär matrix?', 'Extracellulär matrix är materialet i utrymmet utanför och mellan celler.', 32, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631097257171-7i14', 'bv1-m2', 'Vad är DNA och vad är dess funktion?', 'DNA (deoxiribonukleinsyra) är en makromolekyl av två polynukleotidsträngar som bildar en dubbelhelix. Det innehåller den genetiska arvsmassan i form av gener som kodar för proteiner.', 33, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631097365523-tcbp', 'bv1-m2', 'Vad är RNA och vad används det främst till?', 'RNA (ribonukleinsyra) är en makromolekyl som består av en polynukleotidkedja och främst används vid proteinsyntesen. Det finns i alla levande organismer.', 34, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631097586007-oei7', 'bv1-m2', 'Vad är en kromosom uppbyggd av?', 'En kromosom är en trådlik struktur uppbyggd av DNA och proteiner. Den innehåller en organisms gener och hela arvsmassa.', 35, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631097647647-u2oj', 'bv1-m2', 'Vad är en gen?', 'En gen är en specifik enhet av arvsmassan som består av en sekvens som kodar för ett specifikt protein.', 36, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631097684428-5b94', 'bv1-m2', 'Vad menas med genom?', 'Genomet är den kompletta uppsättningen gener, det vill säga hela arvsmassan.', 37, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631098013465-r98w', 'bv1-m2', 'Vad kännetecknar en stamcell?', 'En icke-specialiserad cell som kan differentiera till olika celltyper och dela sig ett obegränsat antal gånger.', 38, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631098167479-pi68', 'bv1-m2', 'Vad är regenerativ medicin?', 'Ett forskningsområde som syftar till att ersätta, konstruera eller regenerera mänskliga celler, vävnader eller organ för att återställa normal funktion, bland annat genom att odla vävnader i laboratoriemiljö och implantera dem.', 39, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631098220338-dw1i', 'bv1-m2', 'Vad är reparativ medicin?', 'Inriktning som syftar till att reparera, ta bort och/eller ersätta skadade organ och vävnader vid olycksfall eller sjukdom.', 40, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631098822866-sn5l', 'bv1-m2', 'Hur många kromosomer har en människa normalt?', '46 kromosomer, det vill säga 23 par, där 23 kommer från vardera föräldern.', 41, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631098890584-1ff5', 'bv1-m2', 'Under vilken period växer människan relativt sett mest?', 'Under fosterperioden, som varar cirka 7 månader.', 42, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631098917738-rnxe', 'bv1-m2', 'Vad sker under embryonalperioden?', 'Alla organ och vävnader bildas.', 43, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631098958821-n35y', 'bv1-m2', 'Vad sker under fetalperioden?', 'Organen och vävnaderna som bildades under embryonalperioden mognar och växer i storlek.', 44, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631098999915-i3ee', 'bv1-m2', 'Under vilken period är människan känsligast för alkoholskador?', 'Under embryonalperioden.', 45, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631099118861-km41', 'bv1-m2', 'Hur kan graviditetstid räknas inom embryologin?', 'Antingen från första dagen för ägglossningen (cirka 2 veckor efter utebliven mens) eller från första dagen av senaste menstruationen.', 46, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631099271665-juei', 'bv1-m2', 'Vad menas med ärftlighet (hereditet)?', 'Hur egenskaper nedärvs från generation till generation, det vill säga processen genom vilken en cell eller organism förvärvar egenskaper från moderceller eller föräldraorganismen.', 47, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631099394006-0kkg', 'bv1-m2', 'Vad är en mutation?', 'En förändring i cellens genetiska material, oftast DNA men ibland RNA.', 48, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631099507222-subp', 'bv1-m2', 'Vad innebär naturligt urval (selektion)?', 'De organismer som är bäst anpassade till miljön har störst chans att föra sina gener vidare till nästa generation – survival of the fittest.', 49, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631099534330-kxio', 'bv1-m2', 'Vad är genflöde?', 'Överföring av gener från en population till en annan av samma art.', 50, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631099628068-0ljp', 'bv1-m2', 'Vad är konvergent evolution?', 'Obesläktade organismer i samma miljö anpassas genom mutationer och naturligt urval så att de börjar likna varandra och få liknande egenskaper.', 51, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631099727873-7c23', 'bv1-m2', 'Vad är divergent evolution?', 'Organismer av samma art utvecklar olika egenskaper på olika geologiska platser som följd av miljön, och skiljer sig alltmer tills de blir separata arter.', 52, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631099771088-4apg', 'bv1-m2', 'Vad är fylogeni?', 'Läran om härstamning, det vill säga hur organismer är besläktade med varandra.', 53, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631100012829-uv7q', 'bv1-m2', 'Vilka fyra typer av evidens stödjer evolutionen?', 'Fossiler, molekylär evidens (DNA-data), anatomisk/morfologisk evidens och embryologi.', 54, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631100080281-il1y', 'bv1-m2', 'Vad visar hybridisering (interbreeding) mellan den moderna människan och andra människogrupper?', 'Att modern människa korsat sig med neandertalare och denisovaner, vilket gett spår av deras DNA i vissa populationer.', 55, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631100208991-vhpq', 'bv1-m2', 'Varför har mitokondrier eget DNA?', 'Mitokondrier har prokaryot ursprung enligt endosymbiontteorin och behöll därför eget DNA.', 56, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631100377279-uqw7', 'bv1-m2', 'Vad innebär endosymbiontteorin?', 'Att eukaryota celler uppstod när bakterier invaderade arkéer och började leva i symbios med dem.', 57, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631100484303-ogfq', 'bv1-m2', 'Vilka fyra teorier finns om livets uppkomst?', 'Den varma pölen, kemisk soppa med åska (Miller-Urey), kometteorin och ytor i jordskorpan.', 58, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631100602960-pb19', 'bv1-m2', 'Vad kännetecknar en prokaryot cell?', 'Den saknar cellkärna och membranbundna organeller och är encellig.', 59, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631100690054-5fwj', 'bv1-m2', 'Vilken organell fungerar som cellens sorteringscentral?', 'Golgi-apparaten.', 60, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631100749661-ggqz', 'bv1-m2', 'Vad kännetecknar en eukaryot cell?', 'Den har cellkärna och membranbundna organeller och kan vara både encellig och flercellig.', 61, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631100805518-az35', 'bv1-m2', 'Vilka strukturer kan en viruskapsid ha?', 'Helikal (spiralformad) eller ikosahedral (fotbollsformad) struktur.', 62, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631100854381-9f3s', 'bv1-m2', 'Vad är en kapsid?', 'Ett proteinhölje hos virus som skyddar nukleinsyran (genomet).', 63, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631100901425-lkgj', 'bv1-m2', 'Vilken organell motsvarar kroppens matsäck?', 'Lysosomen.', 64, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631100934661-0u3k', 'bv1-m2', 'Vilken organell tar hand om toxiskt material i cellen?', 'Peroxisomen.', 65, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631101045932-3jrh', 'bv1-m2', 'Vad är ett virushölje?', 'Ett lipidhölje som härstammar från värdcellens membran; virus med hölje kallas höljevirus, utan hölje nakna virus.', 66, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631101318370-vkfg', 'bv1-m2', 'Hur varierar mängden DNA per cell mellan olika livsformer?', 'Mängden DNA per cell varierar stort mellan olika livsformer.', 67, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631101379010-vkpr', 'bv1-m2', 'Var i cellen finns cellorganellerna?', 'Cellorganellerna finns i cytoplasman.', 68, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631103225454-m9gn', 'bv1-m2', 'Varför anses protozoer ha uppstått senare än bakterier, arkéer och virus?', 'Protozoer är eukaryota celler, vilket är en senare evolutionär utveckling än de prokaryota bakterierna och arkéerna.', 69, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631103982591-ixc4', 'bv1-m2', 'Vilken struktur har bakterier men inte eukaryota celler?', 'Peptidoglykan i cellväggen.', 70, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631104906890-hxbd', 'bv1-m2', 'Var finns stamceller i den vuxna människokroppen?', 'Stamceller finns nästan överallt i den vuxna kroppen.', 71, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631105082260-5zyi', 'bv1-m2', 'Hur stor del av människans genom utgörs av gener (kodande sekvenser)?', 'Endast ett par procent.', 72, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631105149831-94sq', 'bv1-m2', 'Vilken cellstruktur har en funktion analog med musklerna i kroppen?', 'Cytoskelettet, som ger cellen rörelse och form.', 73, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631105314674-vlny', 'bv1-m2', 'Vilken är den mest sannolika ordningen i livets utveckling?', 'Gaser → enkla organiska molekyler → proteiner och nukleinsyror → protoceller → första celler.', 74, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631738601408-oypp', 'bv1-m2', 'Vad är en loop i proteinstruktur?', 'En utsträckt, oregelbunden sväng i polypeptidkedjan som förbinder sekundärstrukturelement, t.ex. mellan en alfahelix och ett betablad.', 75, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631738643191-gxg9', 'bv1-m2', 'Vad menas med supersekundärstruktur?', 'En kombination av flera sekundärstrukturelement, t.ex. alfahelixar och betablad, som tillsammans bildar ett återkommande motiv.', 76, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631738756256-8h6t', 'bv1-m2', 'Hur anpassar sig ett proteins sekundärstruktur till en polär respektive opolär miljö?', 'I hydrofil miljö exponeras hydrofila delar medan hydrofoba delar omsluts inåt; i hydrofob miljö är förhållandet det omvända.', 77, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631738874171-97pc', 'bv1-m2', 'Vad är en proteindomän (modul)?', 'En region i polypeptidkedjan som veckar sig stabilt och oberoende av resten av kedjan. I små proteiner utgör domänen hela proteinet.', 78, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631739009278-hpbm', 'bv1-m2', 'Vad innebär kvartär struktur?', 'Flera polypeptidkedjor (subenheter) hålls samman till ett proteinkomplex, och deras inbördes positioner och förhållande beskrivs.', 79, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631739030961-i7nf', 'bv1-m2', 'Vilken bindning håller samman primärstrukturen?', 'Peptidbindningar mellan aminosyrorna i kedjan.', 80, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631739052024-6g74', 'bv1-m2', 'Vilken typ av bindning stabiliserar sekundärstrukturen?', 'Vätebindningar mellan atomgrupper i polypeptidens huvudkedja.', 81, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631739102499-xf4j', 'bv1-m2', 'Vilka bindningar stabiliserar tertiärstrukturen?', 'Vätebindningar, jonbindningar, hydrofoba effekter, van der Waals-krafter och disulfidbryggor.', 82, 'anki-ai')
