INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632350624661-epo6', 'bv1-m2', 'Hur skiljer sig jonkoncentrationerna mellan intracellulär och extracellulär vätska?', 'Den totala jonkoncentrationen (osmolariteten) är i stort sett densamma, men jonerna skiljer sig åt: intracellulärt dominerar kalium, extracellulärt dominerar natrium.', 131, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632351080846-s2z6', 'bv1-m2', 'Vilka två övergripande funktioner har njuren?', 'Att reglera kroppens inre miljö och att avlägsna ämnen från kroppen.', 132, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632351146515-rnlx', 'bv1-m2', 'Vilka tre faktorer reglerar njuren?', 'Vatten- och saltbalans, syra-basbalans (pH) samt blodtryck (via blodvolym).', 133, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632351175819-9t49', 'bv1-m2', 'Vilka två typer av ämnen avlägsnar njuren?', 'Avfallsprodukter från metabolismen och främmande ämnen (t.ex. läkemedel och toxiner).', 134, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632351239890-70av', 'bv1-m2', 'Genom vilka fyra steg åstadkoms njurens urinbildning?', 'Filtration, återresorption, sekretion och utsöndring.', 135, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632351273192-yt5t', 'bv1-m2', 'Vad är filtrationens roll i njurens urinbildning?', 'Filtration är det första steget där plasma filtreras i glomerulus till primärurin i Bowmans kapsel.', 136, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632351402116-lj1t', 'bv1-m2', 'Vad sker vid filtrationen i glomerulus?', 'Blod kommer in via arteriola afferens och det höga trycket pressar vatten, salter och små ämnen (t.ex. glukos) ut i Bowmans kapsel. Erytrocyter och proteiner stannar kvar och lämnar glomerulus via arteriola efferens.', 137, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632351457291-bbv8', 'bv1-m2', 'Vilka ämnen passerar normalt inte glomerulusfiltret?', 'Erytrocyter och proteiner, eftersom de är för stora. Förekomst av dessa i urinen är ofta ett tecken på sjukdom.', 138, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632352830486-hyrh', 'bv1-m2', 'Vilken del av nefronet utgörs av en lång, rak slynga ned i medulla renalis?', 'Henles slynga (loop of Henle) är den del av nefronet som sträcker sig rakt ned i medulla renalis och där återresorption av vatten och salt sker.', 139, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431146132-1hgu', 'bv1-m2', 'Vad menas med parenkym i ett organ?', 'Parenkymet är den funktionella vävnaden i ett organ.', 140, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431175634-mbu2', 'bv1-m2', 'Vad menas med stroma i ett organ?', 'Stroma är stödjevävnaden mellan parenkymet, dvs. bindväven i ett organ.', 141, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431205237-tzd1', 'bv1-m2', 'Vilken funktion har bindväv/stroma i ett organ?', 'Stödjevävnaden ger organets vävnader struktur; utan den skulle allt flyta runt.', 142, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431252684-3d0p', 'bv1-m2', 'Vad definierar en vävnad?', 'En vävnad är en samling celler i en organism som har liknande uppgifter.', 143, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431300332-r83w', 'bv1-m2', 'Vad är ett organ?', 'En yttre eller inre kroppsdel med specifik funktion och form. Ett organ består av vävnader.', 144, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431368263-x4qw', 'bv1-m2', 'Vilka är kroppens fyra huvudvävnadstyper?', 'Epitelvävnad, bindvävnad, muskelvävnad och nervvävnad.', 145, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431428170-dade', 'bv1-m2', 'Vilka två huvudtyper av epitelvävnad finns?', 'Ytepitel och körtelepitel.', 146, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431512715-swvd', 'bv1-m2', 'Var finns ytepitel och hur är cellerna arrangerade?', 'Ytepitel finns på kroppens ytor (hud och slemhinnor) och i lumen. Cellerna står på ett basalmembran och sitter tätt ihop.', 147, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431558478-ih9f', 'bv1-m2', 'Varför sitter ytepitelceller tätt intill varandra?', 'De bildar en barriär så att innehåll i lumen eller utanför kroppen inte kan läcka förbi.', 148, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431637559-cawx', 'bv1-m2', 'Vilka ytstrukturer kan ytepitelceller ha?', 'Mikrovilli, som ökar arean vid näringsupptag i tarmen, och kinocilier (flimmerhår), som rör på sig och finns i luftvägarna.', 149, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431701613-ua5v', 'bv1-m2', 'Vilka tre typer av cellförband finns mellan epitelceller?', 'Zonula occludens (ZO), zonula adherens (ZA) och macula adherens (MA).', 150, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431746059-vh1w', 'bv1-m2', 'Vad är typiskt för epitelvävnad gällande cellförband?', 'Cellerna har täta cellförband och sammanfogas med hjälp av fogsatser (junctional complexes).', 151, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431764003-bazp', 'bv1-m2', 'Vad är körtelepitel?', 'Körtelepitel utgör den aktiva delen i körtlar.', 152, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431872188-n6vd', 'bv1-m2', 'Vilka huvudtyper av bindväv finns?', 'Egentlig bindväv, fettväv, brosk, ben och benmärg.', 153, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431966792-dfav', 'bv1-m2', 'Vilka celltyper förekommer i egentlig bindväv?', 'Mesenkymceller, fibroblaster, mastceller och makrofager.', 154, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632431982686-teiq', 'bv1-m2', 'Vilken celltyp är karakteristisk för fettväv?', 'Adipocyter (fettceller).', 155, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632432001931-h7uz', 'bv1-m2', 'Vilka celltyper finns i brosk?', 'Kondroblaster och kondrocyter.', 156, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632432036094-qrf9', 'bv1-m2', 'Vilka celltyper finns i ben?', 'Osteoblaster, osteocyter och osteoklaster.', 157, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632432066566-q5na', 'bv1-m2', 'Vilka celltyper finns i blod?', 'Erytrocyter, leukocyter och trombocyter.', 158, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632432084389-mf2c', 'bv1-m2', 'Vad bildas i benmärgen?', 'Benmärgen är förstadiet till blodceller (hematopoes).', 159, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632432187703-d2zb', 'bv1-m2', 'Vilka typer av muskelvävnad finns?', 'Skelettmuskulatur (tvärstrimmig), glatt muskulatur och hjärtmuskulatur (tvärstrimmig).', 160, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv1-m3-c1', 'bv1-m3', 'Vilka är kroppens fyra grundvävnader?', 'Epitelvävnad, bindvävnad, muskelvävnad och nervvävnad – alla organ är uppbyggda av dessa i olika kombinationer.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv1-m3-c2', 'bv1-m3', 'Vad är skillnaden mellan parenkym och stroma?', 'Parenkym = organets funktionella celler; stroma = stödjevävnad med bindväv, kärl och nerver.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv1-m3-c3', 'bv1-m3', 'Vilka tre makromolekylgrupper dominerar ämnesomsättningen?', 'Kolhydrater (energi), lipider (energi, membran, signalering) och proteiner (enzymer, struktur, transport). Nukleotider bär information och energi (ATP).', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv1-m3-c4', 'bv1-m3', 'Vad är skillnaden mellan anabolism och katabolism?', 'Anabolism bygger upp molekyler och kräver energi (ATP); katabolism bryter ner molekyler och frigör energi.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631734691311-zix4', 'bv1-m3', 'Vilka är de fyra näringsämnena?', 'Kolhydrater, fetter, proteiner och nukleinsyror.', 5, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631734881809-yz6g', 'bv1-m3', 'Vilken typ av karbonylgrupp har kolhydrater?', 'Kolhydrater har antingen en aldehydgrupp (aldoser) eller en ketongrupp (ketoser).', 6, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631734905647-jr3t', 'bv1-m3', 'Vilket monosackarid är det viktigaste i människokroppen?', 'D-glukos är det viktigaste sockret.', 7, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631734946125-worz', 'bv1-m3', 'Vad kännetecknar Fischer- respektive Haworthprojektion?', 'Fischerprojektionen visar kedjeformen med raka bindningar; Haworthprojektionen visar den cykliska formen som en ring.', 8, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631735034674-xs2g', 'bv1-m3', 'Åt vilket håll pekar hydroxylgruppen vid anomert kol i α- respektive β-D-glukos?', 'I α-D-glukos pekar hydroxylgruppen nedåt; i β-D-glukos pekar den uppåt.', 9, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631735069689-p8bk', 'bv1-m3', 'Vilken anomer av glukos kan spjälkas av glykosidaser?', 'α-glukos kan spjälkas; β-glukos kan inte spjälkas av motsvarande enzym.', 10, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631735131596-lhi5', 'bv1-m3', 'Vilken typ av stereoisomerer är glukos och galaktos?', 'Glukos och galaktos är diastereoisomerer (epimerer) som skiljer sig vid kol 4.', 11, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631735219487-9b7h', 'bv1-m3', 'Vilka av följande är pentoser respektive hexoser: glukos, fruktos, galaktos, ribos, deoxyribos?', 'Pentoser: ribos och deoxyribos. Hexoser: glukos, fruktos och galaktos.', 12, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631735296804-oill', 'bv1-m3', 'Hur skiljer sig α- och β-glukosidbindningen i disackarider?', 'α-glukosidbindningen pekar nedåt och kan spjälkas; β-glukosidbindningen pekar uppåt och kan inte spjälkas av motsvarande enzym.', 13, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631735414115-0iy6', 'bv1-m3', 'Vilka huvudgrupper av kolhydrater finns?', 'Monosackarider, disackarider och polysackarider.', 14, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631735530433-wysf', 'bv1-m3', 'Vilka huvudgrupper av lipider finns?', 'Fettsyror, triacylglycerider, fosfolipider och steroider (t.ex. kolesterol).', 15, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631735597919-fpiu', 'bv1-m3', 'Vad kännetecknar en mättad respektive omättad fettsyra?', 'Mättad fettsyra saknar dubbelbindningar; omättad har en eller flera dubbelbindningar. Fleromättad har mer än en dubbelbindning, enkelomättad har en.', 16, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631735647413-fcyy', 'bv1-m3', 'I vilken kemisk form förekommer större delen av fettet i vår föda?', 'Som triacylglycerol.', 17, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1631735706402-qsxl', 'bv1-m3', 'Vad består triacylglycerol av?', 'En triester av glycerol med tre fettsyror.', 18, 'anki-ai')
