VALUES ('anki-1632397119061-zsbv', 'bv1-m3', 'Vad är ductus pancreaticus accessorius?', 'En accessorisk pankreasgång som mynnar i papilla duodeni minor.', 66, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632397203622-62x7', 'bv1-m3', 'Vad kännetecknar vätskan från ductus pancreaticus accessorius?', 'Den innehåller mycket enzymer i inaktiv form som aktiveras först i duodenum, och den är buffrande.', 67, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632397276806-k91g', 'bv1-m3', 'Vilka är de tre stora spottkörtlarna?', 'Glandula parotis, glandula submandibularis och glandula sublingualis.', 68, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632397349690-xctu', 'bv1-m3', 'Vad innehåller saliv?', 'Saliv består främst av vatten, men innehåller även enzymer, bikarbonat som skyddar tänderna mot karies, och antikroppar.', 69, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632428611553-9x8i', 'bv1-m3', 'Vad är anabolism?', 'Anabolism är uppbyggande reaktioner som ofta är energikrävande.', 70, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632428630988-zqa6', 'bv1-m3', 'Vad menas med katabolism?', 'Katabolism är nedbrytande reaktioner där komplexa molekyler bryts ned, vilket ofta frigör energi.', 71, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632428658608-gb7c', 'bv1-m3', 'Vad är metabolism?', 'Metabolism är ämnesomsättningen, det vill säga summan av katabolism och anabolism.', 72, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632428760611-0qwk', 'bv1-m3', 'Vad sker i glykolysen?', 'En glukosmolekyl bryts ned till två pyruvatjoner. Energin används för att bilda högenergiföreningarna ATP och NADH.', 73, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632428794398-8nec', 'bv1-m3', 'Var i cellen sker glykolysen?', 'Glykolysen sker i cytosolen hos alla celler i kroppen.', 74, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632428866015-1r1b', 'bv1-m3', 'Vad är glukoneogenes?', 'Glukoneogenes är bildning av glukos från enklare föreningar, till exempel intermediärer i glykolysen.', 75, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632428918192-itny', 'bv1-m3', 'Var sker glukoneogenesen?', 'Glukoneogenesen sker huvudsakligen i levern under fasta, men även i njurbarken, i cytosolen.', 76, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632428971684-wj6t', 'bv1-m3', 'Vad innebär transaminering?', 'Vid transaminering förs en aminogrupp över från en aminosyra till en karboxylsyra.', 77, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429022178-fps6', 'bv1-m3', 'Vad innebär deaminering av aminosyror?', 'Vid överskott av aminosyror kan de deamineras, vilket innebär att aminosyran oxideras till en karboxylsyra och ammoniak.', 78, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429040904-wm0h', 'bv1-m3', 'Var sker transaminering och deaminering främst?', 'Transaminering och deaminering sker främst i cytosolen i levern.', 79, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429094576-3qcu', 'bv1-m3', 'Vad är lipolys?', 'Lipolys är nedbrytning av en triacylglycerol till tre fettsyror och en glycerol genom hydrolys av esterbindningarna.', 80, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429116417-hdt4', 'bv1-m3', 'Var i cellen sker lipolys?', 'Lipolys sker i cytosolen i adipocyter.', 81, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429165709-4c4m', 'bv1-m3', 'Vilken typ av bindning förenar fettsyror och glycerol i triacylglycerol?', 'Fettsyror är bundna till glycerol via esterbindningar.', 82, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429227983-c0z5', 'bv1-m3', 'Vad innebär beta-oxidation?', 'Beta-oxidation är nedbrytning av fettsyror där varje cykelvarv avspjälkar två kolatomer som acetyl-CoA.', 83, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429252372-p3cm', 'bv1-m3', 'Var i cellen sker beta-oxidation?', 'Beta-oxidation sker delvis i cytosolen och delvis i mitokondrier.', 84, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429352244-5e2r', 'bv1-m3', 'Vad är citronsyracykeln?', 'Citronsyracykeln är en serie reaktioner där acetyl-CoA binds till oxalacetat och bildar citrat; varje varv frigör ATP, NADH och FADH2.', 85, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429372351-xb8u', 'bv1-m3', 'Var i cellen sker citronsyracykeln?', 'Citronsyracykeln sker i mitokondriernas matrix.', 86, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429502193-fnr2', 'bv1-m3', 'Vad är andningskedjan?', 'Andningskedjan (elektrontransportkedjan) är proteinkomplex i mitokondriens innermembran där elektroner från NADH och FADH2 driver pumpning av vätejoner, vilket skapar en membranpotential som driver ATP-syntes.', 87, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429531631-u2jh', 'bv1-m3', 'Var i mitokondrien sker andningskedjan?', 'Andningskedjan sker i mitokondriens innermembran.', 88, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429576841-yg06', 'bv1-m3', 'Vad är fettsyrasyntes (lipogenes)?', 'Fettsyrasyntes är processen där fettsyror bildas från acetyl-CoA, i princip motsatt beta-oxidation.', 89, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429604346-2lq8', 'bv1-m3', 'Var sker fettsyrasyntes huvudsakligen?', 'Fettsyrasyntes sker främst i levern, men även till viss del i hjärnan och bröstkörtlarna.', 90, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429673650-rc00', 'bv1-m3', 'Vad är ureacykeln?', 'En cykel som omvandlar fri ammoniak från deamineringen till urea, som kan transporteras i blodet och utsöndras via njurarna. Den är en del av kvävemetabolismen.', 91, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429690125-35v0', 'bv1-m3', 'Var sker ureacykeln?', 'Främst i levern.', 92, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429774641-znuw', 'bv1-m3', 'Vad är glykogenes?', 'Bildning av glykogen genom att glukosmolekyler läggs på glykogenkedjor. Processen stimuleras av insulin vid höga blodsockernivåer.', 93, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429802707-6h51', 'bv1-m3', 'Var sker glykogenes?', 'Framför allt i lever- och muskelceller.', 94, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429860830-dc29', 'bv1-m3', 'Vad är glykogenolys?', 'Nedbrytning av lagrat glykogen till glukos. Processen stimuleras av glukagon vid låga blodsockernivåer.', 95, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429884470-ipkk', 'bv1-m3', 'Var sker glykogenolys?', 'Främst i lever- och muskelceller där glykogen finns lagrat.', 96, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632429975311-69pz', 'bv1-m3', 'Vilken roll har ATP i cellen?', 'ATP driver kemiska reaktioner genom att avge energi.', 97, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430039749-bile', 'bv1-m3', 'Vilken roll har NADH och FADH2 i cellandningen?', 'De fungerar som elektrondonatorer i elektrontransportkedjan (ETC) när ATP bildas.', 98, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430130208-r31a', 'bv1-m3', 'Hur och när används syre i cellen?', 'Vid cellandningen, närmare bestämt i elektrontransportkedjan, där syre binder vätejoner och bildar H2O som restprodukt.', 99, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430221766-poe6', 'bv1-m3', 'Vad kännetecknar steroider strukturellt?', 'Fyra sammankopplade kolväteringar som är kondenserade, dvs. ihopsatta med en gemensam vägg per ringpar.', 100, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430280242-3skw', 'bv1-m3', 'Vilka två huvudfunktioner har aminosyror utöver att bygga proteiner?', 'Aminosyror kan deamineras/transamineras och gå in i citronsyracykeln som energisubstrat. De bygger också upp proteiner.', 101, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430377679-4t51', 'bv1-m3', 'Vad menas med en subenhet i ett protein?', 'En enskild proteinmolekyl som binder till andra proteinmolekyler för att bilda en funktionell enhet, t.ex. en ribosom eller hemoglobinets globinkedjor.', 102, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430448414-59u4', 'bv1-m3', 'Vad är post-translationella proteinmodifieringar?', 'Kovalenta förändringar av ett protein som sker efter translationen, t.ex. glykosylering, fosforylering eller klyvning.', 103, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430514618-sjaz', 'bv1-m3', 'Varför är proteolytisk klyvning viktig för vissa enzym?', 'Klyvning kan aktivera ett proenzym först när det nått rätt plats, så att det inte bryter ner vävnad i förtid.', 104, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430550867-m8l0', 'bv1-m3', 'Vad innebär hydroxylering av en aminosyra?', 'Att en hydroxylgrupp (OH) binds till aminosyrans sidokedja.', 105, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430587535-kqlh', 'bv1-m3', 'Vad innebär gamma-karboxylering av en aminosyra?', 'Att en karboxylgrupp binds till aminosyrans gamma-kol, vilket ger en extra negativ laddning som kan binda kalcium.', 106, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430622984-usbv', 'bv1-m3', 'Vad innebär N-glykosylering av ett protein?', 'Att en sockergrupp binds till kvävet i aminosyrans aminogrupp (vanligen asparagin).', 107, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430659817-c1nw', 'bv1-m3', 'Vad innebär O-glykosylering av ett protein?', 'Att en sockergrupp binds till syreatomen i en hydroxylgrupp på aminosyrans sidokedja (vanligen serin eller treonin).', 108, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430687705-1aqr', 'bv1-m3', 'Vad är en disulfidbrygga?', 'En kovalent bindning mellan två svavelatomer, vanligen i cysteinsidokedjor, som stabiliserar proteinets struktur.', 109, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430749495-r4ab', 'bv1-m3', 'Vad innebär fettmodifiering (lipidmodifiering) av ett protein?', 'Att en lipidgrupp, t.ex. via glycerol, kovalent binds till en aminosyra och förankrar proteinet i membranet.', 110, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430797622-op0r', 'bv1-m3', 'Vad kännetecknar fibrösa proteiner och vad används de till?', 'Fibrösa proteiner bygger upp strukturer som hud och hår. Kollagen är ett typiskt exempel.', 111, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430831291-iidz', 'bv1-m3', 'Vad kännetecknar globulära proteiner?', 'Globulära proteiner används för de biokemiska processerna i kroppen.', 112, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430870174-fy2n', 'bv1-m3', 'Vad är ett konjugerat protein?', 'Ett protein som är bundet till en icke-protein för att få en speciell funktion, t.ex. hemproteiner eller receptorer.', 113, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632430907124-f6q4', 'bv1-m3', 'Vilket vitamin är kollagenbildningen beroende av?', 'Kollagen är beroende av vitamin C för att bildas.', 114, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
