  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632840153024-ad48', 'bv1-m4', 'Vad är en gyrus i hjärnbarken?', 'En gyrus är en vindling/upphöjning i cortex cerebri, belägen mellan två sulci.', 36, 'anki-ai')
