ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632907055174-udqu', 'bv1-m4', 'Vad heter dorsalhornet på latin?', 'Cornu posterius.', 104, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632907287937-rpvz', 'bv1-m4', 'Vilken funktion har ventralhornet?', 'Ventralhornet är motoriskt: härifrån utgår axoner från motoriska neuron som skickar signaler ut från CNS till PNS.', 105, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632907372831-n1dv', 'bv1-m4', 'Vilken funktion har dorsalhornet?', 'Dorsalhornet är sensoriskt: hit kommer afferenta signaler från sensoriska neuron i dorsalrotsgangliet in i ryggmärgen.', 106, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632907391789-ca6f', 'bv1-m4', 'Vad menas med afferent information?', 'Afferent information är signaler som kommer in till nervsystemet, dvs. sensorisk information från periferin mot CNS.', 107, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632907506237-duuc', 'bv1-m4', 'Vad menas med efferent information?', 'Efferent information är signaler som skickas ut från nervsystemet, dvs. motoriska kommandon från CNS mot periferin.', 108, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632907673028-jz17', 'bv1-m4', 'Vilken funktion har radix posterior och vad händer vid skada?', 'Radix posterior (bakre spinalroten) förmedlar sensorik; en skada ger förlorad sensorik.', 109, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632907714910-im4w', 'bv1-m4', 'Vilken funktion har radix anterior och vad händer vid skada?', 'Radix anterior (främre spinalroten) förmedlar motorik; en skada ger förlorad motorik.', 110, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632907926546-tw3f', 'bv1-m4', 'Vilka två rötter bildar en spinalnerv?', 'Spinalnerven bildas av radix posterior (bakre roten) och radix anterior (främre roten), som går ihop.', 111, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632908003310-4m2g', 'bv1-m4', 'Var sitter cellkropparna för de sensoriska neuronerna som går in i ryggmärgen?', 'De sitter inte i ryggmärgen utan i dorsalrotsganglierna, en bit utanför ryggmärgen.', 112, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632908461737-8d8f', 'bv1-m4', 'Vad är ett dorsalrotsganglion?', 'En samling cellkroppar för sensoriska neuroner utanför ryggmärgen. Neuronerna skickar en axon ut för att samla sensorisk information och en axon in till dorsalhornet för att föra informationen vidare till CNS.', 113, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632909094534-q918', 'bv1-m4', 'Vad kallas den del av ryggmärgen som bildar en spinalnerv?', 'Ett segment.', 114, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632909136598-cb9h', 'bv1-m4', 'I vilka fyra regioner delas ryggmärgens segment in?', 'Cervikala, thorakala, lumbala och sakrala segment.', 115, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632909264073-ehjy', 'bv1-m4', 'Hur många segment finns i varje region av ryggmärgen?', '8 cervikala, 12 thorakala, 5 lumbala och 5 sakrala segment.', 116, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632909513323-kdjr', 'bv1-m4', 'Vilka kroppsdelar försörjer de cervikala segmenten sensoriskt och motoriskt?', 'Övre delen av kroppen: armar, bakhuvud, hals och nacke.', 117, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632909548511-oa5s', 'bv1-m4', 'Vilken kroppsdel försörjer de thorakala segmenten sensoriskt och motoriskt?', 'Bålen.', 118, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632909573616-eup6', 'bv1-m4', 'Vilka områden försörjer de lumbala segmenten sensoriskt och motoriskt?', 'Framsidan av låren och ländryggen.', 119, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632909604954-bq1s', 'bv1-m4', 'Vilka områden försörjer de sakrala segmenten sensoriskt och motoriskt?', 'Baksidan av låren, rumpan och könsorganen.', 120, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632909665126-m0x9', 'bv1-m4', 'Vilken utsträckning har ryggmärgen embryologiskt?', 'Embryologiskt sträcker sig ryggmärgen från hjärnstammen hela vägen ner till sacrum.', 121, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632909748154-rnzh', 'bv1-m4', 'Varför dras ryggmärgen uppåt i ryggraden under tillväxten?', 'Efter embryonaltiden växer kroppen snabbare än ryggmärgen, vilket gör att ryggmärgens nedre ände förskjuts uppåt.', 122, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632909773277-wc3x', 'bv1-m4', 'Vid vilken kotnivå slutar ryggmärgen vanligen hos vuxna?', 'Hos vuxna slutar ryggmärgen vanligen vid kota L1.', 123, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632909841296-pe34', 'bv1-m4', 'Vad kallas samlingen av spinalnerver nedanför ryggmärgens slut?', 'Nedanför ryggmärgens slut vid kota L1 fortsätter spinalnerverna som en samling som kallas cauda equina.', 124, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632909866950-7a9x', 'bv1-m4', 'Vad kallas samlingen av spinalnerver nedanför kota L1?', 'Cauda equina.', 125, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632909894537-8vmy', 'bv1-m4', 'Vad är cauda equina?', 'Cauda equina är samlingen av spinalnerver som fortsätter ned i ryggraden efter ryggmärgens slut.', 126, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632910008253-l8vy', 'bv1-m4', 'Varför är cauda equina funktionellt viktig?', 'Eftersom ryggmärgen tar slut men spinalnerverna fortsätter finns vätska i nervsystemet mellan L1 och S3, vilket är funktionellt viktigt.', 127, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632910052867-4tr8', 'bv1-m4', 'Var finns spinalvätskan i ryggraden?', 'Spinalvätskan finns nedanför ryggmärgen vid cauda equina, mellan L1 och S3.', 128, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632910118886-4eyk', 'bv1-m4', 'Vad kan man göra med spinalvätskan mellan L1 och S3?', 'Man kan sticka in en nål i regionen mellan L1 och S3 och ta ut spinalvätska för olika prover.', 129, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632910168213-z3wl', 'bv1-m4', 'Vilka strukturer ingår i CNS?', 'CNS består av storhjärna, hjärnstam, lillhjärna och ryggmärg.', 130, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632910188106-ev96', 'bv1-m4', 'Vad är centrala nervsystemets (CNS) huvudsakliga funktion?', 'CNS är den del av nervsystemet som integrerar information och fattar beslut.', 131, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632910225038-sq59', 'bv1-m4', 'Vad utgör det perifera nervsystemet (PNS)?', 'Allt nervvävnad utanför CNS, det vill säga perifera nerver och ganglier.', 132, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632910289642-irsg', 'bv1-m4', 'Vilken funktion har PNS jämfört med CNS?', 'PNS fungerar som kablar som skickar signaler till och från CNS. PNS har bättre förmåga till regeneration än CNS.', 133, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632910367257-e6gc', 'bv1-m4', 'Vilken artär utgör det främre blodförsörjningssystemet till hjärnan?', 'A. carotis interna.', 134, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632910392895-kriw', 'bv1-m4', 'Hur stor andel av hjärnvävnaden försörjs av a. carotis interna?', 'Cirka 80 %.', 135, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632910434459-lita', 'bv1-m4', 'I vilka två kärl förgrenar sig a. carotis interna intracerebralt?', 'A. cerebri media och a. cerebri anterior.', 136, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632910486937-ysqe', 'bv1-m4', 'Hur förlöper a. cerebri media?', 'Den fortsätter rakt lateralt och lägger sig runt hjärnan och försörjer stora delar av den laterala hjärnhemisfären.', 137, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632910547175-vgw8', 'bv1-m4', 'Hur förlöper a. cerebri anterior?', 'Den avgår nästan 90 grader från a. cerebri media och försörjer den främre och mediala delen av hjärnan.', 138, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632910574147-zelq', 'bv1-m4', 'Vilket kärl försörjer hjärnan via det bakre systemet?', 'A. vertebralis.', 139, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632910614562-ngle', 'bv1-m4', 'Hur stor andel av hjärnvävnaden försörjs av a. vertebralis?', 'Cirka 20 %.', 140, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632920825160-tk8m', 'bv1-m4', 'Var går a. vertebralis in i kraniet och hur löper den vidare?', 'A. vertebralis löper på vardera sida om medulla oblongata och avgrenar små kärl som försörjer hjärnstammen och cerebellum.', 141, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632921163606-iteq', 'bv1-m4', 'Var bildas a. basilaris?', 'Precis under pons går de två a. vertebralis samman och bildar a. basilaris.', 142, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632921366348-6too', 'bv1-m4', 'Hur fortsätter a. basilaris efter att ha bildats?', 'A. basilaris löper uppåt och förgrenar sig till ett kärl på vardera sidan, a. cerebri posterior.', 143, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632921443895-1c4e', 'bv1-m4', 'Hur löper a. cerebri posterior efter avgreningen från a. basilaris?', 'De två a. cerebri posterior böjer sig bakåt och löper tillbaka mot den bakre delen av hjärnan.', 144, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632921789755-36kw', 'bv1-m4', 'Vilka två huvudstrukturer försörjs av a. cerebri posterior?', 'A. cerebri posterior försörjer occipitalloben och thalamus.', 145, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632921970008-balf', 'bv1-m4', 'Vad kallas nätverket av sammankopplade stora hjärnkärl och vad förbinder dem?', 'De stora kärlen förbinds av mindre kommunikanter och bildar tillsammans circulus Willisi.', 146, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632922010189-9u3f', 'bv1-m4', 'Vad är kommunikanter i hjärnans kärlsystem?', 'Små kärl som kopplar ihop de stora hjärnkärlen och ingår i circulus Willisi.', 147, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632922065732-hs51', 'bv1-m4', 'Vilken funktion har kommunikanserna i circulus Willisi?', 'Om ett stort kärl täpps till, t.ex. a. carotis interna, kan blod omdirigeras från övriga kärl för att kompensera.', 148, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632922596491-ft1l', 'bv1-m4', 'I vilka tre funktionella delar kan en neuron delas in?', 'Mottagande del, fortledande del och överförande del.', 149, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632922627826-pqyh', 'bv1-m4', 'Vilka strukturer utgör neuronets mottagande del?', 'Cellkroppen med cellkärna samt dendriterna.', 150, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1632922658280-5236', 'bv1-m4', 'Vilka strukturer ingår i neuronets fortledande del?', 'Axonet med myelinskida och ranviers noder.', 151, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
