INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv1-m5-c1', 'bv1-m5', 'Vad skiljer inflammation från infektion?', 'Inflammation är kroppens ospecifika reaktion (rodnad, värme, svullnad, smärta, funktionsnedsättning) och kan uppstå utan mikroorganismer; infektion kräver en mikroorganism.', 1, 'kapitel')
