  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv1-m5-c2', 'bv1-m5', 'Vilka celler presenterar antigen på HLA klass I respektive klass II?', 'HLA klass I finns på alla kärnförande celler och presenteras för cytotoxiska CD8+ T-celler. HLA klass II finns på antigenpresenterande celler (dendritceller, makrofager, B-celler) och presenteras för CD4+ hjälp-T-celler.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv1-m5-c3', 'bv1-m5', 'Vad menas med etiologi och patogenes?', 'Etiologi = orsaken till sjukdomen (t.ex. mutation, infektion). Patogenes = mekanismen bakom hur sjukdomen utvecklas.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv1-m5-c4', 'bv1-m5', 'Vad är skillnaden mellan farmakokinetik och farmakodynamik?', 'Farmakokinetik = vad kroppen gör med läkemedlet (ADME). Farmakodynamik = vad läkemedlet gör med kroppen (verkningsmekanism, dos–respons).', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
