  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633531668496-r6z7', 'bv1-m5', 'Vad är Helicobacter pylori?', 'En bakterie som följt människan genom evolutionen men hos en liten del orsakar magsår eller magcancer.', 40, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633531711008-xf0x', 'bv1-m5', 'Vad är Plasmodium falciparum?', 'En parasit som orsakar malaria och sprids via mygga som vektor.', 41, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633531889224-cov6', 'bv1-m5', 'Varför kan mikroorganismer orsaka sjukdom?', 'Patogena/virulenta mikroorganismer orsakar sjukdom; viktiga virulensfaktorer är toxiner och adhesionsfaktorer.', 42, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633532100165-4ozn', 'bv1-m5', 'Vilka typer av smittvägar finns det?', 'Kontaktsmitta (direkt/indirekt), luftburen smitta/droppsmitta, sexuellt överförd smitta och blodsmitta.', 43, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633532294747-x65d', 'bv1-m5', 'Hur bidrar adhesionsfaktorer till mikroorganismers patogenicitet?', 'Adhesionsfaktorer låter mikroorganismer fästa vid endotel- eller epitelceller, t.ex. i tarmen, så att de inte spolas bort och kan kolonisera området. Var de fäster kan också avgöra var sjukdomen uppstår.', 44, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633532322518-vvig', 'bv1-m5', 'Vad är ett toxin?', 'En virulensfaktor hos patogener som skadar celler.', 45, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633532383190-c82a', 'bv1-m5', 'Hur påverkar ett toxin sin målcell?', 'Toxinet påverkar eller skadar specifika mekanismer i specifika målceller, t.ex. för att skaffa näring eller gynna patogenen.', 46, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633532767015-qgfx', 'bv1-m5', 'Vad betyder immunologi?', 'Läran om immunförsvaret, dess reaktion på smittämnen och vad som händer när immunsystemet inte fungerar som det ska.', 47, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633532822975-4wt1', 'bv1-m5', 'Vad är inflammation?', 'En reaktion där kroppens immunförsvar svarar på en skada eller ett angrepp; infektion är den vanligaste orsaken.', 48, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633532878898-yp1t', 'bv1-m5', 'Vad är en infektion?', 'Tillståndet när kroppen angrips av ett smittämne, t.ex. bakterier, virus eller svamp.', 49, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633532899056-egic', 'bv1-m5', 'Vilka är de vanligaste smittämnena?', 'Bakterier, virus och svamp.', 50, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633533165584-fjw7', 'bv1-m5', 'Vilka komponenter ingår i det medfödda försvaret?', 'Granulocyter (neutrofiler, eosinofiler, basofiler), monocyter/makrofager, dendritiska celler, NK-celler, mastceller och cytokiner.', 51, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633533301058-uxs7', 'bv1-m5', 'Vilka komponenter ingår i det yttre försvaret?', 'Hud med antimikrobiella peptider, saliv och tårar med antimikrobiella egenskaper, slemmhinnor med flimmerhår samt magsaft med lågt pH och nedbrytande enzymer.', 52, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633533361399-bias', 'bv1-m5', 'Vilka celler ingår i det medfödda försvaret?', 'Granulocyter (neutrofiler, eosinofiler, basofiler), monocyter/makrofager, dendritiska celler och NK-celler.', 53, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633533430799-4c0c', 'bv1-m5', 'Vad kännetecknar det medfödda immunförsvaret?', 'Det är medfött, ospecifikt och aktiveras omedelbart vid infektion. Det svarar snabbare än det adaptiva försvaret.', 54, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633533458102-kohr', 'bv1-m5', 'Vilka delar består det medfödda försvaret av?', 'Det består av både ett yttre försvar (barriärer) och ett inre försvar.', 55, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633533500769-tcso', 'bv1-m5', 'Vad aktiverar det adaptiva immunförsvaret?', 'Det aktiveras av det medfödda försvaret efter att detta reagerat på en infektion.', 56, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633533586094-gawu', 'bv1-m5', 'Vad kännetecknar det adaptiva immunförsvaret?', 'Det är specifikt mot patogenen, måste utvecklas och tar längre tid att verka än det medfödda försvaret.', 57, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633533635238-s3xf', 'bv1-m5', 'Vad förmedlar det adaptiva immunförsvaret?', 'Det förmedlas av lymfocyter och innefattar bildande av antikroppar och aktiverade lymfocyter som angriper en specifik patogen.', 58, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633533693994-cyy0', 'bv1-m5', 'Vad är det adaptiva immunförsvarets särskilda egenskap?', 'Förmågan att känna igen och reagera specifikt mot främmande makromolekyler, så kallade antigen.', 59, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633533765061-2b9k', 'bv1-m5', 'Vilka celltyper ingår i det adaptiva immunförsvaret?', 'Lymfocyter: T-celler (hjälparceller och cytotoxiska mördarceller) samt B-celler (plasmaceller och minnesceller).', 60, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633533808392-q6m3', 'bv1-m5', 'Vad är B-cellernas funktion?', 'B-celler differentieras till plasmaceller som producerar antikroppar.', 61, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633533854006-q011', 'bv1-m5', 'Vad är T-cellernas funktion?', 'T-celler inducerar celldöd i infekterade celler och signalerar till andra delar av immunförsvaret.', 62, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633533960494-627v', 'bv1-m5', 'Vad är komplementsystemet?', 'Ett system av proteiner som länkar samman delar av immunförsvaret, bland annat genom att underlätta fagocytos av mikroorganismer.', 63, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633534052699-652t', 'bv1-m5', 'Vad gör aktiverade komplementproteiner?', 'Aktiverade komplementproteiner kan aktivera makrofager via ytreceptorer, vilka i sin tur kan aktivera det adaptiva immunförsvaret så att mikroorganismen elimineras.', 64, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633534196871-7xn5', 'bv1-m5', 'Vad är ett antigen?', 'Ett antigen är ett ämne som är främmande för kroppen och framkallar en immunreaktion, t.ex. bakterier, virus eller svamp. Det kan också vara en molekyl på en cells yta som T-celler reagerar på.', 65, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633534439390-1m39', 'bv1-m5', 'Vilka huvudsakliga skillnader finns mellan det medfödda och det adaptiva immunförsvaret?', 'Det medfödda immunförsvaret är snabbt, aktiveras omedelbart och är generellt. Det adaptiva immunförsvaret är långsammare (timmar till veckor), specifikt, har minne och inkluderar lymfocyter och antikroppar.', 66, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633534763296-ecr5', 'bv1-m5', 'Vilken typ av receptorer använder det medfödda immunförsvaret för att känna igen mikroorganismer?', 'Det medfödda immunförsvaret använder pattern recognition receptors (PRRs) som är kodade i genomet och känner igen evolutionärt bevarade molekylära mönster hos patogener, så kallade pathogen associated molecular patterns (PAMPs). Dessa uttrycks aldrig av kroppens egna celler och orsakar därför inte autoimmuna reaktioner.', 67, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633534790186-ye8t', 'bv1-m5', 'Vilket immunförsvar ligger bakom autoimmuna sjukdomar?', 'Autoimmuna sjukdomar orsakas av det adaptiva immunförsvaret, särskilt T-celler.', 68, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633535014898-3rws', 'bv1-m5', 'Vad är HLA-molekyler?', 'HLA (human leukocyte antigen) är en grupp proteiner som hjälper immunsystemet att identifiera kroppens egna celler och skilja dem från främmande. HLA är människans histokompatibilitetskomplex (MHC).', 69, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633535511758-vs7z', 'bv1-m5', 'Vad är HLA-molekylers funktion i förhållande till T-celler?', 'HLA-molekyler presenterar slumpmässigt producerade och utvalda peptider för T-celler. Immunförsvaret läser kontinuerligt av alla HLA-komplex i kroppen, och vid upptäckt av främmande antigen bundet till HLA initieras ett immunförsvar.', 70, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633535687876-cakj', 'bv1-m5', 'Vilka två klasser av HLA-molekyler finns det och var uttrycks de?', 'HLA klass I finns på alla kärnbärande celler (vanliga celler). HLA klass II finns på antigenpresenterande celler som B-celler, dendritiska celler och makrofager.', 71, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633535801058-xc4h', 'bv1-m5', 'Var finns HLA-molekyler?', 'HLA-molekyler finns på cellytan hos alla celler med cellkärna i kroppen och presenterar där antigen för T-celler att inspektera.', 72, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633536139806-6wuz', 'bv1-m5', 'Hur bildas B- och T-cellsreceptorer?', 'Varje adaptiv immuncell har en unik receptor som skapas utan genetisk mall genom DNA-rekombination. Processen är densamma för B- och T-celler: DNA rekombineras två gånger per cell, vilket ger unika receptorer på grund av de många enskilda rekombinationerna, följt av transkription, splicing och translation.', 73, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633536201193-ztc1', 'bv1-m5', 'Var bildas lymfocyter och var mognar T- respektive B-celler?', 'Lymfocyter bildas i benmärgen. T-celler mognar i thymus och B-celler i den röda benmärgen.', 74, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633536251688-koot', 'bv1-m5', 'Vilken funktion har thymus för T-cellerna?', 'I thymus mognar T-cellerna genom en selektiv process där de måste godkännas innan de släpps ut i kroppen.', 75, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633536440184-tudd', 'bv1-m5', 'Vad innebär den selektiva mognaden av T-celler i thymus?', 'T-cellerna måste lära sig känna igen eget HLA bundet till antigen. T-celler som attackerar kroppseget HLA godkänns inte, eftersom de annars kan ge autoimmun sjukdom.', 76, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633536458076-fja6', 'bv1-m5', 'Vad aktiveras i lymfknutorna?', 'Lymfocyter aktiveras i lymfknutorna.', 77, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633536606992-01wa', 'bv1-m5', 'Hur kan autoimmuna sjukdomar uppstå?', 'T-celler kan missta kroppseget HLA för patogent och attackera kroppsegna celler. Det kan också ske om ett patogent protein liknar ett kroppseget och immunförsvaret därmed attackerar kroppseget.', 78, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633536955902-q094', 'bv1-m5', 'Varför tar det tid innan det adaptiva immunförsvaret blir effektivt?', 'Det bygger på igenkänning av främmande antigen och måste aktiveras och mogna innan det blir effektivt. Minnesceller mot en angripare bildas först efter att kroppen utsatts för antigenet.', 79, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633537164689-dtfc', 'bv1-m5', 'Vad är immunologiskt minne?', 'Efter genomgången infektion kommer kroppen ihåg organismen. Immunförsvaret kan då reagera snabbare och effektivare mot antigenet, så infektionen går över snabbare.', 80, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633537210402-wqww', 'bv1-m5', 'Vilket försvar har immunologiskt minne?', 'Det adaptiva immunförsvaret.', 81, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633543902089-eibo', 'bv1-m5', 'Vilken immuncell är effektiv mot extracellulära organismer?', 'B-celler, via antikroppar.', 82, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633543929342-s8t2', 'bv1-m5', 'Vilken immuncell är effektiv mot intracellulära organismer?', 'Cytotoxiska T-celler (mördarceller).', 83, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633544080776-eyfj', 'bv1-m5', 'Vad är ett vaccin?', 'Ett läkemedel som ger immunitet mot en patogen genom att utnyttja immunförsvarets minnesfunktion. Man tillför fragment av döda eller försvagade virus/bakterier så att immunförsvaret bildar antikroppar och minnesceller mot antigenen.', 84, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633544162388-esga', 'bv1-m5', 'Vad kännetecknar en autoimmun sjukdom?', 'Immunförsvaret reagerar på kroppens egna celler som om de vore främmande och attackerar dem. Det leder till att cellernas funktion går förlorad.', 85, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633544204783-13qm', 'bv1-m5', 'Till följd av vad kan en autoimmun sjukdom uppstå?', 'Den kan uppstå till följd av sjukdom eller behandling, till exempel cancerbehandling.', 86, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633544240302-groi', 'bv1-m5', 'Vilken funktion hos immunsystemet utnyttjar vaccin?', 'Minnesfunktionen hos B-lymfocyter (minnesceller).', 87, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633544315317-hn8o', 'bv1-m5', 'Ge exempel på autoimmuna sjukdomar.', 'Multipel skleros, psoriasis, Crohns sjukdom, typ 1-diabetes och reumatoid artrit.', 88, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633544381554-6vkl', 'bv1-m5', 'Vad sker i kroppen vid en autoimmun sjukdom?', 'Immunförsvaret förväxlar kroppsegna strukturer med främmande och attackerar de egna cellerna. Cellernas funktion försvinner i takt med att de förstörs.', 89, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633546126827-dhsd', 'bv1-m5', 'Vilken ytterligare analys kompletterar numera den mikroskopiska undersökningen i screeningprogrammet för livmoderhalscancer?', 'HPV-analys, som kan göras på egenprovtaget prov som skickas till laboratorium för analys.', 90, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633546490951-c92s', 'bv1-m5', 'Vad är skillnaden mellan infektion och inflammation?', 'En infektion uppstår när kroppen angrips av ett kroppsfrämmande ämne; inflammationen är kroppens svar på infektionen.', 91, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633546684228-dcyo', 'bv1-m5', 'Vilka organ ingår i det medfödda respektive det adaptiva immunförsvaret?', 'Medfödda: hud, magsäck, mjälte och benmärg. Adaptiva: benmärg och thymus.', 92, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633546888252-5063', 'bv1-m5', 'Vilka delar av immunförsvaret är viktiga vid bakteriella infektioner respektive virusinfektioner?', 'Bakterier: lymfocyter, dendritiska celler, makrofager, neutrofiler, eosinofiler och NK-celler. Virus: lymfocyter, dendritiska celler, makrofager och NK-celler.', 93, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633554499920-8u66', 'bv1-m5', 'Vad innebär immunitet?', 'Immunitet är egenskapen att inte vara mottaglig för infektion av en viss patogen, såsom virus, bakterier eller eukaryota organismer.', 94, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633554650467-i02x', 'bv1-m5', 'Vilka fem klassiska tecken ses vid inflammation?', 'Rodnad, svullnad, smärta, lokal värmeökning och nedsatt funktion.', 95, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633554750688-lxqp', 'bv1-m5', 'Från vilka celler utvecklas leukocyter?', 'Leukocyter utvecklas från stamceller i benmärgen.', 96, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633554770616-jhiv', 'bv1-m5', 'Vad är leukocyter?', 'Leukocyter är vita blodkroppar.', 97, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633554869253-73tm', 'bv1-m5', 'I vilka två huvudkategorier delas leukocyter in efter ursprung?', 'Leukocyter med myeloidt ursprung och leukocyter med lymfoidt ursprung.', 98, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633554957615-60xq', 'bv1-m5', 'Vilka leukocyter har myeloidt ursprung?', 'Granulocyter, monocyter, makrofager och NK-celler – celler i det medfödda immunförsvaret.', 99, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633555016151-k31o', 'bv1-m5', 'Vilka leukocyter har lymfoidt ursprung?', 'T-celler och B-celler, som ingår i det adaptiva immunförsvaret.', 100, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633555191892-46sc', 'bv1-m5', 'Vad gör komplementsystemet?', 'Komplementproteiner aktiveras i kaskader och bildar porer i bakteriemembran, vilket leder till lys av bakterien.', 101, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633555247866-tuwa', 'bv1-m5', 'Hur stor andel av leukocyterna utgör det medfödda respektive det adaptiva försvaret?', 'Det medfödda försvaret utgör cirka 50–60 % av leukocyterna och det adaptiva cirka 30–40 %.', 102, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633555288964-2xow', 'bv1-m5', 'Till vilket immunförsvar hör komplementsystemet?', 'Komplementsystemet tillhör det medfödda, ospecifika immunförsvaret.', 103, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633555339592-91y0', 'bv1-m5', 'Vilka organ är viktiga för immunförsvaret?', 'Mjälten, thymus och lymfknutarna är viktiga organ för immunförsvaret.', 104, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633555405731-lbf8', 'bv1-m5', 'Hur lång tid tar aktiveringen av det medfödda respektive det adaptiva immunförsvaret?', 'Det medfödda försvaret aktiveras inom minuter till timmar, medan det adaptiva tar dagar till veckor.', 105, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633555653866-4b3v', 'bv1-m5', 'Vilka immunceller riktar sig mot extracellulära respektive intracellulära infektioner?', 'B-celler och antikroppar riktar sig mot extracellulära infektioner och hjälper komplementsystemet. T-celler, bland annat mördar-T-celler, riktar sig mot intracellulära infektioner genom att känna igen infekterade celler via HLA.', 106, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633555925144-htiy', 'bv1-m5', 'Hur samarbetar det medfödda och det adaptiva immunförsvaret?', 'De är beroende av varandra; dendritiska celler presenterar antigener för T-celler, som sedan aktiveras i lymfknutor och kan döda virusinfekterade celler.', 107, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633556048434-vv0l', 'bv1-m5', 'Vad gör cytokiner?', 'Cytokiner påverkar utmognad och aktivering av immunceller.', 108, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633556072626-th6g', 'bv1-m5', 'Vad är patogenicitet?', 'Patogenicitet är förmågan att orsaka sjukdom.', 109, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633556112656-oq8n', 'bv1-m5', 'Vad kallas sjukdomsframkallande mikroorganismer?', 'De kallas patogena eller virulenta.', 110, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633556173511-llka', 'bv1-m5', 'Vad kännetecknar patogena bakterier?', 'Patogena bakterier har eller har förvärvat virulensfaktorer som gör att de kan ge upphov till sjukdom.', 111, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633556224157-4jp9', 'bv1-m5', 'Vad menas med virulensfaktorer?', 'Virulensfaktorer är de gener och motsvarande proteiner eller strukturer som gör en mikroorganism sjukdomsframkallande.', 112, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633556325909-5vpu', 'bv1-m5', 'Vilka två viktiga grupper av virulensfaktorer finns?', 'Toxiner (gifter) och adhesionsfaktorer, som fäster mikroorganismen vid cellen.', 113, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633556431548-k25t', 'bv1-m5', 'Vad är virulens?', 'Virulens är ett mått på hur aggressiv eller sjukdomsframkallande en mikroorganism är för sin värd (patogenpotential). Patogena mikroorganismer växer på bekostnad av värdens vävnads- eller organfunktion.', 114, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633556502948-r7si', 'bv1-m5', 'Vad är en virulensfaktor?', 'En virulensfaktor är en egenskap hos mikroorganismen som bidrar till dess sjukdomsframkallande förmåga. En mikroorganism kan ha en eller flera virulensfaktorer.', 115, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633556658610-770h', 'bv1-m5', 'Vad är patogenicitetsöar?', 'Hos bakterier kan gener som uttrycker virulensfaktorer vara organiserade i patogenicitetsöar. Virulens är ett koordinerat genuttryck som initieras av yttre stimuli som signalerar rätt miljö, t.ex. pH och temperatur.', 116, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633556751736-5d6j', 'bv1-m5', 'Hur sker kontaktsmitta?', 'Direkt kontaktsmitta sker via hudinfektion utan mellanled. Indirekt kontaktsmitta sker via hud, slemhinnor eller ytor.', 117, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633556850108-273a', 'bv1-m5', 'Hur sker luftburen smitta?', 'Droppsmitta från luftvägssekret har 0,5–2 m räckvidd och smittar direkt genom inhalation eller som droppkontaktsmitta via händer till ögon eller näsa. Smitta kan också spridas med luftströmmar.', 118, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633556959191-kml4', 'bv1-m5', 'Vilka smittvägar finns in i kroppen?', 'Intag, inhalation, insektsbett och sexuell överföring.', 119, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633557032826-vvwu', 'bv1-m5', 'Vilka värd- och mikroorganismfaktorer påverkar risken för infektion?', 'Immunstatus, var infektionen sker, trauma/sår, främmande kropp, typ och mängd av infekterande mikroorganism samt om det är en opportunistisk mikroorganism.', 120, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633557084667-dn9i', 'bv1-m5', 'Vad är en opportunistisk mikroorganism?', 'En normalt ofarlig eller kommensal mikroorganism som drar nytta av tillstånd som gör värden känslig och då orsakar skada.', 121, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633557170380-6wgs', 'bv1-m5', 'Vad är adhesionsfaktorer och vad har de för funktion?', 'Molekyler på mikroorganismens yta som specifikt binder receptorer på värdens epitel- eller endotelceller. Det gör att mikroorganismen inte sköljs bort och kan kolonisera vävnaden.', 122, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633557310849-kwfz', 'bv1-m5', 'Ge exempel på fem vanliga patogena organismer.', 'Helicobacter pylori, Streptococcus pneumoniae, Escherichia coli, humant papillomvirus (HPV) och Plasmodium falciparum.', 123, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633589601005-gwvr', 'bv1-m5', 'Vad är immunförsvaret översiktligt?', 'Ett nätverk av celler, vävnader och organ som koordinerar kroppens försvar mot hot mot hälsan. Utan det skulle även en vanlig förkylning eller ett sår kunna vara dödligt.', 124, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633589672545-u1a4', 'bv1-m5', 'Hur många vita blodkroppar finns normalt per ml blod?', 'Cirka 4 000–11 000 leukocyter per ml blod.', 125, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633589725171-c9j6', 'bv1-m5', 'Var bildas leukocyter och var mognar T-celler?', 'Leukocyter produceras i benmärgen och migrerar sedan till blod och lymfsystem. T-celler migrerar till thymus för att mogna.', 126, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633589751493-l64w', 'bv1-m5', 'I vilka två huvudgrupper delas leukocyter?', 'Fagocyter och lymfocyter.', 127, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633589860178-pynk', 'bv1-m5', 'Vad är fagocyters huvudsakliga funktion?', 'De tar upp och destruerar kroppsfrämmande ämnen genom fagocytos. De bidrar också till att trigga immunresponsen.', 128, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633589952036-0mcm', 'bv1-m5', 'Hur förmedlar fagocyter information om antigen till lymfocyterna?', 'Fagocyten identifierar antigen hos det upptagna ämnet och presenterar denna information för lymfocyter, vilket aktiverar den adaptiva immunresponsen.', 129, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633590019722-vvsp', 'bv1-m5', 'Vad gör T-celler generellt?', 'De identifierar celler som infekterats av kroppsfrämmande ämnen och dödar dem, bland annat genom att inducera apoptos.', 130, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633590175467-p3xe', 'bv1-m5', 'Vad bildar B-celler efter aktivering av hjälpar-T-celler?', 'B-celler aktiveras med hjälp av hjälpar-T-celler och differentierar till plasmaceller som producerar antigenspecifika antikroppar. Antikropparna binder specifikt till antigenet enligt ''lock and key''-principen.', 131, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633590260562-06xj', 'bv1-m5', 'Vad är plasmacellers huvudsakliga funktion?', 'Plasmaceller är differentierade B-celler som producerar stora mängder antikroppar. Antikropparna cirkulerar i kroppen och binder till angripare.', 132, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633590305526-kfms', 'bv1-m5', 'Vilka två huvudsakliga processer bidrar till immunresponsen vid inflammation?', 'Feber (temperaturhöjning) och svullnad.', 133, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633590363482-omaz', 'bv1-m5', 'Hur hjälper feber immunförsvaret?', 'En högre kroppstemperatur försvårar för bakterier och virus att föröka sig och sprida sig, eftersom de är temperatursensitiva.', 134, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633590439914-ohhk', 'bv1-m5', 'Hur bidrar svullnad till immunresponsen?', 'Svullnad attraherar fagocyter som tar hand om antigener och skadade celler.', 135, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633590466788-wgv6', 'bv1-m5', 'Hur uppstår svullnad vid vävnadsskada?', 'Skadade celler utsöndrar kemiska mediatorer som gör att vätska läcker ut i omgivande vävnad, vilket ger svullnad.', 136, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633590567074-k36f', 'bv1-m5', 'Vad är immunresponsens huvudsakliga uppgift?', 'Att hindra kroppsfrämmande ämnen från att nå farligt höga nivåer i kroppen. Immunresponsen har inte till uppgift att alltid förhindra att man blir sjuk.', 137, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633590716423-sw1u', 'bv1-m5', 'Hur uppstår långtidsimmunitet?', 'När B- och T-celler bekämpat ett antigen kan de bevara information om det och känna igen angriparen vid ett senare tillfälle. Vid återkomst kan motsvarande antikroppar snabbt bildas innan hotet hinner skada fler celler.', 138, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633590765449-yqcx', 'bv1-m5', 'Ungefär hur många förkylningar bekämpar immunförsvaret under en livstid?', 'Cirka 300 stycken.', 139, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633590821991-hi0r', 'bv1-m5', 'Hur skyddar huden som barriär mot patogener?', 'Huden utgör ett skyddande lager som hindrar ämnen från att tränga in i kroppen och producerar dessutom vissa antimikrobiella ämnen.', 140, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633590861307-kp7g', 'bv1-m5', 'Hur skyddar tårar och saliv mot infektioner?', 'De innehåller ämnen som dödar bakterier. Tårar sköljer dessutom bort främmande partiklar från hornhinnan.', 141, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633590918348-j1hk', 'bv1-m5', 'Hur skyddar magens saltsyra mot infektioner?', 'Saltsyran har lågt pH och dödar många bakterier som kommer in via maten. Den innehåller även vissa antimikrobiella ämnen.', 142, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633590998145-i778', 'bv1-m5', 'Hur skyddar slemhinnor och flimmerhår luftvägarna?', 'Näsans slemhinna har små hår som fångar upp partiklar ur inandningsluften. I luftstrupe och luftrör transporterar flimmerhår bort slem och partiklar.', 143, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633591189558-qfq8', 'bv1-m5', 'Vilka funktioner har immunförsvaret utöver att bekämpa infektioner?', 'Immunförsvaret lagar skador, tar hand om restprodukter och städar upp i vävnader.', 144, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633591242169-n737', 'bv1-m5', 'Vilka delar ingår i immunförsvaret?', 'Vita blodkroppar, andra celltyper, blodet, lymfan, lymfknutar, mjälten och thymus.', 145, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633591311252-5miz', 'bv1-m5', 'Hur kan epitelceller bidra till immunförsvaret?', 'Epitelceller i lungor, tarmar och vävnader kan reagera på virusinfektion genom att signalera fara och kalla på hjälp.', 146, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633591335876-ztql', 'bv1-m5', 'Vilken roll har blodet i immunförsvaret?', 'Blodet transporterar vita blodkroppar.', 147, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633591363129-srxe', 'bv1-m5', 'Vilken roll har lymfan i immunförsvaret?', 'Lymfan är en vätska i lymfkärlen som transporterar vita blodkroppar.', 148, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633591395966-nli2', 'bv1-m5', 'Vilken roll har lymfkörtlarna i immunförsvaret?', 'Lymfkörtlarna ingår i lymfsystemet och innehåller många vita blodkroppar.', 149, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633591431216-wo16', 'bv1-m5', 'Vilken roll har mjälten i immunförsvaret?', 'Mjälten är ett organ som innehåller många vita blodkroppar.', 150, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633591474013-s6eh', 'bv1-m5', 'Vilken funktion har thymus i immunförsvaret?', 'I thymus mognar T-lymfocyter, en typ av vita blodkroppar. Thymus kallas också brässen och ligger under bröstbenet.', 151, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633591594892-r8e7', 'bv1-m5', 'Vad är antigener och vad används de till i immunförsvaret?', 'Antigener är ämnen på cellers yta som immunförsvaret känner igen, ofta presenterade i HLA-molekyler. De avgör om en cell tillhör kroppen eller är främmande.', 152, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633591653648-brgf', 'bv1-m5', 'Vilka fyra typer av immunreaktioner finns?', 'Försvar via inflammation, via antikroppar, via mördarceller och via storätande celler.', 153, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633591738578-qexi', 'bv1-m5', 'Vad kan utlösa en inflammation?', 'Inflammation är en reaktion på skada eller angrepp, t.ex. infektion, muskelöverbelastning eller hudskada.', 154, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633591917545-t9h7', 'bv1-m5', 'Vad händer i vävnaden vid en inflammation?', 'Skadade celler frisätter kemiska ämnen som ökar vätskeutträdet i vävnaden och lockar dit vita blodkroppar. Ökad blodtillströmning ger värme och svullnad.', 155, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633592012336-amag', 'bv1-m5', 'Vad består var av?', 'Var består av döda neutrofila granulocyter, döda bakterier och nedbruten vävnad. Var bildas i infekterade sår som en del av försvaret och läkningen.', 156, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633592138595-unv7', 'bv1-m5', 'Varför går immunförsvaret snabbare vid en andra exponering för samma antigen?', 'Vid första exponeringen tar det tid att bilda tillräckligt med antikroppar. Vid ny attack av samma typ går det snabbare tack vare minnesceller.', 157, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633592261639-gq02', 'bv1-m5', 'Hur aktiveras B-celler att bilda antikroppar?', 'B-celler bildar antikroppar mot ett visst ämne. När ett främmande protein, t.ex. från en bakterie, binder in sätts en process igång där B-celler bildar antikroppar mot det.', 158, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633592330724-cvkn', 'bv1-m5', 'Vad är minnesceller?', 'Minnesceller är B-celler som kommer ihåg en tidigare inkräktare och snabbt kan bilda nya antikroppar om samma virus eller bakterie återkommer.', 159, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1633592362294-pul2', 'bv1-m5', 'Vad är antikroppar?', 'Antikroppar är proteiner som immunförsvaret använder för att bekämpa främmande ämnen.', 160, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m1-c1', 'bv2-m1', 'Vilka faser har cellcykeln och var sitter kontrollpunkterna?', 'G1 → S (DNA-replikation) → G2 → M (mitos). Kontrollpunkter vid G1/S och G2/M; CDK–cyklinkomplex driver övergångarna.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m1-c2', 'bv2-m1', 'Vad gör DNA-polymeras på ledande respektive sackande strängen?', 'Ledande strängen kopieras kontinuerligt i 5''→3''; sackande strängen kopieras i Okazaki-fragment som sedan fogas ihop av DNA-ligas.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m1-c3', 'bv2-m1', 'Vad är epigenetik?', 'Ärftliga förändringar i genuttryck utan ändrad DNA-sekvens – t.ex. DNA-metylering och histonmodifieringar (acetylering, metylering).', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m1-c4', 'bv2-m1', 'Vad skiljer apoptos från nekros?', 'Apoptos är programmerad, ATP-krävande celldöd utan inflammation (kaspaser). Nekros är passiv celldöd med svullnad, läckage och inflammation.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635183758562-137j', 'bv2-m1', 'Vad orsakar genetiska sjukdomar?', 'Genetiska sjukdomar orsakas helt eller delvis av mutationer, det vill säga förändringar i arvsmassan.', 5, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635183816164-isrc', 'bv2-m1', 'När är en genetisk sjukdom ärftlig?', 'En genetisk sjukdom är ärftlig om den orsakande mutationen finns i föräldrarnas könsceller och därmed kan föras vidare till avkomman.', 6, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635183890534-lk6g', 'bv2-m1', 'Vad avgör vilka symtom en genetisk sjukdom ger?', 'Symtomen beror på vilken funktion det muterade proteinet har och var i kroppen det är aktivt.', 7, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184001934-01sf', 'bv2-m1', 'Är alla genetiska sjukdomar ärftliga?', 'Nej. Vissa är helt ärftliga, de flesta är delvis ärftliga, och mutationer kan också uppstå under livet i somatiska celler.', 8, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184034286-72o1', 'bv2-m1', 'Vad innebär det att en genetisk sjukdom är delvis ärftlig?', 'Att sjukdomen uppstår i ett samspel mellan genetiska faktorer och miljöfaktorer.', 9, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184088778-21iy', 'bv2-m1', 'Hur begränsas effekten av en somatisk mutation?', 'Effekten begränsas ofta till enstaka vävnader eller organ, till exempel vid vissa former av cancer.', 10, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184150568-dmw5', 'bv2-m1', 'Vilka huvudgrupper av genetiska sjukdomar finns?', 'Monogena, polygena, multifaktoriella, mitokondriella sjukdomar, kromosomavvikelser samt förvärvade/icke-ärftliga sjukdomar.', 11, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184188000-lqda', 'bv2-m1', 'Vad orsakar monogena sjukdomar?', 'Monogena sjukdomar orsakas av mutationer i en enda gen.', 12, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184259959-25f2', 'bv2-m1', 'Vad orsakar polygena sjukdomar?', 'Polygena sjukdomar orsakas av mutationer i flera gener och kan dessutom vara multifaktoriella.', 13, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184292402-cn7v', 'bv2-m1', 'Vad menas med en multifaktoriell sjukdom?', 'En sjukdom som påverkas av både ärftliga riskfaktorer och miljöfaktorer.', 14, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184327220-62k0', 'bv2-m1', 'Vad orsakar mitokondriella sjukdomar?', 'De orsakas oftast av mutationer i gener som finns i mitokondriens eget DNA.', 15, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184351609-ljux', 'bv2-m1', 'Vad kännetecknar mitokondriella sjukdomar?', 'De kännetecknas av att mitokondriernas funktion störs.', 16, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184387528-2lxx', 'bv2-m1', 'Vad orsakar kromosomavvikelser?', 'De uppkommer till följd av mutationer som involverar hela eller delar av kromosomer.', 17, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184444763-9cz8', 'bv2-m1', 'Vad kallas sjukdomar som orsakas av mutationer uppkomna under livet i somatiska celler?', 'De kallas förvärvade eller icke-ärftliga sjukdomar.', 18, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184512919-cmrf', 'bv2-m1', 'Vad kännetecknar monogena sjukdomar?', 'De orsakas av mutationer i en enda gen, är generellt ovanliga och ofta allvarliga.', 19, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184532180-gqwx', 'bv2-m1', 'Vilken grupp av sjukdomar är särskilt i fokus vid utveckling av genterapier?', 'Monogena sjukdomar.', 20, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184616005-z3oj', 'bv2-m1', 'Vad innebär det att nedärvningsmönstret syns tydligt vid en monogen sjukdom?', 'Att man kan förutspå risken för att ett barn ärver en förälders sjukdom.', 21, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184656837-cskw', 'bv2-m1', 'Hur delas monogena sjukdomar upp utifrån nedärvningsmönster?', 'I dominanta och recessiva sjukdomar.', 22, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184733186-hmu4', 'bv2-m1', 'Vad krävs för att en person ska utveckla en recessiv sjukdom?', 'Mutationen måste finnas på båda kromosomerna, som ärvts från vardera förälder.', 23, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184814884-83iv', 'bv2-m1', 'Vad kallas en person som ärvt en recessiv mutation från endast en förälder?', 'En frisk bärare – bäraren utvecklar inte sjukdomen men kan föra mutationen vidare till nästa generation.', 24, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184859945-zaku', 'bv2-m1', 'Vad krävs för att en dominant sjukdom ska manifesteras?', 'Det räcker med en muterad allel på en kromosom, nedärvd från en förälder.', 25, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184929615-1sf6', 'bv2-m1', 'Hur kan monogena sjukdomar delas in efter kromosomtyp?', 'De delas in i autosomala eller X-bundna beroende på vilken kromosom mutationen finns på.', 26, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635184975877-0y9o', 'bv2-m1', 'Vad kallas de 44 kromosomerna som inte är könskromosomer?', 'De kallas autosomala kromosomer. Könskromosomerna är X och Y.', 27, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635185032698-cksi', 'bv2-m1', 'Varför talar man oftast om X-bundna och inte Y-bundna sjukdomar?', 'Y-kromosomen har få gener och mycket få genetiska sjukdomar är kopplade till den.', 28, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635185074283-8nwh', 'bv2-m1', 'Vad är genterapi ett hopp om för vilken typ av sjukdomar?', 'Främst för monogena sjukdomar finns hopp om att genterapi ska kunna användas som behandlingsform.', 29, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635185136833-uf90', 'bv2-m1', 'Hur går genterapi till?', 'En frisk genkopia förs in i patientens celler för att ersätta den genkopia som bär den sjukdomsalstrande mutationen.', 30, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635185191498-zsi6', 'bv2-m1', 'Vilken sjukdom har godkänd genterapi som behandlingsform?', 'Muskeldystrofi är ett exempel där genterapi redan är godkänd.', 31, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635185235005-rlp0', 'bv2-m1', 'Ge tre exempel på monogena sjukdomar.', 'Sicklecellanemi, hemofili A och B samt tibial muskeldystrofi.', 32, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635185337481-94g5', 'bv2-m1', 'Vilken typ av sjukdom är sicklecellanemi och vad orsakar den?', 'Sicklecellanemi är en autosomalt recessiv sjukdom som orsakas av en mutation i betaglobingenen HBB på kromosom 11.', 33, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635185375031-5d6o', 'bv2-m1', 'Vad är betaglobin?', 'Betaglobin är en viktig beståndsdel av hemoglobin, som ansvarar för syretransporten i de röda blodkropparna.', 34, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635185535010-o022', 'bv2-m1', 'Vad leder mutationen i betaglobingenen till vid sicklecellanemi?', 'Felaktigt hemoglobin bildas som polymeriserar och gör att de röda blodkropparna sicklar (deformeras) och får kortare livstid. Blodet rinner långsammare, kärl täpps till och ger syrebrist som orsakar symtom som akut smärta, bensår, njurskada samt blodproppar och blödningar i hjärnan.', 35, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635185681704-7ic5', 'bv2-m1', 'Vilka behandlingsprinciper finns vid sicklecellanemi?', 'Smärtförebyggande åtgärder och i vissa fall stamcellstransplantation. Genterapi prövas kliniskt, bl.a. med CRISPR/Cas9, där stamceller redigeras att bilda fetalt hemoglobin (2 alfa, 2 gamma) som kompenserar bristen på fungerande vuxet hemoglobin.', 36, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635185741313-h0bk', 'bv2-m1', 'Vilka två former av blödarsjuka finns och vilken typ av sjukdom är de?', 'Hemofili A och hemofili B. Båda är X-bundna recessiva monogena sjukdomar.', 37, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635185828541-5uv2', 'bv2-m1', 'Vilka gener är muterade vid hemofili A respektive B?', 'Hemofili A orsakas av mutation i F8 och hemofili B av mutation i F9. Båda generna ligger på X-kromosomen och kodar för koagulationsfaktorer som behövs för att blodet ska koagulera.', 38, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635185886628-wlij', 'bv2-m1', 'Varför drabbas i stort sett bara män av hemofili?', 'Män har bara en X-kromosom och saknar därmed en frisk genkopia. Kvinnor med två X-kromosomer har oftast en frisk kopia som gör att koagulationsfaktorerna tillverkas normalt.', 39, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635185935275-wetg', 'bv2-m1', 'Vilket nedärvningsmönster har hemofili?', 'X-bundet recessivt nedärvningsmönster.', 40, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635186127634-pvyp', 'bv2-m1', 'Hur yttrar sig medelsvår till svår hemofili?', 'Blödningar uppstår lätt i leder och muskler, till synes spontant eller efter mindre skada, och är ofta mycket smärtsamma. Utan förebyggande behandling ger de bestående förändringar i ledkapsel, ledbrosk och ben med funktionsnedsättning och kronisk smärta.', 41, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635186260730-8ypx', 'bv2-m1', 'Hur behandlas hemofili idag?', 'Barn behandlas från tidig ålder med injektioner av koncentrat av den saknade koagulationsfaktorn, flera gånger i veckan, vilket förebygger ledskador och förbättrar livskvaliteten. Genterapier med införande av en fungerande F8- eller F9-gen prövas kliniskt.', 42, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635186489858-41pw', 'bv2-m1', 'Vad orsakar en multifaktoriell sjukdom?', 'Flera genetiska riskfaktorer i samspel med miljöfaktorer.', 43, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635186530474-cjpy', 'bv2-m1', 'Vad är typiskt för nedärvningen vid multifaktoriella sjukdomar?', 'Sjukdomen "ligger i släkten" men saknar ett tydligt nedärvningsmönster.', 44, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635186570756-jk86', 'bv2-m1', 'Vilken sjukdomsgrupp tillhör folksjukdomar som åldersdiabetes och högt blodtryck?', 'Multifaktoriella sjukdomar.', 45, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635186709360-h44u', 'bv2-m1', 'Varför talar man om genetiska riskfaktorer snarare än mutationer vid multifaktoriella sjukdomar?', 'Varje riskfaktor medför bara en liten ökad risk för sjukdomen; det handlar om ärftlig benägenhet, inte en sjukdomsalstrande mutation.', 46, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635186748439-cr32', 'bv2-m1', 'Hur påverkas risken för en multifaktoriell sjukdom av sjukdom hos nära släkting?', 'Risken att drabbas ökar om en nära släkting är sjuk.', 47, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635186901322-vk2r', 'bv2-m1', 'Vilken roll spelar livsstilsfaktorer vid multifaktoriella sjukdomar?', 'Kost, motion, infektioner, rökning och alkohol påverkar om sjukdomen bryter ut; vissa livsstilsfaktorer kan ha skyddande effekt och motverka den ärftliga benägenheten.', 48, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635186943870-nb9o', 'bv2-m1', 'Ge tre exempel på multifaktoriella sjukdomar.', 'Bröstcancer, Alzheimers sjukdom och åldersdiabetes.', 49, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635187011821-y0el', 'bv2-m1', 'Vilka gener utgör de största genetiska riskfaktorerna för bröstcancer?', 'BRCA1 och BRCA2.', 50, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635187077755-pnui', 'bv2-m1', 'Varför analyserar man BRCA1 och BRCA2?', 'För riskbedömning hos en frisk person eller för att välja behandling hos en sjuk.', 51, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635187136283-j9gc', 'bv2-m1', 'Vad talar för förhöjd risk att drabbas av bröstcancer?', 'Om flera kvinnliga släktingar drabbats av bröstcancer före 50 års ålder är risken förhöjd.', 52, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635187243997-zo3y', 'bv2-m1', 'Vilket samband finns mellan bröstcancer och andra gynekologiska cancersjukdomar i släkten?', 'Gemensamma genetiska riskfaktorer gör att risken för bröstcancer ökar om en nära släkting tidigt insjuknat i äggstocks- eller äggledarcancer.', 53, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635187325430-56w7', 'bv2-m1', 'Vilka livsstils- och hormonfaktorer ökar risken för bröstcancer?', 'Övervikt och fetma efter klimakteriet ökar risken. Lång menstruationstid ökar risken, medan tidigt barnafödande verkar ha viss skyddande effekt.', 54, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635187384054-8eb6', 'bv2-m1', 'I vilka två kategorier delas Alzheimers sjukdom in?', 'I en ärftlig och en sporadisk form.', 55, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635187427567-i8vy', 'bv2-m1', 'Vad kännetecknar den ärftliga formen av Alzheimers sjukdom?', 'Den är ovanlig och debuterar tidigt, före 50 års ålder.', 56, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635187451434-7jr7', 'bv2-m1', 'Vad kännetecknar den sporadiska formen av Alzheimers sjukdom?', 'Den är starkt kopplad till hög ålder.', 57, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635187711118-ioqf', 'bv2-m1', 'Vilka är de tidiga symtomen vid Alzheimers sjukdom?', 'Tidiga symtom är minnesförlust. Senare tillkommer tilltagande problem med språk och motorik.', 58, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635188854706-2qep', 'bv2-m1', 'Vilka gener ger mutationer som alltid leder till Alzheimers sjukdom?', 'Ovanliga mutationer i APP, presenilin 1 och presenilin 2 leder alltid till Alzheimers sjukdom.', 59, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635188914325-opoj', 'bv2-m1', 'Vilka livsstilsfaktorer är kopplade till sporadisk Alzheimers sjukdom?', 'Rökning, högt blodtryck, högt kolesterolvärde samt fetma och diabetes i medelåldern.', 60, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635189290053-pmt5', 'bv2-m1', 'Vad är en centromer?', 'Den centrala punkten på kromosomen där de båda systerkromatiderna hänger samman.', 61, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635189347783-pi9m', 'bv2-m1', 'Vad är telomerer?', 'De distala ändarna på kromosomen som skyddar den mot att uppfattas som ett DNA-brott.', 62, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635189491949-5k3q', 'bv2-m1', 'Vad är en replikationsstart (origin of replication)?', 'En specifik DNA-sekvens där DNA-replikationen initieras och fortsätter bidirektionellt.', 63, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635189535494-0luf', 'bv2-m1', 'Vilka faser ingår i interfasen?', 'G1-, S- och G2-faserna.', 64, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635189967949-1ol3', 'bv2-m1', 'Hur är cellkärnan organiserad?', 'Cellkärnan omges av en dubbelmembran med kärnpårer som reglerar transport av proteiner och RNA.', 65, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635190011262-8q9w', 'bv2-m1', 'Vad är det humana genomet?', 'Två uppsättningar kromosomer, 2x23 par, en från vardera föräldern.', 66, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635190054093-kazz', 'bv2-m1', 'I vilket tillstånd är kromosomerna strax före celldelning?', 'De är kondenserade strax före celldelning.', 67, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635191176203-71nl', 'bv2-m1', 'I vilket tillstånd är kromosomerna utanför M-fasen?', 'De är i form av löst packat kromatin, men behåller sina egna kromosomterritorier i kärnan.', 68, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635191377694-ccyw', 'bv2-m1', 'Vilka strukturer är viktiga för en kromosoms replikation och segregation?', 'Telomerer, centromerer och replikationsstartpunkter.', 69, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635191437478-781c', 'bv2-m1', 'Vad är telomerer och vilken funktion har de?', 'Telomerer är ändarna på kromosomerna och skyddar dem från att uppfattas som DNA-brott, vilket annars kan utlösa apoptos.', 70, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635191537822-bw4m', 'bv2-m1', 'Vad är centromerer och vad är de nödvändiga för?', 'Centromerer är regioner på kromosomen där systerkromatiderna hålls samman och där spindelapparaten fäster. De är avgörande för korrekt kromosomsegregation under mitos.', 71, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635191660062-4s52', 'bv2-m1', 'Vad är replikationsorigor?', 'Specifika ställen på kromosomen där DNA-replikationen startar. Varje kromosom har många origor så att replikationen kan ske tillräckligt snabbt.', 72, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635191759505-ff0d', 'bv2-m1', 'Vad är cellcykelns övergripande syfte?', 'Att duplicera cellens innehåll och dela upp det i två dotterceller.', 73, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635191808145-0lg9', 'bv2-m1', 'Vad är avgörande för en korrekt cellcykel?', 'Att alla kromosomer dupliceras så att varje dottercell får samma genetiska information.', 74, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635191890878-yrvx', 'bv2-m1', 'Vad får en cell att gå in i cellcykeln?', 'Många celler delar sig inte normalt utan börjar först när de exponeras för en signal som kallas mitogen, vilken binder till cellytan och säger att cellen får inträda i cellcykeln.', 75, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635191932726-lehs', 'bv2-m1', 'Vad är mitogener och vad gör de?', 'Mitogener är signaler som binder till cellytan och talar om för cellen att den får inträda i cellcykeln och duplicera sig.', 76, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635191954967-yy66', 'bv2-m1', 'Vad kallas duplicering av en kromosom?', 'Replikation.', 77, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635191975356-kl2f', 'bv2-m1', 'Hur lång är en typisk mänsklig cellcykel?', 'Cirka 24 timmar.', 78, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192038795-4ohq', 'bv2-m1', 'Vilka två huvudfaser delas cellcykeln in i och vad händer i dem?', 'Interfasen, där cellen växer och duplicerar sina kromosomer och förbereder sig för mitos, samt M-fasen (mitosen), där cellen delar sig.', 79, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192089954-ds4j', 'bv2-m1', 'Vad står G för i cellcykelns fasbeteckningar?', 'G står för gap (engelska för lucka/mellanrum).', 80, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192110297-19fl', 'bv2-m1', 'Vad står S för i cellcykeln?', 'S står för synthesis (DNA-syntes).', 81, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192132152-zf8q', 'bv2-m1', 'Vad sker i G1-fasen?', 'Cellen växer och förbereder sig inför DNA-syntesen.', 82, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192160156-ck54', 'bv2-m1', 'Vad sker i S-fasen?', 'DNA replikeras så att kromosomerna dupliceras.', 83, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192209566-c0y1', 'bv2-m1', 'Vad sker i G2-fasen?', 'Cellen kontrollerar att allt DNA har duplicerats korrekt inför mitosen.', 84, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192246051-t2cb', 'bv2-m1', 'Vad kännetecknar G0-fasen?', 'G0 är den fas de flesta celler stannar i när mitogen saknas; cellen är då inte i aktiv delning.', 85, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192307905-64h4', 'bv2-m1', 'Vad sker i M-fasen?', 'Mitosen äger rum: systerkromatider segregerar och cellen delas i två dotterceller.', 86, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192322982-far4', 'bv2-m1', 'Vad är CDK?', 'CDK står för cyclin-dependent kinase, ett enzym som reglerar cellcykeln.', 87, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192418123-f88q', 'bv2-m1', 'Hur varierar CDK-aktiviteten under cellcykeln?', 'Låg aktivitet vid start av replikationen, hög aktivitet vid mitosens start och ingen aktivitet efter mitosen.', 88, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192475397-ll8g', 'bv2-m1', 'Vad gör CDK (cyklinberoende kinas)?', 'CDK fosforylerar andra proteiner, vilket ändrar deras aktivitet.', 89, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192520528-iivx', 'bv2-m1', 'Vad krävs för att CDK ska bli aktivt?', 'CDK måste binda till cyklin för att bli aktivt. Aktivt CDK fosforylerar tusentals proteiner i cellen.', 90, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192561742-u96z', 'bv2-m1', 'Hur regleras cyklinnivåerna?', 'Cyklinnivåerna regleras genom produktion och nedbrytning.', 91, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192612602-5idw', 'bv2-m1', 'Vilken roll har cyklin i cellcykeln?', 'Cyklin säkerställer att cellcykeln går i en riktning. G1-cyklin ökar transkriptionen och M-cyklin ökar proteolysen.', 92, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192657615-r710', 'bv2-m1', 'Vad är syftet med mitosen?', 'Att separera kromosomerna och bilda två dotterceller.', 93, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192723852-9uu8', 'bv2-m1', 'Vad gör CDK i profasen?', 'CDK-aktivitet leder till att mikrotubuli organiseras från två poler (centrioler) och att DNA-kondensation initieras.', 94, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192806662-988b', 'bv2-m1', 'Vad gör CDK i prometafasen?', 'CDK-aktivitet leder till att kärnmembranet bryts ned och att mikrotubuli fäster vid kromosomernas centromerer. Systerkromatiderna hålls samman så att mikrotubuli vet vad de ska dra i.', 95, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192852743-4vl4', 'bv2-m1', 'Vilka faser kan mitosen delas in i?', 'Profas, prometafas, metafas, anafas, telofas och cytokinas.', 96, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192926695-oymi', 'bv2-m1', 'Vad gör CDK i metafasen?', 'CDK-aktivitet leder till att kromosomerna trycks och dras till cellens centrum av mikrotubuli (metafasplattan). När alla kromosomer är fästa vid mikrotubuli från två håll degraderas M-fascykliner.', 97, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635192976920-pvbg', 'bv2-m1', 'När och i vilken fas degraderas M-fascykliner?', 'I metafasen av mitosen, när alla kromosomer är fästa vid mikrotubuli från två håll.', 98, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193036710-ljls', 'bv2-m1', 'Vad händer i anafasen när CDK-aktiviteten upphör?', 'Avsaknad av CDK leder till nedbrytning av kohesinkomplexet som håller systerkromatiderna samman, varefter kromosomerna dras mot cellens två poler.', 99, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193095182-dnqd', 'bv2-m1', 'I vilka faser av M-fasen är CDK-aktiviteten hög respektive frånvarande?', 'CDK-aktivitet finns i profas, prometafas och metafas. CDK-aktiviteten är frånvarande i anafas, telofas och cytokinas.', 100, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193126653-1vg1', 'bv2-m1', 'Vilket proteinkomplex håller systerkromatiderna samman?', 'Kohesinkomplexet (cohesin) håller systerkromatiderna samman.', 101, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193171316-uriz', 'bv2-m1', 'Vad utlöser avsaknaden av CDK i telofasen?', 'Avsaknad av CDK gör att kromosomerna når polerna och att kontraktila proteiner (aktin och myosin) snörar åt cellen på mitten.', 102, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193198635-g0w3', 'bv2-m1', 'Vilka kontraktila proteiner driver insnörningen i telofasen?', 'Aktin och myosin.', 103, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193275102-ojlv', 'bv2-m1', 'Vad säkerställer avsaknaden av CDK-aktivitet i cytokinasen?', 'En kontraktil proteinring delar cellen på mitten, vilket ger två dotterceller med genetiskt material identiskt med modercellen.', 104, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193320781-zxfb', 'bv2-m1', 'Vad innebär cellcykelkontroll?', 'Kontrollpunkter verifierar att föregående steg är slutfört och att förutsättningarna är uppfyllda innan cellcykeln fortsätter.', 105, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193404323-isac', 'bv2-m1', 'Var i cellcykeln finns kontrollpunkterna och vad kontrolleras vid varje?', 'G1-kontrollen (restriktionspunkten) startar cellcykeln, G2-kontrollen verifierar att allt DNA är replikerat och att kromosomerna är oskadade, och M-kontrollen verifierar att alla kromosomer är fästa vid mitotiska spolen.', 106, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193456370-en2d', 'bv2-m1', 'Vad kontrolleras vid G1-kontrollpunkten?', 'Det är en restriktionspunkt där cellcykeln startar, bland annat genom närvaro av mitogen.', 107, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193473346-yqe4', 'bv2-m1', 'Vad kontrolleras vid G2-kontrollpunkten?', 'Att allt DNA är replikerat och att kromosomerna inte är skadade.', 108, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193490571-t3wc', 'bv2-m1', 'Vad kontrolleras i mitotiska spindelkontrollpunkten?', 'Att alla kromosomer är korrekt fästa vid den mitotiska spindeln innan anafas inleds.', 109, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193525354-87oj', 'bv2-m1', 'Vad innebär DNA-replikation?', 'DNA dupliceras i en semikonservativ process inför celldelning.', 110, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193613400-0aez', 'bv2-m1', 'Vad menas med att DNA-replikation är semikonservativ?', 'Varje ny DNA-molekyl består av en gammal (parental) sträng och en nysyntetiserad sträng. En dubbelhelix blir två.', 111, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193649249-zd0b', 'bv2-m1', 'I vilken fas av cellcykeln sker DNA-replikationen?', 'I S-fasen, som i humana celler varar cirka 8 timmar.', 112, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193667992-d99v', 'bv2-m1', 'Hur lång är S-fasen i humana celler?', 'Cirka 8 timmar.', 113, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635193698627-b2yq', 'bv2-m1', 'I vilken riktning syntetiseras nytt DNA?', 'Från 5''-änden mot 3''-änden (5''→3'').', 114, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635194065611-kehr', 'bv2-m1', 'Hur inleds DNA-replikationen?', 'Helikas vecklar upp dubbelhelixen vid replikationsgaffeln och bildar en replikationsbubbla. Replikationen startar vid ursprungsställen (origins of replication).', 115, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635194678052-era3', 'bv2-m1', 'Varifrån kommer energin som används vid DNA-replikation?', 'Från nukleotidens trifosfatgrupp.', 116, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635194777425-7xd2', 'bv2-m1', 'Vad krävs innan DNA-polymeras kan påbörja syntesen?', 'En primer – en kort RNA-sträng som läggs ut av primas och fungerar som startpunkt.', 117, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635194854487-pdbk', 'bv2-m1', 'Vad händer efter att RNA-primern lagts ut på ledande strängen?', 'DNA-polymeras fyller på med nukleotider i 5''→3''-riktning genom basparning, så att ledande strängen förlängs kontinuerligt.', 118, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635195208707-rh55', 'bv2-m1', 'Hur replikeras den släpande strängen?', 'Eftersom den släpande strängen löper 3''→5'' sker syntesen i korta bitar: RNA-primas lägger primrar och DNA-polymeras fyller på i 5''→3'' mellan dessa, vilket bildar Okazaki-fragment.', 119, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635195328139-3ivs', 'bv2-m1', 'Vilket enzym katalyserar det sista steget i replikationen?', 'DNA-ligas katalyserar det sista steget och sammanfogar Okazaki-fragmenten till en sammanhängande sträng.', 120, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635195389528-laom', 'bv2-m1', 'Varför avlägsnas RNA-primern efter replikationen?', 'Primern tas bort för att undvika inblandning av RNA i DNA:t och för att förhindra basparningsfel.', 121, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635195452250-4rwh', 'bv2-m1', 'Var startar replikationen på DNA och hur avslutas den?', 'Replikationen startar vid många replikationsorigo och avslutas när replikationsbubblorna smälter samman.', 122, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635195563866-faql', 'bv2-m1', 'Hur löses 5''→3''-problemet på den släpande strängen?', 'RNA-primas bildar primrar, DNA-polymeras syntetiserar Okazaki-fragment, RNA tas bort och ersätts med DNA, och DNA-ligas sammanfogar fragmenten.', 123, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635195596814-gx3k', 'bv2-m1', 'Vad är Okazaki-fragment?', 'De DNA-fragment som DNA-polymeras bildar mellan RNA-primrarna på den släpande strängen.', 124, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635195765674-3ajb', 'bv2-m1', 'Hur går replikationen av den ledande strängen till sammanfattningsvis?', 'Prereplikationskomplexet binder till origo, helicas öppnar DNA:t, primas lägger en primer och DNA-polymeras förlänger kontinuerligt i 5''→3''-riktning tills replikationsgafflarna möts.', 125, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635195874555-ra5r', 'bv2-m1', 'Vilken korrekturläsningsfunktion har DNA-polymeras?', 'DNA-polymeras har exonukleasaktivitet som tar bort felaktigt inbyggda nukleotider i 3''→5''-riktning, varefter syntesen kan fortsätta.', 126, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635195936014-rlgg', 'bv2-m1', 'Vilka funktioner har DNA-polymeras i respektive riktning?', 'I 5''→3''-riktning bygger polymeraset in nukleotider; i 3''→5''-riktning avlägsnar dess exonukleasaktivitet felaktiga nukleotider.', 127, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635195978109-koz6', 'bv2-m1', 'Hur många mutationer uppstår ungefär per replikationsomgång?', 'Ungefär en mutation per 10^9 nukleotider.', 128, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196003967-fzv9', 'bv2-m1', 'Hur många nukleotider består det mänskliga genomet av?', '3,2 × 10^9 nukleotider.', 129, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196041367-o3g1', 'bv2-m1', 'Vilket problem uppstår vid replikering av telomererna?', 'Det finns ingen plats för RNA-primern, så kopian förlängs inte fullt ut.', 130, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196098342-3h1k', 'bv2-m1', 'Hur löses telomerproblemet?', 'Med telomeras, som är uppbyggt av aminosyror och har en bunden RNA-molekyl som används som primer för att fylla i den sista biten av kromosomen.', 131, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196176189-kbt9', 'bv2-m1', 'Vilka celler har telomeras?', 'Inte alla celler har telomeras, vilket innebär att en bit av telomeren försvinner vid varje cellcykel. När tillräckligt mycket av telomeren har försvunnit induceras apoptos, så celler kan bara replikera cirka 100 gånger.', 132, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196216504-t41n', 'bv2-m1', 'Hur många gånger kan DNA replikeras i normala celler och varför?', 'Cirka 100 gånger innan apoptos, eftersom för mycket av telomeren har försvunnit på grund av brist på telomeras i cellen.', 133, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196282108-8jku', 'bv2-m1', 'I vilka celler finns telomeras?', 'I oocyter, spermier och stamceller, där man vill ha fulla telomerer. Ibland finns telomeras även i cancerceller.', 134, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196354492-5fbh', 'bv2-m1', 'Vad är lösningen på telomerproblemet?', 'Enzymet telomeras som förlänger template-strängen för lagging strand genom att tillverka DNA med hjälp av en RNA-bit inbyggd i enzymet, vilket skapar en sekvens för en primer.', 135, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196445934-ay1m', 'bv2-m1', 'Beskriv telomeras funktion i detalj.', '1. Telomeras binder till template-strängen. 2. Telomeras adderar telomerupprepningar till template-strängen (RNA-templerad DNA-syntes). 3. DNA-polymeras fullbordar lagging strand (DNA-templerad DNA-syntes).', 136, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196495929-sa9b', 'bv2-m1', 'Vad händer om telomeras saknas?', 'Kromosomerna förkortas vid varje cellcykel.', 137, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196569161-xkzb', 'bv2-m1', 'Varför delar sig de flesta celler bara cirka 100 gånger?', 'Utan telomeras kortas kromosomerna vid varje celldelning. Efter cirka 100 delningar induceras apoptos, vilket förhindrar tumörutveckling.', 138, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196598052-xkoy', 'bv2-m1', 'Vilka celler har hög telomerasaktivitet?', 'Könsceller och stamceller, som behöver kunna dela sig många gånger.', 139, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196687190-i2ou', 'bv2-m1', 'Vad är problemet med torsionsstress vid replikation?', 'Övervridning av DNA framför replikationsgaffeln kan blockera gaffeln om den inte avlägsnas.', 140, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196716541-tpt2', 'bv2-m1', 'Vid brist på vilket enzym byggs torsionsstress upp?', 'Vid brist på topoisomeras.', 141, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196796558-veqh', 'bv2-m1', 'Hur löser topoisomeras torsionsstress?', 'Enzymet klyver DNA:t, håller kvar vid brottet och återförsluter det efter att vridningen relaxerats.', 142, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196842271-tje7', 'bv2-m1', 'Vilken typ av brott skapar topoisomeras?', 'Ett tillfälligt enkelsträngsbrott i DNA.', 143, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635196937211-ncc2', 'bv2-m1', 'Vad möjliggör topoisomerasets enkelsträngsbrott?', 'Fri rotation av dubbelhelixen kring fosfodiesterbindningen, vilket relaxerar torsionsstress framför helikas; därefter försluts brottet.', 144, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635197051510-qna3', 'bv2-m1', 'Varför är topoisomeras viktigt inom cancerbehandling?', 'Topoisomerashämmare låser enzymet efter att det skapat ett DNA-brott, vilket dödar snabbt delande celler som cancerceller.', 145, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635197170423-9mxc', 'bv2-m1', 'Vilka huvudtyper av DNA-reparation finns?', 'Bland annat mismatch-reparation, bas-excision, enkelsträngsbrottsreparation och nukleotid-excision.', 146, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635197197959-7rvc', 'bv2-m1', 'Vilken process liknar "remove and fill in"-reparation?', 'Mognad av Okazaki-fragment.', 147, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635197268336-1pfm', 'bv2-m1', 'Vilka enzymer ingår i remove-and-fill-in-repair?', 'Nukleas och glykosylas avlägsnar den skadade delen. DNA-polymeras fyller i och DNA-ligas förseglar strängen.', 148, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635197306326-g02s', 'bv2-m1', 'Varför behövs DNA-reparation?', 'Utan korrekturläsning och reparation ackumuleras mutationer, vilket kan leda till tumörer. Reparation skyddar mot mutationer och sker kontinuerligt i celler.', 149, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635197350356-wzqo', 'bv2-m1', 'Vad händer om DNA inte repareras?', 'DNA-sekvensen förändras permanent (mutation). Om mutationen påverkar en gen kan proteinets funktion försämras, vilket kan orsaka sjukdom som cancer.', 150, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635197528547-9y1t', 'bv2-m1', 'Vad innebär en mutation i somatiska celler?', 'Den är inte ärftlig och påverkar endast individen.', 151, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635197550771-78dd', 'bv2-m1', 'Vad innebär en mutation i könsceller?', 'Den ärvs vidare till nästa generation.', 152, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635197633173-4z4r', 'bv2-m1', 'Hur fungerar mismatch repair?', 'Nukleas avlägsnar den felaktigt parade basen och ersätter den med korrekt bas, med föräldrasträngen som mall. Man kan skilja strängarna åt eftersom föräldrasträngens backben skiljer sig.', 153, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635197682227-06vc', 'bv2-m1', 'Hur kan föräldra- och dottersträngar skiljas vid DNA-reparation?', 'Föräldrasträngen har ett annat utseende på backbenet.', 154, 'anki-ai')
