INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635197763412-xzcb', 'bv2-m1', 'Hur fungerar base excision repair?', 'Glykosylas avlägsnar den skadade basen och nukleas klipper DNA-backbenet. DNA-polymeras fyller i och DNA-ligas förseglar.', 155, 'anki-ai')
