INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635197913408-49j7', 'bv2-m1', 'Hur repareras solskadat DNA?', 'Via nucleotide excision repair: nukleaser klipper och degraderar den skadade DNA-strängen, DNA-polymeras fyller i och DNA-ligas förseglar.', 157, 'anki-ai')
