INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635197977737-vxbs', 'bv2-m1', 'Vad reparerar homolog rekombination?', 'DNA-dubbelsträngsbrott. Reparationen sker med en oskadad systerkromatid som mall och blir exakt, utan förlust av nukleotider.', 158, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635198130612-szgg', 'bv2-m1', 'Vad är skillnaden mellan homolog rekombination och end joining?', 'Homolog rekombination kräver en oskadad systerkromatid som mall och ger exakt reparation. End joining fogar ihop de två brutna ändarna direkt, vilket ger viss förlust av nukleotider.', 159, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635198152155-u954', 'bv2-m1', 'När kan homolog rekombination respektive end joining användas?', 'Båda används vid dubbelsträngsbrott, t.ex. vid replikation av enkelsträngsbrott eller efter gammastrålning.', 160, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m2-c1', 'bv2-m2', 'Vilka tre komponenter bygger cellskelettet?', 'Mikrofilament (aktin) – form och rörelse; intermediärfilament (keratin, vimentin) – mekanisk styrka; mikrotubuli (tubulin) – transport och celldelning.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m2-c2', 'bv2-m2', 'Vilka är de viktigaste komponenterna i extracellulär matrix?', 'Kollagen (styrka), elastin (elasticitet), proteoglykaner och glykoproteiner (t.ex. fibronektin) samt bindvävsceller som fibroblaster.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m2-c3', 'bv2-m2', 'Vad skiljer passiv från aktiv transport över membranet?', 'Passiv transport följer gradienten utan energi (diffusion, facilitetad diffusion, osmos). Aktiv transport går mot gradienten och kräver ATP (primär) eller en jon-gradient (sekundär).', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m2-c4', 'bv2-m2', 'Vad gör lysosomen och vad händer vid defekt lysosomal funktion?', 'Lysosomen bryter ner material med sura hydrolaser. Defekter ger lysosomala lagringssjukdomar där substrat ansamlas i cellen.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635186392013-g651', 'bv2-m2', 'Vad orsakar tibial muskeldystrofi?', 'En autosomal dominant sjukdom orsakad av mutation i TTN-genen på kromosom 1, som kodar för titin. Mutationen gör att muskelfibrer inte kan förnyas normalt, vilket leder till muskelsvaghet och förtvining.', 5, 'anki-ai')
