  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635186451805-8gcm', 'bv2-m2', 'Hur vanlig är tibial muskeldystrofi i Sverige och vilket påbrå har de flesta patienter?', 'Ett hundratal personer i Sverige har sjukdomen, och de flesta har släktband till Finland där mutationen är vanligare.', 6, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
