VALUES ('anki-1635356038912-qyq3', 'bv2-m2', 'Vilken funktion har mikrotubuli?', 'De fungerar som cellens transportvägar och möjliggör intracellulär transport.', 44, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635356074826-4woj', 'bv2-m2', 'Vilken funktion har aktinfilament?', 'De är cellens muskler och är viktiga för rörelse och för att bibehålla cellformen.', 45, 'anki-ai')
