INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635356660191-scqy', 'bv2-m2', 'Vilka fyra huvudtyper av intermediära filament finns?', 'Keratinfilament, vimentin (och vimentinrelaterade) filament, neurofilament samt nukleära filament (laminer).', 51, 'anki-ai')
