  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635356672734-a0mk', 'bv2-m2', 'I vilka celler finns keratinfilament?', 'Keratinfilament finns i epitelceller.', 52, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635356735449-7rf6', 'bv2-m2', 'Var finns vimentin och vimentinrelaterade filament?', 'I bindvävsceller, muskelceller och glialceller.', 53, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635356745510-va3m', 'bv2-m2', 'I vilka celler finns neurofilament?', 'Neurofilament finns i nervceller.', 54, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635356762484-qocz', 'bv2-m2', 'Var finns nukleär lamina?', 'Nukleär lamina finns i alla djurceller, på insidan av kärnmembranen.', 55, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635357499528-x8kn', 'bv2-m2', 'Hur bildas intermediära filament från monomerer?', 'Monomerer med alfa-helikal region bildar coiled-coil-dimerer, som parar sig antiparallellt och förskjutet till tetramerer. Tetramererna associerar lateralt till rep-liknande filament med diameter ca 10 nm.', 56, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635357532575-abqa', 'bv2-m2', 'Vad håller tetramererna samman i intermediära filament?', 'Tetramererna hålls samman av jon- och van der Waals-interaktioner.', 57, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635357637622-6rce', 'bv2-m2', 'Vad består en tetramer i intermediära filament av?', 'Två coiled-coil-dimerer som ligger förskjutna och antiparallella mot varandra.', 58, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635357718798-uixk', 'bv2-m2', 'Vad är nukleär lamina?', 'Ett tätt fibrillärt nätverk under den nukleära envelopet, uppbyggt av lamin A/C och lamin B.', 59, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635357782165-4rzz', 'bv2-m2', 'Vilka funktioner har den nukleära laminan?', 'Den ger mekaniskt stöd åt nukleära strukturer och reglerar DNA-replikation och celldelning.', 60, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635357896707-lkfw', 'bv2-m2', 'Vilken roll har mikrotubuli i cellen?', 'De utgör cellens transportsystem, längs vilket organeller och vesiklar positioneras och färdas.', 61, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635357982901-4jae', 'bv2-m2', 'Vilka cellbihang bildas av mikrotubuli?', 'Stabila, rytmiskt slående cellbihang som cilia och flagella.', 62, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635358079521-lzx3', 'bv2-m2', 'Vilka funktioner har mikrotubuli?', 'De utgör maskineri för segregering av genetiskt material vid celldelning och transportvägar för organeller, makromolekyler och vesiklar.', 63, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635358203727-vva6', 'bv2-m2', 'Hur är en mikrotubulus uppbyggd?', 'Alfa- och beta-tubulin bildar heterodimerer som bildar protofilament; 13 protofilament bildar en ihålig cylinder med 25 nm diameter.', 64, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635358303263-st3u', 'bv2-m2', 'Vilken strukturell polaritet har protofilamenten i mikrotubuli?', 'Alfa-tubulin-änden är minus (-) och beta-tubulin-änden är plus (+).', 65, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635358384957-ostw', 'bv2-m2', 'Vilken laddning har alfa-tubulin-änden i en mikrotubulus?', 'Negativ (-).', 66, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635358406380-9z81', 'bv2-m2', 'Vilken laddning har beta-tubulin-änden i en mikrotubulus?', 'Positiv (+).', 67, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635358551940-8npk', 'bv2-m2', 'Vilken typ av struktur är mikrotubuli?', 'Mikrotubuli är dynamiska strukturer som kontinuerligt växlar mellan att växa och att krympa.', 68, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635358594258-rwbt', 'bv2-m2', 'Vad menas med dynamisk instabilitet hos mikrotubuli?', 'Att mikrotubuli ständigt förändras i storlek genom att växla mellan tillväxt och krympning.', 69, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635358735355-vcls', 'bv2-m2', 'Vilken typ av enzym reglerar mikrotubulis dynamiska instabilitet?', 'GTPaser reglerar mikrotubulis dynamiska instabilitet.', 70, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635358887913-l9gn', 'bv2-m2', 'Vad innebär GTP- respektive GDP-bunden tubulin för mikrotubuli?', 'GTP-bunden tubulin främjar tillväxt, medan GDP-bunden tubulin främjar krympning.', 71, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635359011657-kkue', 'bv2-m2', 'Vilken effekt har GDP-bunden tubulin på mikrotubuli?', 'GDP destabiliserar mikrotubuli och främjar dissociation av tubulinenheterna.', 72, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635359037756-yqnc', 'bv2-m2', 'Vilken effekt har GTP-bunden tubulin på mikrotubuli?', 'GTP stabiliserar mikrotubuli och främjar addition av nya tubulindimerer.', 73, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635359115690-9pvo', 'bv2-m2', 'Vid vilken cap växer respektive krymper mikrotubulus?', 'Vid GTP-cap växer mikrotubulus, vid GDP-cap krymper det.', 74, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635359181507-myg9', 'bv2-m2', 'Hur skiljer sig ändarna på en mikrotubulus i stabilitet?', 'Ena änden består av stabila GTP-monomerer, medan resten av tubulus består av instabila GDP-monomerer.', 75, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635359377011-u8fp', 'bv2-m2', 'Hur sker tillväxt vid GTP-cap på mikrotubuli?', 'GTP-tubulindimerer läggs till snabbare än GTP hydrolyseras, så tillväxten fortsätter.', 76, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635359561827-4yf3', 'bv2-m2', 'Hur sker krympning vid GDP-änden på mikrotubuli?', 'Protofilament med GDP-tubulin skalas av från tubulusväggen och GDP-tubulin frisätts till cytosolen.', 77, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635359675472-04tb', 'bv2-m2', 'Vad bestämmer tillväxten respektive krympningen (shrinkage) av mikrotubuli?', 'Tillväxt och krympning beror på hastigheten av GTP-hydrolys samt tillgängligheten och bindningen av fria GTP-bundna tubulindimärer.', 78, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635359723595-oy9f', 'bv2-m2', 'Vad innebär selektiv stabilisering av mikrotubuli?', 'Att mikrotubuli stabiliseras genom capping-proteiner vid plusänden i vissa celldelar.', 79, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635359793583-dcx4', 'bv2-m2', 'Varför är dynamisk instabilitet (tillväxt och krympning) viktig för mikrotubuli?', 'Den snabba remodelleringen av ostabila mikrotubuli är nödvändig för deras funktion.', 80, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635359935899-84wg', 'bv2-m2', 'Vilka funktioner har mikrotubuli-associerade proteiner (MAPs)?', 'MAPs stabiliserar och destabiliserar mikrotubuli, guidar dem till specifika cellulära platser, korslänkar dem och förmedlar interaktioner med andra proteiner samt fungerar som motorproteiner.', 81, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635359987554-7u61', 'bv2-m2', 'Vad är funktionen hos mikrotubulusorganiserande center (MTOC)?', 'Mikrotubuli växer ut från MTOC, som utgör nukleationsstället för mikrotubuli.', 82, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635360047109-smea', 'bv2-m2', 'Ge tre exempel på mikrotubulusorganiserande center (MTOC).', 'Centrosom i icke-delande cell, de två polerna i en mitotisk spindel i delande cell samt basal body i cilia.', 83, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635360230511-9ay3', 'bv2-m2', 'Hur kan en mikrotubulus stabiliseras vid sin plusände?', 'Genom att plusänden fäster vid ett capping-protein eller en cellstruktur, vilket förhindrar tubulin-depolymerisation.', 84, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635360272757-iuxd', 'bv2-m2', 'Hur positioneras organeller i cellen med hjälp av mikrotubuli?', 'Genom stabilisering av mikrotubuli där plusänden fäster vid capping-proteiner eller cellstrukturer.', 85, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635360496539-uvy1', 'bv2-m2', 'Hur är en centrosom uppbyggd?', 'Två vinkelrätt orienterade centrioler omgivna av centrosommatrix (pericentriolärt material) med gamma-tubulinringar som nukleationsställen. Minusänden (alfa-tubulin) är inbäddad i centrosomen medan beta-tubulinändarna sträcker sig ut i cytoplasman.', 86, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635360586013-ur0t', 'bv2-m2', 'Hur förändras mikrotubuli vid celldelning?', 'Mikrotubuli bryts ned och byggs upp igen till mitotiska spindlar som nukleeras från de dubblerade centrosomerna.', 87, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635360626061-9ra9', 'bv2-m2', 'Vilken funktion har mitotiska spindlar?', 'De separerar systerkromatiderna till dottercellerna under mitosen.', 88, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635360693947-lfnv', 'bv2-m2', 'Hur verkar cellgifter som blockerar mikrotubuli?', 'De hämmar ombyggnaden av mikrotubuli, vilket stoppar mitosen.', 89, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
