  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635361213671-pzck', 'bv2-m2', 'Vad gör ATPas-enzymer?', 'De katalyserar hydrolys av en fosfatbindning i ATP till ADP, vilket frisätter energi.', 98, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635361252822-jqqd', 'bv2-m2', 'Hur får motorproteiner energi?', 'Genom ATP-hydrolys till ADP, katalyserad av ATPas-enzymer.', 99, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635361367614-ose6', 'bv2-m2', 'Vad kännetecknar aktinmikrofilament?', 'De är tunna och flexibla filament som bland annat avgör cellens form.', 100, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635361414847-8vg6', 'bv2-m2', 'Vad är aktinmikrofilament viktiga för vid cellytan?', 'De är essentiella för cellrörelse som involverar cellytan.', 101, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635361488311-b74x', 'bv2-m2', 'Hur är aktinmikrofilament kopplade till andra celler och till ECM?', 'De kopplas till närliggande celler via adherens junctions och till ECM via focal adhesions.', 102, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635361545053-8fmr', 'bv2-m2', 'Vilka specialiserade funktioner bidrar aktinmikrofilament till?', 'De bidrar till kontraktil funktion i muskelceller och till mikrovilli hos epitelceller.', 103, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635361587760-kafy', 'bv2-m2', 'Hur stödjer aktinmikrofilament celldelning?', 'De bildar en kontraktil ring som driver cytokinesen.', 104, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635361645688-x58q', 'bv2-m2', 'Är aktinmikrofilament stabila eller dynamiska?', 'De genomgår kontinuerlig omorganisering men finns också som mer stabila strukturer, t.ex. kontraktila buntar.', 105, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635361820874-73c7', 'bv2-m2', 'Hur är aktinmikrofilament uppbyggda?', 'Globulära aktinmonomerer polymeriserar till filament med strukturell polaritet (+ och -ände); två filament bildar en tvinnad dubbelkedja med diameter ca 7 nm, som sedan kan arrangeras i buntar, 2D-flak och 3D-nät.', 106, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635361844645-0lak', 'bv2-m2', 'Vilken enzymaktivitet har aktin?', 'Aktin är ett ATPas-enzym.', 107, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635361917844-5oyi', 'bv2-m2', 'Varför sker ATP-hydrolys vid aktinfilamentets minusände?', 'ATP-hydrolys på aktin främjar frisättningen av aktinsubenheter från filamentänden, vilket möjliggör depolymerisering.', 108, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635361994593-h66z', 'bv2-m2', 'Vad händer med aktins bundna ATP efter inkorporering i filamentet?', 'Efter inkorporering hydrolyseras aktins bundna ATP till ADP + Pi.', 109, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635362051251-hpz1', 'bv2-m2', 'Vad bestämmer tillväxt respektive krympning av ett aktinfilament?', 'Det beror på koncentrationen av fria aktinmonomerer och hastigheten av ATP-hydrolys.', 110, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635362196314-d16q', 'bv2-m2', 'Vad är treadmilling?', 'Treadmilling innebär att ena änden av ett filament växer medan den andra krymper, så att filamentet ser ut att röra sig genom cytosolen. Fenomenet ses i aktinfilament och mikrotubuli.', 111, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635362227854-9uw6', 'bv2-m2', 'Vad sker med aktinmikrofilament vid en intermediär aktinmonomerkoncentration?', 'Vid intermediär koncentration råder jämvikt mellan polymerisation och depolymerisation, vilket ger treadmilling.', 112, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635362328261-d540', 'bv2-m2', 'Vilka arrangemang kan aktinmikrofilament bilda och vad gör de?', 'Kontraktila buntar (stressfibrer) ger cellrörelse, gelnätverk i cellkortex stabiliserar cellmembranet och tighta parallella buntar bildar filopodier.', 113, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635362491750-h01t', 'bv2-m2', 'Vad gör aktinbindande proteiner (ABP)?', 'ABP reglerar aktincytoskelettet olika i olika delar av cellen genom att stabilisera filament eller monomerer, tvärbinda filament eller fungera som motorproteiner.', 114, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
