VALUES ('anki-1635366317336-21ib', 'bv2-m2', 'Vilka proteiner bygger upp adherence junctions och vad binder de?', 'De formas huvudsakligen av klassiska cadheriner som via anchorproteiner (katenin, plakoglobin) binder aktinmikrofilament. De bildar ett bälte runt cellen – zonula adherens.', 139, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635366368796-v866', 'bv2-m2', 'Vilken embryologisk funktion kan adherence junctions bidra till?', 'De kan facilitera invagination samt tub- och vesikelbildning av epitellager.', 140, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635366392369-q8yx', 'bv2-m2', 'Vad kallas desmosomer också?', 'Desmosomer kallas också spot-like junctions (macula adherens).', 141, 'anki-ai')
