  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635366480530-hhd6', 'bv2-m2', 'Vilka proteiner bygger upp desmosomer och vad binder de intracellulärt?', 'Desmosomer formas av icke-klassiska cadheriner (desmoglein, desmocollin) och binder intermediära filament (keratin, vimentin, neurofilament) via adapterproteiner (plakoglobin, plakophilin, desmoplakin).', 142, 'anki-ai')
