INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635366674740-v3g8', 'bv2-m2', 'Vilka proteiner bygger upp gap junctions och hur är de arrangerade?', 'Gap junctions formas av connexiner: sex connexiner bildar en connexon (hemichannel), och två connexoner kopplas ände-till-ände mellan grannceller.', 147, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635366697531-jpxc', 'bv2-m2', 'Vad är connexin?', 'Ett singel-pass transmembranprotein som bygger upp connexoner (gap junction-kanaler).', 148, 'anki-ai')
