  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635366833870-mc99', 'bv2-m2', 'Vad är en connexon?', 'En hemikanal (hemichannel) som består av sex connexin-subenheter arrangerade i en cylinder.', 149, 'anki-ai')
