  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635366884181-hq8n', 'bv2-m2', 'Vilken funktion har gap junctions?', 'De låter små molekyler under ca 1000 Da (joner, socker, cAMP) flöda mellan celler och ger elektrisk koppling så att celler kan agera synkroniserat.', 150, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635366949202-tlml', 'bv2-m2', 'I vilka tillstånd kan gap junctions befinna sig?', 'De kan vara öppna eller stängda, och tillståndet regleras av faktorer som dopamin, H+ och Ca2+.', 151, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635367039527-57dt', 'bv2-m2', 'Vilka faktorer reglerar om gap junctions är öppna eller stängda?', 'Bland annat dopamin, H+ och Ca2+.', 152, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635367161172-bwib', 'bv2-m2', 'Var är gap junctions elektriska koppling särskilt viktig?', 'I hjärtats kardiomyocyter, glatt muskulatur i tarmen (peristaltik), gravid livmoder (koordinerade kontraktioner vid förlossning) och i elektriska synapser i CNS.', 153, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635367200404-s36o', 'bv2-m2', 'Vilka två huvudtyper av cell–ECM-adhesionskomplex finns?', 'Hemidesmosomer och focal adhesions.', 154, 'anki-ai')
