  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635367274869-t8tb', 'bv2-m2', 'Vad gör cell–ECM-förankringskomplex?', 'De förankrar celler till specifika ECM-proteiner, huvudsakligen via integriner, och kopplar cytoskelettet till adherenspunkter via intracellulära adapterproteiner.', 155, 'anki-ai')
