INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m3-c1', 'bv2-m3', 'Vad händer under första fosterveckan?', 'Befruktning i ampullen, celldelningar (morula), blastocystbildning och implantation i endometriet runt dag 6–7.', 1, 'kapitel')
