  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m3-c2', 'bv2-m3', 'Vilka tre groddblad bildas vid gastrulationen och vad ger de upphov till?', 'Ektoderm (hud, nervsystem), mesoderm (muskel, skelett, kärl, njurar) och endoderm (tarm, lever, lungor).', 2, 'kapitel')
