  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m3-c3', 'bv2-m3', 'Vad är neurulation och när sker den?', 'Neuralrörsbildningen under vecka 3–4: neuralplattan viker sig till neuralröret som ger hjärna och ryggmärg. Bristande sluten neuralrör ger ryggmärgsbråck eller anencefali.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m3-c4', 'bv2-m3', 'Vad kännetecknar meiotisk överkorsning?', 'Homologa kromosomer byter segment i profas I (crossing-over) vilket ger nya kombinationer av alleler och genetisk variation.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
