VALUES ('anki-1635797825017-av9q', 'bv2-m3', 'Vad kännetecknar enäggstvillingar som delas mycket sent?', 'Mycket sen delning ger monokorioniska, monoamniotiska tvillingar som delar amnion, korion och placenta.', 130, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635797955425-9imb', 'bv2-m3', 'Vilka huvudhändelser sker under embryonala vecka 2?', 'Embryot blir bilaminärt (epiblast och hypoblast), implanteras helt i livmoderslemhinnan och placentabildningen börjar med lakuner som kopplas till moderns cirkulation.', 131, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635798062675-re8d', 'bv2-m3', 'Vilka huvudhändelser sker under embryonala vecka 3?', 'Gastrulering sker (bilaminärt blir trilaminärt med tre groddblad), primitivstrimma och primitivknottra bildas, samt somiter och notokord anläggs.', 132, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
