VALUES ('anki-1635798081582-2u6t', 'bv2-m3', 'Vilken struktur bildar nervsystemet under neuruleringen?', 'Notokordet (ryggsträngen) fungerar som signalcentrum och inducerar bildandet av nervsystemet under neuruleringen.', 133, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
