VALUES ('anki-1635798108590-g9p2', 'bv2-m3', 'Vad kallas ryggsträngen med ett annat namn?', 'Notokordet.', 134, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635798138607-mimt', 'bv2-m3', 'Vilken funktion har notokordet?', 'Det fungerar som signalcentrum och inducerar senare, under neuruleringen, bildandet av nervsystemet.', 135, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635798201713-61ri', 'bv2-m3', 'Vilka strukturer bildas tidigt under vecka 3?', 'Primitivstrimma, primitivknottra samt kloakmembran och buccofaryngealmembran bildas, och dorsal-ventral axel etableras.', 136, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635798230129-qap5', 'bv2-m3', 'Vad är primitivstrimman?', 'En långsträckt förtjockning på epiblastens yta där gastruleringen börjar.', 137, 'anki-ai')
