INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1637238192672-mpnm', 'bv2-m4', 'Varför förekommer inte Fischerprojektionen i naturen?', 'Fischerprojektionen är energimässigt ogynnsam och representerar inte den verkliga rymdstrukturen.', 39, 'anki-ai')
