  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1637238267606-fh77', 'bv2-m4', 'Hur beskrivs en Fischerprojektion?', 'I Fischerprojektionen är den funktionella gruppen uppåt, sidokedjorna pekar utåt åt sidorna och detta avgör D- eller L-konfigurationen.', 40, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1637238361245-3bvb', 'bv2-m4', 'Vad betecknar alfa och beta?', 'Alfa och beta betecknar olika anomerer av en sockerart.', 41, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1637238419354-t2bs', 'bv2-m4', 'Vad avgör om en anomer blir alfa eller beta?', 'Om hydroxylgruppen vid det anomera kolet hamnar på höger sida i Fischerprojektionen blir det alfa, på vänster sida beta.', 42, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1637238588864-w4y6', 'bv2-m4', 'Vad är en anomer?', 'En anomer är en stereoisomer som skiljer sig åt vid det anomera kolet.', 43, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1637238652930-wyek', 'bv2-m4', 'Vilken funktionell grupp är ofta den vid en Fischerprojektion?', 'Aldehydgruppen är ofta den funktionella gruppen i en Fischerprojektion.', 44, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1637238741841-1yw1', 'bv2-m4', 'Vilken struktur har glukos oftast?', 'Glukos är oftast ringslutet, men kan också öppna upp sig till en öppen kedja.', 45, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1637238813058-kapc', 'bv2-m4', 'Varför är en öppen aldehyd reaktiv?', 'Karbonylkolet i en öppen aldehyd är en mycket reaktiv elektrofil punkt som kan attackeras av nukleofiler.', 46, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1637238842344-axb9', 'bv2-m4', 'Vad är ringslutningen av en monosackarid ett exempel på?', 'En intramolekylär nukleofil attack på karbonylkolet, där en hydroxylgrupp bildar en hemiacetal.', 47, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1637238914380-ohub', 'bv2-m4', 'Vad bildas vid ringslutning när karbonylkolet är kol 5 i en aldohexos?', 'En sexledad pyranosring, till exempel glukopyranos.', 48, 'anki-ai')
