  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1637238962858-j06w', 'bv2-m4', 'Vilka strukturförändringar sker vid bildning av en pyranos från en öppen aldohexos?', 'Karbonylkolet blir ett nytt kiralt centrum (anomert kol) och en hemiacetal bildas. Molekylen är fortfarande en cyklisk hemiacetal, inte omättad med karboxylgrupp.', 49, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1637239025211-86nh', 'bv2-m4', 'Vad används RS-nomenklaturen till?', 'För att stereokemiskt korrekt namnge kirala centra, särskilt när en molekyl har flera kirala centra.', 50, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
