  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1637257591266-5nhh', 'bv2-m4', 'Vad menas med att keratansulfat I & II kan vara heterogena?', 'Att de kan förekomma både sulfaterade och osulfaterade.', 113, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1637257635979-l4s1', 'bv2-m4', 'Var återfinns keratansulfat I respektive II?', 'Keratansulfat I finns i cornea; keratansulfat II finns i bindväv i aggregat med kondroitinsulfat.', 114, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m5-c1', 'bv2-m5', 'Var sker glykolysen respektive oxidativ fosforylering?', 'Glykolysen i cytoplasman (netto 2 ATP + 2 NADH per glukos); oxidativ fosforylering i mitokondriens inre membran (cirka 30–32 ATP totalt).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m5-c2', 'bv2-m5', 'Vilka är de tre oåterkalleliga stegen i glykolysen och vilka enzymer katalyserar dem?', 'Hexokinas (glukos→G6P), PFK-1 (F6P→F1,6BP) och pyruvatkinas (PEP→pyruvat).', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m5-c3', 'bv2-m5', 'Vad är glukoneogenes och var sker den?', 'Nybildning av glukos från laktat, glycerol och aminosyror – framför allt i levern (och njurbarken) under fasta, reglerad av glukagon och insulin.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m5-c4', 'bv2-m5', 'Vad gör glykogenfosforylas respektive glykogensyntas?', 'Glykogenfosforylas bryter ner glykogen till glukos-1-fosfat (aktiveras av adrenalin/glukagon); glykogensyntas bygger upp glykogen (aktiveras av insulin).', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636836424678-t11a', 'bv2-m5', 'Vad står cAMP för?', 'Cykliskt adenosinmonofosfat.', 5, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-a1a750fb', 'bv2-m5', 'Var i cellen sker glykolysen och var sker glukoneogenesen?', 'Glykolysen sker i cytoplasman (cytosolen). Glukoneogenesen sker till största delen i cytoplasman och mitokondrien, huvudsakligen i lever och njurbark.', 6, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-b0462c55', 'bv2-m5', 'Vilket enzym katalyserar det hastighetsbestämmande steget i glykolysen?', 'Fosfofruktokinas-1 (PFK-1), som omvandlar fruktos-6-fosfat till fruktos-1,6-bisfosfat. Det är glykolysens viktigaste reglerande enzym.', 7, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-6483de6e', 'bv2-m5', 'Vilka två signalmolekyler aktiverar PFK-1 respektive hämmar det?', 'Aktiveras av AMP och fruktos-2,6-bisfosfat. Hämmas av ATP och citrat.', 8, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-40a300da', 'bv2-m5', 'Vilka tre irreversibla steg skiljer glykolysen från glukoneogenesen?', 'Hexokinas/glukokinas (glukos→glukos-6-fosfat), PFK-1 (fruktos-6-fosfat→fruktos-1,6-bisfosfat) och pyruvatkinas (fosfoenolpyruvat→pyruvat). Dessa kringgås av egna glukoneogenetiska enzymer.', 9, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-3a9abad8', 'bv2-m5', 'Vilket enzym katalyserar det reglerande steget i glukoneogenesen från fruktos-1,6-bisfosfat?', 'Fruktos-1,6-bisfosfatas, som hydrolyserar fruktos-1,6-bisfosfat till fruktos-6-fosfat. Det är glukoneogenens motstycke till PFK-1.', 10, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-f4def591', 'bv2-m5', 'Var i cellen sker citronsyracykeln och oxidativ fosforylering?', 'Citronsyracykeln sker i mitokondriens matrix. Oxidativ fosforylering sker vid det inre mitokondriemembranet.', 11, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-f6990609', 'bv2-m5', 'Vilket enzym katalyserar det hastighetsbestämmande steget i citronsyracykeln och vad hämmas det av?', 'Isocitratdehydrogenas, som omvandlar isocitrat till α-ketoglutarat. Det aktiveras av ADP och hämmas av ATP och NADH.', 12, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-cc58324f', 'bv2-m5', 'Vad är substratet för citronsyracykeln och vad bildas i första steget?', 'Acetyl-CoA kondenseras med oxaloacetat till citrat, katalyserat av citratsyntas. Därmed är cykeln beroende av både acetyl-CoA och oxaloacetat.', 13, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-47c0a7dc', 'bv2-m5', 'Vilken roll har NADH och FADH2 i oxidativ fosforylering?', 'De donerar elektroner till elektrontransportkedjan i det inre mitokondriemembranet. Elektronflödet driver protonpumpning och ATP-syntas producerar ATP.', 14, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-ecfc53eb', 'bv2-m5', 'Vilket enzym reglerar glykogenolysen och vilket reglerar glykogensyntesen?', 'Glykogenfosforylas klyver glykogen till glukos-1-fosfat (glykogenolys). Glykogensyntas bygger glykogen från UDP-glukos (glykogensyntes).', 15, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-c62eff91', 'bv2-m5', 'Vilken är HMP-shuntens (pentosfosfatvägens) huvudsakliga funktion?', 'Att producera NADPH för reduktiva synteser och ribos-5-fosfat för nukleotidsyntes. Den ger också metaboliter till glykolysen.', 16, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-10833af6', 'bv2-m5', 'Vilket enzym är hastighetsbestämmande i HMP-shunten och vad hämmas det av?', 'Glukos-6-fosfatdehydrogenas (G6PD), som oxiderar glukos-6-fosfat till 6-fosfoglukonolakton. Det hämmas av NADPH.', 17, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-0d6b15ba', 'bv2-m5', 'Var i cellen sker glykolysen, och vad är dess nettoutbyte per glukos?', 'I cytoplasman. Per glukos bildas 2 pyruvat, 2 ATP (netto) och 2 NADH. Reaktionerna är anaeroba.', 18, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-006798ed', 'bv2-m5', 'Vilket substrat driver glukoneogenesen från mitokondrien till cytoplasman?', 'Oxaloacetat omvandlas till malat, som lämnar mitokondrien och sedan återbildas till oxaloacetat i cytoplasman. Detta kringgår att oxaloacetat inte kan passera mitokondriemembranen.', 19, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-a7db0a22', 'bv2-m5', 'Vilka tre irreversibla enzymer i glykolysen kringgås i glukoneogenesen?', 'Hexokinas/glukokinas (kringgås av glukos-6-fosfatas), PFK-1 (av fruktos-1,6-bisfosfatas) och pyruvatkinas (via pyruvatkarboxylas och PEPCK).', 20, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-70388bef', 'bv2-m5', 'Varför kräver glukoneogenesen mer ATP än glykolysen producerar?', 'Glukoneogenesen är inte en direkt omvändning; de irreversibla stegen kringgås med energikrävande reaktioner. Netto åtgår 6 ATP-ekvivalenter per bildat glukos.', 21, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-97ec62e7', 'bv2-m5', 'Vilken roll har acetyl-CoA för pyruvatdehydrogenaskomplexet?', 'Acetyl-CoA är en allosterisk aktivator av komplexet (positiv feed-forward). Det signalerar att acetyl-CoA är rikligt och att pyruvat bör oxideras vidare.', 22, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-4fa7d5cf', 'bv2-m5', 'Vad bildas per acetyl-CoA i citronsyracykeln, och hur många gånger per glukos?', 'Per acetyl-CoA bildas 3 NADH, 1 FADH2, 1 GTP och 2 CO2. Per glukos bildas 2 acetyl-CoA, alltså två varv.', 23, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-ca62e044', 'bv2-m5', 'Vilket enzym är hastighetsbestämmande i citronsyracykeln?', 'Citratsyntas, som bildar citrat av acetyl-CoA och oxaloacetat. Det hämmas av ATP och NADH och aktiveras av ADP.', 24, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-0a27e1bf', 'bv2-m5', 'Vad är chemiosmos och var sker den?', 'Elektronöverföring i andningskedjan pumpar H+ ut i mitokondriens intermembranrum och skapar en protongradient. ATP-syntas driver ATP-bildning när H+ strömmar tillbaka till matrix.', 25, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-04c4ad60', 'bv2-m5', 'Vilket hormon aktiverar glykogenolys i levern, och via vilken intracellulär signal?', 'Glukagon höjer cAMP, vilket aktiverar proteinkinas A. PKA fosforylerar och aktiverar glykogenfosforylas samt hämmar glykogensyntas.', 26, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-c33d664a', 'bv2-m5', 'Vilket hormon främjar glykogensyntes i muskel och lever?', 'Insulin aktiverar proteinfosfataser, som defosforylerar glykogensyntas (aktiverar) och glykogenfosforylas (hämmar). Nettoeffekt: glykogenlagring.', 27, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-77d6c1d0', 'bv2-m5', 'Vad är HMP-shuntens (pentosfosfatvägens) två huvudprodukter?', 'NADPH för reduktiva synteser (t.ex. fettsyrasyntes och glutationregenerering) samt ribos-5-fosfat för nukleotidsyntes. Den är särskilt aktiv i lever, fettväv och erytrocyter.', 28, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-6ea60538', 'bv2-m5', 'Var i cellen sker glykolysen och varför just där?', 'I cytoplasman (cytosolen), eftersom alla glykolysens enzymer är cytosolära. Reaktionen kräver inget mitokondrieupptag och ger netto 2 ATP + 2 NADH per glukos.', 29, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-8a3ac598', 'bv2-m5', 'Vilka tre irreversibla enzym styr glykolysen?', 'Hexokinas (glukokinas i lever), fosfofruktokinas-1 (PFK-1) och pyruvatkinas. Dessa är de reglerande, hastighetsbestämmande stegen.', 30, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-7372b7f7', 'bv2-m5', 'Vilket enzym är det viktigaste reglerande steget i glykolysen?', 'Fosfofruktokinas-1 (PFK-1), som omvandlar fruktos-6-fosfat till fruktos-1,6-bisfosfat. Hämmas av ATP och citrat, aktiveras av AMP/ADP och fruktos-2,6-bisfosfat.', 31, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-ef03412d', 'bv2-m5', 'Vilka tre irreversibla steg skiljer glukoneogenesen från glykolysen?', 'Pyruvat→oxaloacetat (pyruvatkarboxylas), fruktos-1,6-bisfosfat→fruktos-6-fosfat (fruktos-1,6-bisfosfatas) och glukos-6-fosfat→glukos (glukos-6-fosfatas, endast i lever och njure).', 32, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-1baf70cd', 'bv2-m5', 'Var sker glukoneogenesen och vilka substrat används?', 'Huvudsakligen i lever (även njurbarken). Substrat: laktat, glycerol, aminosyror (alanin) och glukogena metaboliter. Kräver mitokondriell pyruvatkarboxylas för första steget.', 33, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-59142eae', 'bv2-m5', 'Vilket hormonellt svar aktiverar glykogenolys respektive glykogensyntes?', 'Glukagon och adrenalin aktiverar glykogenolys via cAMP→PKA→fosforylering av glykogenfosforylas. Insulin aktiverar glykogensyntes via defosforylering (aktivering av glykogensyntas).', 34, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-35dee54f', 'bv2-m5', 'Vilket enzym är hastighetsbestämmande i glykogensyntesen och hur regleras det?', 'Glykogensyntas. Aktiveras genom defosforylering (av fosfatas, insulin-driven) och hämmas genom fosforylering (PKA).', 35, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-a34a2dbc', 'bv2-m5', 'Vilket är det viktigaste reglerande enzymet i pentosfosfatvägen?', 'Glukos-6-fosfatdehydrogenas (G6PD). Det bildar NADPH; brist ger hemolys vid oxidativ stress (t.ex. primakin, bönor).', 36, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-99bb3bf4', 'bv2-m5', 'Vilket enzym saknas vid essentiell fruktosuri och vad blir följden?', 'Fruktokinas saknas, så fruktos ansamlas i blodet och utsöndras i urinen. Godartat tillstånd; fruktos kan ändå metaboliseras via hexokinas i små mängder.', 37, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-5bd95d8f', 'bv2-m5', 'Varför ger fruktos-1-fosfat ansamling vid hereditär fruktosintolerans cellskada?', 'Brist på aldolas B ger ackumulering av fruktos-1-fosfat, som hämmar glykogenolys och glukoneogenes. Följd: hypoglykemi, leverpåverkan och metabolisk kris vid fruktosintag.', 38, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-a0f7c4d9', 'bv2-m5', 'Vilket enzym är defekt vid klassisk galaktosemi och varför är det farligt?', 'Galaktos-1-fosfaturidyltransferas (GALT). Galaktos-1-fosfat ansamlas och är toxiskt för lever, njure och lins (katarakt); behandling är galaktosfri diet.', 39, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-ebe5de4a', 'bv2-m5', 'Var i cellen sker glykolysen och varför krävs ingen syre?', 'I cytoplasman (cytosolen). Glykolysen är anaerob eftersom den bara använder substratfosforylering och NAD+ som återbildas via laktat- eller alkoholjäsning när syre saknas.', 40, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-e6b77b45', 'bv2-m5', 'Vilka tre irreversibla enzym reglerar glykolysen?', 'Hexokinas (glukokinas i lever), fosfofruktokinas-1 (PFK-1) och pyruvatkinas. Dessa är de hastighetsbestämmande stegen och regleras allosteriskt och hormonellt.', 41, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-58683055', 'bv2-m5', 'Vilket är det viktigaste reglerande enzymet i glykolysen och vad aktiverar det?', 'Fosfofruktokinas-1 (PFK-1). Aktiveras av AMP, ADP och fruktos-2,6-bisfosfat; hämmas av ATP och citrat.', 42, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-0e380b96', 'bv2-m5', 'Varför är glukokinas i levern viktigt för blodglukosregleringen?', 'Glukokinas har högt Km för glukos och tar bara upp glukos när blodkoncentrationen är hög (efter måltid). Det gör levern till en glukossänka utan att konkurrera med hjärnan.', 43, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-7090d87e', 'bv2-m5', 'Var sker glukoneogenesen och varför krävs mitokondrien?', 'Huvudsakligen i lever (och njurbark). Första steget, pyruvatkarboxylas, sker i mitokondrien eftersom det kräver biotin och acetyl-CoA som allosterisk aktivator.', 44, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-1d872e99', 'bv2-m5', 'Vilken roll har acetyl-CoA i citronsyracykeln och var bildas det?', 'Acetyl-CoA är ingångssubstratet som med oxaloacetat bildar citrat via citratsyntas. Det bildas i mitokondriematrisen genom pyruvatdehydrogenas eller beta-oxidation.', 45, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-af5b7b87', 'bv2-m5', 'Vilka är citronsyracykelns huvudprodukter för energiförsörjningen?', 'Per acetyl-CoA: 3 NADH, 1 FADH2 och 1 GTP (ATP). NADH och FADH2 driver oxidativ fosforylering i elektrontransportkedjan.', 46, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-4c8059ec', 'bv2-m5', 'Vad är substratfosforylering och ge ett exempel i glykolysen?', 'ATP bildas direkt genom överföring av fosfatgrupp från ett substrat till ADP. Exempel: fosfoglyceratkinas och pyruvatkinas i glykolysen.', 47, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-efb2225e', 'bv2-m5', 'Vilket enzym är hastighetsbestämmande i glykogenolysen och vad aktiverar det?', 'Glykogenfosforylas. Aktiveras av glukagon och adrenalin via cAMP→PKA, och hämmas av glukos-6-fosfat och ATP.', 48, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-d169b11f', 'bv2-m5', 'Vilket enzym reglerar glykogensyntesen och hur regleras det?', 'Glykogensyntas. Aktiveras av insulin via defosforylering (fosfatas) och hämmas av PKA-medierad fosforylering.', 49, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m5-722610f7', 'bv2-m5', 'Vad är HMP-shuntens (pentosfosfatvägens) två huvudfunktioner?', 'Att producera NADPH för reduktiva synteser och glutation-regenerering, samt ribos-5-fosfat för nukleotidsyntes. Sker i cytoplasman.', 50, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m6-c1', 'bv2-m6', 'Vilka lipoproteiner finns och vad transporterar de?', 'Chylomikroner (kostfett), VLDL (endogent TAG), LDL (kolesterol till perifera vävnader), HDL (kolesterol tillbaka till levern).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m6-c2', 'bv2-m6', 'Vad är det hastighetsbestämmande enzymet i kolesterolsyntesen och vad hämmar det?', 'HMG-CoA-reduktas; hämmas av statiner (och av överskott av kolesterol via SREBP-reglering).', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m6-c3', 'bv2-m6', 'Vad gör karnitinshuttle-systemet?', 'Transporterar långa fettsyror in i mitokondriens matrix där beta-oxidationen sker – brist ger nedsatt energiförsörjning vid fasta (hypoglykemi, kardiomyopati).', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m6-c4', 'bv2-m6', 'Vad händer med ammoniak i aminosyrametabolismen?', 'Aminosyrornas aminosyragrupp överförs (transaminering) och ammoniak avgiftas i ureacykeln till urea i levern – urea utsöndras via njurarna.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635775026672-lt97', 'bv2-m6', 'Är alla celltyper lika drabbade vid Gauchers sjukdom?', 'Nej, endast vissa celltyper drabbas.', 5, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635775081849-uhhs', 'bv2-m6', 'Vad avgör vilka celltyper och organ som drabbas vid Gauchers sjukdom?', 'Typen av mutation (eller kombination av mutationer) avgör vilka celltyper och organ som drabbas.', 6, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635775100241-v3gx', 'bv2-m6', 'Skulle Gauchers sjukdom kunna vara ett mål för genterapi?', 'Ja, troligen om kvarvarande enzymaktivitet kan återställas med genterapi.', 7, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635775229975-0brp', 'bv2-m6', 'Varför kallas en typ av Gauchers sjukdom ibland för "Norrbottensjukan"?', 'En typ av Gauchers sjukdom är vanligare i Norrbotten än i övriga Sverige.', 8, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-c44b4b5c', 'bv2-m6', 'Var i cellen sker beta-oxidation av fettsyror, och var sker fettsyrasyntes?', 'Beta-oxidation sker i mitokondriematrisen (via karnitin-skytteln). Fettsyrasyntes sker i cytosolen.', 9, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-268324c3', 'bv2-m6', 'Vilket bärarmolekyl krävs för att långa fettsyror ska komma in i mitokondrien för beta-oxidation?', 'Karnitin. Fettsyran aktiveras till fettsyra-CoA och kopplas till karnitin av CPT1 på yttre mitokondriemembranen.', 10, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-7ae09b27', 'bv2-m6', 'Vilket CoA-derivat bildas vid varje beta-oxidationscykel som acetyl-CoA?', 'Varje cykel klyver av en tvåkol-enhet som acetyl-CoA, samt bildar NADH och FADH2. Acetyl-CoA går in i citronsyracykeln.', 11, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-38cc5108', 'bv2-m6', 'Vilka två huvudsubstrat används för ketonkroppssyntes i levern?', 'Acetyl-CoA från beta-oxidation. Vid hög beta-oxidation och låg oxaloacetat bildas ketonkropper (acetoacetat, beta-hydroxibutyrat, aceton).', 12, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-816eabc5', 'bv2-m6', 'Vilket organ producerar ketonkroppar, och vilka organ utnyttjar dem?', 'Levern producerar ketonkroppar men kan inte använda dem själv. Hjärna, hjärta och skelettmuskulatur utnyttjar dem som bränsle.', 13, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-d8d466e9', 'bv2-m6', 'Vad är hastighetsbestämmande enzym i fettsyrasyntesen?', 'Acetyl-CoA-karboxylas, som bildar malonyl-CoA från acetyl-CoA. Malonyl-CoA hämmar samtidigt CPT1 och därmed beta-oxidationen.', 14, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-c23d2125', 'bv2-m6', 'Vilken bärarmolekyl används vid fettsyrasyntes i cytosolen?', 'Acyl carrier protein (ACP) bundet till fettsyrasyntaskomplexet. Syntesen sker via upprepade kondensationer, reduktioner och dehydreringar.', 15, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-ce8f74d8', 'bv2-m6', 'Vilket enzym klyver TAG i adipocyter vid lipolys, och vad aktiverar det?', 'Hormonkänsligt lipas (HSL). Det aktiveras av PKA efter adrenerg stimulering och hydrolyserar TAG till fria fettsyror och glycerol.', 16, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-6ee41645', 'bv2-m6', 'Vilket lipoprotein transporterar endogent syntetiserade TAG från levern till perifera vävnader?', 'VLDL. I perifera vävnader frisätts fettsyror via lipoproteinlipas (LPL), och VLDL omvandlas successivt till IDL och LDL.', 17, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-193ad70c', 'bv2-m6', 'Vilket lipoprotein tar upp kolesterol från perifera vävnader till levern (omvänd kolesteroltransport)?', 'HDL. HDL tar upp kolesterol via ABCA1 och LCAT och återför det till levern.', 18, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-3910dbd5', 'bv2-m6', 'Vilket enzym är hastighetsbestämmande i kolesterolsyntesen?', 'HMG-CoA-reduktas, som omvandlar HMG-CoA till mevalonat. Statiner hämmar detta enzym.', 19, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-839cdd78', 'bv2-m6', 'Vilken aminosyra är startpunkt för ureacykelns kväveavgivning?', 'Ammonium (NH4+) från aminosyradeaminering. I levern kopplas NH4+ ihop med CO2 till karbamoylfosfat, som driver ureacykeln.', 20, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-071ce714', 'bv2-m6', 'Var i cellen sker fettsyrasyntes respektive beta-oxidation?', 'Fettsyrasyntes sker i cytosolen. Beta-oxidation sker i mitokondriens matrix (även peroxisomer för mycket långa fettsyror).', 21, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-eaddf246', 'bv2-m6', 'Vilket bärarmolekyl används vid fettsyrasyntes och varför?', 'ACP (acyl carrier protein) bundet till fettsyrasyntaskomplexet. Syntesen bygger på malonyl-CoA och NADPH som reduktionskraft, till skillnad från beta-oxidationens CoA och NAD+/FAD.', 22, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-558fdc95', 'bv2-m6', 'Vilket enzym är hastighetsbestämmande i fettsyrasyntesen och hur regleras det?', 'Acetyl-CoA-karboxylas (ACC), som bildar malonyl-CoA. Aktiveras av insulin och citrat, hämmas av palmitoyl-CoA och AMPK (fosforylering).', 23, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-1af57f17', 'bv2-m6', 'Vad är acetyl-CoA-karboxylas huvudsakliga reaktion?', 'Karboxylerar acetyl-CoA till malonyl-CoA med hjälp av ATP och biotin. Malonyl-CoA är substrat för fettsyrasyntasen och hämmar dessutom CPT1.', 24, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-bb40004b', 'bv2-m6', 'Vad händer med fettsyror vid insulinresistens i fettväv?', 'Lipolysen ökar eftersom insulinets hämmande effekt på hormonsensitiv lipas (HSL) minskar. Det ger ökad frisättning av fria fettsyror och glycerol till blodet.', 25, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-d0978e45', 'bv2-m6', 'Vilket enzym katalyserar det hastighetsbestämmande steget i lipolys i adipocyter?', 'Hormonsensitiv lipas (HSL), aktiverat av PKA efter adrenerg stimulering. Det hydrolyserar TAG till diacylglycerol; ATGL och MGL bidrar i övriga steg.', 26, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-3c191061', 'bv2-m6', 'Vilka tre ketonkroppar bildas vid ketogenes och var sker det?', 'Acetoacetat, beta-hydroxietyrat och aceton. Ketogenesen sker i mitokondrierna i lever (från acetyl-CoA) och ketonkropparna används som bränsle av extrahepatiska vävnader.', 27, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-eb154cf0', 'bv2-m6', 'Varför kan levern inte använda ketonkroppar som bränsle?', 'Levern saknar enzymet tioforas (beta-ketoacyl-CoA-transferas, SCOT), som krävs för att aktivera ketonkroppar till acetyl-CoA i extrahepatiska vävnader.', 28, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-8b82b3db', 'bv2-m6', 'Vilket enzym är hastighetsbestämmande i kolesterolsyntesen och hur regleras det?', 'HMG-CoA-reduktas, som omvandlar HMG-CoA till mevalonat. Regleras av sterolreglerande bindningsprotein (SREBP) vid låg kolesterolhalt och hämmas av statiner samt högt intracellulärt kolesterol.', 29, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-acca7693', 'bv2-m6', 'Vilken lipoproteinpartikel transporterar kolesterol från perifera vävnader till levern?', 'HDL. Det tar upp kolesterol via ABCA1 och LCAT, och levererar det till levern direkt eller via SR-B1-receptorn.', 30, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-6d260e0d', 'bv2-m6', 'Vilket apolipoprotein är viktigt för chylomikronernas och VLDL:s struktur och nedbrytning?', 'ApoC-II aktiverar lipoproteinlipas (LPL) så att TAG hydrolyseras i kapillärerna. ApoE medierar upptag via leverreceptorer.', 31, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-33ebfd52', 'bv2-m6', 'Vad är ureacykelns huvudsakliga funktion och var sker den?', 'Avgiftar ammoniak genom att bilda urea från ammoniumjoner och aspartat. Sker i levermitokondrier och cytosol; urea utsöndras via njurarna.', 32, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-da7de2c2', 'bv2-m6', 'Vilket bärarmolekyl krävs för att fettsyror ska kunna beta-oxideras i mitokondrien?', 'Karnitin. Fettsyran aktiveras till acyl-CoA och kopplas via CPT1 på yttre mitokondriemembranen till karnitin för transport in.', 33, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-a79b6fa4', 'bv2-m6', 'Vilken koenzymbrist gör att beta-oxidationen avstannar vid lång fasta?', 'Brist på fria CoA/carnitin. När acetyl-CoA ansamlas binds CoA, och utan tillgängligt CoA kan beta-oxidationen inte fortsätta.', 34, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-121ac2b7', 'bv2-m6', 'Vilka tre ketonkroppar bildas vid ketogenes och var sker den?', 'Acetoacetat, beta-hydroxietyrat och aceton. Ketogenes sker i mitokondrierna i leverceller (hepatocyter).', 35, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-e19b1bb3', 'bv2-m6', 'Varför kan levern bilda ketonkroppar men inte använda dem?', 'Levern saknar enzymet beta-ketotiolas (tiolas) för ketonkropparnas nedbrytning. Ketonkroppar exporteras till extrahepatiska vävnader, särskilt hjärna och skelettmuskel.', 36, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-b5495480', 'bv2-m6', 'Vilket enzym är hastighetsbegränsande i fettsyrasyntesen och vad gör det?', 'Acetyl-CoA-karboxylas, som omvandlar acetyl-CoA till malonyl-CoA. Malonyl-CoA är substrat för fettsyrasyntas.', 37, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-f55108fe', 'bv2-m6', 'Hur reglerar malonyl-CoA beta-oxidationen?', 'Malonyl-CoA hämmar CPT1, vilket blockerar transport av fettsyror in i mitokondrien. Vid aktiv fettsyrasyntes hämmas därmed beta-oxidationen.', 38, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-9f26fe82', 'bv2-m6', 'Vilken är den viktigaste regulatoriska skillnaden mellan fettsyrasyntes och beta-oxidation avseende NADPH?', 'Fettsyrasyntes kräver NADPH (från pentosfosfatvägen och malat-enzymet). Beta-oxidation producerar NADH och FADH2.', 39, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-cbbba693', 'bv2-m6', 'Vilket enzym är hastighetsbegränsande för kolesterol-syntesen?', 'HMG-CoA-reduktas, som omvandlar HMG-CoA till mevalonat. Det är mål för statiner.', 40, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-172afa40', 'bv2-m6', 'Vilken lipoproteinpartikel transporterar kolesterol från perifer vävnad till levern?', 'HDL. Det tar upp kolesterol via ABCA1 och levererar det till levern, bl.a. via SR-B1-receptorn (omvänt kolesteroltransport).', 41, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-9792ad8e', 'bv2-m6', 'Vilket apolipoprotein på LDL-partikeln känner igen LDL-receptorn?', 'ApoB-100. LDL tas upp i levern via LDL-receptorn som binder apoB-100.', 42, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-d9935612', 'bv2-m6', 'Vilket enzym frisätter fettsyror från TAG i adipocyter vid lipolys?', 'Hormonkänsligt lipas (HSL), aktiverat av glukagon/adrenalin via cAMP-PKA. Det hydrolyserar TAG till fria fettsyror och glycerol.', 43, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-762fb555', 'bv2-m6', 'Var sker fettsyrasyntes intracellulärt och vilket bärarmolekyl används?', 'I cytosolen. Acetyl- och malonylgrupper bärs av acyl carrier protein (ACP) i fettsyrasyntaskomplexet.', 44, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-e6e8744e', 'bv2-m6', 'Vilket enzym är hastighetsbegränsande i fettsyrasyntesen och hur regleras det?', 'Acetyl-CoA-karboxylas (ACC), som bildar malonyl-CoA. Aktiveras allosteriskt av citrat och stimuleras av insulin; hämmas av palmitoyl-CoA och glukagon.', 45, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-f80af759', 'bv2-m6', 'Varför sker fettsyrasyntes och beta-oxidation inte samtidigt i samma cellutrymme?', 'De är rumsligt åtskilda: syntes i cytosolen, beta-oxidation i mitokondriematrisen. Det förhindrar en energiskt ofördelaktig samtidig nedbrytning och uppbyggnad.', 46, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-49e57438', 'bv2-m6', 'Vilka tre steg bildar ketonkroppar och var sker de?', 'I mitokondriematrisen i levern: acetyl-CoA → acetoacetyl-CoA → HMG-CoA → acetoacetat (via HMG-CoA-syntas). Acetoacetat reduceras sedan till beta-hydroxibutyrat.', 47, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-37f28ce1', 'bv2-m6', 'Vilket enzym är hastighetsbegränsande i kolesterolbiosyntesen och hur regleras det?', 'HMG-CoA-reduktas, som bildar mevalonat. Regleras genom feedback av kolesterol (hämning av transkription och enzymaktivitet) samt av insulin/glukagon.', 48, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-43d03b84', 'bv2-m6', 'Vad kännetecknar LDL och vilken är dess huvudsakliga funktion?', 'LDL bär apoB-100 och är kolesterolrikt. Det transporterar kolesterol från levern till perifera vävnader via LDL-receptorn.', 49, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-884a3ca1', 'bv2-m6', 'Vad kännetecknar HDL och vilken är dess huvudsakliga funktion?', 'HDL bär apoA-I och är proteinrikt. Det utför omvänt kolesteroltransport: tar upp kolesterol från vävnader och för det tillbaka till levern.', 50, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-94bb81d7', 'bv2-m6', 'Vilket enzym klyver TAG i adipocyter under lipolys och vad aktiverar det?', 'Hormonkänsligt lipas (HSL) och ATGL klyver TAG. De aktiveras av glukagon och adrenalin via cAMP→PKA, medan insulin hämmar lipolysen.', 51, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-0048a5a0', 'bv2-m6', 'Vilket kofaktor- och kofaktorkrav har beta-oxidationens dehydrogenaser?', 'Dehydrogenaserna är NAD+- och FAD-beroende; FAD används i acyl-CoA-dehydrogenas (första steget), NAD+ i hydroxiacyl-CoA-dehydrogenas. Varje cykel ger 1 FADH2 och 1 NADH.', 52, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-931133a8', 'bv2-m6', 'Vad är enkolpoolen och vilken molekyl är dess huvudsakliga bärare?', 'Enkolpoolen är gruppen av enkolöverförande metaboliter. Tetrahydrofolat (THF) är huvudbäraren, som överför enkolgrupper i olika oxidationstillstånd vid nukleotidsyntes och metionincykeln.', 53, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-8a36152c', 'bv2-m6', 'Vilka två huvudvägar bryter ned hem och vad bildas?', 'Hem oxygenas i retikuloendoteliala celler öppnar hemringen till biliverdin och frisätter Fe2+ och CO. Biliverdin reduceras till bilirubin, som konjugeras i levern.', 54, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-566590a5', 'bv2-m6', 'Vilket enzym är hastighetsbestämmande i fettsyrasyntesen?', 'Acetyl-CoA-karboxylas, som omvandlar acetyl-CoA till malonyl-CoA. Det aktiveras av insulin och inhiberas av glukagon.', 55, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-4d30e8e7', 'bv2-m6', 'Varför krävs malonyl-CoA för fettsyrasyntes?', 'Malonyl-CoA är substratet som donerar tvåkolensenheter till den växande fettsyrakedjan via fettsyrasyntaskomplexet (FAS).', 56, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-8ca4a39a', 'bv2-m6', 'Vilken roll har karnitin i fettsyrametabolismen?', 'Karnitin transporterar långkedjiga fettsyror som acylkarnitin över den inre mitokondriemembranen via karnitinpalmitoyltransferas I (CPT1), rate-limiting för beta-oxidation.', 57, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-63a39220', 'bv2-m6', 'Vad bildas vid fullständig beta-oxidation av en fettsyra?', 'Acetyl-CoA, NADH och FADH2. Acetyl-CoA går in i citronsyracykeln; NADH/FADH2 driver oxidativ fosforylering.', 58, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-dee177f8', 'bv2-m6', 'Varför kan fettsyror inte omvandlas till glukos i djurceller?', 'Acetyl-CoA från beta-oxidation kan inte omvandlas till oxaloacetat; pyruvatdehydrogenasreaktionen är oåterkallelig. Fettsyror ger därför ketonkroppar, inte netto glukos.', 59, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-a43d8953', 'bv2-m6', 'Var bildas ketonkroppar och vilka är de tre?', 'I levermitokondrierna. De tre är acetoacetat, beta-hydroxibutyrat och aceton.', 60, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-566bc519', 'bv2-m6', 'Varför bildas ketonkroppar vid långvarig fasta?', 'Lågt insulin/högt glukagon ökar lipolys och lever-beta-oxidation; överskott av acetyl-CoA driver ketogenes. Ketonkroppar ersätter glukos för hjärnan.', 61, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-2fec4f72', 'bv2-m6', 'Vad är rate-limiting enzym i kolesterolsyntesen?', 'HMG-CoA-reduktas, som omvandlar HMG-CoA till mevalonat. Det regleras av SREBP och statiner inhiberar det.', 62, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-9008f5d8', 'bv2-m6', 'Vilken lipoproteinpartikel transporterar endogent TAG från levern?', 'VLDL. Det avges från levern, får ApoC-II och ApoE, och lipolyseras av lipoproteinlipas till IDL och LDL.', 63, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-78f8f933', 'bv2-m6', 'Vad gör lipoproteinlipas (LPL) och var sitter det?', 'LPL hydrolyserar TAG i kylomikroner och VLDL till fria fettsyror för upptag i vävnad. Det sitter på kapillärendotelet, aktiveras av ApoC-II.', 64, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('ai-card-bv2-m6-7c70c568', 'bv2-m6', 'Vilket receptor medierar cellulärt upptag av LDL?', 'LDL-receptorn, som känner igen ApoB-100. Upptag via klatrinberoende endocytos; brist leder till familjär hyperkolesterolemi.', 65, 'ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m7-c1', 'bv2-m7', 'Vilka hormoner reglerar hunger och mättnad?', 'Ghrelin (hunger, från magsäcken), leptin (mättnad, från fettväv), GLP-1 och PYY (mättnad, från tarmen) samt insulin.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m7-c2', 'bv2-m7', 'Vad är feed-fast-cykeln?', 'Växlingen mellan näringsintag (anabolt: insulin högt, glykogenes och lipogenes) och fasta (katabolt: glukagon högt, glykogenolys, lipolys, ketogenes).', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m7-c3', 'bv2-m7', 'Vad är inkretineffekten?', 'Att glukos givet via munnen ger större insulinfrisättning än samma mängd glukos intravenöst, tack vare GLP-1 och GIP från tarmen.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m7-c4', 'bv2-m7', 'Vad gör polyolvägen vid hyperglykemi?', 'Glukos omvandlas via aldosreduktas till sorbitol som ansamlas i celler (lins, nerv, njure) och ger osmotisk stress – en förklaring till diabeteskomplikationer.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635189017760-ckiv', 'bv2-m7', 'Vad kännetecknar diabetes typ 2?', 'Cellerna blir sämre på att använda insulin och kan inte ta hand om blodsockret efter måltid, vilket ger förhöjt blodsocker. Bukspottkörteln kompenserar med ökad insulinutsöndring.', 5, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635189067124-twve', 'bv2-m7', 'Vilka livsstilsfaktorer är kopplade till diabetes typ 2?', 'Fetma, dålig kost och stress, utöver många genetiska riskfaktorer.', 6, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635189123884-wyff', 'bv2-m7', 'Hur kan det negativa förloppet vid diabetes typ 2 bromsas?', 'Genom livsstilsförändringar som viktnedgång, ökad fysisk aktivitet, rökstopp och sundare matvanor.', 7, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636102051954-4qat', 'bv2-m7', 'Vilken myndighet ger kostråd i Sverige?', 'Livsmedelsverket ansvarar för de svenska kostråden.', 8, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m8-c1', 'bv2-m8', 'Vad innebär öppet lyssnande i patientmötet?', 'Öppna invitationer (''berätta''), sammanfattningar och bekräftelse som låter patienten berätta klart innan läkaren styr samtalet.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m8-c2', 'bv2-m8', 'Vilka är de basala hygienrutinerna?', 'Handdesinfektion före och efter patientkontakt, handskar vid risk för kroppsvätskekontakt, kortärmade kläder utan armband/klocka och rent skyddsförkläde.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m8-c3', 'bv2-m8', 'Vad skiljer explicit, implicit och konfirmationsbias?', 'Explicit fördom: medveten och uttalad. Implicit: omedveten automatisk association. Konfirmationsbias: tendens att bara söka information som bekräftar den egna hypotesen.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv2-m8-c4', 'bv2-m8', 'Vad ska du kontrollera vid venös provtagning för att göra det patientsäkert?', 'Identifiera patienten med namn och personnummer, kontrollera indikation och rörtyp (färg), använd stasband kortvarigt, desinfektera och märk rören vid patienten – undvik felprov.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635340008004-vjxl', 'bv2-m8', 'Vilka målgrupper har informationen i Socialstyrelsens databaser?', 'Patienter, vårdpersonal, forskare, patientorganisationer och läkarstudenter.', 5, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635434843720-gdgl', 'bv2-m8', 'Vilka lager delas huden in i?', 'Epidermis, dermis och subkutanvävnad.', 6, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635434965432-q774', 'bv2-m8', 'Vilka strukturer finns i dermis?', 'Bland annat oljekörtlar, lymfkärl, nerver, hårrötter och svettkörtlar.', 7, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635435002399-yk15', 'bv2-m8', 'Vilka komponenter finns i subkutan vävnad?', 'Artärer, vener och fettvävnad.', 8, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635435094688-5fco', 'bv2-m8', 'Vad kännetecknar läkt hud efter sårläkning?', 'Huden är reparerad men inte helt återställd; ärrvävnad kan ersätta ursprunglig vävnad och alla ursprungliga funktioner återställs inte alltid.', 9, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635435995451-wkjt', 'bv2-m8', 'Vad definierar ett sår?', 'Ett sår är en mekanisk skada där integriteten hos täckt vävnad (hud eller muköst membran) är bruten, orsakad av externt våld eller mekanisk agent snarare än sjukdom.', 10, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635436121044-v5sk', 'bv2-m8', 'Vad kännetecknar ett primärt läkande sår?', 'Sår utan vävnadsdefekt där sårkanterna ligger mot varandra och kan sys ihop, t.ex. operationssår och skärsår.', 11, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635436133621-dvfp', 'bv2-m8', 'Vilken latinsk term används för primärt läkande sår?', 'Vulnus (sår). Primär läkning sker per primam intentionem.', 12, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635436152679-4mus', 'bv2-m8', 'Vilken latinsk term används för sekundärt läkande sår?', 'Ulcus (sår med vävnadsdefekt som läker per secundam intentionem).', 13, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635436215100-5836', 'bv2-m8', 'Vad kännetecknar ett sekundärt läkande sår?', 'Sår med vävnadsdefekt som måste fyllas i innan det kan läka, t.ex. bensår och trycksår.', 14, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635436241269-0kyj', 'bv2-m8', 'Vad är en erosion?', 'En ytlig skada begränsad till epidermis som läker utan ärrbildning.', 15, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635436399701-otlt', 'bv2-m8', 'Vad är ett ulcus?', 'En skada som omfattar både epidermis och dermis (full-thickness wound) och som läker med ärr.', 16, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635436425089-exfb', 'bv2-m8', 'Hur läker ett ulcus?', 'Vävnadsdefekten måste först fyllas i, varefter såret läker med ärrbildning.', 17, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635436453343-933j', 'bv2-m8', 'Vilken engelsk term används för ulcus?', 'Full-thickness wound.', 18, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635436512130-8n25', 'bv2-m8', 'Vilka hudstrukturer skadas vid ett sår?', 'Epidermis med dess bihang, basalmembranet och dermis skadas.', 19, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635436580667-fjfz', 'bv2-m8', 'Vilka delar av epidermis skadas vid ett sår?', 'Det interfollikulära epidermis och hårstråna skadas.', 20, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635436642306-1926', 'bv2-m8', 'Vilka strukturer i dermis skadas vid ett sår?', 'Extracellulär matrix, nerver, blod- och lymfkärl samt fibroblaster och fettväv skadas.', 21, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635436699230-8gzq', 'bv2-m8', 'Var ligger basalmembranet i huden och vad gör det?', 'Det ligger mellan epidermis och dermis och sammankopplar de två vävnadsstrukturerna.', 22, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635436852946-lyyy', 'bv2-m8', 'Vilka basala cellfunktioner krävs för att reparera ett sår?', 'Celler måste kunna migrera, interagera, proliferera och differentiera; flera olika celltyper är involverade.', 23, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635436926745-uw8k', 'bv2-m8', 'Vilka faser ingår i sårläkningen?', 'Intermediär läkning (hemostas), inflammatorisk respons, ny vävnadsformation och återmodellering till ärr.', 24, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437070980-17x3', 'bv2-m8', 'Vad händer i den intermediära fasen av sårläkning?', 'Skadan på vävnad och kärl startar direkt haemostas, där en fibrinpropp av fibrin och blodplättar bildas. Det stoppar blödning, motverkar vätskeförlust och bakteriell infestation.', 25, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437139316-j14k', 'bv2-m8', 'Hur bidrar haemostas till sårläkningen?', 'Blödningen startar koagulationen och en propp av fibrin och blodplättar bildas, vilket stoppar blödning och vätskeförlust.', 26, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437198237-6l79', 'bv2-m8', 'När börjar den inflammatoriska fasen i sårläkning?', 'Den börjar vid skadetillfället och pågår tills sårytan är renad.', 27, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437214733-k6jr', 'bv2-m8', 'Hur länge varar den inflammatoriska fasen i sårläkning?', 'Cirka 1–6 dagar.', 28, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437256363-3omt', 'bv2-m8', 'Vilka tre celltyper/faktorer är centrala i sårläkningens inflammatoriska fas?', 'Trombocyter (blodplättar), monocyter och makrofager.', 29, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437342458-4u2e', 'bv2-m8', 'Vilken roll har trombocyter i den inflammatoriska fasen?', 'De frisätter vasoaktiva faktorer som attraherar leukocyter, huvudsakligen neutrofiler, vilka i sin tur frisätter cytokiner som attraherar monocyter från cirkulationen.', 30, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437380303-e1tp', 'bv2-m8', 'Vad gör monocyter i den inflammatoriska fasen?', 'De mognar till makrofager som rensar såret från bakterier, död vävnad och främmande material.', 31, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437418903-9w5u', 'bv2-m8', 'Vilken ytterligare funktion har makrofager i sårläkningen?', 'De producerar tillväxtfaktorer som stimulerar andra celler att bidra till sårläkningen.', 32, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437448093-3v1z', 'bv2-m8', 'Vad menas med maggot medicine (larvterapi)?', 'Sårrening med sterila larver.', 33, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437549594-1gvt', 'bv2-m8', 'Hur fungerar larvterapi vid sårrening?', 'Sterila larver används t.ex. på diabetiska sår med nedsatt blodcirkulation; larverna livnär sig på död vävnad och lämnar frisk vävnad ifred.', 34, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437581583-zv8u', 'bv2-m8', 'Vilka tre symtom är typiska vid inflammation?', 'Smärta, ödem samt värme och rodnad.', 35, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437666193-00wj', 'bv2-m8', 'Varför uppstår smärta vid inflammation?', 'Döda celler frisätter substanser som irriterar fria nervändar, och histamin frisätts som en del av den inflammatoriska responsen.', 36, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437707259-amzs', 'bv2-m8', 'Hur uppstår ödem vid inflammation?', 'Vaskulär dilation gör att kärlen läcker vätska, vilket orsakar svullnad och ödem.', 37, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437753920-dcbe', 'bv2-m8', 'Varför uppstår värme och rodnad vid inflammation?', 'Förbättrad mikrocirkulation ökar blodflödet till vävnaden, vilket ger värme och rodnad.', 38, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437823374-4w9v', 'bv2-m8', 'När börjar den tredje fasen av sårläkning (ny vävnadsbildning)?', 'Den börjar efter några dagar och varar i 7–10 dagar beroende på ålder och sårstorlek.', 39, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437858774-qoa2', 'bv2-m8', 'Hur länge varar den tredje fasen av sårläkning?', '7–10 dagar beroende på ålder och sårstorlek.', 40, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635437897371-d5es', 'bv2-m8', 'Vad sker i den tredje fasen av sårläkning?', 'Stora förändringar sker i både epidermis och dermis och ny vävnad bildas.', 41, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635438048253-lydc', 'bv2-m8', 'Vad sker i epidermis under den tredje fasen av sårläkning?', 'Åter-epitelisering sker: keratinocyter prolifererar och migrerar till fibrinproppen under sårskorpan. De migrerande cellerna uttrycker lamellära utsprång och enzymer som löser upp vävnaden framför dem.', 42, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635438092399-g5tv', 'bv2-m8', 'Vilken roll har hårsäckarna vid åter-epitelisering i tredje fasen?', 'De hjälper till med åter-epiteliseringen, men sår kan också läka utan hårsäckar.', 43, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635438123420-6668', 'bv2-m8', 'Vilken celltyp börjar proliferera i epidermis under tredje fasen?', 'Keratinocyter.', 44, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635438219629-whak', 'bv2-m8', 'Vad sker i dermis under den tredje fasen av sårläkning?', 'Granulationsvävnad bildas: fibrinproppen ersätts långsamt av fibroblaster. Fibroblaster vid sårkanten omvandlas till myofibroblaster som kontraherar och minskar såret.', 45, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635438245062-4xug', 'bv2-m8', 'Vad omvandlas fibroblaster till i den tredje fasen?', 'De omvandlas till myofibroblaster, som är muskelliknande.', 46, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635438269305-wrqn', 'bv2-m8', 'Var anses myofibroblaster vara viktigare?', 'De är viktigare i djur än i människor.', 47, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635438301340-65c9', 'bv2-m8', 'Vad kan myofibroblaster ge upphov till?', 'De skapar ärr, särskilt om de blir kvar efter att såret läkt.', 48, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635438345651-fwuj', 'bv2-m8', 'Hur länge kan remodelleringsfasen i sårläkning pågå?', 'Remodelleringsfasen kan pågå i månader till år.', 49, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635438432680-t0ps', 'bv2-m8', 'Vad sker i epidermis under remodelleringsfasen?', 'Keratinocyternas snabba proliferation avstannar och de börjar differentiera, vilket återuppbygger ett tjockt epidermis. Huden återgår dock inte till ursprungligt stadium eftersom hårsäckar och körtlar saknas.', 50, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635438477594-4429', 'bv2-m8', 'Varför återgår huden inte till ursprunglig struktur efter sårläkning?', 'Bland annat för att hårsäckar och körtlar saknas i det läkta området.', 51, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635438596009-jl8w', 'bv2-m8', 'Vad sker i dermis under remodelleringsfasen?', 'Blodkärlsnätverket förfinas, tät ECM blir mjukare och mer strukturerad, myofibroblasterna försvinner och makrofager fagocyterar neutrofilerna och återvänder till vaskulaturen.', 52, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635438613778-w5ld', 'bv2-m8', 'Vilken struktur bildar myofibroblasterna i såret?', 'Myofibroblasterna bildar en struktur likt en muskelring.', 53, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
