  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1635438982966-rqe7', 'bv2-m8', 'Vad är målet med all sårvård?', 'Målet är att läka såret, minska lidande och underlätta vardagslivet. Det uppnås genom att identifiera och behandla orsaken till såret samt läkningshämmande faktorer.', 59, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
