INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636634309270-ma1w', 'bv2-m8', 'Patienten uttrycker oro för stroke – hur svarar läkaren omedelbart på bästa sätt?', 'Bekräfta att det var bra att hon berättade om oron och förklara att du nu ska göra en ordentlig undersökning och försöka hjälpa henne på bästa sätt.', 97, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636634340705-px9y', 'bv2-m8', 'Hur försäkrar sig läkaren bäst om att hen förstått patientens agenda?', 'Genom en övergripande sammanfattning av patientens spontana anamnes samt tankar, oro och önskemål, följt av frågan om det stämmer eller om något ska tilläggas.', 98, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636634365677-npcp', 'bv2-m8', 'Vad är det viktigaste skälet till att arbeta patientcentrerat?', 'Att patientens presentation av symtom och problem inte räcker för att förstå besöksorsaken och patientens frågor.', 99, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636718389606-jszj', 'bv2-m8', 'Vad innebär inspektion vid en klinisk undersökning?', 'En systematisk visuell undersökning av kroppen för att upptäcka avvikelser.', 100, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636718473199-ohfw', 'bv2-m8', 'Vad innebär auskultation?', 'Att lyssna på kroppens egna ljud med stetoskop, till exempel hjärta och lungor.', 101, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636718542833-nmay', 'bv2-m8', 'Vad innebär palpation?', 'Att känna med händer och fingrar på kroppen för att upptäcka sjukliga förändringar.', 102, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636718642201-z210', 'bv2-m8', 'Vad innebär perkussion som undersökningsmetod?', 'Man knackar på kroppsytan med fingrarna och bedömer det ljud som uppstår för att undersöka underliggande organ.', 103, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636718832235-t8aq', 'bv2-m8', 'Vad alstrar det första hjärtljudet?', 'Stängning av mitralis- och tricuspidalisklaffarna, där blodet studsar tillbaka mot klaffarna.', 104, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636718832235-3shm', 'bv2-m8', 'Vad alstrar det andra hjärtljudet?', 'Stängning av aortaklaffen och pulmonalisklaffen, där blodet studsar tillbaka mot klaffarna.', 105, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636718942985-5kkm', 'bv2-m8', 'Var auskulteras aortaklaffen bäst?', 'I 2:a interkostalrummet till höger om sternum.', 106, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
