VALUES ('anki-1636718942985-x4fy', 'bv2-m8', 'Var auskulteras pulmonalisklaffen bäst?', 'I 2:a interkostalrummet till vänster om sternum.', 107, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636718942985-epsh', 'bv2-m8', 'Var auskulteras tricuspidalisklaffen bäst?', 'I 4:e interkostalrummet till vänster om sternum.', 108, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636718942985-aont', 'bv2-m8', 'Var auskulteras mitralisklaffen bäst?', 'Lateralt i 5:e interkostalrummet, i apexområdet.', 109, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636719055535-gjy8', 'bv2-m8', 'Varför auskulteras lungorna på flera punkter på bröstkorgen?', 'För att kunna jämföra olika lungpartier och upptäcka skillnader, så att ett påverkat område kan lokaliseras trots att övriga lungor är opåverkade.', 110, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636719113076-jln5', 'bv2-m8', 'Vilken information ger perkussion av bröstkorgen?', 'Man kan bestämma lunggränserna och upptäcka vätskeansamling.', 111, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636719253192-99qo', 'bv2-m8', 'Varför låter normala andningsljud vesikulära över lungfälten?', 'Ljudet uppstår till följd av lobernas elasticitet.', 112, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636719253192-ulq3', 'bv2-m8', 'Hur låter andningsljudet över bronkerna på bröstbenet?', 'Mer ihåligt/rörartat än över lungfälten.', 113, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636719370374-6kjt', 'bv2-m8', 'Vad utmärker vesikulära andningsljud?', 'De är mjuka, lågtoniga, lätt rostlande och relativt svaga vid utandning.', 114, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636719370374-vjz8', 'bv2-m8', 'Varifrån kommer inandningsljudet respektive utandningsljudet?', 'Inandningsljudet kommer från de lobulära och segmentala luftvägarna; utandningsljudet från mer centrala luftvägar som bronkerna.', 115, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636719534984-8ur1', 'bv2-m8', 'Hur förhåller sig inandningsfasen till utandningsfasen vid normal andning?', 'Inandningsfasen är längre än utandningsfasen, ungefär i förhållandet 2:1, och ljudet är ofta starkare.', 116, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636719707472-9jr0', 'bv2-m8', 'Var kan bronkiala andningsljud höras normalt?', 'Nära de större luftvägarna, t.ex. över bronkerna, bröstbenet och trakea.', 117, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636719776090-itf5', 'bv2-m8', 'Hur låter bronkiala andningsljud?', 'De är starkare och har en längre expirationsfas.', 118, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636720010751-2tcy', 'bv2-m8', 'Varför uppstår Korotkoff-ljud vid systoliskt tryck och försvinner vid diastoliskt tryck?', 'Vid systoliskt tryck släpps blodet igenom den delvis komprimerade artären och ger turbulens som hörs som ljud. Vid diastoliskt tryck komprimeras inte kärlet längre, flödet blir laminärt och ljudet upphör.', 119, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636720245663-qwf8', 'bv2-m8', 'Vilka två syften har en palpatorisk blodtrycksmätning?', 'Att uppskatta hur högt manchetten ska pumpas inför auskultatorisk mätning, och att få ett blodtrycksvärde när auskultation inte fungerar.', 120, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636720504228-xs7k', 'bv2-m8', 'Nämn vanliga felkällor vid blodtrycksmätning.', 'Exempelvis stress, koffein, rökning, otillräcklig vila, vitrockshypertoni, fel manchettstorlek, manchett över kläder, oavslappnad arm utan stöd, arm ej i hjärthöjd, samtal, kyla, fylld urinblåsa, korsade ben och avsaknad av ryggstöd.', 121, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740138733-lphu', 'bv2-m8', 'Vilka strukturer i trumhinnan kan man se med otoskop?', 'Man kan se hammarens skaft (manubrium mallei), ljusreflexen och trumhinnan.', 122, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740208469-nvgz', 'bv2-m8', 'Hur långt för man in otoskopet i hörselgången och varför?', 'Cirka 1 cm, förbi håren. Längre in är huden mycket känslig och undersökningen kan göra ont.', 123, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740251018-kvw0', 'bv2-m8', 'Varför drar man i ytterörat vid öronundersökning?', 'Hörselgången är krökt; genom att dra i ytterörat rätas den ut så att trumhinnan kan ses.', 124, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740339544-fexl', 'bv2-m8', 'Vilka nio regioner delas buken in i?', 'Höger och vänster arcus, epigastrium, höger och vänster flank, umbilikalregionen, höger och vänster fossa samt hypogastrium.', 125, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740360632-snns', 'bv2-m8', 'Vilka organ ligger under höger arcus?', 'Levern och gallblåsan.', 126, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740381924-8p9e', 'bv2-m8', 'Vilka organ ligger under höger flank?', 'Höger njure och colon ascendens.', 127, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740396484-jo13', 'bv2-m8', 'Vilka strukturer ligger under höger fossa?', 'Cecum och appendix vermiformis.', 128, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740485730-fspm', 'bv2-m8', 'Vilka organ ligger under vänster arcus costalis?', 'Mjälten och eventuellt magsäcken.', 129, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740518829-043k', 'bv2-m8', 'Vilka organ ligger i vänster flank?', 'Vänster njure och colon descendens.', 130, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740535072-7fhx', 'bv2-m8', 'Vilket organ ligger i vänster fossa iliaca?', 'Colon sigmoideum.', 131, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740596711-ayjm', 'bv2-m8', 'Vilka organ ligger i epigastriet?', 'Magsäcken, bukspottskörteln och en del av levern. Binjurarna ligger också här.', 132, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740636495-xohm', 'bv2-m8', 'Vilka organ ligger i hypogastriet?', 'Urinblåsan, tunntarm och ändtarm; hos kvinnor även livmoder.', 133, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740659005-8o7m', 'bv2-m8', 'Vilka strukturer ligger i den umbilikala regionen?', 'Tunntarm, aorta, aa./vv. renales och colon transversum.', 134, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740773648-0tac', 'bv2-m8', 'Vad ger systematisk ytlig palpation av buken information om?', 'Man trycker ned ca 1 cm och känner ömhet i en specifik kvadrant.', 135, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740828305-4kfj', 'bv2-m8', 'Vad ger systematisk djup palpation av buken information om?', 'Man trycker ned ca 4–5 cm och använder det för att upptäcka massor, organ och organomegaly.', 136, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636740935123-rwks', 'bv2-m8', 'Hur palpterar man njurarna?', 'En hand läggs under patientens rygg under revbenen; den andra handen palperar motsvarande kvadrant medialt till lateralt för att hitta njuren.', 137, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636741213097-t7sq', 'bv2-m8', 'Hur mäter man bukaortans storlek vid palpation?', 'Med två pekfingrar riktade mot varandra trycker man ned i umbilikalregionen tills puls känns, flyttar sedan fingrarna stegvis isär tills pulsen inte längre känns – avståndet anger aortans bredd.', 138, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636741317051-0set', 'bv2-m8', 'Hur palpterar man levern?', 'Be patienten andas in djupt och sedan ut. Lägg fingrarna vid revbenen i höger arcus och tryck in dem när patienten andas ut. Då får man handen mellan revbenen och levern och kan ana levern under revbenen.', 139, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636741818469-wtz6', 'bv2-m8', 'Hur undersöker man för en förstorad lever?', 'Utför djup palpation från höger fossa och palpera systematiskt uppåt genom höger fossa och flank tills du når höger arcus. Be patienten andas in djupt och sedan ut, lägg fingrarna under revbenen och tryck försiktigt in dem när patienten andas ut.', 140, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636741994940-wamg', 'bv2-m8', 'Hur undersöker man för en förstorad mjälte?', 'Palpera diagonalt över kvadranterna: börja i höger fossa och arbeta dig upp diagonalt genom höger fossa, umbilikalregionen och vänster arcus med djup palpation. Be patienten andas in djupt, lägg fingrarna under revbenen och tryck försiktigt in dem när patienten andas ut.', 141, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636742042501-zodn', 'bv2-m8', 'Varför auskulterar man lungorna på motsvarande ställen på båda sidor?', 'För att kunna jämföra om ljudet skiljer sig mellan sidorna, till exempel om en lunga verkar vätskefylld i basen.', 142, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636742398891-4x6l', 'bv2-m8', 'Hur undersöker man lungorna vid auskultation?', 'På ryggen: perkutera först lunggränserna och lyssna sedan på 8 ställen (4 parallella på vardera sida): strax ovanför skapula, mellan skapula, nedre delen av skapula och nedanför skapula. På bröstet: nedanför nyckelbenen, mitten av lungan, nedersta delen av lungan och eventuellt trakea.', 143, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636742434723-0qlk', 'bv2-m8', 'Vad mer auskulterar man förutom hjärtat vid hjärtundersökning?', 'Man auskulterar även aa. carotis.', 144, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636742539092-tm94', 'bv2-m8', 'Varför auskulterar man aa. carotis?', 'För att det speglar ventrikulär systolisk funktion och kan upptäcka vissa typer av hjärtklaffssjukdomar.', 145, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636742675081-hl49', 'bv2-m8', 'Vilka tre typer av bi- och blåsljud finns?', 'Fysiologiska (normala), förträngning (stenos) och läckage (insufficiens).', 146, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636742873024-cfif', 'bv2-m8', 'Vilka systoliska bi- och blåsljud är vanliga och vilka klaffar gäller det?', 'Fysiologiska ljud, förträngning (aortastenos) och läckage (mitralisinsufficiens).', 147, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636742940445-uvpn', 'bv2-m8', 'Vilka klaffar är involverade vid diastoliska bi- och blåsljud?', 'Förträngning: mitralisstenos. Läckage: aortainsufficiens.', 148, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636742986090-ocic', 'bv2-m8', 'Vad ska patienten göra vid auskultation av a. carotis och varför?', 'Be patienten hålla andan, eftersom andningsljud kan störa auskultationen och uppfattas som falska bi- eller blåsljud.', 149, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636743057075-7f4b', 'bv2-m8', 'På vilka fyra sätt kan blodtryck mätas?', 'Palpatoriskt, auskultatoriskt, automatiskt (oscillometriskt) och invasivt.', 150, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636743642595-nzaa', 'bv2-m8', 'Vilka är de vanligaste extremitetsreflexerna?', 'Patellarreflexen, Achillesreflexen, bicepsreflexen, brachioradialisreflexen och tricepsreflexen.', 151, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636743819414-i9xf', 'bv2-m8', 'Hur utlöses sträckreflexen?', 'Ett slag mot senan sträcker muskeln; muskelspolen signalerar via sensoriska neuron till ryggmärgens dorsalhorn, kopplas om till en alfa-motoneuron i ventralhornet som kontraherar muskeln. Reciprok hämning kan samtidigt ske.', 152, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636743976160-fzvp', 'bv2-m8', 'Hur undersöker man Babinskis tecken?', 'Man drar reflexhammarens spetsiga del mot fotsulan från hälen via fotvalvet upp mot främre fotsulan.', 153, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636744024570-gbaf', 'bv2-m8', 'Hur tolkas Babinskis tecken?', 'Positivt: stortån dorsalflexas (böjs uppåt). Negativt (normalt): stortån plantarflexas (böjs nedåt).', 154, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636745190211-v3rp', 'bv2-m8', 'Vad är systematisk kognitiv forcering?', 'Att vid varje diagnostiskt beslut medvetet använda strategier som minskar påverkan av bias, t.ex. att överväga alternativ.', 155, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636745268042-499s', 'bv2-m8', 'Vad innebär explicit bias?', 'Våra medvetna fördomar och föreställningar.', 156, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636745296878-pk4q', 'bv2-m8', 'Vad innebär implicit bias?', 'Våra omedvetna fördomar och föreställningar.', 157, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636745610952-qv0h', 'bv2-m8', 'Vilken typ av bias utgör en större risk för det diagnostiska arbetet?', 'Implicit bias är antagligen en större risk eftersom det är omedvetet.', 158, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636745754123-k342', 'bv2-m8', 'Vad är det bra om vi kan göra om implicit bias till?', 'Det är bra om vi kan göra om implicit bias till explicit bias, eller helt bli av med bias.', 159, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('anki-1636745792920-3kgm', 'bv2-m8', 'Hur måste vi hantera implicit bias?', 'Vi utgår ifrån att de allra flesta har implicit bias och måste därför ha systematiska sätt att hantera detta.', 160, 'anki-ai')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv3-m1-c1', 'bv3-m1', 'Vilka delar har plexus brachialis?', 'Rötter (C5–Th1), trunci, divisiones, funiklar och grenar. Viktiga nerver: axillaris, musculocutaneus, radialis, medianus och ulnaris.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv3-m1-c2', 'bv3-m1', 'Vad skiljer Erb-Duchennes från Klumpkes pares?', 'Erb: skada på övre rötterna C5–C6 → armen hänger i adduktion och inåtrotation (''waiter''s tip''). Klumpke: C8–Th1 → klomshand och ptos (Horner).', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv3-m1-c3', 'bv3-m1', 'Vilka strukturer passerar genom diafragma?', 'Aorta (hiatus aorticus, Th12), matstrupen och vagus (hiatus oesophageus, Th10) samt vena cava inferior (foramen venae cavae, Th8).', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv3-m1-c4', 'bv3-m1', 'Vad kännetecknar ljumskbråck anatomiskt?', 'Indirekt bråck går genom inre ljumskringen lateralt om inferiora epigastriska kärl; direkt bråck går medialt om dem genom trigonum Hesselbachi.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv3-m2-c1', 'bv3-m2', 'Vilka fyra grundvävnader finns och vad kännetecknar dem?', 'Epitel (täcker/utsöndrar, celltätt), bindväv (stöd, rik matrix), muskel (kontraktion) och nerv (signalering).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv3-m2-c2', 'bv3-m2', 'Vad skiljer exokrin från endokrin körtel?', 'Exokrin har utförsgång och utsöndrar till yta/lumen; endokrin saknar gång och utsöndrar hormoner till blodet.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv3-m2-c3', 'bv3-m2', 'Vilka lager bygger mag-tarmkanalens vägg?', 'Mukosa (epitel, lamina propria, muscularis mucosae), submukosa, muscularis externa och serosa/adventitia.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv3-m2-c4', 'bv3-m2', 'Vad är skillnaden mellan stroma och parenkym?', 'Parenkym = organets funktionella celler; stroma = stödjevävnad med bindväv, kärl och nerver.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv3-m3-c1', 'bv3-m3', 'Vilka tre delar har den patientcentrerade konsultationen?', 'Initiering (kontakt, patientens agenda), mitten (anamnes, undersökning, förklaring och plan) och avslutning (sammanfattning, förståelse, nästa steg).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv3-m3-c2', 'bv3-m3', 'Vad innebär basal hygien i vården?', 'Handdesinfektion före och efter patientkontakt, handskar vid risk för kroppsvätskor, kortärmat utan klockor och rent skyddsförkläde – bryter kontaktsmitta.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv3-m3-c3', 'bv3-m3', 'Vilka faktorer påverkar hälsa utöver biologin?', 'Sociala, ekonomiska och psykosociala faktorer samt genus och diskrimineringsgrunder – viktiga för ojämlik hälsa och bemötande.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv3-m3-c4', 'bv3-m3', 'Vad skiljer explicit, implicit och konfirmationsbias?', 'Explicit fördom är medveten; implicit är omedveten; konfirmationsbias är att bara söka information som bekräftar hypotesen.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m1-c1', 'bv4-m1', 'Vad bestämmer vilopotentialen?', 'Na+/K+-ATPasets elektrogena pump, läckage av K+ utåt och membranets relativt höga K+-permeabilitet – ger cirka −70 mV.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m1-c2', 'bv4-m1', 'Vad sker vid en synaps när aktionspotentialen når terminalen?', 'Ca2+ strömmar in via spänningsstyrda kanaler, vesiklar fusioneras med membranet och neurotransmittor frisätts i synaptiska kleften.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m1-c3', 'bv4-m1', 'Vilka är de viktigaste transmittorsystemen i CNS?', 'Glutamat (excitatoriskt), GABA (inhibitoriskt), dopamin, noradrenalin, serotonin och acetylkolin.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m1-c4', 'bv4-m1', 'Vad gör en återupptagshämmare (SSRI/SNRI)?', 'Blockerar återupptaget av serotonin (och noradrenalin) i synapskleften så att transmittorn verkar längre – effekten kommer först efter några veckor.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m2-c1', 'bv4-m2', 'Vilka banor leder beröring respektive smärta?', 'Beröring/ledsagning (dorsal column–medial lemniscus) korsar i medulla; smärta/temperatur (spinothalamiska) korsar i ryggmärgen.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m2-c2', 'bv4-m2', 'Hur fungerar hörseltransduktionen?', 'Ljudvågor → trumhinna → ossikler → ovala fönstret → vätskerörelse i cochlea → böjning av stereocilier på hårceller → depolarisering och nervsignal i n. cochlearis.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m2-c3', 'bv4-m2', 'Vad är gate control-teorin?', 'Beröring och tryck (Aβ-fibrer) kan hämma smärtsignaler (C/Aδ) i ryggmärgens bakre horn – grunden för TENS och för att gnugga ett ställe som gör ont.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m2-c4', 'bv4-m2', 'Var sitter luktreceptorerna och hur förmedlas lukt?', 'I luktepitelet högt i näshålan; axonerna går direkt till bulbus olfactorius och vidare till cortex utan att passera talamus.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m3-c1', 'bv4-m3', 'Vilken väg leder viljestyrda rörelser från cortex till alfa-motorneuron?', 'Pyramidbanan (tractus corticospinalis): cortex → capsula interna → decussatio pyramidum i medulla → laterala kortikospinala banan → alfa-motorneuron.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m3-c2', 'bv4-m3', 'Vad är en monosynaptisk reflex och ge exempel?', 'Endast en synaps mellan sensoriskt och motoriskt neuron – t.ex. knäreflexen (patellarreflexen) via L2–L4.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m3-c3', 'bv4-m3', 'Vad gör de basala ganglierna?', 'Modulerar och väljer motoriska program via direkta (aktiverande) och indirekta (hämmande) vägen; dysfunktion ger hypo- eller hyperkinetiska rörelsesjukdomar.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m3-c4', 'bv4-m3', 'Vad innebär spasticitet och var uppstår den?', 'Ökad muskeltonus med hastighetsberoende motstånd efter skada i centrala motorbanor (övre motorneuron), ofta med hyperreflexi och Babinski.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m4-c1', 'bv4-m4', 'Vilka funktioner räknas till exekutiva funktioner?', 'Planering, arbetsminne, impulskontroll, kognitiv flexibilitet och beslutsfattande – framför allt frontalloben.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m4-c2', 'bv4-m4', 'Vilken roll har amygdala?', 'Emotionell bearbetning, särskilt rädsla och hotdetektion samt emotionskoppling till minnen (t.ex. PTSD).', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m4-c3', 'bv4-m4', 'Vad skiljer arbetsminne från långtidsminne?', 'Arbetsminnet håller information aktivt i sekunder (prefrontalcortex), långtidsminnet lagras mer stabilt (kortikala nätverk, hippocampus för konsolidering).', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m4-c4', 'bv4-m4', 'Vad gör atypiska antipsykotika jämfört med klassiska?', 'Blockerar dopamin D2 men också serotonin 5-HT2A – mindre extrapyramidala biverkningar men mer metabola biverkningar.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m5-c1', 'bv4-m5', 'Vilka hormoner producerar hypofysens framlob?', 'GH, TSH, ACTH, FSH, LH och prolaktin – regleras av hypotalamiska releasing/inhibiting hormones och av negativ återkoppling från målorgan.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m5-c2', 'bv4-m5', 'Hur verkar tyreoideahormoner?', 'T3/T4 binder nukleära receptorer och ökar basalmetabolism, värmeproduktion, hjärtfrekvens och proteinsyntes. Jod krävs för syntesen.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m5-c3', 'bv4-m5', 'Vad kännetecknar Cushings syndrom?', 'Förhöjt kortisol: central fetma, månansikte, hypertoni, hyperglykemi, osteoporos, striae och hudatrofi.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m5-c4', 'bv4-m5', 'Vad är skillnaden mellan hormonell och neural reglering av binjuremärgen?', 'Binjuremärgen innerveras direkt av sympatiska preganglionära fibrer och frisätter adrenalin/noradrenalin vid stress – en neural, inte hypofysstyrd, väg.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m6-c1', 'bv4-m6', 'Vilka kärl ingår i circle of Willis?', 'A. cerebri anterior, a. cerebri media, a. communicans anterior och posterior samt a. cerebri posterior – sammankopplade via a. basilaris och a. carotis interna.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m6-c2', 'bv4-m6', 'Var bildas cerebrospinalvätskan och var cirkulerar den?', 'I plexus choroideus i ventriklarna; cirkulerar via ventriklarna och subarachnoidalrummet och resorberas i arachnoideavilli.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m6-c3', 'bv4-m6', 'Vad kännetecknar en övre respektive nedre motorneuronskada?', 'Övre: spasticitet, hyperreflexi, Babinski, ingen atrofi. Nedre: slapphet, atrofi, fascikulationer, areflexi.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv4-m6-c4', 'bv4-m6', 'Vad gör sympatikus i kroppen?', 'Kamp/flykt: ökad hjärtfrekvens och blodtryck, bronkdilatation, pupilldilatation, minskad tarmmotorik, frisättning av adrenalin från binjuremärgen.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m1-c1', 'bv5-m1', 'Vad är skillnaden mellan farmakokinetik och farmakodynamik?', 'Farmakokinetik = vad kroppen gör med läkemedlet (ADME). Farmakodynamik = vad läkemedlet gör med kroppen (verkningsmekanism, dos–respons).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m1-c2', 'bv5-m1', 'Vad menas med halveringstid och vad styr den?', 'Tiden till halva plasmakoncentrationen; avgörs av clearance och distributionsvolym. Vid cirka 4–5 halveringstider har steady state nåtts.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m1-c3', 'bv5-m1', 'Vilka fyra huvudmekanismer har antibiotika?', 'Cellväggssyntes (betalaktamer, glykopeptider), proteinsyntes (aminoglykosider, tetracykliner), DNA/RNA (kinoloner, rifampicin) och folsyrasyntes (sulfa/trimetoprim).', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m1-c4', 'bv5-m1', 'Vad gör en immunsuppressiv respektive immunmodulerande behandling?', 'Immunsuppression dämpar immunsvaret (t.ex. vid transplantation, autoimmun sjukdom); immunmodulering justerar svaret (t.ex. interferon, checkpoint-hämmare).', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m2-c1', 'bv5-m2', 'Vad är excitation–kontraktion-koppling i skelettmuskeln?', 'Aktionspotential → T-tubuli → Ca2+ frisätts från sarkoplasmatiskt retiklet → Ca2+ binder troponin C → tropomyosin flyttas → aktin–myosinkorsbryggor cyklar → kontraktion.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m2-c2', 'bv5-m2', 'Vilka fyra hjärtljud och vad motsvarar de?', 'S1 (mitralis/trikuspidalis stängs), S2 (aorta/pulmonalis stängs), S3 (tidig snabb fyllnad, kan vara normal hos unga) och S4 (förmakskontraktion).', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m2-c3', 'bv5-m2', 'Vad är skillnaden mellan HFrEF och HFpEF?', 'HFrEF = nedsatt ejektionsfraktion med dilaterad vänster kammare; HFpEF = bevarad EF med diastolisk dysfunktion och stel kammare, vanligare hos äldre med hypertoni.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m2-c4', 'bv5-m2', 'Vad gör loop-diuretika?', 'Hämmar Na+/K+/2Cl−-transportören i tjocka uppåtstigande Henles slynga → kraftig diures, minskad preload. Biverkningar: hypokalemi, hypomagnesemi, ototoxicitet.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m3-c1', 'bv5-m3', 'Vad ingår i blodets buffertsystem och vad transporterar hemoglobin?', 'Bikarbonat (viktigast), fosfat och proteiner buffrar pH; hemoglobin transporterar syre och en del CO2 (som karbaminohemoglobin) och buffrar H+.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m3-c2', 'bv5-m3', 'Vad är skillnaden mellan primär och sekundär hemostas?', 'Primär: kärlkontraktion och trombocytplugg (sekunder, vWF). Sekundär: koagulationskaskad med fibrinbildning (minuter). Fibrinolys löser upp koaglet.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m3-c3', 'bv5-m3', 'Vilka faktorer påverkar slagvolymen?', 'Preload (fyllnad), afterload (motstånd) och kontraktilitet. Hjärtminutvolym = slagvolym × hjärtfrekvens.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m3-c4', 'bv5-m3', 'Vad kännetecknar anemi med lågt MCV respektive högt MCV?', 'Lågt MCV (mikrocytär): järnbrist, talassemi. Högt MCV (makrocytär): B12-/folatbrist, alkohol, myelodysplasi.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m4-c1', 'bv5-m4', 'Vad driver inandningen?', 'Diafragma (n. phrenicus) och yttre interkostalmuskler sänker pleuratrycket så att lungorna expanderar – inandning är aktiv, utandning passiv vid vila.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m4-c2', 'bv5-m4', 'Vad är dead space och när ökar det?', 'Ventilerad luft som inte deltar i gasutbytet (anatomiskt + alveolärt). Ökar vid lungemboli, hypoperfusion och vid stora tidalvolymer.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m4-c3', 'bv5-m4', 'Vad styr andningsdrivet?', 'Centrala kemoreceptorer i medulla reagerar på pCO2/pH (viktigast), perifera i glomus caroticum/aorticum på pO2. Andningen ökar vid acidos och hypoxi.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m4-c4', 'bv5-m4', 'Vad visar en spirometri vid obstruktiv respektive restriktiv sjukdom?', 'Obstruktiv: sänkt FEV1/FVC (<0,7), t.ex. KOL och astma. Restriktiv: normalt eller högt FEV1/FVC men sänkt FVC/total lungkapacitet.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m5-c1', 'bv5-m5', 'Var reabsorberas största delen av filtratet och vad driver det?', 'I proximala tubuli (cirka 65 procent) via Na+/K+-ATPas i basolateralmembranet; glukos och aminosyror via sekundär aktiv transport.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m5-c2', 'bv5-m5', 'Hur koncentreras urinen i Henles slynga?', 'Motströmsmekanism: nedåtstigande delen är vattenpermeabel men inte saltpermeabel, uppåtstigande pumpar ut salt – skapar en osmotisk gradient som ADH kan utnyttja i samlingsröret.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m5-c3', 'bv5-m5', 'Vad gör ADH i njuren?', 'Ökar insättandet av aquaporin-2 i samlingsrörets celler → mer vatten reabsorberas → koncentrerad urin och minskad urinvolym. Brist ger diabetes insipidus.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv5-m5-c4', 'bv5-m5', 'Hur reglerar njuren syra-bas-balansen?', 'Utsöndrar H+ (via buffertar som fosfat och ammonium), reabsorberar filtrerat bikarbonat och nybildar bikarbonat – kompensationen tar timmar till dygn.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m1-c1', 'bv6-m1', 'Vilka huvudgrupper av mikroorganismer finns?', 'Bakterier (prokaryoter), virus (icke-cellulära), svampar och protozoer (eukaryoter) samt helminter (maskar).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m1-c2', 'bv6-m1', 'Vad är skillnaden mellan exotoxin och endotoxin?', 'Exotoxin utsöndras av bakterien, ofta värmekänsligt och mycket potent (t.ex. tetanustoxin). Endotoxin är LPS i Gramnegativa yttermembran, värmestabilt och ger feber och septisk chock.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m1-c3', 'bv6-m1', 'Vilka smittvägar finns?', 'Kontakt (direkt/indirekt), droppsmitta, luftsmitta, fekal-oral, blod/sexuell kontakt samt vektoröverförd (mygga, fästing).', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m1-c4', 'bv6-m1', 'Vad menas med mikrobiota och varför är den viktig?', 'Den naturliga bakteriefloran på hud och slemhinnor; skyddar mot patogener (kolonisationsresistens), bildar vitaminer och påverkar immunförsvar och metabolism.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m2-c1', 'bv6-m2', 'Vilka är de fem Plasmodium-arterna som smittar människa och vilken är farligast?', 'P. falciparum (farligast, cerebral malaria), P. vivax, P. ovale, P. malariae och P. knowlesi.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m2-c2', 'bv6-m2', 'Vad menas med DALY i global hälsa?', 'Funktionsjusterade levnadsår – summan av förlorade levnadsår vid förtidig död och år levda med funktionsnedsättning; används för att jämföra sjukdomsbörda.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m2-c3', 'bv6-m2', 'Vilka åtgärder förebygger tuberkulosspridning?', 'Tidig diagnostik (sputum-PCR, IGRA), luftsmittsisolering med FFP3, kontaktspårning och BCG-vaccin till riskgrupper.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m2-c4', 'bv6-m2', 'Vad kännetecknar dengue och vilket varningstecken är allvarligt?', 'Aedes-överförd flavivirus med hög feber, muskelsmärta och utslag; varningsstecken är blödningar, trombocytopeni, plasmalläckage och buksmärta (dengue shock).', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m3-c1', 'bv6-m3', 'Vilka huvudprinciper finns för antibiotikabehandling?', 'Rätt indikation, rätt preparat (smalspektrum när möjligt), rätt dos och duration, samt odling innan behandling när det är möjligt.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m3-c2', 'bv6-m3', 'Vad är skillnaden mellan baktericid och bakteriostatisk effekt?', 'Baktericid dödar bakterien (betalaktamer, aminoglykosider); bakteriostatisk hämmar tillväxten så att immunförsvaret kan ta hand om den (tetracykliner, makrolider).', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m3-c3', 'bv6-m3', 'Vilka vaccintyper finns?', 'Levande försvagade (MMR, BCG), inaktiverade (hepatit A, influensa), toxoid (stelkramp, difteri), subenhets-/konjugatvaccin (Hib, pneumokocker) samt mRNA-vaccin.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m3-c4', 'bv6-m3', 'Hur diagnostiseras en tarmpatogen i laboratoriet?', 'Odlings-PCR-panel på feces (t.ex. Salmonella, Campylobacter, EHEC, C. difficile-toxin), ibland odling med resistensbestämning.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m4-c1', 'bv6-m4', 'Vilka barnsjukdomar ingår i det svenska vaccinationsprogrammet och vad ger de?', 'Mässling, påssjuka, röda hund (MMR), vattkoppor, difteri, stelkramp, kikhosta, polio, Hib, pneumokocker, hepatit B och HPV – skyddar mot allvarliga komplikationer.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m4-c2', 'bv6-m4', 'Vad skiljer samhällsförvärvad från sjukhusförvärvad pneumoni?', 'Samhällsförvärvad: oftast pneumokocker, mykoplasma, influensa. Sjukhusförvärvad: resistenta gramnegativa bakterier och S. aureus – kräver bredare behandling.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m4-c3', 'bv6-m4', 'Vad är impetigo och hur behandlas det?', 'Ytlig hudinfektion med gula krustor, oftast stafylokocker eller streptokocker. Lokal behandling med fusidinsyra eller retapamulin; peroral antibiotika vid omfattande engagemang.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m4-c4', 'bv6-m4', 'Vilka parasitsjukdomar är vanliga i Sverige respektive tropikerna?', 'Sverige: fästingburen borrelia och TBE, springmask. Tropikerna: malaria, schistosomiasis, strongyloidiasis, giardia och trypanosomiasis.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m5-c1', 'bv6-m5', 'Hur diagnosticeras bakteriell meningit?', 'Lumbalpunktion: celltal (neutrofil pleocytos), glukos (lågt i förhållande till plasma), protein (högt) samt odling/PCR. Blododling och snabb-PCR tas samtidigt.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m5-c2', 'bv6-m5', 'Vad kännetecknar borrelia respektive TBE?', 'Borrelia (Borrelia burgdorferi) ger erytema migrans och kan ge neuroborrelios; TBE är ett virus som ger hjärninflammation – vaccin finns mot TBE men inte mot borrelia.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m5-c3', 'bv6-m5', 'Vilka är de viktigaste sexuellt överförbara infektionerna?', 'Klamydia, gonorré, syfilis, HIV, HPV, herpes simplex och hepatit B – testning, kondom och vaccination (HPV, hepatit B) förebygger.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('bv6-m5-c4', 'bv6-m5', 'Vad är ett prion och vilken sjukdom ger det?', 'Ett felaktigt veckat protein utan nukleinsyra som sprider veckningsfelet i hjärnan – ger Creutzfeldt-Jakobs sjukdom med snabbt progredierande demens.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-1-c1', 'km1-1', 'Vilka steg ingår i ABCDE?', 'Airway (fria luftvägar), Breathing (andning och syresättning), Circulation (puls, blodtryck, perfusion), Disability (medvetande, GCS, pupiller) och Exposure (helkroppsundersökning, temperatur). Varje steg åtgärdas innan nästa påbörjas.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-1-c2', 'km1-1', 'Vilka fyra chocktyper finns?', 'Hypovolem (blödning, vätskeförlust), kardiogen (pumpsvikt), distributiv (septisk, anafylaktisk, neurogen) och obstruktiv (hjärttamponad, spänningsthorax, massiv lungemboli).', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-1-c3', 'km1-1', 'Vilka är de tidiga kliniska tecknen på chock?', 'Takykardi, kalla och marmorerade extremiteter, förlängd kapillär återfyllnad, oliguri, oro eller förvirring och stigande andningsfrekvens. Blodtrycksfall är ett sent tecken.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-1-c4', 'km1-1', 'Vad kännetecknar spänningsthorax och hur behandlas det?', 'Ensidig avsaknad av andningsljud, distenderade halsvener, hypotension och trakealförskjutning. Behandling är omedelbar nål­dekompression följt av thoraxdrän.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-1-c5', 'km1-1', 'Varför mäts laktat vid chock?', 'Förhöjt laktat speglar vävnadshypoperfusion och används både diagnostiskt och för att följa effekten av återupplivningen.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-1-c6', 'km1-1', 'Vilka kvalitetsmål finns vid vuxen-HLR?', 'Kompressioner 5–6 cm djupa, frekvens 100–120/min, fullständig utlösning mellan kompressionerna, avbrott under 10 sekunder och byte av komprimerande person varannan minut.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-2-c1', 'km1-2', 'Vilka EKG-avledningar motsvarar vilka väggar?', 'V1–V4 framväggen (LAD), II, III och aVF inferiorväggen (RCA), I och aVL lateralt (LCx). Spegelvända ST-sänkningar i motsatta avledningar stöder diagnosen.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-2-c2', 'km1-2', 'Vad står NYHA-klass I–IV för?', 'I: ingen begränsning. II: lätt begränsning vid måttlig ansträngning. III: påtaglig begränsning vid lätt ansträngning. IV: symtom i vila.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-2-c3', 'km1-2', 'Vilka är de fyra prognosförbättrande behandlingspelarna vid HFrEF?', 'ACE-hämmare/ARB (eller ARNI), betablockerare, MRA (mineralokortikoidreceptorantagonist) och SGLT2-hämmare. Diuretika ges symtomatiskt vid kongestion.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-2-c4', 'km1-2', 'Vad ingår i CHA2DS2-VASc?', 'Hjärtsvikt, hypertoni, ålder (65–74 respektive ≥75 år), diabetes, stroke/TIA/tromboembolism, kärlsjukdom och kvinnligt kön. Poängen styr indikationen för antikoagulation.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-2-c5', 'km1-2', 'Vilken klassisk triad har aortastenos?', 'Angina pectoris, synkope vid ansträngning och dyspné – samt systoliskt utstrålande blåsljud mot karotiderna. Symtomatisk svår aortastenos behandlas med kirurgisk klaff eller TAVI.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-2-c6', 'km1-2', 'Vad kännetecknar HFpEF?', 'Hjärtsvikt med bevarad ejektionsfraktion: diastolisk dysfunktion, vänsterkammarhypertrofi, typiskt äldre kvinna med hypertoni och förmaksflimmer. SGLT2-hämmare har visad effekt.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-3-c1', 'km1-3', 'Vad är HbA1c ett mått på?', 'Genomsnittlig glukosnivå de senaste cirka två till tre månaderna, eftersom det speglar glykeringen av hemoglobin under erytrocytens livslängd.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-3-c2', 'km1-3', 'Hur skiljer man diabetesketoacidos från hyperosmolärt tillstånd?', 'DKA: ketoner, acidos, buksmärta, Kussmaul-andning, vanligen typ 1-diabetes. HHS: uttalad hyperglykemi och hyperosmolalitet utan betydande ketoacidos, typiskt äldre med typ 2-diabetes.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-3-c3', 'km1-3', 'Vad är tyreostatika och vad är risken?', 'Tionamider (metimazol, propyltiouracil) hämmar tyreoidea peroxidas och hormon­syntesen. Risken är agranulocytos – feber och halsont ska föranleda provtagning.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-3-c4', 'km1-3', 'Hur behandlas Graves sjukdom på sikt?', 'Tyreostatika i första hand, alternativt radiojod eller kirurgi. Betablockerare ges symtomatiskt; rökstopp är viktigt eftersom rökning ökar risken för tyreoideaassocierad oftalmopati.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-3-c5', 'km1-3', 'Vad kännetecknar primär hyperaldosteronism (Conns syndrom)?', 'Hypertoni med hypokalemi och metabol alkalos, lågt renin och högt aldosteron. Behandlas med kirurgi vid adenom eller mineralokortikoidreceptorantagonist.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-3-c6', 'km1-3', 'Vad är akut binjurebarkskris?', 'Livshotande kortisolbrist med hypotension, hyponatremi, hyperkalemi och feber, ofta utlöst av infektion. Behandlas omedelbart med intravenöst glukokortikoid och vätska.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-4-c1', 'km1-4', 'Vad skiljer astma från KOL spirometriskt?', 'Astma: variabel och reversibel obstruktion, ofta normaliserad FEV1/FVC mellan skoven. KOL: persistent obstruktion med FEV1/FVC under 0,7 efter bronkdilatation, vanligen hos rökare.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-4-c2', 'km1-4', 'Varför är LABA monoterapi kontraindicerat vid astma?', 'Utan inflammationshämning ökar risken för svåra exacerbationer och astmarelaterad död. LABA ska alltid kombineras med inhalationssteroider.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-4-c3', 'km1-4', 'Vad mäter PEF-variabilitet?', 'Dygnsvariationen i luftflöde; ökad variabilitet stöder astmadiagnos och används för att följa sjukdomskontroll.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-4-c4', 'km1-4', 'Vad används CURB-65 till?', 'Riskbedömning vid samhällsförvärvad pneumoni utifrån konfusion, urea, andningsfrekvens, blodtryck och ålder ≥65 år – underlag för vem som kan behandlas i hemmet.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-4-c5', 'km1-4', 'Vilka är symtom på anafylaxi?', 'Akut debut med urtikaria, angioödem, stridor, bronkospasm, buksmärtor och hypotension efter exponering för allergen, läkemedel eller insektsstick.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-4-c6', 'km1-4', 'Vad är viktigast i KOL-behandlingen utöver rökstopp?', 'Bronkdilaterare (LAMA/LABA), vaccinationer, fysisk träning och nutrition; inhalationssteroider endast vid upprepade exacerbationer eller astma-KOL-överlapp.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-5-c1', 'km1-5', 'Vilka tre kategorier av akut njurskada finns?', 'Prerenal (hypoperfusion, t.ex. dehydrering eller hjärtsvikt), renal (akuta tubulär nekros, glomerulonefrit, interstitiell nefrit) och postrenal (obstruktion, t.ex. prostatahyperplasi eller dubbelsidig sten).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-5-c2', 'km1-5', 'Vad skiljer nefrotiskt från nefritiskt syndrom?', 'Nefrotiskt: stor proteinuri, hypoalbuminemi, ödem, hyperlipidemi. Nefritiskt: hematuri med dysmorfa erytrocyter, erytrocytcylindrar, hypertoni och oliguri.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-5-c3', 'km1-5', 'I vilken ordning behandlas svår hyperkalemi?', '1) Kalcium för membranstabilisering, 2) insulin-glukos och beta2-agonist för intracellulär förflyttning, 3) elimination via kalciumbindare, loopdiuretika eller dialys.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-5-c4', 'km1-5', 'Vilka indikationer finns för akut dialys?', 'AEIOU: Acidose, Elektrolytrubbning (refraktär hyperkalemi), Intoxikation, Overload (volymöverbelastning) och Uremi (encefalopati, perikardit).', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-5-c5', 'km1-5', 'Hur indelas kronisk njursjukdom?', 'Utifrån eGFR-stadium G1–G5 och albuminuri A1–A3. Diagnosen kräver nedsatt njurfunktion eller skademarkör under minst tre månader.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-5-c6', 'km1-5', 'Varför ger njursvikt anemi?', 'Minskad produktion av erytropoetin från njurarnas fibroblaster leder till normocytär normokrom anemi; järnbrist och inflammation bidrar också.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-6-c1', 'km1-6', 'Vad ingår i Child-Pugh-klassificeringen?', 'Bilirubin, albumin, INR/protrombintid, ascites och encefalopati. Används för att skatta prognos och operativ risk vid levercirros.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-6-c2', 'km1-6', 'Hur förebyggs varicerblödning vid portahypertension?', 'Icke-selektiv betablockad (propranolol, karvedilol) eller endoskopisk varicebehandling som primärprofylax; vid akut blödning ges vasoaktiv behandling, antibiotikaprofylax och endoskopisk åtgärd.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-6-c3', 'km1-6', 'Vad är hepatisk encefalopati och hur behandlas den?', 'Neuropsykiatriska symtom vid nedsatt leverfunktion med ökad ammoniakbelastning. Behandling: laktulos och vid behov rifaximin samt åtgärdande av utlösande orsak (infektion, blödning, förstoppning).', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-6-c4', 'km1-6', 'Hur skiljer sig Crohns sjukdom från ulcerös kolit?', 'Crohn: diskontinuerlig, transmural inflammation, engagerar hela GI-kanalen och kan ge fistlar och strikturer. Ulcerös kolit: kontinuerlig slemhinneinflammation från rektum och proximalt, typiskt blodig diarré.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-6-c5', 'km1-6', 'Vad kännetecknar akut kolecystit?', 'Ihållande högersidig buksmärta, feber och positivt Murphys tecken, ofta efter gallstensanfall. Behandling är antibiotika och tidig kolecystektomi.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-6-c6', 'km1-6', 'Vilka är de viktigaste prognosfaktorerna vid akut pankreatit?', 'Organsvikt och förekomst av nekros; CRP-stegring och sjunkande saturation/trombocyter samt klinisk försämring inom första dygnet indikerar svår sjukdom.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-7-c1', 'km1-7', 'Hur skiljer man järnbrist från anemi vid kronisk sjukdom?', 'Järnbrist: lågt ferritin, låg transferrinmättnad, högt lösligt transferrinreceptor. Kronisk sjukdom: ferritin normalt eller högt (akutfasprotein), låg transferrinmättnad.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-7-c2', 'km1-7', 'Vad säger retikulocyter vid anemi?', 'Höga retikulocyter talar för ökad produktion och perifer förlust/blödning eller hemolys; låga talar för produktionsbrist i benmärgen.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-7-c3', 'km1-7', 'Vilka symtom ger akut leukemi?', 'Trötthet och infektioner på grund av cytopenier, blåmärken och blödningar, bendömhet samt eventuellt gingivahypertrofi. Diagnos via benmärgsundersökning med blastceller.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-7-c4', 'km1-7', 'Vad kännetecknar Hodgkins lymfom?', 'Reed-Sternberg-celler, typisk åldersfördelning med toppar unga vuxna och äldre, samt B-symtom (feber, nattliga svettningar, viktminskning). Ofta god prognos.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-7-c5', 'km1-7', 'Vad är skillnaden mellan warfarin och DOAK?', 'Warfarin hämmar vitamin K-beroende faktorer (II, VII, IX, X) och kräver INR-kontroll; DOAK hämmar trombin eller faktor Xa direkt och kontrolleras inte rutinmässigt men har begränsningar vid svår njursvikt.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-7-c6', 'km1-7', 'Vilka är vanliga orsaker till trombocytopeni?', 'Minskad produktion (benmärgssvikt, läkemedel), ökad nedbrytning (ITP, TTP, HIT) och sekestation (stor mjälte). HIT misstänks vid trombocytfall efter heparinbehandling.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-8-c1', 'km1-8', 'Vilka prover är centrala vid misstänkt reumatoid artrit?', 'SR/CRP, RF och anti-CCP (anti-CCP är mer specifikt), samt röntgen och ultraljud av händer/fötter för att påvisa synovit och erosioner.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-8-c2', 'km1-8', 'Vad kännetecknar artros?', 'Mekaniskt betingad värk som förvärras vid belastning, kort morgonstelhet, engagemang av DIP-leder och knän/ höfter, osteofyter och minskad ledspalt på röntgen.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-8-c3', 'km1-8', 'Hur skiljer man gikt från pseudogikt?', 'Gikt: monosodiumuratkristaller (nålformade, negativt dubbelbrytande), ofta MTP I. Pseudogikt: kalciumpyrofosfat (rhomboida, positivt dubbelbrytande), ofta knä, med kondrokalcinos på röntgen.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-8-c4', 'km1-8', 'Vad är polymyalgia rheumatica?', 'Symmetrisk värk och stelhet i skuldror och höfter hos äldre, kraftigt förhöjd SR/CRP och snabb respons på låg dos glukokortikoid. Ofta överlappande med jättecellsarterit.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-8-c5', 'km1-8', 'Vilka fynd talar för SLE?', 'ANA hos nästan alla, anti-dsDNA och anti-Sm mer specifika, tillsammans med hudutslag, artrit, serosit, cytopenier och njurengagemang (lupusnefrit).', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km1-8-c6', 'km1-8', 'Vilka är de viktigaste riskfaktorerna för osteoporos?', 'Hög ålder, kvinnligt kön och postmenopausal tid, långvarig glukokortikoidbehandling, rökning, låg BMI, immobilisering och tidigare fraktur. DXA T-score ≤ −2,5 definierar osteoporos.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-1-c1', 'km2-1', 'Vad skiljer delirium från demens?', 'Delirium: akut debut (timmar–dagar), fluktuerande, nedsatt uppmärksamhet, ofta synhallucinationer och omvänd sömnrytm. Demens: smygande debut över månader–år, stabilt progredierande, uppmärksamheten relativt bevarad tidigt.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-1-c2', 'km2-1', 'Vilka är de vanligaste utlösande orsakerna till delirium?', 'Infektion, läkemedel (särskilt antikolinergika och bensodiazepiner), elektrolytrubbning, smärta, urinretention, förstoppning, sömnbrist och sensorisk deprivation.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-1-c3', 'km2-1', 'Vad innebär skörhet (frailty)?', 'Nedsatt fysiologisk reserv med ökad sårbarhet; bedöms med gångtid, greppstyrka, viktnedgång, uttröttbarhet och aktivitetsnivå. Predicerar fall, sjukhusinläggning och död.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-1-c4', 'km2-1', 'Varför får äldre starkare läkemedelseffekter?', 'Minskad muskelmassa och kroppsvatten ökar koncentrationen av vattenlösliga läkemedel, njur- och leverfunktion avtar och ökad fettandel förlänger halveringstiden för fettlösliga läkemedel.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-1-c5', 'km2-1', 'Vad är poängen med läkemedelsgenomgång enligt STOPP/START?', 'STOPP identifierar olämpliga läkemedel hos äldre (t.ex. långverkande bensodiazepiner, antikolinergika), START identifierar underbehandling (t.ex. saknad statin eller bensodiazepin vid indikation).', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-1-c6', 'km2-1', 'Hur förebyggs trycksår?', 'Riskbedömning (t.ex. Norton), lägesändring, tryckavlastning, hudvård och nutrition. Trycksår uppstår av ischemi i vävnad utsatt för tryck och skjuvkrafter.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-2-c1', 'km2-2', 'Hur definieras sepsis och septisk chock enligt Sepsis-3?', 'Sepsis: livshotande organdysfunktion på grund av dysreglerat svar på infektion (ökning i SOFA ≥2 poäng). Septisk chock: hypotension som kräver vasopressor för att nå målet trots adekvat vätsketillförsel, med förhöjt laktat.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-2-c2', 'km2-2', 'Vilka agens dominerar vid infektiös endokardit?', 'Streptokocker, Staphylococcus aureus och enterokocker; koagulasnegativa stafylokocker vid protesklaffar. Blododlingar tas från flera olika punktioner före antibiotika.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-2-c3', 'km2-2', 'Vad kännetecknar bakteriell meningit i likvor?', 'Högt cellantal med neutrofil dominans, högt protein, lågt glukos och positiv gramfärgning eller odling.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-2-c4', 'km2-2', 'Hur diagnosticeras latent tuberkulos?', 'Med IGRA eller tuberkulinprov; aktiv sjukdom krävs för att starta behandling, och diagnosen stöds av röntgen, mikroskopi, PCR och odling.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-2-c5', 'km2-2', 'När ska hivtest erbjudas?', 'Vid tecken på serokonversion, oklar långdragen feber, opportunistiska infektioner, vid sexuell exponering samt rutinmässigt vid graviditet och vid många andra infektioner.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-2-c6', 'km2-2', 'Vad är PEP vid hiv?', 'Postexpositionsprofylax med antiretrovirala läkemedel som startas så snabbt som möjligt efter exponering – effekten avtar snabbt med tiden och den ska erbjudas utan dröjsmål.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-3-c1', 'km2-3', 'Vad står ABCD(E) för vid melanommisstanke?', 'Asymmetri, Border (oregelbunden kant), Color (varierande färg), Diameter över 6 mm samt Evolution (förändring över tid).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-3-c2', 'km2-3', 'Vad kännetecknar basaliom?', 'Pärlglänsande papele med telangiektasier och rullande kant, ofta i solbelyst ansikte. Växer långsamt lokalt invasivt men metastaserar i princip inte.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-3-c3', 'km2-3', 'Vad kännetecknar skivepitelcancer i huden?', 'Hyperkeratotisk, ibland sårig och lättblödande lesion i solbelyst hud. Kan metastasera, särskilt vid högriskfynd som stor tjocklek eller lokalisation öra/läpp.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-3-c4', 'km2-3', 'Vad är den viktigaste basbehandlingen vid atopiskt eksem?', 'Daglig mjukgörande behandling för att återställa hudbarriären, kombinerat med topikala glukokortikoider vid inflammation och undvikande av irritanter.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-3-c5', 'km2-3', 'Vilka behandlingsprinciper gäller vid plackpsoriasis?', 'Topikala glukokortikoider och vitamin-D-analog vid lindrig sjukdom; ljusbehandling, metotrexat eller biologiska läkemedel vid måttlig till svår. Rökstopp och viktminskning har effekt.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-3-c6', 'km2-3', 'Vad är SJS/TEN?', 'Livshotande läkemedelsutlöst hudreaktion med utbredd epidermal nekros och slemhinneengagemang. Läkemedlet ska sättas ut omedelbart och patienten vårdas på brännskadeenhet.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-4-c1', 'km2-4', 'Hur verkar betalaktamantibiotika?', 'De binder penicillinbindande proteiner (transpeptidaser) och hämmar cellväggssyntesen, vilket ger baktericid effekt. Verkan kräver aktiv celldelning.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-4-c2', 'km2-4', 'Vilka fyra huvudmekanismer för antibiotikaresistens finns?', 'Enzymatisk inaktivering (betalaktamaser), förändrad målstruktur (PBP2a, ribosommutation), minskad upptag/permeabilitet och aktiv efflux av läkemedlet.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-4-c3', 'km2-4', 'Vilka biverkningar är typiska för aminoglykosider?', 'Nefrotoxicitet och ototoxicitet (både hörsel och balans). Verkar på 30S-subenheten och är baktericida; koncentrationen följs med läkemedelsanalys.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-4-c4', 'km2-4', 'Varför undviks kinoloner i första hand?', 'Bredspektrum med resistensdrivande effekt samt risk för tendinopati, QT-förlängning och påverkan på centrala nervsystemet. Används när andra alternativ saknas.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-4-c5', 'km2-4', 'Vad innebär rationell antibiotikaanvändning?', 'Rätt indikation, rätt preparat med smalast möjliga spektrum, rätt dos, rätt administrationsväg och kortast möjliga behandlingstid – samt omprövning när odlingssvar föreligger.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km2-4-c6', 'km2-4', 'Vad gör klindamycin vid toxinbildande infektioner?', 'Hämmar proteinsyntesen (50S) och därmed toxinproduktionen, vilket är en av anledningarna till dess roll vid allvarliga streptokock- och stafylokockinfektioner.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-1-c1', 'km3-1', 'Vilken är den vanligaste orsaken till mekanisk tunntarmsileus?', 'Adherenser efter tidigare bukkirurgi. Andra orsaker är bråck, tumör och inflammatorisk striktur.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-1-c2', 'km3-1', 'Hur skiljer man mekanisk ileus från paralytisk ileus på bukauskultationen?', 'Mekanisk ileus: först ökade, klingande (metalliska) tarmljud, senare tystnad vid utvecklad ischemi. Paralytisk ileus: tyst buk från början.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-1-c3', 'km3-1', 'Vad innebär positivt Blumberg-tecken?', 'Släppömhet – smärtan förvärras när handen snabbt lyfts från buken – vilket talar för peritonealinflammation.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-1-c4', 'km3-1', 'Vilka fyra klassiska tecken finns på akut appendicit?', 'Migrerande smärta från naveln till höger fossa, ömhet i McBurneys punkt, försvar/rebound och låggradig feber med lätt leukocytos.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-1-c5', 'km3-1', 'Vad kännetecknar akut mesenterial ischemi?', 'Svår buksmärta som är ''out of proportion'' mot ett relativt diskret bukstatus, förmaksflimmer eller kraftig ateroskleros i anamnesen, ofta förhöjt laktat och metabol acidos – kräver akut utredning med DT-angiografi.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-1-c6', 'km3-1', 'När ska en patient med gallstensanfall opereras?', 'Vid symtomgivande gallsten rekommenderas kolecystektomi, i regel inom samma vårdtillfälle vid kolecystit eftersom tidig operation minskar recidiv och komplikationer.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-2-c1', 'km3-2', 'Vad står ABCDE för i primär traumaomhändertagande?', 'Airway (med halsryggsskydd), Breathing, Circulation (blödningskontroll), Disability (neurologisk status, GCS) och Exposure (avklädning, temperatur).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-2-c2', 'km3-2', 'Varför ger en medial höftfraktur risk för caputnekros?', 'Blodförsörjningen sker huvudsakligen via a. circumflexa femoris medialis som löper intrakapsulärt; vid dislokation skadas den och caput femoris blir ischemiskt.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-2-c3', 'km3-2', 'Vilka är de tidiga tecknen på kompartmentsyndrom?', 'Oproportionerlig smärta, smärta vid passiv uttänjning, spänd och hård kammare samt parestesi. Pulslöshet är ett sent fynd.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-2-c4', 'km3-2', 'Vad är ett öppet bråck och varför är det akut?', 'Ett bråck där tarm tömmer sig via huden. Vid inkärkning/strangulation uppstår ischemi – tecken är tilltagande smärta, hård och öm bråckport samt ileussymtom.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-2-c5', 'km3-2', 'Hur skiljer man en distorsion från en fraktur i fotleden?', 'Ottawas regler avgör behovet av röntgen: ömhet över bakre malleolrand, laterala malleolen eller os naviculare, oförmåga att stödja fyra steg. Fraktur misstänks vid felställning, punktömhet över ben och stödjelösa patienter.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-2-c6', 'km3-2', 'Varför ska en fraktur stabiliseras och belastas tidigt?', 'Stabil, tidig belastning stimulerar benläkning (mekanisk signalering) och minskar risken för immobiliseringskomplikationer som DVT, trycksår och ledstelhet.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-3-c1', 'km3-3', 'Vad bedömer ASA-klassificeringen?', 'Patientens fysiska status och komorbiditet inför anestesi, från ASA I (frisk) till ASA V (moribund) samt ASA VI (organdonator). Den säger inget om själva ingreppets omfattning.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-3-c2', 'km3-3', 'Vilka är de tre komponenterna i generell anestesi?', 'Hypnos (sömn), analgesi (smärtlindring) och muskelrelaxation, ofta kombinerat med kontrollerad ventilation.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-3-c3', 'km3-3', 'Varför ger cytostatika och opioidbehandling perioperativa problem?', 'Opioider ger andningsdepression, obstipation och tolerans; cytostatika kan ge påverkan på sårläkning, benmärg och hjärtfunktion.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-3-c4', 'km3-3', 'Vad är den viktigaste skillnaden mellan spinal- och epiduralanestesi?', 'Spinal ges i subaraknoidalrummet med snabb, djup blockad; epidural ges utanför dura i epiduralrummet med kateter för kontinuerlig blockad. Båda ger sympatikusblockad med blodtrycksfall.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-3-c5', 'km3-3', 'Vilka är de vanligaste postoperativa komplikationerna?', 'Smärta, illamående (PONV), hypotermi, urinretention, sårinfektion, atelektas/pneumoni och venös tromboembolism.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-3-c6', 'km3-3', 'Vad innebär ERAS-konceptet?', 'Enhanced Recovery After Surgery: evidensbaserad perioperativ vård med kort fasta, opioidbesparande analgesi, tidig mobilisering och tidigt födointag för att minska komplikationer och vårdtid.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-4-c1', 'km3-4', 'Vilka symtom är typiska vid godartad prostatahyperplasi?', 'Försvagad stråle, startbesvär, nokturi, täta trängningar och känsla av ofullständig tömning. Symtomen kallas LUTS och graderas med IPSS.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-4-c2', 'km3-4', 'Varför är feber vid njurstensobstruktion ett akut tillstånd?', 'Obstruktion med infektion ger pyonefros och risk för urosepsis. Behandlingen är omedelbar avlastning av urinvägen, inte bara antibiotika.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-4-c3', 'km3-4', 'Vilka är de klassiska tecknen på testistorsion?', 'Plötslig svår ensidig skrotalsmärta, högställd och tvärställd testikel, saknad cremasterreflex, illamående och svullnad. Exploration utan dröjsmål.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-4-c4', 'km3-4', 'Vad är ett normalt PSA och vad kan förhöja det förutom cancer?', 'PSA är ett prostataspecifikt men inte cancerspecifikt protein. Förhöjning ses även vid prostatahyperplasi, prostatit, efter kateterisering, cykling och ejakulation.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-4-c5', 'km3-4', 'Vilka är de vanligaste stenarna i urinvägarna?', 'Kalciumoxalatstenar är vanligast, därefter urat-, fosfat- och struvitstenar. Struvit (magnesiumammoniumfosfat) förknippas med ureasproducerande bakterier och infektion.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-4-c6', 'km3-4', 'Vad är akut urinretention och hur handläggs den?', 'Plötslig oförmåga att tömma blåsan med smärta och palpabel blåsa. Avlastas med kateter; orsaker är bland annat prostatahyperplasi, blodpropp i blåsan och läkemedel med antikolinerg effekt.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-5-c1', 'km3-5', 'Vad innebär begreppet ''de sex P'' vid akut extremitetsischemi?', 'Pain, Pallor, Pulselessness, Paresthesia, Paralysis och Perishing cold (ibland även polar). Tidiga tecken är smärta och blekhet; paralys och kalla muskler är sena och allvarliga.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-5-c2', 'km3-5', 'Vilka riskfaktorer finns för bukaortaaneurysm?', 'Manligt kön, hög ålder, rökning, hypertoni och ateroskleros. Rökstopp är den viktigaste enskilda åtgärden för att bromsa tillväxten.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-5-c3', 'km3-5', 'Hur skiljer man arteriellt sår från venöst bensår?', 'Arteriellt: lokaliserat på tå/häl, torrt, blekt botten, dåliga pulsar, smärtsamt. Venöst: kring malleolerna, fuktigt, hyperpigmentering och ödem, oftast smärtfattigt.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-5-c4', 'km3-5', 'Vad är venös insufficiens och varför uppstår ödem?', 'Otillräckliga klaffar i djupa eller superficiala vener ger venstas med ökat kapillärtryck och läckage av vätska. Behandling är kompression och elevation.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km3-5-c5', 'km3-5', 'Varför är diabetesfoten en kärlkirurgisk patient?', 'Diabetes ger både makroangiopati och neuropati; kombinationen leder till trycksår, infektioner och högt amputationrisiko. Bedömning av perfusion är avgörande innan revision.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-1-c1', 'km4-1', 'Vad ingår i en strukturerad neurologisk status?', 'Vakenhet och orientering, kranialnerver, motorik (kraft och tonus), reflexer, sensibilitet, koordination och gång. Alltid jämförelse höger/vänster.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-1-c2', 'km4-1', 'Vad är skillnaden mellan central och perifer facialispares?', 'Central pares drabbar nedre delen av ansiktet kontralateralt (pannan kan rynkas); perifer pares drabbar hela halvan ipsilateralt, inklusive pannan. Central pares tyder på lesion ovan kärnan.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-1-c3', 'km4-1', 'Vad kännetecknar ett epileptiskt anfall jämfört med synkope?', 'Epileptiska anfall ger ofta prodromer, tonisk-kloniska rörelser, tungbett, cyanos och lång postiktal förvirring. Synkope ger blekhet, snabb återhämtning och ofta utlösande faktor som ortostas.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-1-c4', 'km4-1', 'Vilka varningsflaggor vid huvudvärk kräver akut utredning?', 'Plötslig debut med maximal intensitet, feber med nackstelhet, neurologiska bortfall, debut efter 50 års ålder, förändrat beteende och huvudvärk som förvärras i liggande.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-1-c5', 'km4-1', 'Hur presenterar sig multipel skleros typiskt?', 'Recidiverande neurologiska skov med symtom spridda i tid och rum, till exempel optikusneurit, sensoriska bortfall, ataxi och urinträngningar, vanligtvis hos unga vuxna kvinnor.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-1-c6', 'km4-1', 'Vad är de viktigaste åtgärderna vid akut stroke utöver trombolys/trombektomi?', 'Säkra luftväg och syresättning, reglera blodtryck och blodsocker, tidig DT och neurologbedömning, sväljtest innan födointag och trombosprofylax samt tidig rehabilitering.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-2-c1', 'km4-2', 'Hur länge ska symtomen ha varat för diagnosen egentlig depression?', 'Minst två veckor, med nedstämdhet eller anhedoni plus minst fyra ytterligare symtom (sammanlagt fem) och funktionspåverkan.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-2-c2', 'km4-2', 'Vad skiljer bipolär typ I från typ II?', 'Typ I: minst en manisk episod (kan ha haft depression). Typ II: depressiva episoder och hypomana episoder, men aldrig mani.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-2-c3', 'km4-2', 'Vad är skillnaden mellan hallucination och illusion?', 'Hallucination är en varseblivning utan yttre stimulus; illusion är en felaktig tolkning av en verklig sinnesintryck.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-2-c4', 'km4-2', 'Vilka symtomdomäner bedöms vid en suicidriskbedömning?', 'Aktuella tankar, planer och tillgång till medel, tidigare försök, pågående psykos eller rus, hopplöshet, skyddande faktorer och behov av omedelbar inläggning.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-2-c5', 'km4-2', 'Vad kännetecknar Wernickes encefalopati och vad är behandlingen?', 'Tiaminbrist, vanligt vid alkoholbruk, ger ögonmotorikstörningar, ataxi och förvirring. Behandlas med tiamin och kan övergå i Korsakoffs syndrom med kvarstående minnesstörning.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-2-c6', 'km4-2', 'Varför är antidepressiva medel inte verksamma direkt?', 'De ökar monoaminöverföringen snabbt, men klinisk effekt kommer först efter några veckor – förklaras av adaptiva förändringar som nedreglering av receptorer och ökad neuroplasticitet.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-3-c1', 'km4-3', 'Vilka fynd talar för akut trångvinkelglaukom?', 'Svår ögonsmärta, rött öga, grumlig kornea, medelvid reaktionslös pupill, halosyn, illamående och kraftigt förhöjt ögontryck.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-3-c2', 'km4-3', 'Vad är katarakt och vilken är den enda botande behandlingen?', 'Grumling av linsen ger långsamt tilltagande dimsyn och bländning. Enda botande behandlingen är operation med byte av linsen till konstgjord lins.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-3-c3', 'km4-3', 'Hur skiljer man torr från våt makuladegeneration?', 'Torr form: långsam atrofi med drusen. Våt form: kärlnybildning under näthinnan som läcker, med snabbare synnedsättning och behandling med anti-VEGF-injektioner.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-3-c4', 'km4-3', 'Vilka symtom ska alltid leda till akut ögonläkarbedömning?', 'Plötslig synnedsättning, synfältsbortfall, smärta med rött öga, trauma, ljusblixtar med skuggfält och ny upplevelse av dubbelseende.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-3-c5', 'km4-3', 'Vad kännetecknar bakteriell konjunktivit jämfört med viral?', 'Bakteriell: riklig gulgrön sekretion, klibbar igen ögat på morgonen, ofta ensidig. Viral: vattnig sekretion, ofta bilateral, förknippad med förkylning och lymfkörtelförstoring.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-4-c1', 'km4-4', 'Vad innebär Rinne- och Weberproven?', 'Rinne: luftledning jämförs med benledning – normalt hörs luftledning bättre. Weber: stämgaffel på hjässan – lateralisering till det sjuka örat vid ledningshinder, till det friska vid sensorineural nedsättning.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-4-c2', 'km4-4', 'Vilka är de vanligaste agens vid akut otitis media?', 'Streptococcus pneumoniae, Haemophilus influenzae och Moraxella catarrhalis. Virus förekommer också, och de flesta fall läker spontant.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-4-c3', 'km4-4', 'Vad kännetecknar Menières sjukdom?', 'Återkommande attacker av yrsel med sensorineural hörselnedsättning, tinnitus och öronsus, orsakat av endolymfatisk hydrops.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-4-c4', 'km4-4', 'Vilka varningssignaler vid heshet ska utredas?', 'Heshet över tre veckor, särskilt hos rökare, med viktnedgång, palpabel halskörtel eller påverkat allmäntillstånd – misstanke om larynx- eller hypofarynxcancer.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-4-c5', 'km4-4', 'Vad är septumhematom och varför behandlas det?', 'Blodansamling under septumperikondriet efter trauma kan ge trycknekros av brosket med septumperforation eller sadelnäsa. Behandling är incision och dränage.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-5-c1', 'km4-5', 'Vad skiljer epiduralt från subduralt hematom på DT?', 'Epiduralt: linsformad (bikonvex), korsar inte suturer, arteriellt (a. meningea media), snabbt förlopp. Subduralt: halvmåneformat, korsar suturerna, venöst (bryggvener), långsammare.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-5-c2', 'km4-5', 'Vad är Cushings trias?', 'Hypertoni, bradycardi och oregelbunden andning vid höjt intrakraniellt tryck med hotande herniering.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-5-c3', 'km4-5', 'Vilka är tidiga tecken på höjt intrakraniellt tryck?', 'Huvudvärk som förvärras i liggande, illamående/kräkningar, nedsatt vakenhet, påverkad pupill och papillödem.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-5-c4', 'km4-5', 'Varför uppstår hydrocefalus och hur behandlas den?', 'Störd cirkulation eller absorption av cerebrospinalvätska ger dilaterade ventriklar. Behandling är dränage (EVD) eller shunt, vid akut vinkelblockshydrocefalus snabbt.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km4-5-c5', 'km4-5', 'Vad gör man först när en patient med misstänkt intrakraniell blödning försämras?', 'Säkra luftväg (intubation vid GCS under 8), undvika hypoxi och hypotension, höjd huvudända och omedelbar neurokirurgisk kontakt samt DT.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-1-c1', 'km5-1', 'Vid vilken ålder sitter de flesta barn utan stöd, går självständigt och säger sina första ord?', 'Sitter utan stöd 6–8 månader, går självständigt kring 12–15 månader, säger första ord kring 12 månader och tvåordssatser kring 18–24 månader.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-1-c2', 'km5-1', 'Vad innebär primitivreflexernas försvinnande?', 'Reflexer som Moro, grip- och ATNR ska avta under första halvåret. Kvarstående primitivreflexer efter 6 månader är en varningssignal om central påverkan.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-1-c3', 'km5-1', 'Hur bedöms tillväxten praktiskt?', 'Längd, vikt och huvudomfång följs på ålders- och könsjusterade tillväxtkurvor. Huvudomfånget speglar hjärntillväxt och avvikelser utreds särskilt.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-1-c4', 'km5-1', 'Vilka röda flaggor finns i utvecklingen?', 'Utebliven sittning vid 9 månader, utebliven gång vid 18 månader, inga ord vid 18 månader, förlust av förvärvade färdigheter, asymmetri i motorik och avvikande social kontakt.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-1-c5', 'km5-1', 'Vad är skillnaden mellan hereditär kortväxthet och konstitutionell försening?', 'Hereditär kortväxthet: barnet följer en kurva parallellt med normal tillväxthastighet men under medellängd, med kortväxta föräldrar. Konstitutionell försening: sen pubertet och sen benåldersmognad med normal slutlängd.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-2-c1', 'km5-2', 'Vad är Apgar-scoren och vilka parametrar ingår?', 'Snabb bedömning av nyfödd vid 1 och 5 minuter: andning, puls, färg/hudfärg, muskeltonus och reflexirritabilitet. Låg poäng kräver omedelbar åtgärd.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-2-c2', 'km5-2', 'Varför får prematurer RDS?', 'Brist på surfaktant från typ II-pneumocyter ger hög ytspänning, alveolar kollaps, atelektaser och hypoxi. Behandling är framför allt CPAP och vid behov surfaktant.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-2-c3', 'km5-2', 'När är neonatal ikterus fysiologisk respektive patologisk?', 'Fysiologisk: debut efter 24 timmar, topp dag 3–5. Patologisk: debut första dygnet, snabb stegring, hög koncentration eller långvarig ikterus.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-2-c4', 'km5-2', 'Vilka symtom ska väcka misstanke om sepsis hos en nyfödd?', 'Dålig amning, slöhet, temperaturinstabilitet, takypné, blekhet, ökad kräkning och eventuellt hudpåverkan – symtomen är ofta ospecifika.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-2-c5', 'km5-2', 'Vad är neonatal hypoglykemi och vilka riskerar det?', 'Lågt blodsocker efter födseln; riskgrupper är barn till diabetiska mödrar, prematurer, SGA-barn och asfyktiska barn. Symtom är slöhet, tremor, dålig amning och kramper.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-2-c6', 'km5-2', 'Vad gör man vid mekoniumaspiration?', 'Fri luftväg och andningsstöd, undvika överdriven ventilation, överväga CPAP/ventilation och behandla eventuell pulmonell hypertoni. Antibiotika övervägs vid misstänkt infektion.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-3-c1', 'km5-3', 'Vilka sjukdomar ingår i det svenska allmänna barnvaccinationsprogrammet?', 'Difteri, stelkramp, kikhosta, polio, Haemophilus influenzae typ b, pneumokocker, mässling, påssjuka, röda hund, hepatit B, rotavirus och HPV samt i riskgrupper tuberkulos och influensa.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-3-c2', 'km5-3', 'Vad innebär flockimmunitet?', 'När en tillräckligt stor andel av befolkningen är immun minskar smittspridningen så att även de som inte kan vaccineras skyddas – därför är hög täckning avgörande.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-3-c3', 'km5-3', 'Varför ges levande vaccin oftast i två doser?', 'Första dosen ger inte alltid fullgott svar; andra dosen fångar upp dem som inte svarat och höjer skyddet och täckningen.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-3-c4', 'km5-3', 'Vilka komplikationer kan mässling ge?', 'Öroninflammation, pneumoni, encefalit och senare subakut skleroserande panencefalit. Mässling ger också övergående immunologisk påverkan med ökad infektionskänslighet.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-3-c5', 'km5-3', 'Vad kännetecknar scharlakansfeber?', 'Grupp A-streptokocktoxin ger feber, halsfluss, sandpappersutslag och smultrontunga samt senare fjällning. Behandlas med penicillin.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-4-c1', 'km5-4', 'Vad är de tidiga tecknen på andnöd hos barn?', 'Ökad andningsfrekvens, indragningar (subkostalt, interkostalt, suprasternellt), grymtande, nasala fladder och förändrad vakenhet. Bradykardi och tystnad är sena, hotande tecken.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-4-c2', 'km5-4', 'Varför försämras barn snabbt vid cirkulatorisk svikt?', 'Barn kompenserar länge med takykardi och perifer kärlsammandragning, men har begränsad hjärt-/lungreserv. När kompensationen brister faller de snabbt i bradykardi och hjärtstopp.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-4-c3', 'km5-4', 'Hur bedöms dehydreringsgrad kliniskt?', 'Allmäntillstånd, tårproduktion, slemhinnor, hudturgor, puls, kapillär återfyllnad, andning och urinproduktion. Viktnedgång är det mest objektiva måttet.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-4-c4', 'km5-4', 'Vad är skillnaden mellan krupp och epiglottit?', 'Krupp: gradvis debut, skällande hosta, heshet, inspiratorisk stridor, oftast virus. Epiglottit: snabb debut, hög feber, dregling, trippodställning, ingen hosta – luftvägsakut.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km5-4-c5', 'km5-4', 'Vilka differentialdiagnoser finns till akut andnöd hos barn?', 'Bronkiolit, astma, krupp, epiglottit, främmande kropp, anafylaxi, pneumoni, hjärtfel och sepsis – samt metabola orsaker som metabol acidos.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-1-c1', 'km6-1', 'Hur beräknas graviditetslängden?', 'Från första dagen av senaste menstruation (Naegele regel) eller, säkrare, med ultraljud i tidig graviditet. Normal graviditet varar cirka 40 graviditetsveckor.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-1-c2', 'km6-1', 'Vad mäter CTG?', 'Fostrets hjärtfrekvens och livmoderkontraktioner. Basalfrekvens, variabilitet, accelerationer och decelerationer bedöms för att upptäcka syrebrist.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-1-c3', 'km6-1', 'Vad är skillnaden mellan placenta previa och ablatio placentae?', 'Placenta previa: placenta över inre modermunnen, smärtfri blödning. Ablatio: placentan lossnar i förtid från normal position, smärtsam blödning med hård, öm livmoder.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-1-c4', 'km6-1', 'Vilka är förlossningens tre skeden?', 'Öppningsskedet (latent och aktiv fas), utdrivningsskedet och efterbördsskedet. Aktiv fas definieras av regelbundna värkar med tilltagande öppning från cirka 4 cm.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-1-c5', 'km6-1', 'Vad är ett normalt fosterljudsmönster?', 'Basalfrekvens 110–160 slag per minut, god variabilitet, accelerationer vid rörelse och inga upprepade sena decelerationer.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-1-c6', 'km6-1', 'Vilka är de viktigaste orsakerna till postpartumblödning?', 'De fyra T:na – Tonus (atoni), Trauma (bristning, ruptur), Tissue (kvarvarande placenta) och Thrombin (koagulopati).', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-2-c1', 'km6-2', 'Vilka kriterier krävs för diagnosen preeklampsi?', 'Nytillkommen hypertoni efter 20 graviditetsveckor plus proteinuri eller annan organskada (trombocytopeni, njurpåverkan, leverpåverkan, lungödem, neurologiska symtom).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-2-c2', 'km6-2', 'Hur uppstår preeklampsi?', 'Störd trophoblastinvasion och otillräcklig ombyggnad av spiralartärerna ger placentär ischemi, vilket frisätter antiangiogena faktorer som skadar maternella endotelceller och ger hypertoni, proteinuri och ödem.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-2-c3', 'km6-2', 'Varför är extrauterin graviditet livshotande?', 'Tuben kan inte expandera som livmodern. Vid ruptur uppstår massiv intraabdominell blödning med hypovolemisk chock.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-2-c4', 'km6-2', 'Vilka risker medför graviditetsdiabetes?', 'Makrosomi, axelinkärkning, kejsarsnitt, neonatal hypoglykemi och senare typ 2-diabetes hos modern.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-2-c5', 'km6-2', 'Vad är HELLP-syndromet?', 'Hemolys, Elevated Liver enzymes och Low Platelets – en allvarlig variant av preeklampsi som kräver snabb förlossning.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-3-c1', 'km6-3', 'Vilka symtom ger uterusmyom?', 'Rikliga och långvariga menstruationer, tryckkänsla, täta trängningar och ibland infertilitet. Behandling: observation, hormoner, embolisering eller kirurgi.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-3-c2', 'km6-3', 'Varför ska all postmenopausal blödning utredas?', 'Det är det vanligaste symtomet på endometriecancer. Utredning: transvaginalt ultraljud och endometriebiopsi.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-3-c3', 'km6-3', 'Vad är endometrios och vad är typiska fynd?', 'Endometrieliknande vävnad utanför uterus med inflammation och ärrbildning. Fynd: blåaktiga lesioner, adherenser, endometriom. Symtom: dysmenorré, dyspareuni, infertilitet.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-3-c4', 'km6-3', 'Vad är den vanligaste orsaken till akut bäckensmärta hos ung kvinna?', 'Differentialdiagnostik omfattar extrauterin graviditet, ovulationssmärta, ovarialcysta med torsion, salpingit och appendicit – graviditetstest ingår alltid.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-3-c5', 'km6-3', 'Hur förebyggs cervixcancer?', 'HPV-vaccination före sexuell debut och screening med cytologi/HPV-test som upptäcker och behandlar förstadier.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-4-c1', 'km6-4', 'Vilka tre kriterier används vid PCOS (Rotterdam)?', 'Oligo-/anovulation, klinisk eller biokemisk hyperandrogenism och polycystiska ovarier. Minst två av tre krävs, efter uteslutning av andra orsaker.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-4-c2', 'km6-4', 'Vilka är de viktigaste kontraindikationerna för kombinerade hormonella preventivmedel?', 'Tidigare venös tromboembolism, migrän med aura, rökning över 35 år, hypertoni, bröstcancer, leversjukdom och känd trombofili.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-4-c3', 'km6-4', 'Hur fungerar kombinerade p-piller?', 'Östrogen hämmar FSH och därmed follikelmognad; gestagen hämmar LH-toppen och gör cervicalsekretet tjockt och endometriet otillgängligt. Ägglossning uteblir.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-4-c4', 'km6-4', 'Vad ingår i basal infertilitetsutredning?', 'Spermaanalys, bekräftad ovulation (cykelanamnes/progesteron), bedömning av äggledarpassage (HSG) och ultraljud av uterus, samt relevanta blodprover.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km6-4-c5', 'km6-4', 'Vad är akut p-piller och hur verkar det?', 'Hög dos gestagen (eller ulipristal) som fördröjer ägglossningen. Verkan är bäst ju tidigare det tas efter oskyddat samlag; det skyddar inte resten av cykeln och är inte abortivt i strikt mening.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-1-c1', 'km7-1', 'Vad är skillnaden mellan onkogen och tumörsuppressorgen?', 'Onkogen: muterad gen som driver tillväxt, räcker med en aktiverad allel (gain of function, t.ex. RAS, MYC). Tumörsuppressorgen: bromsar cellcykeln, båda alleler måste slås ut (loss of function, t.ex. p53, RB, BRCA).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-1-c2', 'km7-1', 'Vilka sex egenskaper (hallmarks) har en cancercell?', 'Obegränsad proliferation, undvikande av tillväxthämmande signaler, resistens mot apoptos, angiogenes, invasion/metastasering och replikativ immortalitet – ofta tillkommande immunundanflykt och förändrad metabolism.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-1-c3', 'km7-1', 'Vad är skillnaden mellan grad och stadium?', 'Grad = histologisk differentieringsgrad (hur likt normalvävnad tumören är). Stadium = anatomisk utbredning enligt TNM. Stadium styr i högre grad behandlingsval och prognos.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-1-c4', 'km7-1', 'Vilka vägar sprider tumörer sig?', 'Direkt invasion i omgivande vävnad, lymfogen spridning till regionala körtlar och hematogen spridning till lever, lungor, ben och hjärna. Vissa tumörer sprids transcoelomt (peritoneal karcinomatos).', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-1-c5', 'km7-1', 'Varför ger koloncancer ofta järnbristanemi?', 'Tumören blöder långsamt och kontinuerligt utan att ge synligt blod, vilket ger kronisk blodförlust och järnbrist. Symtom är trötthet och anemi snarare än blodig avföring.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-1-c6', 'km7-1', 'Vad är ett paraneoplastiskt syndrom?', 'Symtom orsakade av ämnen tumören producerar, till exempel hyperkalcemi vid skivepitelcancer eller SIADH vid småcellig lungcancer – inte av metastaser.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-2-c1', 'km7-2', 'Vilka fyra huvudmodaliteter finns i cancerbehandling?', 'Kirurgi, strålbehandling, cytostatika och målsökande/immunologisk behandling (inklusive endokrin behandling vid hormonkänsliga tumörer).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-2-c2', 'km7-2', 'Vad är skillnaden mellan adjuvant och neoadjuvant behandling?', 'Adjuvant: efter radikal kirurgi för att eliminera mikrometastaser. Neoadjuvant: före kirurgi för att krympa tumören.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-2-c3', 'km7-2', 'Vad är R0, R1 och R2 vid tumörkirurgi?', 'R0 = radikal resektion utan kvarvarande tumörväxt, R1 = mikroskopisk kvarvarande tumör i resektionsrand, R2 = makroskopisk kvarvarande tumör.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-2-c4', 'km7-2', 'Vilka akuta biverkningar har cytostatika?', 'Myelosuppression med infektionsrisk, mucosit, illamående, håravfall, trötthet och tumörlyssyndrom. Sena biverkningar är bland annat neuropati, kardiotoxicitet och infertilitet.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-2-c5', 'km7-2', 'Hur verkar målsökande behandling?', 'Den riktas mot specifika molekyler i tumörcellen eller dess omgivning, till exempel HER2, EGFR eller VEGF, och är beroende av att tumören uttrycker målmolekylen.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-2-c6', 'km7-2', 'Vad är palliativ cytostatika?', 'Behandling som ges när bot inte är möjlig, i syfte att lindra symtom, bromsa tumörväxt och förbättra livskvalitet – alltid vägd mot biverkningar.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-3-c1', 'km7-3', 'Vad är definitionen av palliativ vård?', 'Aktiv, helhetsinriktad vård av patient med obotlig, livshotande sjukdom. Syftet är att lindra fysiska, psykiska, sociala och existentiella symtom och stödja närstående – inte att påskynda eller fördröja döden.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-3-c2', 'km7-3', 'Vilka fyra dimensioner ingår i total smärta?', 'Fysisk, psykisk, social och existentiell smärta – alla behöver adresseras för att patienten ska få lindring.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-3-c3', 'km7-3', 'Varför blir opioidbehandling aldrig farlig genom att dosen ökas vid behov i palliativa skeden?', 'När dosen titreras mot symtom och tolerans utvecklas mot sedering och andningsdepression har adekvat symtomlindring ingen livsförkortande effekt – detta gäller vid korrekt indikation och titrering.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-3-c4', 'km7-3', 'Vilka läkemedel används mot neuropatisk smärta?', 'Tricykliska antidepressiva (t.ex. amitriptylin), SNRI och antiepileptika som gabapentin och pregabalin – ofta i kombination med opioid.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-3-c5', 'km7-3', 'Hur lindras andnöd i livets slutskede?', 'Opioider mot dyspnéns känsla, syrgas endast vid hypoxi, fläkt/luftdrag, lugnt bemötande, och behandling av bakomliggande orsaker som ansamling av sekret eller pleuravätska.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-3-c6', 'km7-3', 'Vad innebär ''LCP'' eller vård i livets slutskede i praktiken?', 'Regelbunden symtomkontroll, muntorrhetsvård, målstyrd vätska/föda, behandlingsstrategi vid andnöd, smärta och ångest, samt planering för dödsfallet och stöd till närstående.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-4-c1', 'km7-4', 'Vad är definitionen av febril neutropeni?', 'Feber (ofta enstaka temp 38,5 eller 38,0 upprepat) samt neutrofila granulocyter under 0,5 × 10⁹/L. Ett akut tillstånd som kräver omedelbar intravenös bredspektrumantibiotika.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-4-c2', 'km7-4', 'Vilka elektrolytrubbningar ger tumörlyssyndrom?', 'Hyperkalemi, hyperfosfatemi, hyperurikemi och sekundär hypokalcemi samt akut njursvikt. Behandling: hydrering, uratsänkning, elektrolytkorrigering, vid behov dialys.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-4-c3', 'km7-4', 'Vilka symtom ska väcka misstanke om ryggmärgskompression?', 'Progressiv ryggvärk som förvärras i liggande, utstrålande bandsmärta, kraftnedsättning, sensibilitetsstörning, blås- och tarmdysfunktion.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-4-c4', 'km7-4', 'Vad är hyperkalcemi vid cancer och hur lindras den?', 'Vanligt vid skelettmetastaser och vid paraneoplastisk PTHrP-produktion. Symtom: trötthet, konfusion, förstoppning, njursvikt. Behandling: vätska, bisfosfonater eller denosumab, behandling av tumören.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-4-c5', 'km7-4', 'Vad är vena cava superior-syndrom?', 'Tumör eller trombos komprimerar övre hålvenen, vilket ger svullnad i ansikte och armar, utspända halsvener, andnöd och vid snabb utveckling livshotande luftvägsobstruktion eller hjärnödem.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('km7-4-c6', 'km7-4', 'Varför är tid avgörande vid onkologiska akutfall?', 'Neurologisk och renal funktion som förlorats vid kompression, njursvikt eller sepsis är ofta irreversibel. Behandlingsfördröjning försämrar både överlevnad och livskvalitet.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m1-c1', 'mdbi-m1', 'Vad ingår i en blodstatus och vad betyder de viktigaste parametrarna?', 'Hb, EVF, MCV/MCH/MCHC, LPK med differential samt trombocyter. MCV skiljer mikro-/normo-/makrocytär anemi; LPK och differential speglar infektion och hematologisk sjukdom.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m1-c2', 'mdbi-m1', 'Vilka leverprover talar för kolestas respektive hepatocellulär skada?', 'Kolestas: ALP och GT stiger. Hepatocellulär skada: ALAT och ASAT stiger. Bilirubin och albumin/PK visar leverfunktion.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m1-c3', 'mdbi-m1', 'Vad visar CRP och SR och hur skiljer de sig?', 'Båda är inflammationsmarkörer. CRP stiger snabbt (timmar) och sjunker snabbt; SR stiger långsamt och sjunker långsamt (påverkas av albumin/fibrinogen).', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m1-c4', 'mdbi-m1', 'Vad betyder konfidensintervall i en klinisk studie?', 'Det intervall inom vilket den sanna effekten med viss sannolikhet (oftast 95 procent) ligger; brett intervall = osäker skattning.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m2-c1', 'mdbi-m2', 'Vilka vågor och intervall finns på ett EKG och vad motsvarar de?', 'P-våg (förmaksdepolarisering), PR-intervall (AV-ledning), QRS (kammardepolarisering), QT (depolarisering + repolarisering), T-våg (kammarrepolarisering).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m2-c2', 'mdbi-m2', 'Vad är skillnaden mellan arbetsprov, myokardscintigrafi och DT-kranskärl?', 'Arbetsprov: funktionell ischemi vid ansträngning. Scintigrafi: perfusion bild vid belastning/vila. DT: anatomisk karta över kranskärl och plaque – hög negativt prediktivt värde.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m2-c3', 'mdbi-m2', 'Vad visar lungfunktionsundersökning vid obstruktiv sjukdom?', 'Sänkt FEV1 och FEV1/FVC < 0,7; reversibilitetstest med bronkdilaterare skiljer astma från KOL.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m2-c4', 'mdbi-m2', 'När väljer man MR-hjärta framför DT?', 'Vid behov av vävnadskarakterisering utan strålning – t.ex. myokardit, kardiomyopatier, infiltrativa sjukdomar och fibros (late gadolinium enhancement).', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m3-c1', 'mdbi-m3', 'Vilka modaliteter finns och vad är deras styrka?', 'Slätröntgen (snabb, översikt), DT (detaljerad anatomi, akut), MR (mjukdelar utan strålning), ultraljud (realtid, strålningsfritt) och nuklearmedicin/PET (funktion/metabolism).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m3-c2', 'mdbi-m3', 'Vad ska remissen till radiologi innehålla?', 'Frågeställning, relevant anamnes och kliniska fynd, tidigare undersökningar, eventuell graviditet samt kontaktuppgifter för komplettering.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m3-c3', 'mdbi-m3', 'Vad kännetecknar en god lungröntgenbedömning?', 'Systematisk genomgång: projektion och rotation, inspiration, lungfält, hjärta/mediastinum, hilus, diafragma, pleura, skelett och mjukdelar – leta efter fria lungkanter och silhuettecken.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m3-c4', 'mdbi-m3', 'När är jodkontrast respektive gadoliniumkontrast riskabelt?', 'Jodkontrast: nedsatt njurfunktion (kontrastnefropati) och tidigare allvarlig reaktion. Gadolinium: gravt nedsatt njurfunktion (NSF) samt graviditet.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m4-c1', 'mdbi-m4', 'Vilka blodgruppssystem är viktigast vid transfusion?', 'ABO och Rh(D). O-negativ är universaldonator för erytrocyter; AB-positive kan ta emot alla erytrocyter men AB-plasma är universaldonator för plasma.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m4-c2', 'mdbi-m4', 'Hur går en odling och resistensbestämning till?', 'Prov odlas på selektiva medier, identifieras (MALDI-TOF/PCR) och resistens bestäms med diffusions- eller MIC-metod; snabb-PCR kan ge svar inom timmar för kritiska patogener.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m4-c3', 'mdbi-m4', 'Vad visar en ELISA och när används den?', 'Antigen eller antikropp mäts med enzymmarkerad reaktion – används för serologi (HIV, hepatit), autoantikroppar och hormonanalyser.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m4-c4', 'mdbi-m4', 'Vilka transfusionsreaktioner finns?', 'Akut hemolytisk (ABO-fel), febril non-hemolytisk, allergisk/anafylaktisk, TRALI, TACO och fördröjd hemolytisk reaktion.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m5-c1', 'mdbi-m5', 'Vad betyder etiologi, patogenes, morfologi och klinisk bild i patologin?', 'Etiologi = orsak; patogenes = mekanism; morfologi = vävnadsförändringar; klinisk bild = symtom och fynd. Patologin kopplar dessa till diagnos.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m5-c2', 'mdbi-m5', 'Vad skiljer benign från malign tumör morfologiskt?', 'Malign: infiltrativ växt, hög cellatypi, mitoser, nekros, kärlinväxt och metastasering. Benign: välavgränsad, liknar ursprungsvävnad, inga metastaser.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m5-c3', 'mdbi-m5', 'Vilka analyser ingår i hematopatologisk diagnostik?', 'Blodstatus med differential, benmärgsmorfologi, flödescytometri, cytogenetik (FISH/karyotyp), molekylär analys (NGS) samt immunhistokemi.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mdbi-m5-c4', 'mdbi-m5', 'Vad är syftet med klinisk obduktion?', 'Att fastställa dödsorsak, upptäcka diagnoser som missats och ge kvalitetssäkring samt underlag för anhöriga – kräver samtycke enligt lag.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-1-c1', 'mvtm-1', 'Vad står PICO för?', 'Population/Patient, Intervention, Comparison (jämförelse) och Outcome (utfall). Strukturen gör forskningsfrågan precis och sökbar.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-1-c2', 'mvtm-1', 'Vilka är styrkorna med en kohortstudie?', 'Kan beräkna incidens och relativ risk, fastställa tidsordning mellan exponering och utfall samt studera flera utfall samtidigt. Svagheten är confounding och att ovanliga utfall kräver stora populationer.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-1-c3', 'mvtm-1', 'Vilka mått kommer från fall-kontroll respektive kohort?', 'Fall-kontroll ger oddskvot (OR); kohort ger relativ risk (RR) och absolut risk. Vid låg sjukdomsförekomst approximerar OR riskkvoten.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-1-c4', 'mvtm-1', 'Vad är en tvärsnittsstudie bra för?', 'Att mäta förekomst (prevalens) och samband vid en given tidpunkt. Den kan inte fastställa kausalitet eller tidsordning.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-1-c5', 'mvtm-1', 'När används kvalitativ metod?', 'För att undersöka upplevelser, mening, bemötande och processer – ofta med intervjuer eller fokusgrupper och analys med till exempel innehållsanalys.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-1-c6', 'mvtm-1', 'Vad kännetecknar en systematisk översikt med metaanalys?', 'En fördefinierad sökstrategi, systematisk urval och kvalitetsgranskning av alla relevanta studier, ofta med statistisk sammanvägning av effekter och bedömning av heterogenitet.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-2-c1', 'mvtm-2', 'Vad är skillnaden mellan typ I- och typ II-fel?', 'Typ I (alfa): att felaktigt förkasta en sann nollhypotes, dvs. falskt positivt fynd. Typ II (beta): att inte förkasta en falsk nollhypotes, dvs. missad verklig effekt.', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-2-c2', 'mvtm-2', 'Vad betyder statistisk styrka (power)?', 'Sannolikheten att upptäcka en verklig effekt av en given storlek; vanligen eftersträvas 80 %. Styrkan ökar med effektstorlek, minskad spridning och ökat antal deltagare.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-2-c3', 'mvtm-2', 'Hur definieras sensitivitet och specificitet?', 'Sensitivitet = andel sjuka som testas positiva (sanna positiva / alla sjuka). Specificitet = andel friska som testas negativa (sanna negativa / alla friska).', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-2-c4', 'mvtm-2', 'Vad påverkar positivt prediktivt värde?', 'Både testets sensitivitet och specificitet samt sjukdomens prevalens i populationen; PPV stiger när prevalensen stiger.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-2-c5', 'mvtm-2', 'Vad är en normalfördelning och vad följer av den?', 'Symmetrisk klockformad fördelning som beskrivs av medelvärde och standardavvikelse; cirka 95 % av observationerna ligger inom två standardavvikelser från medelvärdet.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-2-c6', 'mvtm-2', 'När används icke-parametriska test?', 'När data inte är normalfördelade, är ordinala eller då urvalet är litet – till exempel Mann-Whitney U-test i stället för t-test.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-3-c1', 'mvtm-3', 'Vilka fyra huvudtyper av bias finns i kliniska studier?', 'Selektionsbias (urvalet), performansbias (avvikelser i behandlingen), detektionsbias (hur utfallet mäts) och attritionsbias (bortfall).', 1, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-3-c2', 'mvtm-3', 'Vad är publikationsbias och hur upptäcks den?', 'Att studier med positiva resultat publiceras oftare än negativa, vilket ger en förskönad bild av effekten. Misstanke väcks via funnel plot, jämförelse av registrerade och publicerade studier samt granskning av studiedesign i systematiska översikter.', 2, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-3-c3', 'mvtm-3', 'Vilka är GRADE:s nivåer för tillit till evidens?', 'Hög, måttlig, låg och mycket låg. Randomiserade studier börjar högt och observationella lågt, varefter nivån justeras ned eller upp utifrån ett antal domäner.', 3, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-3-c4', 'mvtm-3', 'Vad innebär Bradford Hills kausalitetskriterier?', 'Ett antal vägledande kriterier – bland andra temporalitet, dos-respons, styrka, konsistens, specificitet, biologisk plausibilitet och experimentellt stöd. Ingen enskild är nödvändig eller tillräcklig.', 4, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-3-c5', 'mvtm-3', 'Vad är lead-time bias vid screening?', 'Att överlevnadstiden ser längre ut enbart för att diagnosen ställs tidigare, även om dödsfallet inträffar vid samma tidpunkt. Därför mäts sjukdomsspecifik mortalitet hellre än överlevnadstid.', 5, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;
INSERT INTO chapter_cards (id, chapter_id, front, back, sort_order, origin)
VALUES ('mvtm-3-c6', 'mvtm-3', 'Hur hanteras intressekonflikter i granskning?', 'Deklarera bindningar, granska finansiering och författarnas roller samt kontrollera att slutsatser stöds av data. Oberoende replikering och öppna data minskar risken för påverkan.', 6, 'kapitel')
ON CONFLICT (id) DO UPDATE SET chapter_id = EXCLUDED.chapter_id, front = EXCLUDED.front,
  back = EXCLUDED.back, sort_order = EXCLUDED.sort_order, origin = EXCLUDED.origin;

